          </div>
        </div>
      )}

      {isTemplatePickerOpen && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsTemplatePickerOpen(false)}></div>
          <div className="bg-white w-full max-w-xl rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-6 text-white flex justify-between items-center">
              <h3 className="text-xl font-black uppercase">Šablony oprav</h3>
              <button onClick={() => setIsTemplatePickerOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <div className="p-6 max-h-[60vh] overflow-y-auto custom-scrollbar space-y-4">
              {predefinedTasks.map(item => (
                <button 
                  key={item.id} 
                  onClick={() => addFromTemplates(item)}
                  className="w-full text-left p-5 bg-slate-50 hover:bg-blue-50 rounded-2xl transition-all border border-slate-100 group"
                >
                  <span className="block font-black text-slate-900 text-sm mb-1 uppercase tracking-tight group-hover:text-blue-700">{item.label}</span>
                  <span className="block text-xs font-medium text-slate-500 italic leading-relaxed">{item.description}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {isAiImportOpen && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => !aiLoading && setIsAiImportOpen(false)}></div>
          <div className="bg-white w-full max-w-4xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col max-h-[80vh]">
            <div className="bg-emerald-600 p-6 text-white flex justify-between items-center shrink-0">
               <div className="flex items-center gap-4">
                  <div className="bg-white/20 p-2 rounded-xl"><FileSearch className="w-6 h-6" /></div>
                  <h3 className="text-xl font-black uppercase">AI Import ze souboru</h3>
               </div>
               {!aiLoading && <button onClick={() => setIsAiImportOpen(false)} className="p-2 hover:bg-white/10 rounded-xl"><X className="w-5 h-5" /></button>}
            </div>
            <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
              {aiLoading ? (
                <div className="flex flex-col items-center justify-center py-20 gap-4">
                  <Loader2 className="w-12 h-12 text-emerald-600 animate-spin" />
                  <p className="font-black text-slate-900 uppercase">Analyzuji soubor...</p>
                </div>
              ) : (
                <div className="space-y-6">
                  <table className="w-full text-left">
                    <thead><tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b"><th className="p-2">Vybrat</th><th className="p-2">Díl</th><th className="p-2 text-right">Nákupní cena</th><th className="p-2 text-right">Běžná cena</th></tr></thead>
                    <tbody>
                      {aiImportItems.map((item, idx) => (
                        <tr key={idx} className="border-b hover:bg-slate-50 cursor-pointer" onClick={() => {
                          const n = new Set(selectedAiIndices);
                          if (n.has(idx)) n.delete(idx); else n.add(idx);
                          setSelectedAiIndices(n);
                        }}>
                          <td className="p-2"><input type="checkbox" checked={selectedAiIndices.has(idx)} readOnly /></td>
                          <td className="p-2 text-sm font-bold">{item.description}</td>
                          <td className="p-2 text-sm font-bold text-red-600 text-right">{Math.round(item.costPrice || 0).toLocaleString()} Kč</td>
                          <td className="p-2 text-sm font-black text-blue-600 text-right">{Math.round(item.unitPrice || 0).toLocaleString()} Kč</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  <button onClick={() => {
                     const items = aiImportItems.filter((_, i) => selectedAiIndices.has(i)).map(it => {
                        const rawCost = it.costPrice || 0;
                        const rawUnit = it.unitPrice || rawCost;
                        const finalCost = companyInfo.isVatPayer ? (rawCost / 1.21) : rawCost;
                        const finalUnit = companyInfo.isVatPayer ? (rawUnit / 1.21) : rawUnit;

                        return { 
                          id: `ai-${Math.random()}`, 
                          description: it.description || '', 
                          quantity: it.quantity || 1, 
                          unit: 'ks', 
                          unitPrice: finalUnit,
                          costPrice: finalCost 
                        };
                     });
                     setFormData(p => ({ ...p, parts: [...p.parts, ...items] }));
                     setIsAiImportOpen(false);
                  }} className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-black">VLOŽIT VYBRANÉ ({selectedAiIndices.size})</button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {deletingOrder && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingOrder(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] p-8 text-center relative z-10 shadow-2xl">
             <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
             <h3 className="text-xl font-black mb-2">Opravdu smazat?</h3>
             <p className="text-slate-500 mb-8">Zakázka #{deletingOrder.id} bude trvale odstraněna.</p>
             <div className="flex gap-4">
                <button onClick={() => setDeletingOrder(null)} className="flex-1 py-4 bg-slate-100 rounded-xl font-bold">ZRUŠIT</button>
                <button onClick={() => { onDeleteService(deletingOrder.id); setDeletingOrder(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-xl font-bold">SMAZAT</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

const OrderCard: React.FC<{
  order: ServiceRecord;
  vehicles: Vehicle[];
  customers: Customer[];
  onEdit: (o: ServiceRecord) => void;
  onUpdateStatus: (s: any) => void;
  onOpenMenu: (id: string | null) => void;
  openMenuId: string | null;
  onCreateInvoice?: (id: string) => void;
  onDelete: () => void;
}> = ({ order, vehicles, customers, onEdit, onUpdateStatus, onOpenMenu, openMenuId, onCreateInvoice, onDelete }) => {
  const vehicle = vehicles.find(v => v.id === order.vehicleId);
  const customer = customers.find(c => c.id === vehicle?.customerId);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const click = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) onOpenMenu(null); };
    document.addEventListener('mousedown', click);
    return () => document.removeEventListener('mousedown', click);
  }, []);

  return (
    <div className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative">
       <div className="absolute top-4 right-4">
          <button onClick={(e) => { e.stopPropagation(); onOpenMenu(openMenuId === order.id ? null : order.id); }} className="p-2 hover:bg-slate-100 rounded-xl text-slate-400 hover:text-slate-900 transition-all"><MoreHorizontal className="w-6 h-6" /></button>
          {openMenuId === order.id && (
            <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border p-2 z-[60]">
               <button onClick={() => { onEdit(order); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-sm font-bold"><Edit3 className="w-4 h-4" /> Upravit</button>
               {order.status === 'hotovo' && onCreateInvoice && <button onClick={() => { onCreateInvoice(order.id); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 text-sm font-bold"><Receipt className="w-4 h-4" /> Faktura</button>}
               <button onClick={() => { onDelete(); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 text-sm font-bold"><Trash2 className="w-4 h-4" /> Smazat</button>
            </div>
          )}
       </div>
       <div className="flex items-center gap-4 mb-4">
          <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-white font-black ${order.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600' : order.status === 'probíhá' ? 'bg-amber-500' : 'bg-blue-600'}`}><ClipboardList className="w-6 h-6" /></div>
          <div><h4 className="text-lg font-black leading-none">#{order.id}</h4><p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">{formatDate(order.date)}</p></div>
       </div>
       <div className="space-y-2 border-t border-slate-50 pt-4">
          <div className="flex items-center gap-2 text-sm font-bold text-slate-700 truncate"><Car className="w-4 h-4 text-slate-300" /> {vehicle ? `${vehicle.make} ${vehicle.model}` : '---'} <span className="font-mono text-[10px] text-blue-600">{vehicle?.licensePlate}</span></div>
          <div className="flex items-center gap-2 text-sm font-bold text-slate-700 truncate"><User className="w-4 h-4 text-slate-300" /> {customer ? (customer.companyName || `${customer.firstName} ${customer.lastName}`) : '---'}</div>
       </div>
       <div className="mt-6 flex items-center justify-between bg-slate-50 p-3 rounded-2xl">
          <div className="flex flex-col"><span className="text-[8px] font-black text-slate-400 uppercase">Celkem</span><span className="text-sm font-black">{Math.round((order.cost || 0) * 1.21).toLocaleString()} Kč</span></div>
          <select value={order.status} onChange={(e) => onUpdateStatus(e.target.value)} className="text-[10px] font-black uppercase px-2 py-1 rounded-lg border outline-none bg-white">
             <option value="naplánováno">Naplánováno</option><option value="probíhá">Probíhá</option><option value="hotovo">Hotovo</option><option value="zrušeno">Zrušeno</option>
          </select>
       </div>
    </div>
  );
};

export const PrintTemplate: React.FC<{
  order: Partial<ServiceRecord> & { cost: number };
  company: CompanyInfo;
  vehicles: Vehicle[];
  customers: Customer[];
  hourlyRate: number;
  technicians: string[];
  isEditable?: boolean;
  onUpdatePart?: (id: string, field: keyof PartItem, value: any) => void;
  onRemovePart?: (id: string) => void;
  onAddPart?: () => void;
  onUpdateOrder?: (field: string, value: any) => void;
  onOpenPriceList?: () => void;
  onOpenTemplates?: () => void;
  fixedServices?: FixedService[];
  onFileUpload?: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onDeleteAttachment?: (id: string) => void;
  onOpenAttachment?: (att: VehicleAttachment) => void;
}> = ({ order, company, vehicles, customers, hourlyRate, technicians, isEditable, onUpdatePart, onRemovePart, onAddPart, onUpdateOrder, onOpenPriceList, onOpenTemplates, onFileUpload, onDeleteAttachment, onOpenAttachment }) => {
