          {labels.map((item) => (
            <div key={item.key} className="flex items-center justify-between p-1 px-2 border-b border-black h-[22px]">
              <span>{item.label}</span>
              <div className="w-4 h-4 border border-black flex items-center justify-center bg-white cursor-pointer" onClick={() => isEditable && onUpdateOrder?.('checklist', { ...order.checklist, [item.key]: !order.checklist?.[item.key as keyof VehicleChecklist] })}>
                {order.checklist?.[item.key as keyof VehicleChecklist] && <Check className="w-3 h-3 stroke-[4]" />}
              </div>
            </div>
          ))}
        </div>

        {/* Column 2: Attachments (col-span-2) */}
