          <div className="p-1.5 border-b border-black min-h-[34px] flex flex-col">
            <span className="text-[7px] uppercase opacity-50">VOZIDLO:</span>
            {isEditable ? (
              <div className="mt-1 flex flex-col gap-1">
                <div className="no-print flex items-center gap-1.5 bg-blue-50 px-1.5 py-0.5 rounded border border-blue-100 mb-1">
                   <Search className="w-2.5 h-2.5 text-blue-400" />
                   <input type="text" placeholder="Hledat..." className="bg-transparent border-none outline-none text-[8px] font-bold w-full" value={vehicleSearch} onChange={(e) => setVehicleSearch(e.target.value)} />
                </div>
                <select className="w-full bg-white border border-slate-200 outline-none font-bold text-[10px] p-0.5 rounded" value={order.vehicleId} onChange={(e) => onUpdateOrder?.('vehicleId', e.target.value)}>
                  <option value="">-- Vozidlo --</option>
                  {filteredVehicles.map(v => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
                </select>
              </div>
            ) : (
              <div className="mt-1"><p className="font-bold text-[10px]">{vehicle?.make} {vehicle?.model}</p></div>
            )}
          </div>
          <div className="p-1.5 border-b border-black flex-1">Kód: <span className="font-bold">{vehicle?.engineCode || '---'}</span></div>
          <div className="p-1.5 border-b border-black flex-1 flex items-center gap-1">
             <span>Stav km:</span>
             {isEditable ? (
               <div className="bg-blue-50/50 rounded border border-blue-100 px-1.5 flex items-center">
                 <input 
                   type="number" 
                   className="bg-transparent outline-none font-bold text-[10px] w-20 py-0.5" 
                   value={order.mileageAtEntry || 0} 
                   onChange={(e) => onUpdateOrder?.('mileageAtEntry', parseInt(e.target.value) || 0)} 
                 />
