             </div>
          </div>
        </div>

        {/* Column 4: Order details (col-span-3) */}
        <div className="col-span-3 flex flex-col">
          <div className="p-2 border-b border-black flex-1">Předběžná cena zakázky: {isEditable ? <input type="number" className="bg-blue-50/50 outline-none font-bold text-[11px] w-24 px-1.5 rounded" value={order.estimatedPrice || 0} onChange={(e) => onUpdateOrder?.('estimatedPrice', parseInt(e.target.value) || 0)} /> : <span className="font-bold">{Math.round(order.estimatedPrice || 0).toLocaleString()} Kč</span>}</div>
          <div className="p-2 border-b border-black flex-1 flex items-center">Mechanik: {isEditable ? <select className="bg-blue-50/50 outline-none font-bold text-[11px] px-1.5 rounded" value={order.technician} onChange={(e) => onUpdateOrder?.('technician', e.target.value)}>{technicians.map(t => <option key={t} value={t}>{t}</option>)}</select> : <span className="font-bold ml-1">{order.technician}</span>}</div>
          <div className="p-2 border-b border-black flex-1">Objednáno: <span className="font-bold">{formatDate(order.date || '')}</span></div>
          <div className="p-2 border-b border-black flex-1 flex items-center">Dokončení: {isEditable ? <input type="date" className="bg-blue-50/50 outline-none font-bold text-[11px] px-1.5 rounded" value={order.deliveryDate || ''} onChange={(e) => onUpdateOrder?.('deliveryDate', e.target.value)} /> : <span className="font-bold">{formatDate(order.deliveryDate || '')}</span>}</div>
          <div className="p-2 flex-1 flex items-center gap-2">Stav: {isEditable ? <select className="bg-blue-50/50 outline-none font-bold text-[11px] px-1.5 rounded" value={order.status} onChange={(e) => onUpdateOrder?.('status', e.target.value as any)}><option value="naplánováno">Naplánováno</option><option value="probíhá">Probíhá</option><option value="hotovo">Hotovo</option></select> : <span className="font-black uppercase text-[9px]">{order.status}</span>}</div>
        </div>
      </div>

      {/* Main Section Grid with added border-t-2 to fix the green divider line */}
      <div className="grid grid-cols-10 border-x-2 border-black border-t-2 border-b-2 min-h-[600px]">
        <div className="col-span-5 border-r-2 border-black flex flex-col">
          <div className="bg-gray-200 border-b-2 border-black p-2 text-center font-bold uppercase text-[10px] relative">
             <span>Rozsah objednané opravy</span>
             {isEditable && (
                <button type="button" onClick={onOpenTemplates} className="absolute right-2 top-1/2 -translate-y-1/2 p-1 bg-slate-900 text-white rounded no-print">
                   <ListPlus className="w-4 h-4" />
                </button>
             )}
          </div>
          <div className="flex-1 p-5 text-[12px] whitespace-pre-wrap italic font-medium underline decoration-gray-300 underline-offset-8">
            {isEditable ? <textarea className="w-full h-full bg-transparent outline-none resize-none border-none leading-relaxed italic" value={order.description || ''} onChange={(e) => onUpdateOrder?.('description', e.target.value)} placeholder="Popište opravu..." /> : (order.description || "Nebylo specifikováno.")}
          </div>
          <div className="p-5 pt-20 border-t border-black text-[10px] font-bold">
            <div className="flex justify-between mb-10"><span>Podpis objednatele: .................................................</span><span className="tracking-widest">X X X X X X X X</span></div>
            <div className="mt-10 mb-10">
              {isEditable ? (
                <div className="flex items-center gap-6">
                  <span className="text-[11px]">Vyměněné díly:</span>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <div className="w-5 h-5 border border-black flex items-center justify-center bg-white" onClick={() => onUpdateOrder?.('returnParts', 'vrátit')}>
                       {order.returnParts === 'vrátit' && <Check className="w-4 h-4 stroke-[4]" />}
                    </div>
                    <span className="text-[11px]">VRÁTIT</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <div className="w-5 h-5 border border-black flex items-center justify-center bg-white" onClick={() => onUpdateOrder?.('returnParts', 'nevracet')}>
                       {order.returnParts === 'nevracet' && <Check className="w-4 h-4 stroke-[4]" />}
                    </div>
                    <span className="text-[11px]">NEVRACET</span>
                  </label>
                </div>
              ) : (
                <div className="text-[11px]">Vyměněné díly: <span className="underline font-black">{order.returnParts === 'vrátit' ? 'VRÁTIT' : 'NEVRACET'}</span></div>
              )}
            </div>
            <div className="mt-10 pt-10 border-t border-dotted border-black/30"><p className="text-[12px] uppercase">Převzato zákazníkem dne: ............................ Podpis: ............................</p></div>
          </div>
        </div>
        <div className="col-span-5 flex flex-col relative">
          <div className="bg-gray-200 border-b-2 border-black p-2 flex items-center justify-center relative font-bold uppercase text-[10px]">
            <span>{company?.isVatPayer ? 'Materiál/Práce (vč. DPH)' : 'Materiál/Práce'}</span>
            {isEditable && (
              <div className="absolute right-2 flex gap-1.5 no-print">
                <button type="button" onClick={onOpenPriceList} className="p-1 bg-blue-600 text-white rounded"><Tag className="w-4 h-4" /></button>
                <button type="button" onClick={onAddPart} className="p-1 bg-emerald-600 text-white rounded"><Plus className="w-4 h-4" /></button>
              </div>
            )}
          </div>
          <div className="flex-1 relative">
             {/* Permanent vertical lines for the "red box" requirement */}
             <div className="absolute top-0 bottom-0 left-[calc(100%-252px)] w-[1.5px] bg-black"></div>
             <div className="absolute top-0 bottom-0 left-[calc(100%-212px)] w-[1.5px] bg-black"></div>
             <div className="absolute top-0 bottom-0 left-[calc(100%-112px)] w-[1.5px] bg-black"></div>

             <table className="w-full border-collapse text-[10px] relative z-10">
                <thead>
                  <tr className="border-b-2 border-black bg-slate-50">
                    <th className="p-2 px-3 text-left">Položka</th>
                    <th className="p-2 text-center w-[40px]">Mn.</th>
                    <th className="p-2 text-right w-[100px] whitespace-nowrap">{company?.isVatPayer ? 'Běžná cena' : 'Cena'}</th>
                    <th className="p-2 text-right w-[112px]">Celkem</th>
                    {isEditable && <th className="p-2 w-8 no-print"></th>}
                  </tr>
                </thead>
                <tbody className="font-bold">
                   {order.parts?.map((p) => (
                     <tr key={p.id} className="border-b border-gray-200">
                        <td className="p-2 px-3">{isEditable ? <input className="w-full bg-transparent outline-none" value={p.description} onChange={(e) => onUpdatePart?.(p.id, 'description', e.target.value)} /> : p.description}</td>
                        <td className="p-2 text-center">{isEditable ? <input type="number" className="w-full bg-transparent outline-none text-center" value={p.quantity} onChange={(e) => onUpdatePart?.(p.id, 'quantity', parseFloat(e.target.value) || 0)} /> : p.quantity}</td>
                        <td className="p-2 text-right">{isEditable ? <input type="number" className="w-full bg-transparent outline-none text-right" value={displayPrice(p.unitPrice)} onChange={(e) => handlePriceUpdate(p.id, 'unitPrice', e.target.value)} /> : displayPrice(p.unitPrice).toLocaleString()}</td>
                        <td className="p-2 text-right">{Math.round(p.quantity * displayPrice(p.unitPrice)).toLocaleString()}</td>
                        {isEditable && <td className="p-2 text-center no-print"><button onClick={() => onRemovePart?.(p.id)} className="text-red-400"><Trash2 className="w-4 h-4" /></button></td>}
                     </tr>
                   ))}
                   {isEditable && <tr className="no-print"><td colSpan={5} className="p-2 text-right border-t"><button onClick={() => document.getElementById('ai-parts-input')?.click()} className="text-[8px] text-purple-600 font-black px-3 py-1 flex items-center gap-1 ml-auto"><Sparkles className="w-3 h-3" /> AI SCAN DOKLADU</button><input id="ai-parts-input" type="file" className="hidden" onChange={onFileUpload} accept=".xlsx,.xls,.pdf" /></td></tr>}
                </tbody>
             </table>
          </div>
          <div className="mt-auto border-t-2 border-black flex flex-col bg-gray-50">
             <div className="flex justify-between p-2 border-b-2 border-black bg-white items-center">
                <div className="flex items-center gap-3">
                   <span className="text-[9px] uppercase font-bold text-slate-500">PRÁCE (HOD.):</span>
                   <span className="font-black text-[12px]">{order.laborHours || 0} h</span>
                   <span className="text-[9px] text-slate-400 font-normal ml-2">({displayPrice(hourlyRate)} Kč/h)</span>
                </div>
                <span className="font-bold text-[11px]">{Math.round((order.laborHours || 0) * displayPrice(hourlyRate)).toLocaleString()} Kč</span>
             </div>

             {company?.isVatPayer ? (
               <>
                 <div className="flex justify-between p-3 border-b-[1.5px] border-black font-bold bg-gray-100 text-[11px]"><span>SOUČET (BEZ DPH)</span><span>{Math.round(order.cost || 0).toLocaleString()} Kč</span></div>
                 <div className="flex justify-between p-3 border-b border-black text-[11px]"><span>DPH 21%</span><span>{Math.round((order.cost || 0) * 0.21).toLocaleString()} Kč</span></div>
                 <div className="flex flex-col p-5 bg-white min-h-[100px] justify-center border-b-2 border-black"><span className="text-[10px] font-bold uppercase text-slate-400 text-center">Cena opravy celkem (zaokrouhleno)</span><span className="text-[28px] font-black text-center mt-1">{Math.round((order.cost || 0) * 1.21).toLocaleString()} Kč</span></div>
               </>
             ) : (
               <div className="flex flex-col p-10 bg-white min-h-[140px] justify-center border-b-2 border-black">
                 <span className="text-[12px] font-black uppercase text-slate-400 text-center mb-1">CELKOVÁ CENA K ÚHRADĚ</span>
                 <span className="text-[34px] font-black text-center">{Math.round(order.cost || 0).toLocaleString()} Kč</span>
                 <span className="text-[9px] text-slate-300 font-bold uppercase text-center mt-4 tracking-widest">NEJSME PLÁTCI DPH</span>
               </div>
             )}
             <div className="p-3 h-16 bg-gray-100"></div>
          </div>
        </div>
      </div>
      <div className="mt-6 flex justify-between text-[9px] font-bold uppercase opacity-60"><span>71 00 033</span><span>{new Date().toLocaleDateString('cs-CZ')}</span><span>AUTOSERVICE PRO SYSTEM</span></div>
    </div>
  );
};

export default OrderManager;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2, ChevronRight, ChevronDown, ListPlus, Calculator, Layout,
  Paperclip, FilePlus, Image as ImageIcon, Loader2, Table, FileSearch, Sparkles
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask, Invoice, VehicleAttachment } from '../types';
import * as XLSX from 'xlsx';
import { analyzeExcelParts, analyzePdfParts } from '../services/geminiService';

interface OrderManagerProps {
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  invoices: Invoice[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  preselectedVehicleId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers,
  invoices,
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  preselectedVehicleId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);

  const [isAiImportOpen, setIsAiImportOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiImportItems, setAiImportItems] = useState<Partial<PartItem>[]>([]);
  const [selectedAiIndices, setSelectedAiIndices] = useState<Set<number>>(new Set());

  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '50%' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, bezp_klic: false,
      trojuhelnik: false, lekarna: false, lepeni: false
    } as VehicleChecklist,
    attachments: [] as VehicleAttachment[],
    returnParts: 'nevracet' as 'vrátit' | 'nevracet'
  });

  const materialCost = useMemo(() => {
    return formData.parts.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  const resetForm = (vId?: string) => {
    const selectedVeh = vId ? vehicles.find(v => v.id === vId) : null;
    setFormData({
      id: '',
      vehicleId: vId || '',
      description: '',
      parts: [] as PartItem[],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '50%',
      mileageAtEntry: selectedVeh ? selectedVeh.mileage : 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: [],
      returnParts: 'nevracet'
    });
  };

  const handleAddNew = (vId?: string) => {
    resetForm(vId);
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  useEffect(() => {
    if (autoOpen) {
      handleAddNew(preselectedVehicleId || undefined);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, preselectedVehicleId]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
        if (onModalOpened) onModalOpened();
      }
    }
  }, [initialOrderId, services]);

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '50%',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: order.attachments || [],
      returnParts: order.returnParts || 'nevracet'
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);

    const hasInvoice = invoices.some(inv => inv.orderId === finalId);
    if (serviceData.status === 'hotovo' && !hasInvoice) {
      setShowInvoicePrompt(finalId);
    }
    resetForm();
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...formData.parts, { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0, costPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: formData.parts.filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: formData.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const updateOrderField = (field: string, value: any) => {
    if (field === 'vehicleId') {
      const selectedVeh = vehicles.find(v => v.id === value);
      setFormData({
        ...formData,
        vehicleId: value,
        mileageAtEntry: selectedVeh ? selectedVeh.mileage : formData.mileageAtEntry
      });
    } else {
      setFormData({ ...formData, [field]: value });
    }
  };

  const addFromPriceList = (item: FixedService) => {
    const priceValue = item.price / 1.21;
    const costValue = (item.costPrice || 0) / 1.21;

    setFormData({
      ...formData,
      parts: [...formData.parts, { 
        id: Date.now().toString(), 
        description: item.name, 
        quantity: 1, 
        unit: 'ks', 
        unitPrice: priceValue,
        costPrice: costValue
      }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({ ...formData, description: `${currentDesc}${separator}${item.description}` });
    setIsTemplatePickerOpen(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const file = files[0];
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64Data = reader.result as string;
      if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls') || file.type === 'application/pdf') {
        setAiLoading(true);
        setIsAiImportOpen(true);
        try {
          let parts: Partial<PartItem>[] = [];
          if (file.type === 'application/pdf') {
            const splitted = base64Data.split(',');
            parts = await analyzePdfParts(splitted.length > 1 ? splitted[1] : splitted[0], companyInfo.isVatPayer);
          } else {
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer, { type: 'buffer' });
            const jsonData = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
            parts = await analyzeExcelParts(jsonData, companyInfo.isVatPayer);
          }
          setAiImportItems(parts);
          setSelectedAiIndices(new Set(parts.map((_, i) => i)));
        } catch (err) { alert("Chyba při analýze."); }
        finally { setAiLoading(false); }
      }
      const newAttachment: VehicleAttachment = { id: `att-${Date.now()}`, name: file.name, type: file.type, data: base64Data, size: file.size };
      setFormData(prev => ({ ...prev, attachments: [...prev.attachments, newAttachment] }));
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const relatedInvoice = invoices.find(inv => inv.orderId === order.id);
      if (relatedInvoice?.status === 'uhrazeno' && (order.status === 'hotovo' || order.status === 'zrušeno')) return false;
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      const owner = customers.find(c => c.id === vehicle?.customerId);
      if (!search) return true;
      return (order.id || "").toLowerCase().includes(search.toLowerCase()) ||
             (order.description || "").toLowerCase().includes(search.toLowerCase()) ||
             (vehicle?.licensePlate || "").toLowerCase().includes(search.toLowerCase()) ||
             (owner?.lastName || "").toLowerCase().includes(search.toLowerCase());
    });
  }, [services, vehicles, customers, invoices, search]);

  const columns = useMemo(() => ({
    waiting: filteredOrders.filter(o => o.status === 'naplánováno').sort((a, b) => a.date.localeCompare(b.date)),
    active: filteredOrders.filter(o => o.status === 'probíhá').sort((a, b) => a.date.localeCompare(b.date)),
    done: filteredOrders.filter(o => o.status === 'hotovo' || o.status === 'zrušeno').sort((a, b) => b.date.localeCompare(a.date)),
  }), [filteredOrders]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="hidden print:block">
        <PrintTemplate order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} company={companyInfo} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate} technicians={technicians} />
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Přehled zakázek</h2>
          <p className="text-slate-500 font-medium">Správa zakázkových listů a plánování.</p>
        </div>
        <button onClick={() => handleAddNew()} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg">
          <Plus className="w-5 h-5" /> Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input type="text" placeholder="Hledat zakázku (ID, SPZ, Zákazník)..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
        {search && (
          <button 
            onClick={() => onSearchChange('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12 print:hidden">
        <div className="space-y-6">
          <h3 className="text-sm font-black text-slate-600 uppercase tracking-widest px-2">K VYŘÍZENÍ</h3>
          <div className="space-y-4">
            {columns.waiting.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
          </div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-amber-700 uppercase tracking-widest px-2">PROBÍHÁ</h3>
          <div className="space-y-4">
            {columns.active.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
          </div>
        </div>
        <div className="space-y-6">
          <h3 className="text-sm font-black text-emerald-700 uppercase tracking-widest px-2">HOTOVO</h3>
          <div className="space-y-4">
            {columns.done.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
          </div>
        </div>
