             <table className="w-full border-collapse text-[10px] relative z-10">
                <thead>
                  <tr className="border-b-2 border-black bg-slate-50">
                    <th className="p-2 px-3 text-left">Položka</th>
                    <th className="p-2 text-center w-[40px]">Mn.</th>
                    <th className="p-2 text-right w-[100px] whitespace-nowrap">{company?.isVatPayer ? 'Běžná cena' : 'Cena'}</th>
                    <th className="p-2 text-right w-[112px]">Celkem</th>
                    {isEditable && <th className="p-2 w-8 no-print"></th>}
                  </tr>
                </thead>
                <tbody className="font-bold">
                   {(order.parts || []).map((p) => (
                     <tr key={p.id} className="border-b border-gray-200">
                        <td className="p-2 px-3">{isEditable ? <input className="w-full bg-transparent outline-none" value={p.description} onChange={(e) => onUpdatePart?.(p.id, 'description', e.target.value)} /> : p.description}</td>
                        <td className="p-2 text-center">{isEditable ? <input type="number" className="w-full bg-transparent outline-none text-center" value={p.quantity} onChange={(e) => onUpdatePart?.(p.id, 'quantity', parseFloat(e.target.value) || 0)} /> : p.quantity}</td>
                        <td className="p-2 text-right">{isEditable ? <input type="number" className="w-full bg-transparent outline-none text-right" value={displayPrice(p.unitPrice)} onChange={(e) => handlePriceUpdate(p.id, 'unitPrice', e.target.value)} /> : displayPrice(p.unitPrice).toLocaleString()}</td>
                        <td className="p-2 text-right">{Math.round(p.quantity * displayPrice(p.unitPrice)).toLocaleString()}</td>
                        {isEditable && <td className="p-2 text-center no-print"><button onClick={() => onRemovePart?.(p.id)} className="text-red-400"><Trash2 className="w-4 h-4" /></button></td>}
                     </tr>
                   ))}
                   {isEditable && <tr className="no-print"><td colSpan={5} className="p-2 text-right border-t"><button onClick={() => document.getElementById('ai-parts-input')?.click()} className="text-[8px] text-purple-600 font-black px-3 py-1 flex items-center gap-1 ml-auto"><Sparkles className="w-3 h-3" /> AI SCAN DOKLADU</button><input id="ai-parts-input" type="file" className="hidden" onChange={onFileUpload} accept=".xlsx,.xls,.pdf" /></td></tr>}
                </tbody>
             </table>
          </div>
          {/* Bottom Summary Area */}
          <div className="mt-auto border-t-2 border-black flex flex-col bg-gray-50">
             <div className="flex justify-between p-2 border-b-2 border-black bg-white items-center">
                <div className="flex items-center gap-3">
                   <span className="text-[9px] uppercase font-bold text-slate-500">PRÁCE (HOD.):</span>
                   {isEditable ? (
                     <div className="bg-blue-50/50 rounded border border-blue-100 px-2 flex items-center gap-1">
                       <input 
                         type="number" 
                         step="0.5"
                         className="bg-transparent outline-none font-black text-[12px] w-12 py-1 text-center" 
                         value={order.laborHours || 0} 
                         onChange={(e) => onUpdateOrder?.('laborHours', parseFloat(e.target.value) || 0)} 
                       />
                       <span className="text-[10px] font-black">h</span>
                     </div>
                   ) : (
                     <span className="font-black text-[12px]">{order.laborHours || 0} h</span>
                   )}
                   <span className="text-[9px] text-slate-400 font-normal ml-2">({displayPrice(hourlyRate)} Kč/h)</span>
                </div>
                <span className="font-bold text-[11px]">{Math.round((order.laborHours || 0) * displayPrice(hourlyRate)).toLocaleString()} Kč</span>
             </div>

             {company?.isVatPayer ? (
               <>
                 <div className="flex justify-between p-2 border-b-[1.5px] border-black font-bold bg-gray-100 text-[11px]"><span>SOUČET (BEZ DPH)</span><span>{Math.round(order.cost || 0).toLocaleString()} Kč</span></div>
                 <div className="flex justify-between p-2 border-b border-black text-[11px]"><span>DPH 21%</span><span>{Math.round((order.cost || 0) * 0.21).toLocaleString()} Kč</span></div>
                 <div className="flex flex-col p-4 bg-white min-h-[80px] justify-center border-b-2 border-black"><span className="text-[10px] font-bold uppercase text-slate-400 text-center">Cena opravy celkem (zaokrouhleno)</span><span className="text-[26px] font-black text-center mt-1">{Math.round((order.cost || 0) * 1.21).toLocaleString()} Kč</span></div>
               </>
             ) : (
               <div className="flex flex-col p-6 bg-white min-h-[100px] justify-center border-b-2 border-black">
                 <span className="text-[12px] font-black uppercase text-slate-400 text-center mb-1">CELKOVÁ CENA K ÚHRADĚ</span>
                 <span className="text-[32px] font-black text-center">{Math.round(order.cost || 0).toLocaleString()} Kč</span>
                 <span className="text-[9px] text-slate-300 font-bold uppercase text-center mt-3 tracking-widest">NEJSME PLÁTCI DPH</span>
               </div>
             )}
             <div className="p-2 h-10 bg-gray-100"></div>
          </div>
        </div>
      </div>
      <div className="mt-6 flex justify-between text-[9px] font-bold uppercase opacity-60"><span>71 00 033</span><span>{new Date().toLocaleDateString('cs-CZ')}</span><span>AUTOSERVICE PRO SYSTEM</span></div>
    </div>
  );
};

