              <TrendingUp className="w-8 h-8 text-slate-200" />
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-4 custom-scrollbar">
              {vehicleServices.length > 0 ? (
                vehicleServices.map((service) => (
