                    key={service.id} 
                    className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all group flex items-start justify-between cursor-pointer"
                    onClick={() => { onNavigateToOrder(service.id); setHistoryVehicle(null); }}
                  >
                    <div className="flex gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
                        {service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : <Wrench className="w-5 h-5" />}
                      </div>
                      <div>
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs font-black text-slate-900">#{service.id}</span>
                          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{formatDate(service.date)}</span>
                        </div>
                        <p className="text-sm font-bold text-slate-700 leading-snug mb-2">{service.description}</p>
                        <div className="flex items-center gap-4">
                           <div className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase">
                              <User className="w-3 h-3" /> {service.technician}
                           </div>
                           <div className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase">
                              <Gauge className="w-3 h-3" /> {service.mileageAtEntry?.toLocaleString() || '---'} km
                           </div>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-black text-slate-900">{(service.cost * 1.21).toLocaleString()} Kč</p>
                      <button className="text-[9px] font-black text-blue-600 uppercase tracking-widest mt-2 group-hover:underline flex items-center gap-1 ml-auto">
                        Detail <ChevronRight className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="py-20 text-center flex flex-col items-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                    <ClipboardList className="w-10 h-10 text-slate-200" />
                  </div>
                  <h4 className="text-lg font-black text-slate-900 mb-1">Žádná historie</h4>
                  <p className="text-sm font-bold text-slate-400 max-w-xs mx-auto">Pro toto vozidlo zatím nebyly v systému vytvořeny žádné servisní záznamy.</p>
                </div>
              )}
