                  <h3 className="text-xl font-black tracking-tight">{selectedVehicle.make} {selectedVehicle.model}</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">{selectedVehicle.licensePlate}</p>
                </div>
              </div>
              <button onClick={() => setSelectedVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar">
