          <p className="text-[8px] font-black uppercase mb-1">Objednatel / Zákazník</p>
          <div className="text-[12px] font-bold uppercase leading-snug">
            {customer?.customerType === 'firemní' ? (
              <>
                <span className="text-[13px] font-black">{customer?.companyName}</span><br />
                {customer?.companyAddress || customer?.address}<br />
                IČO: {customer?.ico} {customer?.dic ? `| DIČ: ${customer?.dic}` : ''}<br />
                <span className="text-[10px] font-medium opacity-70">Kontaktní osoba: {customer?.firstName} {customer?.lastName}</span>
              </>
            ) : (
              <>
                <span className="text-[13px] font-black">{customer?.firstName} {customer?.lastName}</span><br />
                {customer?.address}<br />
                Tel: {customer?.phone}
              </>
            )}
            <br />Tel: {customer?.phone}
          </div>
        </div>
        <div className="border-r-2 border-black p-4 min-h-[120px] bg-gray-50 flex flex-col">
          <p className="text-[8px] font-black uppercase mb-1">Opravna - DIČ</p>
          <div className="text-[12px] font-bold uppercase leading-snug">
            {company?.name}<br />{company?.address}<br />DIČ: {company?.dic}
          </div>
