        <div className="col-span-2 print:col-span-3 border-r border-black flex flex-col">
          {labels.map((item) => (
            <div key={item.key} className="flex items-center justify-between p-1.5 px-3 border-b border-black h-[28px]">
              <span>{item.label}</span>
              <div className="w-5 h-5 border border-black flex items-center justify-center bg-white cursor-pointer" onClick={() => isEditable && onUpdateOrder?.('checklist', { ...order.checklist, [item.key]: !order.checklist?.[item.key as keyof VehicleChecklist] })}>
