              <div key={att.id} className="flex items-center justify-between bg-slate-50 p-1.5 rounded border group">
                <div className="flex items-center gap-1 truncate max-w-[80px]"><span className="text-[9px] truncate">{att.name}</span></div>
                <div className="flex gap-1 no-print">
                  <button type="button" onClick={() => onOpenAttachment?.(att)} className="text-blue-500"><Eye className="w-3 h-3" /></button>
                  {isEditable && <button type="button" onClick={() => onDeleteAttachment?.(att.id)} className="text-red-400"><X className="w-3.5 h-3.5" /></button>}
                </div>
              </div>
            ))}
