        </div>

        <div className="col-span-3 print:col-span-4 border-r border-black flex flex-col">
          <div className="p-2 border-b border-black min-h-[44px] flex flex-col">
            <span className="text-[8px] uppercase opacity-50">VOZIDLO:</span>
            {isEditable ? (
              <div className="mt-1 flex flex-col gap-1">
                <div className="no-print flex items-center gap-1.5 bg-blue-50 px-2 py-1 rounded border border-blue-100 mb-1">
                   <Search className="w-3 h-3 text-blue-400" />
                   <input type="text" placeholder="Hledat..." className="bg-transparent border-none outline-none text-[9px] font-bold w-full" value={vehicleSearch} onChange={(e) => setVehicleSearch(e.target.value)} />
                </div>
                <select className="w-full bg-white border border-slate-200 outline-none font-bold text-[11px] p-1 rounded" value={order.vehicleId} onChange={(e) => onUpdateOrder?.('vehicleId', e.target.value)}>
                  <option value="">-- Vozidlo --</option>
                  {filteredVehicles.map(v => <option key={v.id} value={v.id}>{v.licensePlate}</option>)}
                </select>
              </div>
            ) : (
              <div className="mt-1"><p className="font-bold text-[11px] uppercase">{vehicle?.make} {vehicle?.model}</p></div>
            )}
          </div>
          <div className="p-2 border-b border-black flex-1">Kód: <span className="font-bold">{vehicle?.engineCode || '---'}</span></div>
          <div className="p-2 border-b border-black flex-1 flex items-center gap-1">
             <span>Stav km:</span>
             {isEditable ? (
               <div className="bg-blue-50/50 rounded border border-blue-100 px-2 flex items-center">
                 <input 
                   type="number" 
                   className="bg-transparent outline-none font-bold text-[11px] w-24 py-1" 
                   value={order.mileageAtEntry || 0} 
                   onChange={(e) => onUpdateOrder?.('mileageAtEntry', parseInt(e.target.value) || 0)} 
                 />
               </div>
             ) : (
               <span className="font-bold">{order.mileageAtEntry?.toLocaleString() || 0}</span>
             )}
          </div>
          <div className="p-2 border-b border-black flex-1 font-mono text-[11px] font-black">{vehicle?.licensePlate || '---'}</div>
          <div className="p-2 flex flex-col gap-1"><span className="text-[8px] uppercase opacity-50">PHM:</span>
             <div className="flex flex-wrap gap-x-2 gap-y-1">
                {fuelLevels.map(l => <span key={l} onClick={() => isEditable && onUpdateOrder?.('fuelLevel', l)} className={`cursor-pointer px-1 rounded text-[9px] border ${order.fuelLevel === l ? 'font-black bg-gray-900 text-white border-black' : 'text-slate-400 border-gray-100'}`}>{l}</span>)}
             </div>
          </div>
        </div>

        <div className="col-span-3 flex flex-col">
          <div className="p-2 border-b border-black flex-1">Předběžná cena zakázky: {isEditable ? <input type="number" className="bg-blue-50/50 outline-none font-bold text-[11px] w-24 px-1.5 rounded" value={order.estimatedPrice || 0} onChange={(e) => onUpdateOrder?.('estimatedPrice', parseInt(e.target.value) || 0)} /> : <span className="font-bold">{Math.round(order.estimatedPrice || 0).toLocaleString()} Kč</span>}</div>
          <div className="p-2 border-b border-black flex-1 flex items-center">Mechanik: {isEditable ? <select className="bg-blue-50/50 outline-none font-bold text-[11px] px-1.5 rounded" value={order.technician} onChange={(e) => onUpdateOrder?.('technician', e.target.value)}>{technicians.map(t => <option key={t} value={t}>{t}</option>)}</select> : <span className="font-bold ml-1">{order.technician}</span>}</div>
          <div className="p-2 border-b border-black flex-1">Objednáno: <span className="font-bold">{formatDate(order.date || '')}</span></div>
          <div className="p-2 border-b border-black flex-1 flex items-center">Dokončení: {isEditable ? <input type="date" className="bg-blue-50/50 outline-none font-bold text-[11px] px-1.5 rounded" value={order.deliveryDate || ''} onChange={(e) => onUpdateOrder?.('deliveryDate', e.target.value)} /> : <span className="font-bold">{formatDate(order.deliveryDate || '')}</span>}</div>
          <div className="p-2 flex-1 flex items-center gap-2">Stav: {isEditable ? <select className="bg-blue-50/50 outline-none font-bold text-[11px] px-1.5 rounded" value={order.status} onChange={(e) => onUpdateOrder?.('status', e.target.value as any)}><option value="naplánováno">Naplánováno</option><option value="probíhá">Probíhá</option><option value="hotovo">Hotovo</option></select> : <span className="font-black uppercase text-[9px]">{order.status}</span>}</div>
        </div>
      </div>

      <div className="grid grid-cols-10 border-x-2 border-black border-t-2 border-b-2 min-h-[740px]">
        <div className="col-span-5 border-r-2 border-black flex flex-col">
          <div className="bg-gray-200 border-b-2 border-black p-2 text-center font-bold uppercase text-[10px] relative">
             <span>Rozsah objednané opravy</span>
             {isEditable && (
                <button type="button" onClick={onOpenTemplates} className="absolute right-2 top-1/2 -translate-y-1/2 p-1 bg-slate-900 text-white rounded no-print">
                   <ListPlus className="w-4 h-4" />
                </button>
             )}
          </div>
          <div className="flex-1 p-5 text-[12px] whitespace-pre-wrap italic font-medium underline decoration-gray-300 underline-offset-8">
