              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingInvoice(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button 
                  onClick={() => { onDeleteInvoice(deletingInvoice.id); setDeletingInvoice(null); }}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm uppercase shadow-lg shadow-red-600/20"
                >
                  Smazat
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const InvoiceCard: React.FC<{
  inv: Invoice;
  customers: Customer[];
  today: string;
  onSelect: (inv: Invoice) => void;
  onDelete: (inv: Invoice) => void;
  onUpdateStatus: (id: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onArchive: (inv: Invoice) => void;
  openMenuId: string | null;
  onOpenMenu: (id: string | null) => void;
}> = ({ inv, customers, today, onSelect, onDelete, onUpdateStatus, onArchive, openMenuId, onOpenMenu }) => {
  const customer = customers.find(c => c.id === inv.customerId);
  const isOverdue = inv.status === 'neuhrazeno' && inv.dueDate < today;
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onOpenMenu(null);
      }
    };
    if (openMenuId === inv.id) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [openMenuId, inv.id, onOpenMenu]);

  return (
    <div className={`bg-white rounded-[2rem] border p-6 transition-all hover:shadow-xl group relative overflow-visible ${isOverdue ? 'border-red-200 bg-red-50/10' : 'border-slate-100'}`}>
      <div className="flex justify-between items-start mb-4">
        <div className="flex items-center gap-4">
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${inv.status === 'uhrazeno' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
            <Receipt className="w-6 h-6" />
          </div>
          <div>
            <h4 className="text-base font-black text-slate-900">{inv.id}</h4>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{formatDate(inv.issueDate)}</p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => onSelect(inv)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all">
            <Eye className="w-5 h-5" />
          </button>
          <div className="relative">
            <button 
              onClick={(e) => { e.stopPropagation(); onOpenMenu(openMenuId === inv.id ? null : inv.id); }}
              className={`p-2 rounded-xl transition-all ${openMenuId === inv.id ? 'bg-slate-100 text-slate-900 shadow-inner' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'}`}
            >
              <MoreHorizontal className="w-5 h-5" />
            </button>
            {openMenuId === inv.id && (
              <div 
                ref={menuRef}
                className="absolute top-10 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
              >
                <button 
                  onClick={(e) => { e.stopPropagation(); onUpdateStatus(inv.id, inv.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno'); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                >
                  {inv.status === 'uhrazeno' ? <XCircle className="w-4 h-4 text-amber-500" /> : <CheckCircle className="w-4 h-4 text-emerald-500" />}
                  {inv.status === 'uhrazeno' ? 'Neuhrazeno' : 'Uhrazeno'}
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); onArchive(inv); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"
                >
                  <Archive className="w-4 h-4" /> Archivovat
                </button>
                <div className="h-px bg-slate-100 my-1"></div>
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(inv); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                >
                  <Trash2 className="w-4 h-4" /> Smazat
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="space-y-2 mb-6">
        <p className="text-sm font-bold text-slate-700 truncate">
          {customer?.customerType === 'firemní' ? (customer?.companyName || `${customer?.firstName} ${customer?.lastName}`) : `${customer?.firstName} ${customer?.lastName}`}
        </p>
        <p className="text-[10px] font-bold text-blue-600 uppercase truncate">{inv.vehicleInfo}</p>
      </div>

      <div className="flex items-center justify-between pt-4 border-t border-slate-50">
        <div className="flex flex-col">
          <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Splatnost</span>
          <span className={`text-[11px] font-black ${isOverdue ? 'text-red-600' : 'text-slate-600'}`}>
            {formatDate(inv.dueDate)}
            {isOverdue && ' (PO SPLATNOSTI)'}
          </span>
        </div>
        <div className="text-right">
          <p className="text-lg font-black text-slate-900">{Math.round(inv.totalInclDph).toLocaleString()} Kč</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase">{inv.totalInclDph !== inv.totalExclDph ? 'včetně DPH' : ''}</p>
        </div>
      </div>
    </div>
  );
};

export const InvoicePrintTemplate: React.FC<{
  invoice: Invoice;
  company: CompanyInfo;
  customers: Customer[];
}> = ({ invoice, company, customers }) => {
  const customer = customers.find(c => c.id === invoice.customerId);
  const totalExclDph = invoice.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  const discountAmount = totalExclDph * ((invoice.discount || 0) / 100);
  const finalExclDph = totalExclDph - discountAmount;

  const isPayer = company.isVatPayer;
  const vatAmount = isPayer ? Math.round(finalExclDph * 0.21) : 0;
  const finalInclDph = isPayer ? Math.round(finalExclDph + vatAmount) : Math.round(finalExclDph);

  return (
    <div className="bg-white p-10 text-black font-sans print-block" style={{ width: '100%', maxWidth: '200mm', minHeight: '270mm', margin: '0 auto' }}>
      <div className="flex justify-between items-start border-b-2 border-black pb-8 mb-8">
        <div>
          <h1 className="text-4xl font-black uppercase tracking-tighter mb-2">Faktura</h1>
          <p className="text-xl font-bold">č. {invoice.id}</p>
        </div>
        <div className="text-right">
          <h2 className="text-2xl font-black">{company.name}</h2>
          <p className="text-sm font-medium">{company.address}</p>
          <p className="text-sm font-medium">IČO: {company.ico}{isPayer ? `, DIČ: ${company.dic}` : ''}</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-12 mb-12">
        <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Dodavatel</h3>
          <p className="text-lg font-black">{company.name}</p>
          <p className="text-sm font-medium">{company.address}</p>
          <div className="mt-4 grid grid-cols-2 gap-2 text-sm">
            <p><span className="font-bold">IČO:</span> {company.ico}</p>
            {isPayer && <p><span className="font-bold">DIČ:</span> {company.dic}</p>}
            <p className="col-span-2"><span className="font-bold">Tel:</span> {company.phone}</p>
            <p className="col-span-2"><span className="font-bold">Email:</span> {company.email}</p>
          </div>
          {!isPayer && <p className="text-[9px] font-black mt-2 uppercase text-slate-400 tracking-tighter">Dodavatel není plátcem DPH</p>}
        </div>
        <div className="p-6 border-2 border-slate-100 rounded-2xl">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Odběratel</h3>
          {customer?.customerType === 'firemní' ? (
            <>
              <p className="text-lg font-black">{customer?.companyName}</p>
              <p className="text-sm font-medium">{customer?.companyAddress || customer?.address}</p>
              <div className="mt-4 grid grid-cols-2 gap-2 text-sm">
                <p><span className="font-bold">IČO:</span> {customer?.ico || '---'}</p>
                <p><span className="font-bold">DIČ:</span> {customer?.dic || '---'}</p>
              </div>
            </>
          ) : (
            <>
              <p className="text-lg font-black">{customer?.firstName} {customer?.lastName}</p>
              <p className="text-sm font-medium">{customer?.address}</p>
              <div className="mt-4 text-sm">
                <p><span className="font-bold">Tel:</span> {customer?.phone}</p>
                <p><span className="font-bold">Email:</span> {customer?.email || '---'}</p>
              </div>
            </>
          )}
        </div>
      </div>

      <div className="grid grid-cols-3 gap-6 mb-12 border-y border-slate-100 py-6">
        <div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Datum vystavení</p>
          <p className="text-base font-bold">{formatDate(invoice.issueDate)}</p>
        </div>
        <div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Datum splatnosti</p>
          <p className="text-base font-bold">{formatDate(invoice.dueDate)}</p>
        </div>
        <div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Způsob úhrady</p>
          <p className="text-base font-bold">{invoice.paymentType}</p>
        </div>
      </div>

      <div className="mb-12">
        <table className="w-full text-left">
          <thead>
            <tr className="border-b-2 border-black text-[10px] font-black uppercase tracking-widest">
              <th className="py-4">Popis položky</th>
              <th className="py-4 text-center">Množství</th>
              <th className="py-4 text-right">Jedn. cena</th>
              <th className="py-4 text-right">Celkem</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {invoice.items.map((item, idx) => {
               return (
                <tr key={idx} className="text-base">
                  <td className="py-4 font-bold">{item.description}</td>
                  <td className="py-4 text-center">{item.quantity} {item.unit || 'ks'}</td>
                  <td className="py-4 text-right">{Math.round(item.unitPrice).toLocaleString()} Kč</td>
                  <td className="py-4 text-right font-black">{Math.round(item.quantity * item.unitPrice).toLocaleString()} Kč</td>
                </tr>
               );
            })}
          </tbody>
        </table>
      </div>

      <div className="ml-auto w-80 space-y-4">
        <div className="flex justify-between text-base">
          <span className="text-slate-500">{isPayer ? 'Základ celkem:' : 'Mezisoučet:'}</span>
          <span className="font-bold">{Math.round(finalExclDph).toLocaleString()} Kč</span>
        </div>
        {invoice.discount && invoice.discount > 0 && (
          <div className="flex justify-between text-base text-blue-600 font-bold">
            <span>Sleva {invoice.discount}%:</span>
            <span>-{Math.round(discountAmount).toLocaleString()} Kč</span>
          </div>
        )}
        {isPayer && (
          <div className="flex justify-between text-base">
            <span className="text-slate-500">DPH 21%:</span>
            <span className="font-bold">{Math.round(vatAmount).toLocaleString()} Kč</span>
          </div>
        )}
        <div className="flex justify-between items-center pt-4 border-t-2 border-black">
          <span className="text-lg font-black uppercase">Celkem k úhradě</span>
          <div className="text-right">
            <p className="text-3xl font-black">{Math.round(finalInclDph).toLocaleString()} Kč</p>
          </div>
        </div>
      </div>

      <div className="mt-auto pt-24 flex justify-between items-end opacity-50">
        <div className="text-[11px] font-bold uppercase tracking-widest">
          <p>Děkujeme za projevenou důvěru.</p>
          <p>Faktura byla vystavena v systému AutoService Pro.</p>
        </div>
        <div className="text-center">
          <div className="w-48 h-24 border-b-2 border-dotted border-black mb-2"></div>
          <p className="text-[11px] font-black uppercase">Razítko a podpis</p>
        </div>
      </div>
    </div>
  );
};

