        <div className="p-4 border-r-2 border-black">
          <p className="text-[10px] font-bold uppercase mb-1">DODAVATEL:</p>
          <div className="text-[12px] leading-tight">
            <p className="font-black text-[14px]">{company.name}</p>
            <p>{company.address}</p>
            <p className="mt-2 font-bold">IČ: {company.ico} {isPayer && `DIČ: ${company.dic}`}</p>
            <p className="mt-1 font-bold italic">Banka: {company.bankAccount || '---'}</p>
          </div>
        </div>
        <div className="p-4 flex flex-col justify-start">
          <h1 className="text-[18px] font-black uppercase mb-4 tracking-tighter">FAKTURA - DAŇOVÝ DOKLAD č.</h1>
          <p className="text-[24px] font-black text-right pr-4">{invoice.id}</p>
        </div>
      </div>

      {/* Odběratel */}
      <div className="border-b-2 border-black p-4 bg-gray-50/30">
        <p className="text-[10px] font-bold uppercase mb-1">ODBĚRATEL:</p>
        <div className="text-[12px] leading-tight ml-4">
          {customer?.customerType === 'firemní' ? (
            <>
              <p className="font-black text-[15px] uppercase">{customer?.companyName}</p>
              <p>{customer?.companyAddress || customer?.address}</p>
              <p className="mt-2 font-bold">IČ: {customer?.ico || '---'} {customer?.dic && `DIČ: ${customer?.dic}`}</p>
            </>
          ) : (
            <>
              <p className="font-black text-[15px] uppercase">{customer?.firstName} {customer?.lastName}</p>
              <p>{customer?.address}</p>
              <p className="mt-2 font-bold">Tel: {customer?.phone}</p>
            </>
          )}
        </div>
      </div>

      {/* Platební a servisní termíny */}
      <div className="grid grid-cols-5 text-[9px] border-b-2 border-black font-bold uppercase bg-gray-100">
        <div className="p-2 border-r-2 border-black text-center">Převzetí do opravy<br /><span className="text-[11px] mt-1 block">{formatDate(order?.date || invoice.issueDate)}</span></div>
        <div className="p-2 border-r-2 border-black text-center">Ukončení opravy<br /><span className="text-[11px] mt-1 block">{formatDate(order?.deliveryDate || invoice.issueDate)}</span></div>
        <div className="p-2 border-r-2 border-black text-center">Datum zdanitel. plnění<br /><span className="text-[11px] mt-1 block">{formatDate(invoice.issueDate)}</span></div>
