      </div>

      {/* Tabulka položek s dotáhnutými vertikálními čarami */}
      <div className="relative border-b-2 border-black" style={{ minHeight: '600px' }}>
        {/* Vertikální dělící čáry fixní pozice */}
        <div className="absolute top-0 bottom-0 left-[70px] w-[1.5px] bg-black"></div>
        <div className="absolute top-0 bottom-0 left-[calc(100%-240px)] w-[1.5px] bg-black"></div>
        <div className="absolute top-0 bottom-0 left-[calc(100%-120px)] w-[1.5px] bg-black"></div>

        <table className="w-full border-collapse relative z-10">
          <thead>
            <tr className="border-b-2 border-black text-[10px] font-black uppercase bg-gray-50 h-10">
