            ))}
            {/* Vyplnění prázdných řádků pro dotáhnutí gridu */}
            {Array.from({ length: emptyRowsCount }).map((_, i) => (
              <tr key={`empty-${i}`} className="border-b border-gray-100 h-8">
                <td></td>
                <td></td>
                <td></td>
                <td></td>
