            <div className="h-px w-full bg-black/10 my-2"></div>
            <p className="text-[10px] font-bold italic opacity-60 text-center">Tato částka zahrnuje DPH v zákonné výši.</p>
          </div>
        </div>
      </div>

      {/* Patička */}
      <div className="mt-4 pt-4 border-t border-dotted border-gray-400 text-[10px] leading-tight opacity-80 italic">
        <p>Registrace u živ. Úřadu v Ústí nad Labem pod č.j. 01/0729Bal. Ze dne {formatDate(company.foundationDate || '2001-02-07')}</p>
        <p>Likvidace odpadů byla provedena v souladu se zákonem č. 12/1977 Sb. o odpadech a pozdějších předpisů.</p>
        <div className="flex justify-between mt-12 mb-4">
          <div className="w-64 border-t border-black pt-2">
            <p className="font-bold uppercase text-[9px] text-center">Podpis a razítko odběratele</p>
          </div>
          <div className="text-center w-72 border-t-2 border-black pt-2">
            <p className="font-black uppercase text-[10px]">Razítko a podpis dodavatele</p>
          </div>
        </div>
      </div>
    </div>
  );
};

