                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kilometry</label>
                    <select 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                      value={formData.serviceIntervalKm || 15000}
                      onChange={e => setFormData({...formData, serviceIntervalKm: parseInt(e.target.value)})}
                    >
                      {[5000, 10000, 15000, 20000, 25000, 30000].map(km => (
                        <option key={km} value={km}>{km.toLocaleString()} km</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Časový (roky)</label>
                    <select 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                      value={formData.serviceIntervalMonths || 12}
                      onChange={e => setFormData({...formData, serviceIntervalMonths: parseInt(e.target.value)})}
                    >
                      {[12, 24, 36].map(m => (
                        <option key={m} value={m}>{m / 12} {m / 12 === 1 ? 'rok' : (m / 12 < 5 ? 'roky' : 'let')}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Barva vozidla</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                  value={formData.color || ''}
                  onChange={e => setFormData({...formData, color: e.target.value})}
                  placeholder="Např. Modrá Race, Černá perleť..."
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník / Zákazník</label>
                <select 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                  value={formData.customerId || ''}
                  onChange={e => setFormData({...formData, customerId: e.target.value})}
                >
                  {customers.map(c => (
                    <option key={c.id} value={c.id}>{c.companyName || `${c.lastName} ${c.firstName}`}</option>
                  ))}
                </select>
              </div>

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4"
              >
                <Check className="w-5 h-5" />
                {editingVehicle ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL HISTORIE OPRAV */}
      {historyVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setHistoryVehicle(null)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-blue-500/20 flex items-center justify-center border border-white/10">
                  <HistoryIcon className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">Historie oprav</h3>
                  <p className="text-blue-100 text-[10px] font-black uppercase tracking-widest mt-1">
                    {historyVehicle.make} {historyVehicle.model} ({historyVehicle.licensePlate?.toUpperCase()})
                  </p>
                </div>
              </div>
              <button onClick={() => setHistoryVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="bg-slate-50 px-8 py-4 border-b border-slate-200 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-6">
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase">Počet zakázek</p>
                  <p className="text-lg font-black text-slate-900">{vehicleServices.length}</p>
                </div>
                <div className="w-px h-8 bg-slate-200"></div>
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase">Celkem investováno</p>
                  <p className="text-lg font-black text-blue-600">{totalSpentOnVehicle.toLocaleString()} Kč <span className="text-[10px] font-bold text-slate-400">vč. DPH</span></p>
                </div>
              </div>
              <TrendingUp className="w-8 h-8 text-slate-200" />
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-4 custom-scrollbar">
              {vehicleServices.length > 0 ? (
                vehicleServices.map((service) => (
                  <div 
                    key={service.id} 
                    className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all group flex items-start justify-between cursor-pointer"
                    onClick={() => { onNavigateToOrder(service.id); setHistoryVehicle(null); }}
                  >
                    <div className="flex gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
                        {service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : <Wrench className="w-5 h-5" />}
                      </div>
                      <div>
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs font-black text-slate-900">#{service.id}</span>
                          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{formatDate(service.date)}</span>
                        </div>
                        <p className="text-sm font-bold text-slate-700 leading-snug mb-2">{service.description}</p>
                        <div className="flex items-center gap-4">
                           <div className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase">
                              <User className="w-3 h-3" /> {service.technician}
                           </div>
                           <div className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase">
                              <Gauge className="w-3 h-3" /> {service.mileageAtEntry?.toLocaleString() || '---'} km
                           </div>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-black text-slate-900">{(service.cost * 1.21).toLocaleString()} Kč</p>
                      <button className="text-[9px] font-black text-blue-600 uppercase tracking-widest mt-2 group-hover:underline flex items-center gap-1 ml-auto">
                        Detail <ChevronRight className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="py-20 text-center flex flex-col items-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                    <ClipboardList className="w-10 h-10 text-slate-200" />
                  </div>
                  <h4 className="text-lg font-black text-slate-900 mb-1">Žádná historie</h4>
                  <p className="text-sm font-bold text-slate-400 max-w-xs mx-auto">Pro toto vozidlo zatím nebyly v systému vytvořeny žádné servisní záznamy.</p>
                </div>
              )}
            </div>

            <div className="p-8 border-t border-slate-50 bg-white shrink-0">
              <button 
                onClick={() => setHistoryVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all hover:bg-slate-800"
              >
                ZAVŘÍT HISTORII
              </button>
            </div>
          </div>
        </div>
      )}

      {selectedVehicle && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-slate-700 flex items-center justify-center font-black">
                  <Car className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">{selectedVehicle.make} {selectedVehicle.model}</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">{selectedVehicle.licensePlate?.toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Info className="w-3 h-3" /> Základní informace
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Značka a model</span>
                    <span className="text-sm font-black text-slate-900">{selectedVehicle.make} {selectedVehicle.model}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Rok výroby</span>
                    <span className="text-sm font-black text-slate-900">{selectedVehicle.year}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Registrační značka</span>
                    <span className="text-sm font-black text-blue-600 font-mono tracking-wider">{selectedVehicle.licensePlate?.toUpperCase()}</span>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Layers className="w-3 h-3" /> Technické parametry
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  <div className="flex flex-col gap-1 p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">VIN kód</span>
                    <span className="text-sm font-mono font-bold text-slate-900 break-all uppercase">{selectedVehicle.vin?.toUpperCase() || 'Neuvedeno'}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Aktuální nájezd</span>
                    <span className="text-sm font-black text-slate-900">{(selectedVehicle.mileage || 0).toLocaleString()} km</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Kód motoru</span>
                    <span className="text-sm font-black text-slate-900 uppercase">{selectedVehicle.engineCode?.toUpperCase() || 'Neuvedeno'}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Barva</span>
                    <div className="flex items-center gap-2">
                      <Palette className="w-3 h-3 text-slate-300" />
                      <span className="text-sm font-bold text-slate-900">{selectedVehicle.color || 'Neuvedeno'}</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Calendar className="w-3 h-3" /> Termíny a intervaly
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Platnost STK</span>
                    <span className={`text-sm font-black ${
                      (selectedVehicle.stkExpirationDate && new Date(selectedVehicle.stkExpirationDate) < new Date()) ? 'text-red-600' : 'text-slate-900'
                    }`}>
                      {formatDate(selectedVehicle.stkExpirationDate)}
                    </span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Příští servis</span>
                    <span className="text-sm font-black text-slate-900">{formatDate(selectedVehicle.nextServiceDate)}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Servisní interval</span>
                    <span className="text-sm font-black text-slate-900">
                      {(selectedVehicle.serviceIntervalKm || 15000).toLocaleString()} km / {(selectedVehicle.serviceIntervalMonths || 12) / 12} rok(y)
                    </span>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                  <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] flex items-center gap-2">
                    <Paperclip className="w-3 h-3" /> Přílohy a dokumentace
                  </h4>
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-all text-[9px] font-black uppercase tracking-widest"
                  >
                    <FilePlus className="w-3 h-3" /> Přidat soubor
                  </button>
                  <input 
                    type="file" 
                    className="hidden" 
                    ref={fileInputRef} 
                    onChange={handleFileUpload} 
                    accept="image/*,.pdf"
                  />
                </div>

                <div className="space-y-2">
                  {selectedVehicle.attachments && selectedVehicle.attachments.length > 0 ? (
                    selectedVehicle.attachments.map(att => (
                      <div key={att.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl group hover:bg-white hover:shadow-md transition-all border border-transparent hover:border-slate-100">
                        <div className="flex items-center gap-3 min-w-0">
                          <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${att.type.includes('pdf') ? 'bg-red-50 text-red-500' : 'bg-blue-50 text-blue-500'}`}>
                            {att.type.includes('pdf') ? <FileText className="w-5 h-5" /> : <ImageIcon className="w-5 h-5" />}
                          </div>
                          <div className="min-w-0">
                            <p className="text-xs font-bold text-slate-900 truncate pr-2">{att.name}</p>
                            <p className="text-[8px] font-black text-slate-400 uppercase">{(att.size / 1024).toFixed(1)} KB</p>
                          </div>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => openAttachment(att)}
                            className="p-2 text-slate-400 hover:text-blue-600 transition-colors"
                            title="Zobrazit"
                          >
                            <Eye className="w-4 h-4" />
                          </button>
                          <button 
                            onClick={() => handleDeleteAttachment(att.id)}
                            className="p-2 text-slate-400 hover:text-red-600 transition-colors"
                            title="Smazat"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="py-8 text-center bg-slate-50/50 rounded-xl border border-dashed border-slate-200">
                      <p className="text-[10px] font-bold text-slate-400 italic">Žádné nahrané dokumenty.</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <User className="w-3 h-3" /> Vlastnictví
                </h4>

                <div className="p-3 bg-slate-50 rounded-xl">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-tight mb-1">Registrovaný vlastník</p>
                  <p 
                    className="text-sm font-black text-blue-600 cursor-pointer hover:underline flex items-center gap-2"
                    onClick={() => { onNavigateToCustomer(selectedVehicle.customerId); setSelectedVehicle(null); }}
                  >
                    {customers.find(c => c.id === selectedVehicle.customerId)?.companyName || 
                     `${customers.find(c => c.id === selectedVehicle.customerId)?.lastName || ''} ${customers.find(c => c.id === selectedVehicle.customerId)?.firstName || ''}`}
                    <ChevronRight className="w-4 h-4" />
                  </p>
                </div>
              </div>
            </div>

            <div className="p-8 border-t border-slate-50 bg-white shrink-0">
              <button 
                onClick={() => setSelectedVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all hover:bg-slate-800 shadow-xl shadow-slate-900/10"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL PRO SMAZÁNÍ VOZIDLA */}
      {deletingVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat vozidlo <span className="font-bold text-slate-900">{deletingVehicle.make} {deletingVehicle.model} ({deletingVehicle.licensePlate?.toUpperCase()})</span>? Tato akce je nevratná a dojde k odstranění všech příloh.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingVehicle(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={handleDeleteConfirm}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-lg shadow-red-600/20"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

export interface PartItem {
  id: string;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
  costPrice?: number; // Nákupní cena (základ daně)
}

export interface FixedService {
  id: string;
  name: string;
  price: number;
  costPrice?: number; // Nákupní cena vč. DPH (zadává se v nastavení)
  unit?: string; // Měrná jednotka
}

export interface PredefinedTask {
  id: string;
  label: string;
  description: string;
}

export interface Invoice {
  id: string;
  orderId: string;
  issueDate: string;
  dueDate: string;
  customerId: string;
  vehicleInfo: string;
  items: PartItem[];
  totalExclDph: number;
  totalInclDph: number;
  costs?: number; // Pořizovací náklady pro výpočet zisku
  paymentType: 'Hotově' | 'Převodem';
  status: 'uhrazeno' | 'neuhrazeno';
  discount?: number;
  archived?: boolean;
}

export interface Customer {
  id: string;
  customerType: 'soukromý' | 'firemní';
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  address: string;
  createdAt: string;
  // Firemní údaje
  companyName?: string;
  companyAddress?: string;
  ico?: string;
  dic?: string;
  contactPerson?: string;
}

export interface VehicleAttachment {
  id: string;
  name: string;
  type: string;
  data: string; // Base64 string
  size: number;
}

export interface Vehicle {
  id: string;
  customerId: string;
  make: string;
  model: string;
  year: number;
  vin: string;
  licensePlate: string;
  mileage: number;
  engineCode: string;
  color: string;
  lastServiceDate: string;
  stkExpirationDate: string;
  nextServiceDate: string;
  serviceIntervalKm?: number;
  serviceIntervalMonths?: number;
  notes?: string;
  attachments?: VehicleAttachment[];
}

export interface VehicleChecklist {
  rezerva: boolean;
  zvedak: boolean;
  klic: boolean;
  bezp_klic: boolean;
  trojuhelnik: boolean;
  lekarna: boolean;
  lepeni: boolean;
}

export interface ServiceRecord {
  id: string;
  vehicleId: string;
  date: string;
  endDate?: string;
  deliveryDate?: string;
  description: string;
  parts?: PartItem[];
  laborHours?: number;
  cost: number;
  status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno';
  technician: string;
  fuelLevel?: string;
  checklist?: VehicleChecklist;
  mileageAtEntry?: number;
  estimatedPrice?: number;
  paymentType?: 'Hotovost' | 'Faktura' | 'Pojišťovna';
  attachments?: VehicleAttachment[];
  returnParts?: 'vrátit' | 'nevracet';
}

export interface CompanyInfo {
  name: string;
  address: string;
  ico: string;
  dic: string;
  phone: string;
  email: string;
  bankAccount?: string;
  isVatPayer: boolean;
  foundationDate?: string; // Datum vzniku/registrace u ŽÚ
}

export interface NotificationSettings {
  stkThresholdDays: number;
  serviceThresholdDays: number;
}

export interface AutoBackupSettings {
  enabled: boolean;
  hour: number;
  lastBackupDate: string | null;
  folderName: string | null;
}

export interface UserSettings {
  enabled: boolean;
  username: string;
  password: string;
}

export type AppView = 'dashboard' | 'customers' | 'vehicles' | 'orders' | 'settings' | 'invoices' | 'archive' | 'stats';

// Add missing types for Gemini-related components
export enum Role {
  USER = 'user',
  MODEL = 'model',
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  metadata?: {
    sources?: Array<{ uri: string; title: string }>;
  };
}

export interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
}

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock, ShieldCheck, ShieldAlert, CreditCard
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice, VehicleAttachment, VehicleChecklist } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const UNITS = ['ks', 'litr', 'gram', 'kg', 'm', 'sada'];

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, invoices, onRestoreData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
  userSettings, onUserSettingsChange
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const esc = (str: any) => {
    if (str === undefined || str === null) return '';
    return String(str).replace(/[<>&"']/g, (c) => {
      switch (c) {
        case '<': return '&lt;';
        case '>': return '&gt;';
        case '&': return '&amp;';
        case '"': return '&quot;';
        case "'": return '&apos;';
        default: return c;
      }
    });
  };

  const xmlTag = (name: string, value: any, indent: string = '    ') => {
    return `${indent}<${name}>${esc(value)}</${name}>\n`;
  };

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="3.0">\n`;

    // 1. FIREMNÍ ÚDAJE
    xml += `  <CompanyInfo>\n`;
    xml += xmlTag('Name', companyInfo?.name || '');
    xml += xmlTag('Address', companyInfo?.address || '');
    xml += xmlTag('ICO', companyInfo?.ico || '');
    xml += xmlTag('DIC', companyInfo?.dic || '');
    xml += xmlTag('Phone', companyInfo?.phone || '');
    xml += xmlTag('Email', companyInfo?.email || '');
    xml += xmlTag('BankAccount', companyInfo?.bankAccount || '');
    xml += xmlTag('IsVatPayer', !!companyInfo?.isVatPayer);
    xml += xmlTag('FoundationDate', companyInfo?.foundationDate || '');
    xml += `  </CompanyInfo>\n`;

    // 2. ZÁKAZNÍCI
    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${esc(c.id)}">\n`;
      xml += xmlTag('CustomerType', c.customerType || 'soukromý');
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.companyAddress) xml += xmlTag('CompanyAddress', c.companyAddress);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      if (c.contactPerson) xml += xmlTag('ContactPerson', c.contactPerson);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    // 3. VOZIDLA
    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${esc(v.id)}" customerId="${esc(v.customerId)}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color || '');
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      if (v.notes) xml += xmlTag('Notes', v.notes);

      if (v.attachments && v.attachments.length > 0) {
        xml += `      <Attachments>\n`;
        v.attachments.forEach(att => {
          xml += `        <Attachment id="${esc(att.id)}">\n`;
          xml += xmlTag('Name', att.name, '          ');
          xml += xmlTag('Type', att.type, '          ');
          xml += xmlTag('Data', att.data, '          ');
          xml += xmlTag('Size', att.size, '          ');
          xml += `        </Attachment>\n`;
        });
        xml += `      </Attachments>\n`;
      }
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    // 4. ZAKÁZKOVÉ LISTY
    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${esc(s.id)}" vehicleId="${esc(s.vehicleId)}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('EndDate', s.endDate || '');
      xml += xmlTag('DeliveryDate', s.deliveryDate || '');
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours || 0);
      xml += xmlTag('FuelLevel', s.fuelLevel || '50%');
      xml += xmlTag('MileageAtEntry', s.mileageAtEntry || 0);
      xml += xmlTag('EstimatedPrice', s.estimatedPrice || 0);
      xml += xmlTag('PaymentType', s.paymentType || 'Hotovost');
      xml += xmlTag('ReturnParts', s.returnParts || 'nevracet');

      if (s.checklist) {
        xml += `      <Checklist>\n`;
        Object.entries(s.checklist).forEach(([k, v]) => {
          xml += `        <${k}>${v}</${k}>\n`;
        });
        xml += `      </Checklist>\n`;
      }

      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${esc(p.id)}">\n`;
          xml += xmlTag('Description', p.description, '          ');
          xml += xmlTag('Quantity', p.quantity, '          ');
          xml += xmlTag('UnitPrice', p.unitPrice, '          ');
          xml += xmlTag('CostPrice', p.costPrice || 0, '          ');
          xml += xmlTag('Unit', p.unit || 'ks', '          ');
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }

      if (s.attachments && s.attachments.length > 0) {
        xml += `      <Attachments>\n`;
        s.attachments.forEach(att => {
          xml += `        <Attachment id="${esc(att.id)}">\n`;
          xml += xmlTag('Name', att.name, '          ');
          xml += xmlTag('Type', att.type, '          ');
          xml += xmlTag('Data', att.data, '          ');
          xml += xmlTag('Size', att.size, '          ');
          xml += `        </Attachment>\n`;
        });
        xml += `      </Attachments>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    // 5. FAKTURY
    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${esc(inv.id)}" orderId="${esc(inv.orderId)}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalExclDph', inv.totalExclDph);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Costs', inv.costs || 0);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += xmlTag('Discount', inv.discount || 0);
      xml += xmlTag('Archived', !!inv.archived);

      if (inv.items && inv.items.length > 0) {
        xml += `      <Items>\n`;
        inv.items.forEach(item => {
          xml += `        <Item id="${esc(item.id)}">\n`;
          xml += xmlTag('Description', item.description, '          ');
          xml += xmlTag('Quantity', item.quantity, '          ');
          xmlTag('Unit', item.unit || 'ks', '          ');
          xml += xmlTag('UnitPrice', item.unitPrice, '          ');
          xml += xmlTag('CostPrice', item.costPrice || 0, '          ');
          xml += `        </Item>\n`;
        });
        xml += `      </Items>\n`;
      }
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    // 6. SYSTÉMOVÉ NASTAVENÍ
    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${esc(fs.id)}">\n`;
      xml += xmlTag('Name', fs.name, '        ');
      xml += xmlTag('Price', fs.price, '        ');
      xml += xmlTag('CostPrice', fs.costPrice || 0, '        ');
      xml += xmlTag('Unit', fs.unit || 'ks', '        ');
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${esc(pt.id)}">\n`;
      xml += xmlTag('Label', pt.label, '        ');
      xml += xmlTag('Description', pt.description, '        ');
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${esc(t)}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;

    xml += `    <NotificationSettings>\n`;
    xml += xmlTag('StkThresholdDays', notifSettings.stkThresholdDays, '      ');
    xml += xmlTag('ServiceThresholdDays', notifSettings.serviceThresholdDays, '      ');
    xml += `    </NotificationSettings>\n`;

    xml += `    <UserSettings>\n`;
    xml += xmlTag('Enabled', userSettings.enabled, '      ');
    xml += xmlTag('Username', userSettings.username, '      ');
    xml += xmlTag('Password', userSettings.password, '      ');
    xml += `    </UserSettings>\n`;

    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_full_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { 
      console.error("Backup failed:", err);
      setBackupStatus('error'); 
    }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const parseError = xmlDoc.getElementsByTagName("parsererror");
        if (parseError.length > 0) throw new Error("Chyba při parsování XML souboru.");

        const getAttachments = (node: Element) => {
          return Array.from(node.querySelectorAll("Attachment")).map(att => ({
            id: att.getAttribute("id") || `att-${Math.random()}`,
            name: att.querySelector("Name")?.textContent || '',
            type: att.querySelector("Type")?.textContent || '',
            data: att.querySelector("Data")?.textContent || '',
            size: parseInt(att.querySelector("Size")?.textContent || "0")
          }));
        };

        const companyNode = xmlDoc.querySelector("CompanyInfo");
        const importedCompany: Partial<CompanyInfo> = companyNode ? {
          name: companyNode.querySelector("Name")?.textContent || '',
          address: companyNode.querySelector("Address")?.textContent || '',
          ico: companyNode.querySelector("ICO")?.textContent || '',
          dic: companyNode.querySelector("DIC")?.textContent || '',
          phone: companyNode.querySelector("Phone")?.textContent || '',
          email: companyNode.querySelector("Email")?.textContent || '',
          bankAccount: companyNode.querySelector("BankAccount")?.textContent || '',
          isVatPayer: companyNode.querySelector("IsVatPayer")?.textContent === 'true',
          foundationDate: companyNode.querySelector("FoundationDate")?.textContent || ''
        } : {};

        const importedData: any = {
          companyInfo: importedCompany,
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id") || `c-${Math.random()}`,
            customerType: node.querySelector("CustomerType")?.textContent || 'soukromý',
            firstName: node.querySelector("FirstName")?.textContent || '',
            lastName: node.querySelector("LastName")?.textContent || '',
            email: node.querySelector("Email")?.textContent || '',
            phone: node.querySelector("Phone")?.textContent || '',
            address: node.querySelector("Address")?.textContent || '',
            createdAt: node.querySelector("CreatedAt")?.textContent || '',
            companyName: node.querySelector("CompanyName")?.textContent || undefined,
            companyAddress: node.querySelector("CompanyAddress")?.textContent || undefined,
            ico: node.querySelector("ICO")?.textContent || undefined,
            dic: node.querySelector("DIC")?.textContent || undefined,
            contactPerson: node.querySelector("ContactPerson")?.textContent || undefined,
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id") || `v-${Math.random()}`,
            customerId: node.getAttribute("customerId") || '',
            make: node.querySelector("Make")?.textContent || '',
            model: node.querySelector("Model")?.textContent || '',
            year: parseInt(node.querySelector("Year")?.textContent || "0"),
            vin: node.querySelector("VIN")?.textContent || '',
            licensePlate: node.querySelector("LicensePlate")?.textContent || '',
            mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
            engineCode: node.querySelector("EngineCode")?.textContent || '',
            color: node.querySelector("Color")?.textContent || '',
            stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent || '',
            nextServiceDate: node.querySelector("NextServiceDate")?.textContent || '',
            notes: node.querySelector("Notes")?.textContent || undefined,
            attachments: getAttachments(node)
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => {
            const checklistNode = node.querySelector("Checklist");
            const checklist: Partial<VehicleChecklist> = {};
            if (checklistNode) {
              Array.from(checklistNode.children).forEach(child => {
                checklist[child.tagName as keyof VehicleChecklist] = child.textContent === 'true';
              });
            }

            return {
              id: node.getAttribute("id") || `s-${Math.random()}`,
              vehicleId: node.getAttribute("vehicleId") || '',
              date: node.querySelector("Date")?.textContent || '',
              endDate: node.querySelector("EndDate")?.textContent || undefined,
              deliveryDate: node.querySelector("DeliveryDate")?.textContent || undefined,
              description: node.querySelector("Description")?.textContent || '',
              cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
              status: node.querySelector("Status")?.textContent || 'naplánováno',
              technician: node.querySelector("Technician")?.textContent || '',
              laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
              fuelLevel: node.querySelector("FuelLevel")?.textContent || '50%',
              mileageAtEntry: parseInt(node.querySelector("MileageAtEntry")?.textContent || "0"),
              estimatedPrice: parseFloat(node.querySelector("EstimatedPrice")?.textContent || "0"),
              paymentType: node.querySelector("PaymentType")?.textContent || 'Hotovost',
              returnParts: node.querySelector("ReturnParts")?.textContent || 'nevracet',
              checklist: checklist as VehicleChecklist,
              parts: Array.from(node.querySelectorAll("Part")).map(p => ({
                id: p.getAttribute("id") || `p-${Math.random()}`,
                description: p.querySelector("Description")?.textContent || '',
                quantity: parseFloat(p.querySelector("Quantity")?.textContent || "1"),
                unitPrice: parseFloat(p.querySelector("UnitPrice")?.textContent || "0"),
                costPrice: parseFloat(p.querySelector("CostPrice")?.textContent || "0"),
                unit: p.querySelector("Unit")?.textContent || 'ks'
              })),
              attachments: getAttachments(node)
            };
          }),
          invoices: Array.from(xmlDoc.querySelectorAll("Invoice")).map(node => ({
            id: node.getAttribute("id") || `i-${Math.random()}`,
            orderId: node.getAttribute("orderId") || '',
            issueDate: node.querySelector("IssueDate")?.textContent || '',
            dueDate: node.querySelector("DueDate")?.textContent || '',
            customerId: node.querySelector("CustomerId")?.textContent || '',
            vehicleInfo: node.querySelector("VehicleInfo")?.textContent || '',
            totalExclDph: parseFloat(node.querySelector("TotalExclDph")?.textContent || "0"),
            totalInclDph: parseFloat(node.querySelector("TotalInclDph")?.textContent || "0"),
            costs: parseFloat(node.querySelector("Costs")?.textContent || "0"),
            status: node.querySelector("Status")?.textContent || 'neuhrazeno',
            paymentType: node.querySelector("PaymentType")?.textContent || 'Převodem',
            discount: parseFloat(node.querySelector("Discount")?.textContent || "0"),
            archived: node.querySelector("Archived")?.textContent === 'true',
            items: Array.from(node.querySelectorAll("Item")).map(i => ({
              id: i.getAttribute("id") || `inv-p-${Math.random()}`,
              description: i.querySelector("Description")?.textContent || '',
              quantity: parseFloat(i.querySelector("Quantity")?.textContent || "1"),
              unit: i.querySelector("Unit")?.textContent || 'ks',
              unitPrice: parseFloat(i.querySelector("UnitPrice")?.textContent || "0"),
              costPrice: parseFloat(i.querySelector("CostPrice")?.textContent || "0"),
            }))
          })),
          settings: {
            hourlyRate: parseInt(xmlDoc.querySelector("HourlyRate")?.textContent || "850"),
            fixedServices: Array.from(xmlDoc.querySelectorAll("FixedService")).map(node => ({
              id: node.getAttribute("id") || `fs-${Math.random()}`,
              name: node.querySelector("Name")?.textContent || '',
              price: parseInt(node.querySelector("Price")?.textContent || "0"),
              costPrice: parseInt(node.querySelector("CostPrice")?.textContent || "0"),
              unit: node.querySelector("Unit")?.textContent || 'ks'
            })),
            predefinedTasks: Array.from(xmlDoc.querySelectorAll("PredefinedTask")).map(node => ({
              id: node.getAttribute("id") || `pt-${Math.random()}`,
              label: node.querySelector("Label")?.textContent || '',
              description: node.querySelector("Description")?.textContent || ''
            })),
            technicians: Array.from(xmlDoc.querySelectorAll("Technician")).map(node => node.textContent || ''),
            discountLevels: Array.from(xmlDoc.querySelectorAll("Level")).map(node => parseInt(node.textContent || "0")),
          }
        };

        const notifNode = xmlDoc.querySelector("NotificationSettings");
        if (notifNode) {
          onNotifSettingsChange({
            stkThresholdDays: parseInt(notifNode.querySelector("StkThresholdDays")?.textContent || "30"),
            serviceThresholdDays: parseInt(notifNode.querySelector("ServiceThresholdDays")?.textContent || "15")
          });
        }

        const userSettNode = xmlDoc.querySelector("UserSettings");
        if (userSettNode) {
          onUserSettingsChange({
            enabled: userSettNode.querySelector("Enabled")?.textContent === 'true',
            username: userSettNode.querySelector("Username")?.textContent || 'admin',
            password: userSettNode.querySelector("Password")?.textContent || ''
          });
        }

        onRestoreData(importedData);
        setBackupStatus('success');
        setTimeout(() => setBackupStatus('idle'), 4000);
      } catch (err) {
        console.error("Restore Error:", err);
        setBackupStatus('error');
      }
    };
    reader.readAsText(file);
    if (event.target) event.target.value = '';
  };

  const handleHourlyRateChange = (value: string) => {
    const rawValue = parseFloat(value) || 0;
    const finalValue = companyInfo.isVatPayer ? (rawValue / 1.21) : rawValue;
    onRateChange(finalValue);
  };

  const displayHourlyRate = () => {
    return companyInfo.isVatPayer ? Math.round(hourlyRate * 1.21) : Math.round(hourlyRate);
  };

  const addDiscountLevel = () => {
    const val = parseInt(newDiscount);
    if (!isNaN(val) && !discountLevels.includes(val)) {
      onDiscountLevelsChange([...discountLevels, val].sort((a, b) => a - b));
      setNewDiscount('');
    }
  };

  const removeDiscountLevel = (val: number) => {
    onDiscountLevelsChange(discountLevels.filter(d => d !== val));
  };

  const addFixedService = () => {
    onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0, costPrice: 0, unit: 'ks' }]);
  };

  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => {
    onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));
  };

  const addTemplate = () => {
    onPredefinedTasksChange([...predefinedTasks, { id: `pt${Date.now()}`, label: '', description: '' }]);
  };

  const updateTemplate = (id: string, field: keyof PredefinedTask, value: string) => {
    onPredefinedTasksChange(predefinedTasks.map(pt => pt.id === id ? { ...pt, [field]: value } : pt));
  };

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };

  const removeTechnician = (name: string) => {
    onTechniciansChange(technicians.filter(t => t !== name));
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 pb-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Nastavení systému</h2>
          <p className="text-slate-500 font-medium">Konfigurace parametrů vašeho servisu.</p>
        </div>
