          <div className="grid grid-cols-1 gap-6">
            {unpaidInvoices.map((inv, idx) => (
              <InvoiceCard 
                key={`${inv.id}-${idx}`} 
                inv={inv} 
                uniqueId={`${inv.id}-${idx}`}
                customers={customers} 
                today={today}
