};

export default InvoiceManager;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock, ShieldCheck, ShieldAlert, CreditCard,
  AlertOctagon
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice, VehicleAttachment, VehicleChecklist } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  onClearAllData: () => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const UNITS = ['ks', 'litr', 'gram', 'kg', 'm', 'sada', 'úkon'];

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  customers, vehicles, services, invoices, onRestoreData, onClearAllData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
  userSettings, onUserSettingsChange
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);
  const [isClearDataConfirmOpen, setIsClearDataConfirmOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const esc = (str: any) => {
    if (str === undefined || str === null) return '';
    return String(str).replace(/[<>&"']/g, (c) => {
      switch (c) {
        case '<': return '&lt;';
        case '>': return '&gt;';
        case '&': return '&amp;';
        case '"': return '&quot;';
        case "'": return '&apos;';
        default: return c;
      }
    });
  };

  const xmlTag = (name: string, value: any, indent: string = '    ') => {
    return `${indent}<${name}>${esc(value)}</${name}>\n`;
  };

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="3.0">\n`;

    // 1. FIREMNÍ ÚDAJE
    xml += `  <CompanyInfo>\n`;
    xml += xmlTag('Name', companyInfo?.name || '');
    xml += xmlTag('Address', companyInfo?.address || '');
    xml += xmlTag('ICO', companyInfo?.ico || '');
    xml += xmlTag('DIC', companyInfo?.dic || '');
    xml += xmlTag('Phone', companyInfo?.phone || '');
    xml += xmlTag('Email', companyInfo?.email || '');
    xml += xmlTag('BankAccount', companyInfo?.bankAccount || '');
    xml += xmlTag('IsVatPayer', !!companyInfo?.isVatPayer);
    xml += xmlTag('FoundationDate', companyInfo?.foundationDate || '');
    xml += `  </CompanyInfo>\n`;

    // 2. ZÁKAZNÍCI
    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${esc(c.id)}">\n`;
      xml += xmlTag('CustomerType', c.customerType || 'soukromý');
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.companyAddress) xml += xmlTag('CompanyAddress', c.companyAddress);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      if (c.contactPerson) xml += xmlTag('ContactPerson', c.contactPerson);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    // 3. VOZIDLA
    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${esc(v.id)}" customerId="${esc(v.customerId)}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color || '');
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      if (v.notes) xml += xmlTag('Notes', v.notes);

      if (v.attachments && v.attachments.length > 0) {
        xml += `      <Attachments>\n`;
        v.attachments.forEach(att => {
          xml += `        <Attachment id="${esc(att.id)}">\n`;
          xml += xmlTag('Name', att.name, '          ');
          xml += xmlTag('Type', att.type, '          ');
          xml += xmlTag('Data', att.data, '          ');
          xml += xmlTag('Size', att.size, '          ');
          xml += `        </Attachment>\n`;
        });
        xml += `      </Attachments>\n`;
      }
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    // 4. ZAKÁZKOVÉ LISTY
    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${esc(s.id)}" vehicleId="${esc(s.vehicleId)}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('EndDate', s.endDate || '');
      xml += xmlTag('DeliveryDate', s.deliveryDate || '');
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours || 0);
      xml += xmlTag('FuelLevel', s.fuelLevel || '50%');
      xml += xmlTag('MileageAtEntry', s.mileageAtEntry || 0);
      xml += xmlTag('EstimatedPrice', s.estimatedPrice || 0);
      xml += xmlTag('PaymentType', s.paymentType || 'Hotovost');
      xml += xmlTag('ReturnParts', s.returnParts || 'nevracet');

      if (s.checklist) {
        xml += `      <Checklist>\n`;
        Object.entries(s.checklist).forEach(([k, v]) => {
          xml += `        <${k}>${v}</${k}>\n`;
        });
        xml += `      </Checklist>\n`;
      }

      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${esc(p.id)}">\n`;
          xml += xmlTag('Description', p.description, '          ');
          xml += xmlTag('Quantity', p.quantity, '          ');
          xml += xmlTag('UnitPrice', p.unitPrice, '          ');
          xml += xmlTag('CostPrice', p.costPrice || 0, '          ');
          xml += xmlTag('Unit', p.unit || 'ks', '          ');
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }

      if (s.attachments && s.attachments.length > 0) {
        xml += `      <Attachments>\n`;
        s.attachments.forEach(att => {
          xml += `        <Attachment id="${esc(att.id)}">\n`;
          xml += xmlTag('Name', att.name, '          ');
          xml += xmlTag('Type', att.type, '          ');
          xml += xmlTag('Data', att.data, '          ');
          xml += xmlTag('Size', att.size, '          ');
          xml += `        </Attachment>\n`;
        });
        xml += `      </Attachments>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    // 5. FAKTURY
    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${esc(inv.id)}" orderId="${esc(inv.orderId)}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalExclDph', inv.totalExclDph);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Costs', inv.costs || 0);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += xmlTag('Discount', inv.discount || 0);
      xml += xmlTag('Archived', !!inv.archived);

      if (inv.items && inv.items.length > 0) {
        xml += `      <Items>\n`;
        inv.items.forEach(item => {
          xml += `        <Item id="${esc(item.id)}">\n`;
          xml += xmlTag('Description', item.description, '          ');
          xml += xmlTag('Quantity', item.quantity, '          ');
          xml += xmlTag('Unit', item.unit || 'ks', '          ');
          xml += xmlTag('UnitPrice', item.unitPrice, '          ');
          xml += xmlTag('CostPrice', item.costPrice || 0, '          ');
          xml += `        </Item>\n`;
        });
        xml += `      </Items>\n`;
      }
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    // 6. SYSTÉMOVÉ NASTAVENÍ
    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);
    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${esc(fs.id)}">\n`;
      xml += xmlTag('Name', fs.name, '        ');
      xml += xmlTag('Price', fs.price, '        ');
      xml += xmlTag('CostPrice', fs.costPrice || 0, '        ');
      xml += xmlTag('Unit', fs.unit || 'ks', '        ');
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;
    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${esc(pt.id)}">\n`;
      xml += xmlTag('Label', pt.label, '        ');
      xml += xmlTag('Description', pt.description, '        ');
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;
    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${esc(t)}</Technician>\n`);
    xml += `    </Technicians>\n`;
    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;

    xml += `    <NotificationSettings>\n`;
    xml += xmlTag('StkThresholdDays', notifSettings.stkThresholdDays, '      ');
    xml += xmlTag('ServiceThresholdDays', notifSettings.serviceThresholdDays, '      ');
    xml += `    </NotificationSettings>\n`;

    xml += `    <UserSettings>\n`;
    xml += xmlTag('Enabled', userSettings.enabled, '      ');
    xml += xmlTag('Username', userSettings.username, '      ');
    xml += xmlTag('Password', userSettings.password, '      ');
    xml += `    </UserSettings>\n`;

    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xmlData = generateBackupXml();
      const blob = new Blob([xmlData], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_full_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 3000);
    } catch (err) { 
      console.error("Backup failed:", err);
      setBackupStatus('error'); 
    }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const parseError = xmlDoc.getElementsByTagName("parsererror");
        if (parseError.length > 0) throw new Error("Chyba při parsování XML souboru.");

        const getAttachments = (node: Element) => {
          return Array.from(node.querySelectorAll("Attachment")).map(att => ({
            id: att.getAttribute("id") || `att-${Math.random()}`,
            name: att.querySelector("Name")?.textContent || '',
            type: att.querySelector("Type")?.textContent || '',
            data: att.querySelector("Data")?.textContent || '',
            size: parseInt(att.querySelector("Size")?.textContent || "0")
          }));
        };

        const companyNode = xmlDoc.querySelector("CompanyInfo");
        const importedCompany: Partial<CompanyInfo> = companyNode ? {
          name: companyNode.querySelector("Name")?.textContent || '',
          address: companyNode.querySelector("Address")?.textContent || '',
          ico: companyNode.querySelector("ICO")?.textContent || '',
          dic: companyNode.querySelector("DIC")?.textContent || '',
          phone: companyNode.querySelector("Phone")?.textContent || '',
          email: companyNode.querySelector("Email")?.textContent || '',
          bankAccount: companyNode.querySelector("BankAccount")?.textContent || '',
          isVatPayer: companyNode.querySelector("IsVatPayer")?.textContent === 'true',
          foundationDate: companyNode.querySelector("FoundationDate")?.textContent || ''
        } : {};

        const importedData: any = {
          companyInfo: importedCompany,
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id") || `c-${Math.random()}`,
            customerType: node.querySelector("CustomerType")?.textContent || 'soukromý',
            firstName: node.querySelector("FirstName")?.textContent || '',
            lastName: node.querySelector("LastName")?.textContent || '',
            email: node.querySelector("Email")?.textContent || '',
            phone: node.querySelector("Phone")?.textContent || '',
            address: node.querySelector("Address")?.textContent || '',
            createdAt: node.querySelector("CreatedAt")?.textContent || '',
            companyName: node.querySelector("CompanyName")?.textContent || undefined,
            companyAddress: node.querySelector("CompanyAddress")?.textContent || undefined,
            ico: node.querySelector("ICO")?.textContent || undefined,
            dic: node.querySelector("DIC")?.textContent || undefined,
            contactPerson: node.querySelector("ContactPerson")?.textContent || undefined,
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id") || `v-${Math.random()}`,
            customerId: node.getAttribute("customerId") || '',
            make: node.querySelector("Make")?.textContent || '',
            model: node.querySelector("Model")?.textContent || '',
            year: parseInt(node.querySelector("Year")?.textContent || "0"),
            vin: node.querySelector("VIN")?.textContent || '',
            licensePlate: node.querySelector("LicensePlate")?.textContent || '',
            mileage: parseInt(node.querySelector("Mileage")?.textContent || "0"),
            engineCode: node.querySelector("EngineCode")?.textContent || '',
            color: node.querySelector("Color")?.textContent || '',
            stkExpirationDate: node.querySelector("STKExpirationDate")?.textContent || '',
            nextServiceDate: node.querySelector("NextServiceDate")?.textContent || '',
            notes: node.querySelector("Notes")?.textContent || undefined,
            attachments: getAttachments(node)
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => {
            const checklistNode = node.querySelector("Checklist");
            const checklist: Partial<VehicleChecklist> = {};
            if (checklistNode) {
              Array.from(checklistNode.children).forEach(child => {
                checklist[child.tagName as keyof VehicleChecklist] = child.textContent === 'true';
              });
            }

            return {
              id: node.getAttribute("id") || `s-${Math.random()}`,
              vehicleId: node.getAttribute("vehicleId") || '',
              date: node.querySelector("Date")?.textContent || '',
              endDate: node.querySelector("EndDate")?.textContent || undefined,
              deliveryDate: node.querySelector("DeliveryDate")?.textContent || undefined,
              description: node.querySelector("Description")?.textContent || '',
              cost: parseFloat(node.querySelector("Cost")?.textContent || "0"),
              status: node.querySelector("Status")?.textContent || 'naplánováno',
              technician: node.querySelector("Technician")?.textContent || '',
              laborHours: parseFloat(node.querySelector("LaborHours")?.textContent || "0"),
              fuelLevel: node.querySelector("FuelLevel")?.textContent || '50%',
              mileageAtEntry: parseInt(node.querySelector("MileageAtEntry")?.textContent || "0"),
              estimatedPrice: parseFloat(node.querySelector("EstimatedPrice")?.textContent || "0"),
              paymentType: node.querySelector("PaymentType")?.textContent || 'Hotovost',
              returnParts: node.querySelector("ReturnParts")?.textContent || 'nevracet',
              checklist: checklist as VehicleChecklist,
              parts: Array.from(node.querySelectorAll("Part")).map(p => ({
                id: p.getAttribute("id") || `p-${Math.random()}`,
                description: p.querySelector("Description")?.textContent || '',
                quantity: parseFloat(p.querySelector("Quantity")?.textContent || "1"),
                unitPrice: parseFloat(p.querySelector("UnitPrice")?.textContent || "0"),
                costPrice: parseFloat(p.querySelector("CostPrice")?.textContent || "0"),
                unit: p.querySelector("Unit")?.textContent || 'ks'
              })),
              attachments: getAttachments(node)
