        if (notifNode) {
          onNotifSettingsChange({
            stkThresholdDays: parseInt(notifNode.querySelector("StkThresholdDays")?.textContent || "30"),
            serviceThresholdDays: parseInt(notifNode.querySelector("ServiceThresholdDays")?.textContent || "15")
          });
