// Component for Invoice Card in lists
const InvoiceCard: React.FC<{
  inv: Invoice;
  uniqueId: string;
  customers: Customer[];
  today: string;
  onSelect: (inv: Invoice) => void;
  onDelete: (inv: Invoice) => void;
  onUpdateStatus: (id: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onArchive: (inv: Invoice) => void;
  openMenuId: string | null;
  onOpenMenu: (id: string | null) => void;
}> = ({ inv, uniqueId, customers, today, onSelect, onDelete, onUpdateStatus, onArchive, openMenuId, onOpenMenu }) => {
  const customer = customers.find(c => c.id === inv.customerId);
  const isOverdue = inv.status === 'neuhrazeno' && inv.dueDate < today;
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onOpenMenu(null);
      }
    };
    if (openMenuId === uniqueId) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [openMenuId, uniqueId, onOpenMenu]);

  return (
    <div 
      className={`bg-white rounded-[2rem] border p-6 shadow-sm hover:shadow-xl transition-all group relative overflow-visible cursor-pointer ${isOverdue ? 'border-red-200 bg-red-50/10' : 'border-slate-100'}`}
      onClick={() => onSelect(inv)}
    >
      <div className="absolute top-0 right-0 p-4">
        <div className="relative" onClick={e => e.stopPropagation()}>
          <button 
            onClick={() => onOpenMenu(openMenuId === uniqueId ? null : uniqueId)}
            className={`p-2 rounded-xl transition-all ${openMenuId === uniqueId ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
          >
            <MoreHorizontal className="w-5 h-5" />
          </button>

          {openMenuId === uniqueId && (
            <div 
              ref={menuRef}
              className="absolute top-12 right-0 w-52 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
            >
              <button 
                onClick={() => { onUpdateStatus(inv.id, inv.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno'); onOpenMenu(null); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 transition-colors text-sm font-bold ${inv.status === 'uhrazeno' ? 'text-amber-600' : 'text-emerald-600'}`}
              >
                {inv.status === 'uhrazeno' ? <XCircle className="w-4 h-4" /> : <CheckCircle className="w-4 h-4" />}
                {inv.status === 'uhrazeno' ? 'Neuhrazeno' : 'Uhrazeno'}
              </button>

              {inv.status === 'uhrazeno' && (
                <button 
                  onClick={() => { onArchive(inv); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"
                >
                  <Archive className="w-4 h-4" /> Archivovat
                </button>
              )}

              <div className="h-px bg-slate-100 my-1 mx-2"></div>

              <button 
                onClick={() => { onDelete(inv); onOpenMenu(null); }}
                className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
              >
                <Trash2 className="w-4 h-4" /> Smazat
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="flex items-center gap-4 mb-4">
        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${inv.status === 'uhrazeno' ? 'bg-emerald-50 text-emerald-600' : isOverdue ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
          <Receipt className="w-6 h-6" />
        </div>
        <div>
          <h4 className="text-base font-black text-slate-900">{inv.id}</h4>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{formatDate(inv.issueDate)}</p>
        </div>
      </div>

      <div className="space-y-3 mb-6">
        <div className="flex items-center gap-2 text-slate-700">
          <User className="w-4 h-4 text-slate-300" />
          <span className="text-sm font-bold truncate">{customer?.companyName || `${customer?.firstName || ''} ${customer?.lastName || ''}`}</span>
        </div>
        <div className="flex items-center gap-2">
          <Car className="w-4 h-4 text-slate-300" />
          <span className="text-[10px] font-black text-blue-600 uppercase font-mono tracking-wider truncate">{inv.vehicleInfo}</span>
        </div>
      </div>

      <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
        <div className="flex flex-col">
          <span className="text-[9px] font-black text-slate-400 uppercase">K úhradě</span>
          <span className="text-lg font-black text-slate-900">{inv.totalInclDph.toLocaleString()} Kč</span>
        </div>
        <div className="flex flex-col items-end">
           <span className="text-[9px] font-black text-slate-400 uppercase">Splatnost</span>
           <span className={`text-[10px] font-black ${isOverdue ? 'text-red-600' : 'text-slate-600'}`}>{formatDate(inv.dueDate)}</span>
