  onNavigateToCustomer: (id: string) => void;
  onNavigateToOrder: (id: string) => void;
  onCreateOrder: (id: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const VehicleManager: React.FC<VehicleManagerProps> = ({ 
  vehicles, 
  customers, 
  services,
  onAddVehicle, 
  onUpdateVehicle, 
  onDeleteVehicle,
  onNavigateToCustomer,
  onNavigateToOrder,
  onCreateOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [historyVehicle, setHistoryVehicle] = useState<Vehicle | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [selectedLetter, setSelectedLetter] = useState<string | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const initialFormData: Partial<Vehicle> = {
    make: 'Škoda',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '',
    stkExpirationDate: '',
    nextServiceDate: '',
    serviceIntervalKm: 15000,
    serviceIntervalMonths: 12,
    customerId: customers[0]?.id || '',
    attachments: []
  };

  const [formData, setFormData] = useState<Partial<Vehicle>>(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialVehicleId) {
      const v = vehicles.find(item => item.id === initialVehicleId);
      if (v) setSelectedVehicle(v);
      if (onModalOpened) onModalOpened();
    }
  }, [initialVehicleId, vehicles, onModalOpened]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const availableMakes = useMemo(() => {
    return Object.keys(VEHICLE_DB);
  }, []);

  const availableModels = useMemo(() => {
    if (formData.make && VEHICLE_DB[formData.make]) {
      return Object.keys(VEHICLE_DB[formData.make]);
    }
    return [];
  }, [formData.make]);

  const availableEngines = useMemo(() => {
    if (formData.make && formData.model && VEHICLE_DB[formData.make] && VEHICLE_DB[formData.make][formData.model]) {
      return VEHICLE_DB[formData.make][formData.model];
    }
    return [];
  }, [formData.make, formData.model]);

  const alphabet = useMemo(() => {
    const letters = new Set<string>();
    vehicles.forEach(v => {
      if (v.make) letters.add(v.make[0].toUpperCase());
    });
    return Array.from(letters).sort((a, b) => a.localeCompare(b, 'cs'));
  }, [vehicles]);

  const filteredVehicles = useMemo(() => {
    return vehicles.filter(v => {
      const customer = customers.find(c => c.id === v.customerId);
      const customerName = customer 
        ? (customer.customerType === 'firemní' ? customer.companyName : `${customer.lastName} ${customer.firstName}`) 
        : "";

      const matchesSearch = 
        (v.licensePlate || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.make || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.model || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.vin || "").toLowerCase().includes(search.toLowerCase()) ||
        customerName?.toLowerCase().includes(search.toLowerCase());

      const matchesLetter = !selectedLetter || (v.make && v.make[0].toUpperCase() === selectedLetter);

      return matchesSearch && matchesLetter;
    }).sort((a, b) => (a.make || "").localeCompare(b.make || "", 'cs'));
  }, [vehicles, search, selectedLetter, customers]);

  const handleAddNew = () => {
    setEditingVehicle(null);
    setFormData(initialFormData);
    setIsModalOpen(true);
  };

  const handleEdit = (v: Vehicle) => {
    setEditingVehicle(v);
    setFormData(v);
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const sanitizedData = {
      ...formData,
      licensePlate: (formData.licensePlate || '').trim().toUpperCase(),
      vin: (formData.vin || '').trim().toUpperCase()
    };

    if (editingVehicle) {
      onUpdateVehicle({ ...editingVehicle, ...sanitizedData } as Vehicle);
    } else {
      onAddVehicle({ ...sanitizedData, id: `v${Date.now()}` } as Vehicle);
    }
    setIsModalOpen(false);
  };

  const handleDeleteConfirm = () => {
    if (deletingVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedVehicle) return;

    const file = files[0];
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64Data = reader.result as string;
      const newAttachment: VehicleAttachment = {
        id: `att-${Date.now()}`,
        name: file.name,
        type: file.type,
        data: base64Data,
        size: file.size
      };

      const updatedVehicle = {
        ...selectedVehicle,
        attachments: [...(selectedVehicle.attachments || []), newAttachment]
      };

      onUpdateVehicle(updatedVehicle);
      setSelectedVehicle(updatedVehicle);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleDeleteAttachment = (attachmentId: string) => {
    if (!selectedVehicle) return;
    const updatedVehicle = {
      ...selectedVehicle,
      attachments: (selectedVehicle.attachments || []).filter(a => a.id !== attachmentId)
    };
    onUpdateVehicle(updatedVehicle);
    setSelectedVehicle(updatedVehicle);
  };

  const openAttachment = (attachment: VehicleAttachment) => {
    try {
      const splitted = attachment.data.split(',');
      if (splitted.length < 2) throw new Error("Invalid base64");

      const base64Parts = splitted;
      const contentType = base64Parts[0].split(':')[1].split(';')[0];
      const byteCharacters = atob(base64Parts[1]);
      const byteArrays = [];

      for (let offset = 0; offset < byteCharacters.length; offset += 512) {
        const slice = byteCharacters.slice(offset, offset + 512);
        const byteNumbers = new Array(slice.length);
        for (let i = 0; i < slice.length; i++) {
          byteNumbers[i] = slice.charCodeAt(i);
        }
        const byteArray = new Uint8Array(byteNumbers);
        byteArrays.push(byteArray);
      }

      const blob = new Blob(byteArrays, { type: contentType });
      const blobUrl = URL.createObjectURL(blob);

      const newWindow = window.open(blobUrl, '_blank');
      if (!newWindow) {
        alert('Prohlížeč zablokoval vyskakovací okno. Povolte prosím vyskakovací okna pro tuto stránku.');
      }

      setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
    } catch (error) {
      console.error('Error opening attachment:', error);
      alert('Soubor se nepodařilo otevřít.');
    }
  };

  const vehicleServices = useMemo(() => {
    if (!historyVehicle) return [];
    return services
      .filter(s => s.vehicleId === historyVehicle.id)
      .sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  }, [historyVehicle, services]);

  const totalSpentOnVehicle = useMemo(() => {
    return vehicleServices.reduce((sum, s) => sum + (Number(s.cost) || 0) * 1.21, 0);
  }, [vehicleServices]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Vozidla</h2>
          <p className="text-slate-500 font-medium">Evidence vozového parku a servisních intervalů.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat podle SPZ, značky, modelu, VIN nebo jména majitele..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
          {search && (
            <button 
              onClick={() => onSearchChange('')}
              className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
            >
              Zrušit filtr
            </button>
          )}
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <div className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 flex items-center gap-2 shrink-0">
            <Type className="w-4 h-4 text-slate-400" />
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">Značka:</span>
          </div>
          <button 
            onClick={() => setSelectedLetter(null)}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
          >
            VŠE
          </button>
          {alphabet.map(letter => (
            <button 
              key={letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVehicles.map(v => (
          <div key={v.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-2xl transition-all group relative">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-5 h-5" />
                </button>

                {openMenuId === v.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-52 bg-white rounded-2xl shadow-[0_10px_40px_rgba(0,0,0,0.15)] border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleEdit(v)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit vozidlo
                    </button>
                    <button 
                      onClick={() => { onCreateOrder(v.id); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"
                    >
                      <ClipboardPlus className="w-4 h-4 text-blue-400" />
                      Vytvořit zakázku
                    </button>
                    <div className="h-px bg-slate-100 my-1 mx-2"></div>
                    <button 
                      onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat vozidlo
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-4">
              <div className="w-16 h-16 rounded-2xl bg-slate-900 flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105">
                <Car className="w-8 h-8" />
              </div>
              <div className="min-w-0">
                <h3 className="text-lg font-black text-slate-900 leading-tight truncate">
                  {v.make} {v.model}
                </h3>
                <p className="text-sm font-black text-blue-600 font-mono tracking-widest mt-1 uppercase">{v.licensePlate?.toUpperCase()}</p>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter mt-0.5">{v.year}</p>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedVehicle(v)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider"
              >
                Detail
              </button>
              <button 
                onClick={() => setHistoryVehicle(v)}
                className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider flex items-center justify-center gap-2"
              >
                <HistoryIcon className="w-3.5 h-3.5" />
                Historie
              </button>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-[0_30px_90px_-15px_rgba(0,0,0,0.45)] border border-slate-100/50 relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center shadow-xl">
              <div>
                <h3 className="text-2xl font-black tracking-tight">{editingVehicle ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Registrace do evidence</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Značka</label>
                  <input 
                    type="text" 
                    list="make-list"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold shadow-sm focus:shadow-md"
                    value={formData.make}
                    onChange={e => setFormData({...formData, make: e.target.value, model: ''})}
                    placeholder="Vyberte nebo napište značku..."
                  />
                  <datalist id="make-list">
                    {availableMakes.map(make => <option key={make} value={make} />)}
                  </datalist>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Model</label>
                  <input 
                    type="text" 
                    list="model-list"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold shadow-sm focus:shadow-md"
                    value={formData.model}
                    onChange={e => setFormData({...formData, model: e.target.value})}
                    placeholder="Vyberte nebo napište model..."
                  />
                  <datalist id="model-list">
                    {availableModels.map(model => <option key={model} value={model} />)}
                  </datalist>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rok výroby</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm focus:shadow-md"
                    value={formData.year}
                    onChange={e => setFormData({...formData, year: parseInt(e.target.value) || 0})}
                  />
                </div>
                <div className="space-y-2 col-span-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">SPZ / RZ</label>
                  <input 
                    required
                    type="text" 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold uppercase shadow-sm focus:shadow-md"
                    value={formData.licensePlate || ''}
                    onChange={e => setFormData({...formData, licensePlate: e.target.value.toUpperCase()})}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">VIN kód</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold uppercase font-mono shadow-sm focus:shadow-md"
                  value={formData.vin || ''}
                  onChange={e => setFormData({...formData, vin: e.target.value.toUpperCase()})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Aktuální nájezd (km)</label>
                  <input 
                    type="number" 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm focus:shadow-md"
                    value={formData.mileage || 0}
                    onChange={e => setFormData({...formData, mileage: parseInt(e.target.value) || 0})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kód motoru</label>
                  <input 
                    type="text" 
                    list="engine-list"
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm focus:shadow-md"
                    value={formData.engineCode || ''}
                    onChange={e => setFormData({...formData, engineCode: e.target.value})}
                    placeholder="Vyberte nebo napište kód..."
                  />
                  <datalist id="engine-list">
                    {availableEngines.map(engine => (
                      <option key={engine} value={engine} />
                    ))}
                  </datalist>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">STK do</label>
                  <input 
                    type="date" 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm focus:shadow-md"
                    value={formData.stkExpirationDate || ''}
                    onChange={e => setFormData({...formData, stkExpirationDate: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Příští servis</label>
                  <input 
                    type="date" 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm focus:shadow-md"
                    value={formData.nextServiceDate || ''}
                    onChange={e => setFormData({...formData, nextServiceDate: e.target.value})}
                  />
                </div>
              </div>

              <div className="bg-blue-50/50 p-6 rounded-[2rem] border border-blue-100 shadow-inner space-y-4">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest flex items-center gap-2">
                  <Clock3 className="w-3.5 h-3.5" /> Servisní intervaly
                </h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kilometry</label>
                    <select 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm"
                      value={formData.serviceIntervalKm || 15000}
                      onChange={e => setFormData({...formData, serviceIntervalKm: parseInt(e.target.value)})}
                    >
                      {[5000, 10000, 15000, 20000, 25000, 30000].map(km => (
                        <option key={km} value={km}>{km.toLocaleString()} km</option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Časový (roky)</label>
                    <select 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm"
                      value={formData.serviceIntervalMonths || 12}
                      onChange={e => setFormData({...formData, serviceIntervalMonths: parseInt(e.target.value)})}
                    >
                      {[12, 24, 36].map(m => (
                        <option key={m} value={m}>{m / 12} {m / 12 === 1 ? 'rok' : (m / 12 < 5 ? 'roky' : 'let')}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Barva vozidla</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold shadow-sm"
                  value={formData.color || ''}
                  onChange={e => setFormData({...formData, color: e.target.value})}
                  placeholder="Např. Modrá Race, Černá perleť..."
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník / Zákazník</label>
                <select 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold shadow-sm"
                  value={formData.customerId || ''}
                  onChange={e => setFormData({...formData, customerId: e.target.value})}
                >
                  {customers.map(c => (
                    <option key={c.id} value={c.id}>{c.companyName || `${c.lastName} ${c.firstName}`}</option>
                  ))}
