              </div>

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/30 transition-all flex items-center justify-center gap-2 mt-4"
              >
                <Check className="w-5 h-5" />
                {editingVehicle ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL HISTORIE OPRAV */}
      {historyVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setHistoryVehicle(null)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-[0_30px_90px_-15px_rgba(0,0,0,0.5)] border border-slate-100/50 relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center shrink-0 shadow-lg">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-blue-500/20 flex items-center justify-center border border-white/10 shadow-inner">
                  <HistoryIcon className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">Historie oprav</h3>
                  <p className="text-blue-100 text-[10px] font-black uppercase tracking-widest mt-1">
                    {historyVehicle.make} {historyVehicle.model} ({historyVehicle.licensePlate?.toUpperCase()})
                  </p>
                </div>
              </div>
              <button onClick={() => setHistoryVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="bg-slate-50 px-8 py-4 border-b border-slate-200 flex items-center justify-between shrink-0 shadow-sm">
              <div className="flex items-center gap-6">
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase">Počet zakázek</p>
                  <p className="text-lg font-black text-slate-900">{vehicleServices.length}</p>
                </div>
                <div className="w-px h-8 bg-slate-200"></div>
                <div>
