                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 shadow-inner">
                    <ClipboardList className="w-10 h-10 text-slate-200" />
                  </div>
                  <h4 className="text-lg font-black text-slate-900 mb-1">Žádná historie</h4>
                  <p className="text-sm font-bold text-slate-400 max-w-xs mx-auto">Pro toto vozidlo zatím nebyly v systému vytvořeny žádné servisní záznamy.</p>
                </div>
