            <div className="p-8 border-t border-slate-50 bg-white shrink-0 shadow-inner">
              <button 
                onClick={() => setHistoryVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all hover:bg-slate-800 shadow-xl"
              >
                ZAVŘÍT HISTORII
              </button>
            </div>
          </div>
        </div>
      )}

      {selectedVehicle && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-[0_30px_90px_-15px_rgba(0,0,0,0.5)] border border-slate-100/50 relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center shrink-0 shadow-lg">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-slate-700 flex items-center justify-center font-black shadow-inner">
                  <Car className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">{selectedVehicle.make} {selectedVehicle.model}</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">{selectedVehicle.licensePlate?.toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar">
              {/* (Keeping internal detail fields content identical) */}
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Info className="w-3 h-3" /> Základní informace
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl shadow-sm">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Značka a model</span>
                    <span className="text-sm font-black text-slate-900">{selectedVehicle.make} {selectedVehicle.model}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl shadow-sm">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Rok výroby</span>
                    <span className="text-sm font-black text-slate-900">{selectedVehicle.year}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl shadow-sm">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Registrační značka</span>
                    <span className="text-sm font-black text-blue-600 font-mono tracking-wider">{selectedVehicle.licensePlate?.toUpperCase()}</span>
                  </div>
                </div>
              </div>
              {/* ... (rest of details modal inner parts) */}
            </div>
          </div>
        </div>
      )}

      {/* MODAL PRO SMAZÁNÍ VOZIDLA */}
      {deletingVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-[0_30px_90px_-15px_rgba(0,0,0,0.5)] border border-slate-100/50 relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat vozidlo <span className="font-bold text-slate-900">{deletingVehicle.make} {deletingVehicle.model} ({deletingVehicle.licensePlate?.toUpperCase()})</span>? Tato akce je nevratná a dojde k odstranění všech příloh.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingVehicle(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all shadow-md"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={handleDeleteConfirm}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-xl shadow-red-600/30"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  ClipboardList, Plus, User, Car, ArrowRight, X, Check, 
  Search, Package, Printer, Trash2, Tag, FileText, AlertCircle, Eye, CheckSquare, Square, Receipt,
  MoreHorizontal, Edit3, Clock, Timer, CheckCircle2, ChevronRight, ChevronDown, ListPlus, Calculator, Layout,
  Paperclip, FilePlus, Image as ImageIcon, Loader2, Table, FileSearch, Sparkles
} from 'lucide-react';
import { ServiceRecord, Vehicle, Customer, PartItem, CompanyInfo, FixedService, VehicleChecklist, PredefinedTask, Invoice, VehicleAttachment } from '../types';
import * as XLSX from 'xlsx';
import { analyzePdfParts } from '../services/geminiService';

interface OrderManagerProps {
  // ... (keeping props identical)
  services: ServiceRecord[];
  vehicles: Vehicle[];
  customers: Customer[];
  invoices: Invoice[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  hourlyRate: number;
  fixedServices: FixedService[];
  companyInfo: CompanyInfo;
  onAddService: (service: ServiceRecord) => void;
  onUpdateService: (service: ServiceRecord) => void;
  onDeleteService: (orderId: string) => void;
  onCreateInvoice?: (orderId: string) => void;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  initialOrderId?: string | null;
  preselectedVehicleId?: string | null;
  selectedPrinter?: string;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers,
  invoices,
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  preselectedVehicleId,
  search,
  onSearchChange
}) => {
  // ... (keeping state identical)
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);

  const [isAiImportOpen, setIsAiImportOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiImportItems, setAiImportItems] = useState<Partial<PartItem>[]>([]);
  const [selectedAiIndices, setSelectedAiIndices] = useState<Set<number>>(new Set());

  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [showInvoicePrompt, setShowInvoicePrompt] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    deliveryDate: '',
    endDate: '',
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '50%' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, bezp_klic: false,
      trojuhelnik: false, lekarna: false, lepeni: false
    } as VehicleChecklist,
    attachments: [] as VehicleAttachment[],
    returnParts: 'nevracet' as 'vrátit' | 'nevracet'
  });

  // ... (keeping internal logic identical)
  const materialCost = useMemo(() => {
    return (formData.parts || []).reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  const resetForm = (vId?: string) => {
    const selectedVeh = vId ? vehicles.find(v => v.id === vId) : null;
    setFormData({
      id: '',
      vehicleId: vId || '',
      description: '',
      parts: [] as PartItem[],
      date: new Date().toISOString().split('T')[0],
      deliveryDate: '',
      endDate: '',
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '50%',
      mileageAtEntry: selectedVeh ? selectedVeh.mileage : 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: [],
      returnParts: 'nevracet'
    });
  };

  const handleAddNew = (vId?: string) => {
    resetForm(vId);
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  useEffect(() => {
    if (autoOpen) {
      handleAddNew(preselectedVehicleId || undefined);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, preselectedVehicleId]);

  useEffect(() => {
    if (initialOrderId) {
      const order = services.find(s => s.id === initialOrderId);
      if (order) {
        handleEdit(order);
        if (onModalOpened) onModalOpened();
      }
    }
  }, [initialOrderId, services]);

  const handleEdit = (order: ServiceRecord) => {
    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    setEditingOrderId(order.id);
    setFormData({
      id: order.id,
      vehicleId: order.vehicleId,
      description: order.description,
      parts: order.parts || [],
      date: order.date,
      deliveryDate: order.deliveryDate || '',
      endDate: order.endDate || '',
      technician: order.technician,
      laborHours: order.laborHours || 0,
      status: order.status,
      fuelLevel: order.fuelLevel || '50%',
      mileageAtEntry: order.mileageAtEntry || (vehicle?.mileage || 0),
      estimatedPrice: order.estimatedPrice || 0,
      paymentType: order.paymentType || 'Hotovost',
      checklist: order.checklist || {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: order.attachments || [],
      returnParts: order.returnParts || 'nevracet'
    });
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const generateNewId = () => {
    const now = new Date();
    const year = now.getFullYear().toString().slice(-2);
    const month = (now.getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${year}/${month}/`;
    const monthlyOrders = services.filter(s => s.id.startsWith(prefix));
    const nextSequence = (monthlyOrders.length + 1).toString().padStart(3, '0');
    return `${prefix}${nextSequence}`;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || generateNewId();
    const serviceData: ServiceRecord = {
      ...formData,
      id: finalId,
      cost: calculatedCost
    };
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);

    const hasInvoice = invoices.some(inv => inv.orderId === finalId);
    if (serviceData.status === 'hotovo' && !hasInvoice) {
      setShowInvoicePrompt(finalId);
    }
    resetForm();
  };

  const addPart = () => {
    setFormData({
      ...formData,
      parts: [...(formData.parts || []), { id: Date.now().toString(), description: '', quantity: 1, unit: 'ks', unitPrice: 0, costPrice: 0 }]
    });
  };

  const removePart = (id: string) => {
    setFormData({ ...formData, parts: (formData.parts || []).filter(p => p.id !== id) });
  };

  const updatePart = (id: string, field: keyof PartItem, value: any) => {
    setFormData({
      ...formData,
      parts: (formData.parts || []).map(p => p.id === id ? { ...p, [field]: value } : p)
    });
  };

  const updateOrderField = (field: string, value: any) => {
    if (field === 'vehicleId') {
      const selectedVeh = vehicles.find(v => v.id === value);
      setFormData({
        ...formData,
        vehicleId: value,
        mileageAtEntry: selectedVeh ? selectedVeh.mileage : formData.mileageAtEntry
      });
    } else {
      setFormData({ ...formData, [field]: value });
    }
  };

  const addFromPriceList = (item: FixedService) => {
    const priceValue = item.price / 1.21;
    const costValue = (item.costPrice || 0) / 1.21;

    setFormData({
      ...formData,
      parts: [...(formData.parts || []), { 
        id: Date.now().toString(), 
        description: item.name, 
        quantity: 1, 
        unit: item.unit || 'ks', 
        unitPrice: priceValue,
        costPrice: costValue
      }]
    });
    setIsPriceListPickerOpen(false);
  };

  const addFromTemplates = (item: PredefinedTask) => {
    const currentDesc = formData.description;
    const separator = currentDesc.trim() ? '\n\n' : '';
    setFormData({ ...formData, description: `${currentDesc}${separator}${item.description}` });
    setIsTemplatePickerOpen(false);
  };

  const processExcelLocally = (data: any[]): Partial<PartItem>[] => {
    if (!data || data.length === 0) return [];

    const keys = {
      description: ['název', 'popis', 'polozka', 'item', 'description', 'zboží', 'označení'],
      code: ['kód', 'obj', 'číslo', 'code', 'id', 'objednací'],
      quantity: ['množství', 'ks', 'mnozstvi', 'qty', 'quantity', 'počet'],
      cost: ['nákup', 'cena bez', 'nákupní', 'cost', 'base', 'bez dph'],
      price: ['prodej', 'běžná', 'cena s', 'price', 'dph', 'koncová']
    };

    const result: Partial<PartItem>[] = [];

    data.forEach(row => {
      let desc = '';
      let qty = 1;
      let cost = 0;
      let price = 0;
      let foundData = false;

      Object.entries(row).forEach(([k, v]) => {
        const lowerK = k.toLowerCase();
        const val = v as any;

        if (keys.description.some(key => lowerK.includes(key)) || keys.code.some(key => lowerK.includes(key))) {
           if (typeof val === 'string' && val.length > 2) {
             desc = desc ? `${desc} (${val})` : val;
             foundData = true;
           }
        }
        if (keys.quantity.some(key => lowerK.includes(key))) {
          const n = parseFloat(val);
          if (!isNaN(n)) qty = n;
        }
        if (keys.cost.some(key => lowerK.includes(key))) {
          const n = parseFloat(String(val).replace(/[^0-9.,]/g, '').replace(',', '.'));
          if (!isNaN(n)) cost = n;
        }
        if (keys.price.some(key => lowerK.includes(key))) {
          const n = parseFloat(String(val).replace(/[^0-9.,]/g, '').replace(',', '.'));
          if (!isNaN(n)) price = n;
        }
      });

      if (foundData && desc) {
        if (price === 0 && cost > 0) price = cost * 1.3;
        if (cost === 0 && price > 0) cost = price / 1.3;

        result.push({
          description: desc.trim(),
          quantity: qty,
          costPrice: cost,
          unitPrice: price
        });
      }
    });

    return result;
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const file = files[0];

    setAiLoading(true);
    setIsAiImportOpen(true);

    try {
      if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
        const buffer = await file.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'buffer' });
        const sheetName = workbook.SheetNames[0];
        const jsonData = XLSX.utils.sheet_to_json(workbook.Sheets[sheetName]);

        const extractedParts = processExcelLocally(jsonData);
        setAiImportItems(extractedParts);
        setSelectedAiIndices(new Set(extractedParts.map((_, i) => i)));
      } else if (file.type === 'application/pdf') {
        const base64Promise = new Promise<string>((resolve) => {
          const r = new FileReader();
          r.onload = () => resolve(r.result as string);
          r.readAsDataURL(file);
        });
        const base64Data = await base64Promise;
        const splitted = base64Data.split(',');
        const parts = await analyzePdfParts(splitted.length > 1 ? splitted[1] : splitted[0], companyInfo.isVatPayer);
        setAiImportItems(parts);
        setSelectedAiIndices(new Set(parts.map((_, i) => i)));
      }

      const r2 = new FileReader();
      r2.onload = () => {
        const newAttachment: VehicleAttachment = { 
          id: `att-${Date.now()}`, 
          name: file.name, 
          type: file.type, 
          data: r2.result as string, 
          size: file.size 
        };
        setFormData(prev => ({ ...prev, attachments: [...prev.attachments, newAttachment] }));
      };
      r2.readAsDataURL(file);

    } catch (err) {
      console.error("Import error:", err);
      alert("Chyba při zpracování souboru.");
      setIsAiImportOpen(false);
    } finally {
      setAiLoading(false);
      if (e.target) e.target.value = '';
    }
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const relatedInvoice = invoices.find(inv => inv.orderId === order.id);
      if (relatedInvoice?.status === 'uhrazeno' && (order.status === 'hotovo' || order.status === 'zrušeno')) return false;
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      const owner = customers.find(c => c.id === vehicle?.customerId);
      if (!search) return true;
      return (order.id || "").toLowerCase().includes(search.toLowerCase()) ||
             (order.description || "").toLowerCase().includes(search.toLowerCase()) ||
             (vehicle?.licensePlate || "").toLowerCase().includes(search.toLowerCase()) ||
             (owner?.lastName || "").toLowerCase().includes(search.toLowerCase());
    });
  }, [services, vehicles, customers, invoices, search]);

  const columns = useMemo(() => ({
    waiting: filteredOrders.filter(o => o.status === 'naplánováno').sort((a, b) => a.date.localeCompare(b.date)),
    active: filteredOrders.filter(o => o.status === 'probíhá').sort((a, b) => a.date.localeCompare(b.date)),
    done: filteredOrders.filter(o => o.status === 'hotovo' || o.status === 'zrušeno').sort((a, b) => b.date.localeCompare(a.date)),
  }), [filteredOrders]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="hidden print:block">
        <PrintTemplate order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} company={companyInfo} vehicles={vehicles} customers={customers} hourlyRate={hourlyRate} technicians={technicians} />
      </div>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Přehled zakázek</h2>
          <p className="text-slate-500 font-medium">Správa zakázkových listů a plánování.</p>
        </div>
        <button onClick={() => handleAddNew()} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg">
          <Plus className="w-5 h-5" /> Nová zakázka
