                  <Archive className="w-4 h-4" /> Archivovat
                </button>
              )}

              <div className="h-px bg-slate-100 my-1 mx-2"></div>

              <button 
                onClick={() => { onDelete(inv); onOpenMenu(null); }}
                className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
              >
                <Trash2 className="w-4 h-4" /> Smazat
              </button>
            </div>
          )}
        </div>
      </div>

      <div className="flex items-center gap-4 mb-4">
        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg ${inv.status === 'uhrazeno' ? 'bg-emerald-50 text-emerald-600' : isOverdue ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
          <Receipt className="w-6 h-6" />
        </div>
        <div>
          <h4 className="text-base font-black text-slate-900">{inv.id}</h4>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{formatDate(inv.issueDate)}</p>
