        <div className="bg-indigo-950 p-10 rounded-[2.5rem] shadow-2xl text-white relative overflow-hidden flex flex-col h-[600px]">
          <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
