              {activeOrders.length > 0 ? activeOrders.map((order) => {
                const vehicle = vehicles.find(v => v.id === order.vehicleId);
                const customer = customers.find(c => c.id === vehicle?.customerId);
                return (
                  <div key={order.id} className="p-6 rounded-3xl border border-indigo-500/30 bg-indigo-500/10 text-indigo-100 transition-all hover:scale-[1.02] cursor-pointer" onClick={() => onViewOrder(order.id)}>
                    <div className="flex justify-between items-start mb-3">
                      <div className="flex items-center gap-2"><Clock className="w-4 h-4" /><span className="text-[10px] font-black uppercase tracking-widest">{order.status}</span></div>
                      <span className="text-[11px] font-black px-2 py-0.5 rounded-full bg-white/10 text-white">{formatDate(order.date)}</span>
                    </div>
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex items-start gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center shrink-0 text-indigo-300 mt-1"><Car className="w-6 h-6" /></div>
                        <div className="min-w-0">
                          <p className="text-[10px] font-black text-indigo-300 uppercase tracking-tighter mb-1">
                            {customer ? (customer.companyName || `${customer.firstName} ${customer.lastName}`) : 'Neznámý zákazník'}
                          </p>
                          <div className="flex items-center gap-2 mb-1 overflow-hidden">
                            <p className="text-base font-black tracking-tight truncate shrink">
                              {vehicle ? `${vehicle.make} ${vehicle.model}` : 'Neznámý vůz'}
                            </p>
                            {vehicle && (
                              <span className="bg-slate-900/50 text-[9px] font-black px-1.5 py-0.5 rounded font-mono uppercase text-indigo-200 border border-indigo-500/20 shrink-0">
                                {vehicle.licensePlate}
