import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Mail, 
  Phone, 
  MapPin, 
  MoreHorizontal, 
  UserPlus, 
  X, 
  Check, 
  Car, 
  Calendar,
  ChevronRight,
  User as UserIcon,
  Edit3,
  Trash2,
  AlertCircle,
  Building2,
  Briefcase,
  Type,
  User
} from 'lucide-react';
import { Customer, Vehicle } from '../types';

interface CustomerProps {
  customers: Customer[];
  vehicles: Vehicle[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer?: (customer: Customer) => void;
  onDeleteCustomer?: (id: string) => void;
  onNavigateToVehicle?: (vehicleId: string) => void;
  initialCustomerId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const CustomerManager: React.FC<CustomerProps> = ({ 
  customers, 
  vehicles, 
  onAddCustomer, 
  onUpdateCustomer, 
  onDeleteCustomer,
  onNavigateToVehicle,
  initialCustomerId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState<Customer | null>(null);
  const [selectedDetailCustomer, setSelectedDetailCustomer] = useState<Customer | null>(null);
  const [selectedVehiclesCustomer, setSelectedVehiclesCustomer] = useState<Customer | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [selectedLetter, setSelectedLetter] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData = {
    customerType: 'soukromý' as 'soukromý' | 'firemní',
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    companyName: '',
    companyAddress: '',
    ico: '',
    dic: '',
    contactPerson: ''
  };

  const [formData, setFormData] = useState(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleOpenAdd();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const alphabet = useMemo(() => {
    const letters = new Set<string>();
    customers.forEach(c => {
      const char = c.customerType === 'firemní' && c.companyName ? c.companyName[0] : (c.lastName ? c.lastName[0] : '');
      if (char) letters.add(char.toUpperCase());
    });
    return Array.from(letters).sort((a, b) => a.localeCompare(b, 'cs'));
  }, [customers]);

  const filtered = useMemo(() => {
    return customers
      .filter(c => {
        const customerVehicles = vehicles.filter(v => v.customerId === c.id);
        const hasMatchingVehicle = customerVehicles.some(v => 
          (v.licensePlate || "").toLowerCase().includes(search.toLowerCase())
        );

        const matchesSearch = 
          `${c.lastName} ${c.firstName}`.toLowerCase().includes(search.toLowerCase()) ||
          c.email.toLowerCase().includes(search.toLowerCase()) ||
          (c.companyName && c.companyName.toLowerCase().includes(search.toLowerCase())) ||
          c.phone.includes(search) ||
          hasMatchingVehicle;

        const char = c.customerType === 'firemní' && c.companyName ? c.companyName[0] : (c.lastName ? c.lastName[0] : '');
        const matchesLetter = !selectedLetter || (char.toUpperCase() === selectedLetter);

        return matchesSearch && matchesLetter;
      })
      .sort((a, b) => {
        const nameA = a.customerType === 'firemní' ? (a.companyName || '') : (a.lastName || '');
        const nameB = b.customerType === 'firemní' ? (b.companyName || '') : (b.lastName || '');
        return nameA.localeCompare(nameB, 'cs');
      });
  }, [customers, search, selectedLetter, vehicles]);

  const handleOpenAdd = () => {
    setEditingCustomer(null);
    setFormData(initialFormData);
    setIsAddModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      customerType: customer.customerType || 'soukromý',
      firstName: customer.firstName || '',
      lastName: customer.lastName || '',
      email: customer.email || '',
      phone: customer.phone || '',
      address: customer.address || '',
      companyName: customer.companyName || '',
      companyAddress: customer.companyAddress || '',
      ico: customer.ico || '',
      dic: customer.dic || '',
      contactPerson: customer.contactPerson || ''
    });
    setIsAddModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const submissionData = {
      ...formData,
      firstName: formData.customerType === 'soukromý' ? formData.firstName.trim() : '',
      lastName: formData.customerType === 'soukromý' ? formData.lastName.trim() : '',
      companyName: formData.customerType === 'firemní' ? formData.companyName.trim() : undefined,
      companyAddress: formData.companyAddress.trim() || undefined,
      ico: formData.ico.trim() || undefined,
      dic: formData.dic.trim() || undefined,
      contactPerson: formData.customerType === 'firemní' ? formData.contactPerson.trim() : undefined
    };

    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...submissionData
        } as Customer);
      }
    } else {
      const newCustomer: Customer = {
        ...submissionData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      } as Customer;
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData(initialFormData);
  };

  const confirmDelete = () => {
    if (deletingCustomer && onDeleteCustomer) {
      onDeleteCustomer(deletingCustomer.id);
      setDeletingCustomer(null);
    }
  };

  const handleViewVehicle = (vehicleId: string) => {
    if (onNavigateToVehicle) {
      onNavigateToVehicle(vehicleId);
      setSelectedVehiclesCustomer(null);
    }
  };

  const customerVehicles = selectedVehiclesCustomer 
    ? vehicles.filter(v => v.customerId === selectedVehiclesCustomer.id)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zákazníci</h2>
          <p className="text-slate-500 font-medium">Správa kontaktů a klientských karet.</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg"
        >
          <UserPlus className="w-5 h-5" />
          Nový zákazník
        </button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
          {search && (
            <button 
              onClick={() => onSearchChange('')}
              className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
            >
              Zrušit filtr
            </button>
          )}
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <button 
            onClick={() => setSelectedLetter(null)}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-500 border border-slate-100'}`}
          >
            VŠE
          </button>
          {alphabet.map(letter => (
            <button 
              key={letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-500 border border-slate-100'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.map(c => (
          <div key={c.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative overflow-visible">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === c.id ? null : c.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === c.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-6 h-6" />
                </button>

                {openMenuId === c.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleOpenEdit(c)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit
                    </button>
                    <button 
                      onClick={() => { setDeletingCustomer(c); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-6">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg ${c.customerType === 'firemní' ? 'bg-slate-900' : 'bg-blue-600'}`}>
                {c.customerType === 'firemní' ? <Building2 className="w-8 h-8" /> : <UserIcon className="w-8 h-8" />}
              </div>
              <div>
                <h3 className="text-lg font-black text-slate-900 leading-tight">
                  {c.customerType === 'firemní' ? (c.companyName || `${c.lastName} ${c.firstName}`) : `${c.lastName} ${c.firstName}`}
                </h3>
                <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md mt-1 inline-block ${c.customerType === 'firemní' ? 'bg-slate-100 text-slate-600' : 'bg-blue-50 text-blue-600'}`}>
                  {c.customerType === 'firemní' ? 'FIRMA' : 'SOUKROMÝ'}
                </span>
              </div>
            </div>

            <div className="space-y-3 pt-4 border-t border-slate-50">
              <div className="flex items-center gap-3 text-slate-600">
                <Mail className="w-4 h-4" />
                <span className="text-sm font-semibold truncate">{c.email || 'Bez e-mailu'}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-600">
                <Phone className="w-4 h-4" />
                <span className="text-sm font-semibold">{c.phone}</span>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedDetailCustomer(c)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase"
              >
                Detail
              </button>
              <button 
                onClick={() => setSelectedVehiclesCustomer(c)}
                className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-colors uppercase"
              >
                Vozidla
              </button>
            </div>
          </div>
        ))}
      </div>

      {deletingCustomer && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingCustomer(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 p-8 text-center">
            <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
            <h3 className="text-2xl font-black text-slate-900 mb-2">Opravdu smazat?</h3>
            <p className="text-slate-500 mb-8">Smazání zákazníka {deletingCustomer.lastName} je nevratné.</p>
            <div className="flex gap-3">
              <button onClick={() => setDeletingCustomer(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-bold">ZRUŠIT</button>
              <button onClick={confirmDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-bold">SMAZAT</button>
            </div>
          </div>
        </div>
      )}

      {selectedDetailCustomer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedDetailCustomer(null)}></div>
          <div className="bg-white w-full max-w-lg rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <h3 className="text-xl font-black tracking-tight">Detail zákazníka</h3>
              <button onClick={() => setSelectedDetailCustomer(null)}><X className="w-6 h-6" /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div><p className="text-[10px] font-black text-slate-400 uppercase">Jméno</p><p className="font-bold">{selectedDetailCustomer.lastName} {selectedDetailCustomer.firstName}</p></div>
                <div><p className="text-[10px] font-black text-slate-400 uppercase">Email</p><p className="font-bold">{selectedDetailCustomer.email || 'N/A'}</p></div>
                <div><p className="text-[10px] font-black text-slate-400 uppercase">Telefon</p><p className="font-bold">{selectedDetailCustomer.phone}</p></div>
                <div className="col-span-2"><p className="text-[10px] font-black text-slate-400 uppercase">Adresa</p><p className="font-bold">{selectedDetailCustomer.address}</p></div>
              </div>
              <button onClick={() => setSelectedDetailCustomer(null)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold">ZAVŘÍT</button>
            </div>
          </div>
        </div>
      )}

      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <h3 className="text-2xl font-black">{editingCustomer ? 'Upravit zákazníka' : 'Nový zákazník'}</h3>
              <button onClick={() => setIsAddModalOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto custom-scrollbar">
              <div className="grid grid-cols-2 gap-4">
                <input required placeholder="Jméno" className="w-full bg-slate-50 p-4 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-blue-500" value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} />
                <input required placeholder="Příjmení" className="w-full bg-slate-50 p-4 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-blue-500" value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} />
              </div>
              <input required placeholder="Adresa" className="w-full bg-slate-50 p-4 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-blue-500" value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
              <div className="grid grid-cols-2 gap-4">
                <input type="email" placeholder="Email" className="w-full bg-slate-50 p-4 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-blue-500" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                <input required placeholder="Telefon" className="w-full bg-slate-50 p-4 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-blue-500" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-blue-700 transition-all">{editingCustomer ? 'ULOŽIT ZMĚNY' : 'ULOŽIT ZÁKAZNÍKA'}</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerManager;

