interface VehicleManagerProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle: (v: Vehicle) => void;
  onUpdateVehicle: (v: Vehicle) => void;
  onDeleteVehicle: (id: string) => void;
  onNavigateToCustomer: (id: string) => void;
  onNavigateToOrder: (id: string) => void;
  onCreateOrder: (id: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const VehicleManager: React.FC<VehicleManagerProps> = ({ 
  vehicles, 
  customers, 
  services,
  onAddVehicle, 
  onUpdateVehicle, 
  onDeleteVehicle,
  onCreateOrder,
  onNavigateToOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);
  const [historyVehicle, setHistoryVehicle] = useState<Vehicle | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData: Partial<Vehicle> = {
    make: 'Škoda',
    model: '',
    year: new Date().getFullYear(),
    vin: '',
    licensePlate: '',
    mileage: 0,
    engineCode: '',
    color: '',
    stkExpirationDate: '',
    nextServiceDate: '',
    customerId: customers[0]?.id || ''
  };

  const [formData, setFormData] = useState<Partial<Vehicle>>(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    if (initialVehicleId) {
      const v = vehicles.find(item => item.id === initialVehicleId);
      if (v) setSelectedVehicle(v);
    }
  }, [initialVehicleId, vehicles]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredVehicles = useMemo(() => {
    return vehicles.filter(v => {
      const matchesSearch = 
        v.licensePlate.toLowerCase().includes(search.toLowerCase()) ||
        v.make.toLowerCase().includes(search.toLowerCase()) ||
        v.model.toLowerCase().includes(search.toLowerCase());
      return matchesSearch;
    }).sort((a, b) => a.make.localeCompare(b.make));
  }, [vehicles, search]);

  const handleAddNew = () => {
    setEditingVehicle(null);
    setFormData(initialFormData);
    setIsModalOpen(true);
  };

  const handleEdit = (v: Vehicle) => {
    setEditingVehicle(v);
    setFormData(v);
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingVehicle) {
      onUpdateVehicle({ ...editingVehicle, ...formData } as Vehicle);
    } else {
      onAddVehicle({ ...formData, id: `v${Date.now()}` } as Vehicle);
    }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Vozidla</h2>
          <p className="text-slate-500 font-medium">Evidence vozového parku.</p>
        </div>
        <button onClick={handleAddNew} className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 shadow-lg flex items-center gap-2">
          <Plus className="w-5 h-5" /> Nové vozidlo
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input type="text" placeholder="Hledat vozidlo..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVehicles.map(v => (
          <div key={v.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative">
            <div className="absolute top-0 right-0 p-4">
              <button onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)} className="p-2 text-slate-300 hover:text-slate-900"><MoreHorizontal className="w-6 h-6" /></button>
              {openMenuId === v.id && (
                <div ref={menuRef} className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-50">
                  <button onClick={() => handleEdit(v)} className="w-full text-left px-4 py-3 rounded-xl hover:bg-slate-50 text-sm font-bold">Upravit</button>
                  <button onClick={() => { onCreateOrder(v.id); setOpenMenuId(null); }} className="w-full text-left px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 text-sm font-bold">Vytvořit zakázku</button>
                  <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full text-left px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 text-sm font-bold">Smazat</button>
                </div>
              )}
            </div>

            <div className="flex items-center gap-5 mb-4">
              <div className="w-16 h-16 rounded-2xl bg-slate-900 flex items-center justify-center text-white shadow-lg"><Car className="w-8 h-8" /></div>
              <div>
                <h3 className="text-lg font-black">{v.make} {v.model}</h3>
                <p className="text-blue-600 font-black font-mono tracking-widest">{v.licensePlate}</p>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button onClick={() => setSelectedVehicle(v)} className="flex-1 py-3 bg-slate-100 rounded-xl font-bold text-xs">Detail</button>
              <button onClick={() => setHistoryVehicle(v)} className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs">Historie</button>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2rem] shadow-2xl relative z-10 overflow-hidden">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center">
              <h3 className="text-2xl font-black">{editingVehicle ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="w-6 h-6" /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <input placeholder="Značka" className="bg-slate-50 p-4 rounded-2xl font-bold outline-none" value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} />
                <input placeholder="Model" className="bg-slate-50 p-4 rounded-2xl font-bold outline-none" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} />
              </div>
              <input placeholder="SPZ" className="bg-slate-50 p-4 rounded-2xl font-bold outline-none" value={formData.licensePlate} onChange={e => setFormData({...formData, licensePlate: e.target.value.toUpperCase()})} />
              <button type="submit" className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl">ULOŽIT VOZIDLO</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

