};

const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers,
  invoices,
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  preselectedVehicleId,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
  const [isPriceListPickerOpen, setIsPriceListPickerOpen] = useState(false);
  const [isTemplatePickerOpen, setIsTemplatePickerOpen] = useState(false);

  const [isAiImportOpen, setIsAiImportOpen] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiImportItems, setAiImportItems] = useState<Partial<PartItem>[]>([]);
  const [selectedAiIndices, setSelectedAiIndices] = useState<Set<number>>(new Set());

  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState({
    id: '',
    vehicleId: '',
    description: '',
    parts: [] as PartItem[],
    date: new Date().toISOString().split('T')[0],
    technician: technicians[0] || '',
    laborHours: 0,
    status: 'naplánováno' as ServiceRecord['status'],
    fuelLevel: '50%' as ServiceRecord['fuelLevel'],
    mileageAtEntry: 0,
    estimatedPrice: 0,
    paymentType: 'Hotovost' as ServiceRecord['paymentType'],
    checklist: {
      rezerva: false, zvedak: false, klic: false, bezp_klic: false,
      trojuhelnik: false, lekarna: false, lepeni: false
    } as VehicleChecklist,
    attachments: [] as VehicleAttachment[],
    returnParts: 'nevracet' as 'vrátit' | 'nevracet'
  });

  const materialCost = useMemo(() => {
    return (formData.parts || []).reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  }, [formData.parts]);

  const calculatedCost = useMemo(() => {
    return (formData.laborHours * hourlyRate) + materialCost;
  }, [formData.laborHours, materialCost, hourlyRate]);

  const resetForm = (vId?: string) => {
    const selectedVeh = vId ? vehicles.find(v => v.id === vId) : null;
    setFormData({
      id: '',
      vehicleId: vId || '',
      description: '',
      parts: [] as PartItem[],
      date: new Date().toISOString().split('T')[0],
      technician: technicians[0] || '',
      laborHours: 0,
      status: 'naplánováno',
      fuelLevel: '50%',
      mileageAtEntry: selectedVeh ? selectedVeh.mileage : 0,
      estimatedPrice: 0,
      paymentType: 'Hotovost',
      checklist: {
        rezerva: false, zvedak: false, klic: false, bezp_klic: false,
        trojuhelnik: false, lekarna: false, lepeni: false
      },
      attachments: [],
      returnParts: 'nevracet'
    });
  };

  const handleAddNew = (vId?: string) => {
    resetForm(vId);
    setEditingOrderId(null);
    setIsModalOpen(true);
  };

  useEffect(() => {
    if (autoOpen) {
      handleAddNew(preselectedVehicleId || undefined);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, preselectedVehicleId]);

  const handleEdit = (order: ServiceRecord) => {
    setEditingOrderId(order.id);
    setFormData({
      ...order,
      parts: order.parts || [],
      attachments: order.attachments || []
    } as any);
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalId = editingOrderId || `SR-${Date.now()}`;
    const serviceData: ServiceRecord = { ...formData, id: finalId, cost: calculatedCost } as any;
    if (editingOrderId) onUpdateService(serviceData);
    else onAddService(serviceData);
    setIsModalOpen(false);
  };

  const filteredOrders = useMemo(() => {
    return services.filter(order => {
      const vehicle = vehicles.find(v => v.id === order.vehicleId);
      if (!search) return true;
      return order.id.toLowerCase().includes(search.toLowerCase()) || (vehicle?.licensePlate || "").toLowerCase().includes(search.toLowerCase());
    });
  }, [services, vehicles, search]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zakázky</h2>
          <p className="text-slate-500 font-medium">Správa servisních listů.</p>
        </div>
        <button onClick={() => handleAddNew()} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold shadow-lg flex items-center gap-2">
          <Plus className="w-5 h-5" /> Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input type="text" placeholder="Hledat zakázku..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12">
        {filteredOrders.map(order => (
          <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-[1100px] h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h3 className="text-xl font-black uppercase">Editace Zakázky</h3>
              <div className="flex gap-4">
                <button onClick={handleSubmit} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-xl hover:bg-blue-700"><Check className="w-5 h-5" /> ULOŽIT</button>
                <button onClick={() => setIsModalOpen(false)}><X className="w-6 h-6" /></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar">
              <div className="bg-white shadow-xl p-10 font-sans text-black w-full max-w-[210mm] min-h-full">
                <PrintTemplate order={{...formData, id: editingOrderId || 'NÁVRH', cost: calculatedCost}} company={companyInfo} vehicles={vehicles} customers={customers} isEditable={true} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

