  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [deletingInvoice, setDeletingInvoice] = useState<Invoice | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const today = new Date().toISOString().split('T')[0];

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => {
      if (inv.archived) return false;
      const customer = customers.find(c => c.id === inv.customerId);
      const searchLower = search.toLowerCase();
      return (
        inv.id.toLowerCase().includes(searchLower) ||
        (customer?.lastName || '').toLowerCase().includes(searchLower) ||
        (inv.vehicleInfo || "").toLowerCase().includes(searchLower)
      );
    });
  }, [invoices, customers, search]);

  const { unpaidInvoices, paidInvoices } = useMemo(() => ({
    unpaidInvoices: filteredInvoices.filter(inv => inv.status === 'neuhrazeno'),
    paidInvoices: filteredInvoices.filter(inv => inv.status === 'uhrazeno')
  }), [filteredInvoices]);

  const handlePrint = () => window.print();

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Faktury</h2>
          <p className="text-slate-500 font-medium">Správa daňových dokladů.</p>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
        <Search className="w-5 h-5 text-slate-400" />
        <input type="text" placeholder="Hledat fakturu..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <h3 className="text-sm font-black text-blue-600 uppercase tracking-widest px-2">K ÚHRADĚ</h3>
          {unpaidInvoices.map(inv => (
            <InvoiceCard key={inv.id} inv={inv} customers={customers} today={today} onSelect={setSelectedInvoice} onDelete={setDeletingInvoice} onUpdateStatus={onUpdateInvoiceStatus} openMenuId={openMenuId} onOpenMenu={setOpenMenuId} />
          ))}
        </div>
        <div className="space-y-4">
          <h3 className="text-sm font-black text-emerald-600 uppercase tracking-widest px-2">UHRAZENO</h3>
          {paidInvoices.map(inv => (
            <InvoiceCard key={inv.id} inv={inv} customers={customers} today={today} onSelect={setSelectedInvoice} onDelete={setDeletingInvoice} onUpdateStatus={onUpdateInvoiceStatus} openMenuId={openMenuId} onOpenMenu={setOpenMenuId} />
          ))}
        </div>
      </div>

      {selectedInvoice && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedInvoice(null)}></div>
          <div className="bg-white w-full max-w-6xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h3 className="text-xl font-black uppercase">Faktura {selectedInvoice.id}</h3>
              <div className="flex gap-4">
                <button onClick={handlePrint} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-xs shadow-xl flex items-center gap-2 hover:bg-blue-700"><Printer className="w-4 h-4" /> TISK</button>
                <button onClick={() => setSelectedInvoice(null)}><X className="w-6 h-6 text-slate-400" /></button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar">
               <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const InvoiceCard: React.FC<any> = ({ inv, customers, today, onSelect, onDelete, onUpdateStatus, openMenuId, onOpenMenu }) => {
  const customer = customers.find((c: any) => c.id === inv.customerId);
  const isOverdue = inv.status === 'neuhrazeno' && inv.dueDate < today;

  return (
    <div className={`bg-white rounded-3xl border p-6 shadow-sm hover:shadow-xl transition-all cursor-pointer ${isOverdue ? 'border-red-200' : 'border-slate-100'}`} onClick={() => onSelect(inv)}>
      <div className="flex items-center gap-4 mb-4">
        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md ${inv.status === 'uhrazeno' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}><Receipt className="w-6 h-6" /></div>
        <div><h4 className="text-base font-black">{inv.id}</h4><p className="text-[10px] font-bold text-slate-400">{formatDate(inv.issueDate)}</p></div>
      </div>
      <p className="text-sm font-bold truncate">{customer?.lastName || 'Neznámý'}</p>
      <div className="pt-4 mt-4 border-t flex justify-between items-center">
        <span className="text-lg font-black">{inv.totalInclDph.toLocaleString()} Kč</span>
        <button onClick={(e) => { e.stopPropagation(); onUpdateStatus(inv.id, inv.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno'); }} className="text-[10px] font-black uppercase text-blue-600">STAV</button>
      </div>
    </div>
  );
};

