import React, { useState, useMemo } from 'react';
import { 
  BarChart3, TrendingUp, Coins, Users, Car, CheckCircle2, 
  Calendar, ArrowUpRight, ArrowDownRight, Briefcase, Wallet, Calculator,
  AlertCircle
} from 'lucide-react';
import { ServiceRecord, Invoice, Vehicle, Customer, StatsSettings } from '../types';

interface StatsManagerProps {
  services: ServiceRecord[];
  invoices: Invoice[];
  vehicles: Vehicle[];
  customers: Customer[];
  statsSettings: StatsSettings;
}

type Period = 'week' | 'month' | 'all';

const StatsManager: React.FC<StatsManagerProps> = ({ services, invoices, vehicles, customers, statsSettings }) => {
  const [period, setPeriod] = useState<Period>('all');

  const stats = useMemo(() => {
    const now = new Date();

    const filterByPeriod = (dateStr: string) => {
      if (period === 'all') return true;
      const date = new Date(dateStr);
      if (period === 'month') {
        return date.getMonth() === now.getMonth() && date.getFullYear() === now.getFullYear();
      }
      if (period === 'week') {
        const startOfWeek = new Date(now);
        const day = now.getDay();
        const diff = now.getDate() - day + (day === 0 ? -6 : 1);
        startOfWeek.setDate(diff);
        startOfWeek.setHours(0, 0, 0, 0);
        return date >= startOfWeek;
      }
      return true;
    };

    const periodServices = services.filter(s => filterByPeriod(s.date));
    const periodInvoices = invoices.filter(inv => filterByPeriod(inv.issueDate));

    const completedOrders = periodServices.filter(s => s.status === 'hotovo').length;

    const turnover = periodInvoices.reduce((sum, inv) => sum + (Number(inv.totalExclDph) || 0), 0);
    const materialAndPartsCosts = periodInvoices.reduce((sum, inv) => sum + (Number(inv.costs) || 0), 0);

    // Výpočet provozních nákladů podle dynamického seznamu
    let overheadCosts = 0;
    const costItems = statsSettings.costItems || [];

    const recurringSum = costItems.filter(item => item.isRecurring).reduce((sum, item) => sum + item.amount, 0);
    const oneTimeSum = costItems.filter(item => !item.isRecurring).reduce((sum, item) => sum + item.amount, 0);

    if (period === 'month') {
      overheadCosts = recurringSum + oneTimeSum;
    } else if (period === 'week') {
      overheadCosts = (recurringSum / 4) + oneTimeSum;
    } else {
      // Pro 'vše' spočítáme počet unikátních měsíců, kde jsou vystavené faktury
      const uniqueMonths = new Set(invoices.map(inv => inv.issueDate.substring(0, 7)));
      const monthsCount = Math.max(1, uniqueMonths.size);
      overheadCosts = (monthsCount * recurringSum) + oneTimeSum;
    }

    const totalCosts = materialAndPartsCosts + overheadCosts;
    const netProfit = turnover - totalCosts;

    return {
      completedOrders,
      turnover: Math.round(turnover),
      netProfit: Math.round(netProfit),
      totalCosts: Math.round(totalCosts),
      overheadCosts: Math.round(overheadCosts),
      materialCosts: Math.round(materialAndPartsCosts),
      invoiceCount: periodInvoices.length
    };
  }, [services, invoices, period, statsSettings]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Statistiky servisu</h2>
          <p className="text-slate-500 font-medium">Ekonomický přehled a výkonnostní ukazatele.</p>
        </div>

        <div className="bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm flex gap-1">
          {[
            { id: 'week', label: 'Týden' },
            { id: 'month', label: 'Měsíc' },
            { id: 'all', label: 'Vše' }
          ].map((p) => (
            <button
              key={p.id}
              onClick={() => setPeriod(p.id as Period)}
              className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${
                period === p.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
                  : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              {p.label.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6">
        <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm relative overflow-hidden group hover:shadow-xl transition-all">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:scale-110 transition-transform">
            <TrendingUp className="w-32 h-32 text-blue-900" />
          </div>
          <div className="relative z-10">
            <div className="w-12 h-12 rounded-2xl bg-blue-50 flex items-center justify-center mb-6">
              <Coins className="w-6 h-6 text-blue-600" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Celkový obrat (bez DPH)</p>
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter">
              {stats.turnover.toLocaleString()} Kč
            </h3>
            <div className="mt-4 flex items-center gap-2 text-blue-600">
              <ArrowUpRight className="w-4 h-4" />
              <span className="text-xs font-bold uppercase">z {stats.invoiceCount} faktur</span>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm relative overflow-hidden group hover:shadow-xl transition-all">
          <div className="relative z-10">
            <div className="w-12 h-12 rounded-2xl bg-red-50 flex items-center justify-center mb-6 text-red-600">
              <Calculator className="w-6 h-6" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Celkové výdaje</p>
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter">
              {stats.totalCosts.toLocaleString()} Kč
            </h3>
            <div className="mt-4 flex flex-col gap-1">
               <div className="flex items-center gap-2 text-red-500">
                  <ArrowDownRight className="w-3 h-3" />
                  <span className="text-[9px] font-bold uppercase">Materiál: {stats.materialCosts.toLocaleString()} Kč</span>
               </div>
               <div className="flex items-center gap-2 text-slate-400">
                  <ArrowDownRight className="w-3 h-3" />
                  <span className="text-[9px] font-bold uppercase">Provoz: {stats.overheadCosts.toLocaleString()} Kč</span>
               </div>
            </div>
          </div>
        </div>

        <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform">
            <BarChart3 className="w-32 h-32 text-emerald-400" />
          </div>
          <div className="relative z-10">
            <div className="w-12 h-12 rounded-2xl bg-emerald-500/20 flex items-center justify-center mb-6 border border-emerald-500/30">
              <TrendingUp className="w-6 h-6 text-emerald-400" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Čistý zisk</p>
            <h3 className="text-3xl font-black text-white tracking-tighter">
              {stats.netProfit.toLocaleString()} Kč
            </h3>
            <div className="mt-4 flex items-center gap-2 text-emerald-400">
              <CheckCircle2 className="w-4 h-4" />
              <span className="text-xs font-bold uppercase">Po odečtení všech nákladů</span>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm relative overflow-hidden group hover:shadow-xl transition-all">
          <div className="relative z-10">
            <div className="w-12 h-12 rounded-2xl bg-amber-50 flex items-center justify-center mb-6">
              <CheckCircle2 className="w-6 h-6 text-amber-600" />
            </div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Hotové zakázky</p>
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter">
              {stats.completedOrders}
            </h3>
            <p className="text-xs font-bold text-slate-400 mt-4 uppercase">Úspěšně odbaveno v období</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-[2.5rem] p-10 border border-slate-100 shadow-sm">
           <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-8 flex items-center gap-3">
              <Briefcase className="w-5 h-5 text-blue-600" />
              Stav databáze
           </h4>
           <div className="grid grid-cols-2 gap-8">
              <div className="space-y-2">
                 <div className="flex items-center gap-2 text-slate-400">
                    <Users className="w-4 h-4" />
                    <span className="text-[10px] font-black uppercase tracking-tighter">Zákazníci</span>
                 </div>
                 <p className="text-3xl font-black text-slate-900">{customers.length}</p>
              </div>
              <div className="space-y-2">
                 <div className="flex items-center gap-2 text-slate-400">
                    <Car className="w-4 h-4" />
                    <span className="text-[10px] font-black uppercase tracking-tighter">Vozidla</span>
                 </div>
                 <p className="text-3xl font-black text-slate-900">{vehicles.length}</p>
              </div>
           </div>
        </div>

        <div className="bg-slate-50 rounded-[2.5rem] p-10 border border-slate-100">
           <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6">Rozdělení financí</h4>
           <div className="space-y-6">
              <div className="space-y-2">
                 <div className="flex justify-between items-end">
                    <span className="text-[10px] font-black text-slate-400 uppercase">Všechny náklady</span>
                    <span className="text-sm font-black text-slate-900">{stats.totalCosts.toLocaleString()} Kč</span>
                 </div>
                 <div className="h-3 bg-slate-200 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-red-400 transition-all duration-1000" 
                      style={{ width: `${stats.turnover > 0 ? (stats.totalCosts / stats.turnover) * 100 : 0}%` }}
                    />
                 </div>
              </div>
              <div className="space-y-2">
                 <div className="flex justify-between items-end">
                    <span className="text-[10px] font-black text-slate-400 uppercase">Zisk</span>
                    <span className="text-sm font-black text-emerald-600">{stats.netProfit.toLocaleString()} Kč</span>
                 </div>
                 <div className="h-3 bg-slate-200 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-emerald-500 transition-all duration-1000" 
                      style={{ width: `${stats.turnover > 0 ? (stats.netProfit / stats.turnover) * 100 : 0}%` }}
                    />
                 </div>
              </div>
           </div>
        </div>
      </div>

      {stats.invoiceCount === 0 && period !== 'all' && (
        <div className="bg-amber-50 border border-amber-100 p-6 rounded-3xl flex items-center gap-4 text-amber-700">
          <AlertCircle className="w-6 h-6" />
