const navItems = [
  { id: 'dashboard', label: 'Nástěnka', icon: LayoutDashboard },
  { id: 'orders', label: 'Zakázky', icon: ClipboardList },
  { id: 'invoices', label: 'Fakturace', icon: Receipt },
  { id: 'customers', label: 'Zákazníci', icon: Users },
  { id: 'vehicles', label: 'Vozidla', icon: Car },
  { id: 'archive', label: 'Archiv', icon: Archive },
  { id: 'stats', label: 'Statistiky', icon: BarChart3 },
  { id: 'settings', label: 'Nastavení', icon: SettingsIcon },
];

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<AppView>('dashboard');

  const [targetVehicleId, setTargetVehicleId] = useState<string | null>(null);
  const [targetOrderId, setTargetOrderId] = useState<string | null>(null);
  const [targetCustomerId, setTargetCustomerId] = useState<string | null>(null);
  const [shouldOpenModal, setShouldOpenModal] = useState(false);

  const [customerSearch, setCustomerSearch] = useState('');
  const [vehicleSearch, setVehicleSearch] = useState('');
  const [orderSearch, setOrderSearch] = useState('');
  const [invoiceSearch, setInvoiceSearch] = useState('');
  const [archiveSearch, setArchiveSearch] = useState('');

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : INITIAL_CUSTOMERS;
  });
  const [vehicles, setVehicles] = useState<Vehicle[]>(() => {
    const saved = localStorage.getItem('vehicles');
    return saved ? JSON.parse(saved) : INITIAL_VEHICLES;
  });
  const [services, setServices] = useState<ServiceRecord[]>(() => {
    const saved = localStorage.getItem('services');
    return saved ? JSON.parse(saved) : INITIAL_SERVICES;
  });
  const [invoices, setInvoices] = useState<Invoice[]>(() => {
    const saved = localStorage.getItem('invoices');
    const data = saved ? JSON.parse(saved) : [];
    // Migrace: doplnění chybějících uid u starších dat v localStorage
    return data.map((inv: any) => ({ ...inv, uid: inv.uid || `inv-uid-${Math.random().toString(36).substr(2, 9)}` }));
  });

  const [hourlyRate, setHourlyRate] = useState<number>(() => {
    const saved = localStorage.getItem('hourlyRate');
    return saved ? JSON.parse(saved) : 850;
  });
  const [fixedServices, setFixedServices] = useState<FixedService[]>(() => {
    const saved = localStorage.getItem('fixedServices');
    return saved ? JSON.parse(saved) : INITIAL_FIXED_SERVICES;
  });
  const [predefinedTasks, setPredefinedTasks] = useState<PredefinedTask[]>(() => {
    const saved = localStorage.getItem('predefinedTasks');
    return saved ? JSON.parse(saved) : INITIAL_PREDEFINED_TASKS;
  });
  const [discountLevels, setDiscountLevels] = useState<number[]>(() => {
    const saved = localStorage.getItem('discountLevels');
    return saved ? JSON.parse(saved) : [0, 5, 10, 15, 20, 25, 50];
  });
  const [technicians, setTechnicians] = useState<string[]>(() => {
    const saved = localStorage.getItem('technicians');
    return saved ? JSON.parse(saved) : ['Jan Mechanik', 'Petr Rychlý', 'Marek Šikovný', 'Tomáš Pečlivý'];
  });
  const [companyInfo, setCompanyInfo] = useState<CompanyInfo>(() => {
    const saved = localStorage.getItem('companyInfo');
    const defaults = {
      name: 'AutoService Pro Praha',
      address: 'Průmyslová 1024/12, 102 00 Praha 10',
      ico: '12345678',
      dic: 'CZ12345678',
      phone: '+420 222 333 444',
      email: 'servis@autoservice.pro',
      bankAccount: '',
      isVatPayer: false,
      foundationDate: '2001-02-07'
    };
    try {
      return saved ? { ...defaults, ...JSON.parse(saved) } : defaults;
    } catch {
      return defaults;
    }
  });
  const [notifSettings, setNotifSettings] = useState<NotificationSettings>(() => {
    const saved = localStorage.getItem('notifSettings');
    return saved ? JSON.parse(saved) : {
      stkThresholdDays: 30,
      serviceThresholdDays: 15
    };
  });

  const [statsSettings, setStatsSettings] = useState<StatsSettings>(() => {
    const saved = localStorage.getItem('statsSettings');
    try {
      return saved ? JSON.parse(saved) : { costItems: [] };
    } catch {
      return { costItems: [] };
    }
  });

  const [selectedPrinter, setSelectedPrinter] = useState<string>(() => {
    const saved = localStorage.getItem('selectedPrinter');
    return saved ? JSON.parse(saved) : 'HP LaserJet Pro M404dn (Kancelář)';
  });

  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('userSettings');
    return saved ? JSON.parse(saved) : { enabled: false, username: 'admin', password: '' };
  });
  const [isAuthenticated, setIsAuthenticated] = useState(!userSettings.enabled);

  const [autoBackupSettings, setAutoBackupSettings] = useState<AutoBackupSettings>(() => {
    const saved = localStorage.getItem('autoBackupSettings');
    return saved ? JSON.parse(saved) : { enabled: false, hour: 20, lastBackupDate: null, folderName: null };
  });

  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);
  useEffect(() => { localStorage.setItem('vehicles', JSON.stringify(vehicles)); }, [vehicles]);
  useEffect(() => { localStorage.setItem('services', JSON.stringify(services)); }, [services]);
  useEffect(() => { localStorage.setItem('invoices', JSON.stringify(invoices)); }, [invoices]);
  useEffect(() => { localStorage.setItem('hourlyRate', JSON.stringify(hourlyRate)); }, [hourlyRate]);
  useEffect(() => { localStorage.setItem('fixedServices', JSON.stringify(fixedServices)); }, [fixedServices]);
  useEffect(() => { localStorage.setItem('predefinedTasks', JSON.stringify(predefinedTasks)); }, [predefinedTasks]);
  useEffect(() => { localStorage.setItem('discountLevels', JSON.stringify(discountLevels)); }, [discountLevels]);
  useEffect(() => { localStorage.setItem('technicians', JSON.stringify(technicians)); }, [technicians]);
  useEffect(() => { localStorage.setItem('companyInfo', JSON.stringify(companyInfo)); }, [companyInfo]);
  useEffect(() => { localStorage.setItem('notifSettings', JSON.stringify(notifSettings)); }, [notifSettings]);
  useEffect(() => { localStorage.setItem('statsSettings', JSON.stringify(statsSettings)); }, [statsSettings]);
  useEffect(() => { localStorage.setItem('selectedPrinter', JSON.stringify(selectedPrinter)); }, [selectedPrinter]);
  useEffect(() => { 
    localStorage.setItem('userSettings', JSON.stringify(userSettings));
    if (!userSettings.enabled) {
      setIsAuthenticated(true);
    }
  }, [userSettings]);

  const syncVehicleMileage = useCallback((vehicleId: string, mileageAtEntry?: number) => {
    if (mileageAtEntry === undefined || mileageAtEntry === null || mileageAtEntry === 0) return;
    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === vehicleId && mileageAtEntry > v.mileage) {
        return { ...v, mileage: mileageAtEntry };
      }
      return v;
    }));
  }, []);

  const syncVehicleDates = useCallback((service: ServiceRecord) => {
    if (service.status !== 'hotovo') return;

    const parts = service.parts || [];
    const hasSTK = parts.some(p => p.description.toLowerCase().includes('ek+tk'));
    const hasOil = parts.some(p => 
      p.description.toLowerCase().includes('motorovy olej') || 
      p.description.toLowerCase().includes('motorový olej')
    );

    if (!hasSTK && !hasOil) return;

    const baseDateStr = service.deliveryDate || service.date;
    const baseDate = new Date(baseDateStr);
    if (isNaN(baseDate.getTime())) return;

    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === service.vehicleId) {
        let updates: Partial<Vehicle> = {};

        if (hasSTK) {
          const nextSTK = new Date(baseDate);
          nextSTK.setFullYear(nextSTK.getFullYear() + 2);
          updates.stkExpirationDate = nextSTK.toISOString().split('T')[0];
        }

        if (hasOil) {
          const nextService = new Date(baseDate);
          const intervalMonths = v.serviceIntervalMonths || 12;
          nextService.setMonth(nextService.getMonth() + intervalMonths);
          updates.nextServiceDate = nextService.toISOString().split('T')[0];
        }

        return { ...v, ...updates };
      }
      return v;
    }));
  }, []);

  const handleAddService = (service: ServiceRecord) => {
    setServices(prev => [service, ...prev]);
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
    syncVehicleDates(service);
  };

  const handleUpdateService = (service: ServiceRecord) => {
    setServices(prev => prev.map(item => item.id === service.id ? service : item));
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
    syncVehicleDates(service);
  };

  const handleUpdateInvoice = (updatedInvoice: Invoice) => {
    setInvoices(prev => prev.map(inv => inv.uid === updatedInvoice.uid ? updatedInvoice : inv));
  };

  const handleCreateInvoiceFromOrder = (orderId: string) => {
    const order = services.find(s => s.id === orderId);
    if (!order) return;

    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    if (!vehicle) return;

    const existingInvoice = invoices.find(inv => inv.orderId === orderId);
    if (existingInvoice) {
      setActiveView('invoices');
      return;
    }

    const invoiceItems: PartItem[] = [];
    let calculatedTotalCosts = 0;

    if (order.parts && order.parts.length > 0) {
      order.parts.forEach(p => {
        invoiceItems.push({ ...p });
        calculatedTotalCosts += (p.costPrice || 0) * p.quantity;
      });
    }

    if (order.laborHours && order.laborHours > 0) {
      invoiceItems.push({ 
        id: `labor-${Date.now()}`, 
        description: `Servisní práce (${order.laborHours} h)`, 
        quantity: order.laborHours, 
        unit: 'h', 
        unitPrice: hourlyRate,
        costPrice: 0 
      });
    }

    if (invoiceItems.length === 0 && order.cost > 0) {
      invoiceItems.push({
        id: `fallback-${Date.now()}`,
        description: 'Servisní práce a materiál (dle zakázky)',
        quantity: 1,
        unit: 'ks',
        unitPrice: order.cost,
        costPrice: 0
      });
    }

    const taxDateStr = order.deliveryDate || order.date;
    const issueDate = new Date(taxDateStr);
    const dueDate = new Date(issueDate);
    dueDate.setDate(dueDate.getDate() + 14);

    const yearPrefix = new Date().getFullYear().toString().slice(-2);
    const monthPrefix = (new Date().getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${yearPrefix}/${monthPrefix}/`;

    setInvoices(prevInvoices => {
      const monthlyInvoices = prevInvoices.filter(inv => inv.id.startsWith(prefix));
      const nextSequence = (monthlyInvoices.length + 1).toString().padStart(3, '0');
      const invoiceId = `${prefix}${nextSequence}`;

      const calculatedTotalExclDph = invoiceItems.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);

      const newInvoice: Invoice = {
        uid: `inv-uid-${Math.random().toString(36).substr(2, 9)}`,
        id: invoiceId,
        orderId: order.id,
        issueDate: taxDateStr,
        dueDate: dueDate.toISOString().split('T')[0],
        customerId: vehicle.customerId,
        vehicleInfo: `${vehicle.make} ${vehicle.model} (${vehicle.licensePlate})`,
        items: invoiceItems,
        totalExclDph: calculatedTotalExclDph,
        totalInclDph: companyInfo.isVatPayer ? Math.round(calculatedTotalExclDph * 1.21) : Math.round(calculatedTotalExclDph),
        paymentType: 'Převodem',
        status: 'neuhrazeno',
        discount: 0,
        costs: Math.round(calculatedTotalCosts)
      };

      return [newInvoice, ...prevInvoices];
    });

    resetAllSearches();
    setActiveView('invoices');
  };

  const resetAllSearches = () => {
    setCustomerSearch('');
    setVehicleSearch('');
    setOrderSearch('');
    setInvoiceSearch('');
    setArchiveSearch('');
  };

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    resetAllSearches();
    setTargetVehicleId(null);
    setTargetOrderId(null);
    setTargetCustomerId(null);
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (fullState: any) => {
    if (fullState.customers) setCustomers([...fullState.customers]);
    if (fullState.vehicles) setVehicles([...fullState.vehicles]);
    if (fullState.services) setServices([...fullState.services]);

    // U faktur v rámci obnovy vždy garantujeme nové unikátní vnitřní UID
    if (fullState.invoices) {
      const fixedInvoices = fullState.invoices.map((inv: any) => ({
        ...inv,
        uid: `inv-uid-restore-${Math.random().toString(36).substr(2, 9)}`
      }));
      setInvoices(fixedInvoices);
    }

    if (fullState.settings) {
      if (fullState.settings.hourlyRate !== undefined) setHourlyRate(fullState.settings.hourlyRate);
      if (fullState.settings.fixedServices) setFixedServices([...fullState.settings.fixedServices]);
      if (fullState.settings.predefinedTasks) setPredefinedTasks([...fullState.settings.predefinedTasks]);
      if (fullState.settings.technicians) setTechnicians([...fullState.settings.technicians]);
      if (fullState.settings.discountLevels) setDiscountLevels([...fullState.settings.discountLevels]);
    }

    if (fullState.companyInfo) setCompanyInfo({...fullState.companyInfo});
    if (fullState.statsSettings) setStatsSettings({...fullState.statsSettings});
  };

  const handleClearAllData = () => {
    setCustomers([]);
    setVehicles([]);
    setServices([]);
    setInvoices([]);
    resetAllSearches();
    setActiveView('dashboard');
  };

  const handleNavigateToVehicle = (vId: string) => { 
    resetAllSearches();
    const v = vehicles.find(item => item.id === vId);
    if (v) setVehicleSearch(v.licensePlate);
    setTargetVehicleId(vId); 
    setActiveView('vehicles'); 
  };

  const handleNavigateToOrder = (oId: string) => { 
    resetAllSearches();
    const order = services.find(item => item.id === oId);
    if (!order) return;

    const relatedInvoice = invoices.find(inv => inv.orderId === order.id);
    const isArchived = relatedInvoice?.status === 'uhrazeno' && (order.status === 'hotovo' || order.status === 'zrušeno');

    if (isArchived) {
      setArchiveSearch(order.id);
      setActiveView('archive');
    } else {
      setOrderSearch(order.id);
      setActiveView('orders');
    }
  };

  const handleCreateOrderForVehicle = (vId: string) => {
    resetAllSearches();
    setTargetVehicleId(vId);
    setTargetOrderId(null);
    setActiveView('orders');
    setShouldOpenModal(true);
  };

  const handleNavigateToCustomer = (cId: string) => { 
    resetAllSearches();
    const c = customers.find(item => item.id === cId);
    if (c) setCustomerSearch(c.lastName || c.companyName || '');
    setTargetCustomerId(cId); 
    setActiveView('customers'); 
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  const companyNameParts = (companyInfo?.name || '').split(' ');

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-sm print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">
                {companyNameParts[0]} <span className="text-blue-600 font-black">{companyNameParts.slice(1).join(' ')}</span>
              </h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-600' 
                      : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} invoices={invoices} technicians={technicians} predefinedTasks={predefinedTasks} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetOrderId(null); setTargetVehicleId(null); }} initialOrderId={targetOrderId} preselectedVehicleId={targetVehicleId} selectedPrinter={selectedPrinter} onCreateInvoice={handleCreateInvoiceFromOrder} search={orderSearch} onSearchChange={setOrderSearch} />}
          {activeView === 'invoices' && <InvoiceManager invoices={invoices} customers={customers} services={services} companyInfo={companyInfo} discountLevels={discountLevels} onDeleteInvoice={(uid) => setInvoices(prev => prev.filter(inv => inv.uid !== uid))} onUpdateInvoiceStatus={(uid, status) => setInvoices(prev => prev.map(inv => inv.uid === uid ? {...inv, status} : inv))} onUpdateInvoice={handleUpdateInvoice} search={invoiceSearch} onSearchChange={setInvoiceSearch} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetCustomerId(null); }} search={customerSearch} onSearchChange={setCustomerSearch} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} onCreateOrder={handleCreateOrderForVehicle} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetVehicleId(null); }} search={vehicleSearch} onSearchChange={setVehicleSearch} />}
          {activeView === 'archive' && <ArchiveManager services={services} invoices={invoices} vehicles={vehicles} customers={customers} companyInfo={companyInfo} hourlyRate={hourlyRate} search={archiveSearch} onSearchChange={setArchiveSearch} onNavigateToOrder={handleNavigateToOrder} />}
          {activeView === 'stats' && <StatsManager services={services} invoices={invoices} vehicles={vehicles} customers={customers} statsSettings={statsSettings} />}
          {activeView === 'settings' && <Settings technicians={technicians} onTechniciansChange={setTechnicians} predefinedTasks={predefinedTasks} onPredefinedTasksChange={setPredefinedTasks} discountLevels={discountLevels} onDiscountLevelsChange={setDiscountLevels} hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} statsSettings={statsSettings} onStatsSettingsChange={setStatsSettings} customers={customers} vehicles={vehicles} services={services} invoices={invoices} onRestoreData={handleRestoreData} onClearAllData={handleClearAllData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={() => {}} setDirectoryHandle={() => {}} directoryHandle={null} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { 
  Search, Receipt, Printer, Trash2, CheckCircle, XCircle, AlertCircle, 
  FileText, X, Percent, CreditCard, Wallet, CalendarDays, TrendingUp, 
  AlertOctagon, MoreHorizontal, Archive, ArrowUpRight, Calculator,
  FileSearch, Loader2, FilePlus, Sparkles, Eye, Calendar
} from 'lucide-react';
import { Invoice, CompanyInfo, Customer, PartItem, ServiceRecord } from '../types';
import * as XLSX from 'xlsx';
import { analyzeCostsFromDocument } from '../services/geminiService';

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

interface InvoiceManagerProps {
  invoices: Invoice[];
  customers: Customer[];
  services?: ServiceRecord[]; 
  companyInfo: CompanyInfo;
  discountLevels: number[];
  onDeleteInvoice: (uid: string) => void;
  onUpdateInvoiceStatus: (uid: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onUpdateInvoice: (invoice: Invoice) => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const InvoiceManager: React.FC<InvoiceManagerProps> = ({ invoices, customers, services = [], companyInfo, discountLevels, onDeleteInvoice, onUpdateInvoiceStatus, onUpdateInvoice, search, onSearchChange }) => {
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [deletingInvoice, setDeletingInvoice] = useState<Invoice | null>(null);
  const [isAiCostLoading, setIsAiCostLoading] = useState(false);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const today = new Date().toISOString().split('T')[0];
  const costFileInputRef = useRef<HTMLInputElement>(null);

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => {
      if (inv.archived) return false;
      const customer = customers.find(c => c.id === inv.customerId);
      const searchLower = search.toLowerCase();
      return (
        (inv.id || "").toLowerCase().includes(searchLower) ||
        (customer?.lastName || '').toLowerCase().includes(searchLower) ||
        (customer?.companyName || '').toLowerCase().includes(searchLower) ||
        (inv.vehicleInfo || "").toLowerCase().includes(searchLower)
      );
    });
  }, [invoices, customers, search]);

  const { unpaidInvoices, paidInvoices, totalUnpaid, totalPaid } = useMemo(() => {
    const unpaid = filteredInvoices.filter(inv => inv.status === 'neuhrazeno');
    const paid = filteredInvoices.filter(inv => inv.status === 'uhrazeno');

    return {
      unpaidInvoices: unpaid,
      paidInvoices: paid,
      totalUnpaid: Math.round(unpaid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0)),
      totalPaid: Math.round(paid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0))
    };
  }, [filteredInvoices]);

  const handlePrint = () => {
    window.print();
  };

  const handleUpdateActiveInvoice = (field: keyof Invoice, value: any) => {
    if (!selectedInvoice) return;

    let updated = { ...selectedInvoice, [field]: value };

    if (field === 'paymentType' || field === 'issueDate') {
      if (updated.paymentType === 'Hotově') {
        updated.dueDate = updated.issueDate;
      } else {
        const currentDiff = Math.round((new Date(selectedInvoice.dueDate).getTime() - new Date(selectedInvoice.issueDate).getTime()) / (1000 * 3600 * 24));
        const diff = isNaN(currentDiff) || currentDiff < 0 ? 14 : currentDiff;
        const date = new Date(updated.issueDate);
        date.setDate(date.getDate() + diff);
        updated.dueDate = date.toISOString().split('T')[0];
      }
    }

    if (field === 'discount' || field === 'items') {
      const currentItems = updated.items || [];
      const baseTotal = currentItems.reduce((sum, item) => sum + (Number(item.quantity) * Number(item.unitPrice)), 0);
      const discountedBase = baseTotal * (1 - ((Number(updated.discount) || 0) / 100));
      updated.totalExclDph = discountedBase;
      updated.totalInclDph = companyInfo.isVatPayer ? Math.round(discountedBase * 1.21) : Math.round(discountedBase);
    }

    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleUpdateDueDays = (days: number) => {
    if (!selectedInvoice) return;
    const date = new Date(selectedInvoice.issueDate);
    date.setDate(date.getDate() + days);
    const updated = { ...selectedInvoice, dueDate: date.toISOString().split('T')[0] };
    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleArchiveInvoice = (inv: Invoice) => {
    const updated = { ...inv, archived: true };
    onUpdateInvoice(updated);
  };

  const handleCostFileAnalyze = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !selectedInvoice) return;

    setIsAiCostLoading(true);
    try {
      let analysisResult: { code: string; description: string; costWithDph: number }[] = [];
      const isPdf = file.type === 'application/pdf';

      if (isPdf) {
        const reader = new FileReader();
        const base64Promise = new Promise<string>((resolve) => {
          reader.onload = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
        const base64Data = await base64Promise;
        const splitted = base64Data.split(',');
        analysisResult = await analyzeCostsFromDocument(splitted.length > 1 ? splitted[1] : splitted[0], true);
      } else {
        const buffer = await file.arrayBuffer();
        const workbook = XLSX.read(buffer, { type: 'buffer' });
        const jsonData = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        analysisResult = await analyzeCostsFromDocument(jsonData, false);
      }

      let totalMatchedCost = 0;
      let matchedCount = 0;

      selectedInvoice.items.forEach(invItem => {
        const invDesc = (invItem.description || "").toLowerCase();
        const invId = (invItem.id || "").toLowerCase();

        const match = analysisResult.find(res => {
          const resCode = (res.code || "").toLowerCase();
          const resDescription = (res.description || "").toLowerCase();

          return (
            (resCode && invId === resCode) || 
            (resCode && invDesc.includes(resCode)) || 
            (resDescription && invDesc.includes(resDescription)) || 
            (resDescription && resDescription.includes(invDesc))    
          );
        });

        if (match) {
          totalMatchedCost += (match.costWithDph || 0);
          matchedCount++;
        }
      });

      if (totalMatchedCost > 0) {
        handleUpdateActiveInvoice('costs', totalMatchedCost);
        alert(`Analýza dokončena. Spárováno ${matchedCount} z ${selectedInvoice.items.length} položek. Celkové náklady: ${Math.round(totalMatchedCost).toLocaleString()} Kč.`);
      } else {
        alert("Nebyly nalezeny žádné odpovídající položky. Ujistěte se, že vaše popisy položek obsahují objednací kódy z dokumentu dodavatele.");
      }
    } catch (error) {
      console.error("Analysis failed:", error);
      alert("Analýza souboru selhala. Zkontrolujte formát souboru.");
    } finally {
      setIsAiCostLoading(false);
      if (costFileInputRef.current) costFileInputRef.current.value = '';
    }
  };

  const selectedOrder = useMemo(() => {
    if (!selectedInvoice) return null;
    return services.find(s => s.id === selectedInvoice.orderId) || null;
  }, [selectedInvoice, services]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">

      <div className="hidden print:block">
        {selectedInvoice && <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} order={selectedOrder} />}
      </div>

      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Fakturační systém</h2>
          <p className="text-slate-500 font-medium">Správa vydaných faktur a sledování plateb.</p>
        </div>

        <div className="bg-white p-4 rounded-[2rem] border border-slate-200 shadow-sm flex items-center gap-8 px-8">
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">K úhradě celkem</span>
            <span className="text-xl font-black text-blue-600">{totalUnpaid.toLocaleString()} Kč</span>
          </div>
          <div className="w-px h-10 bg-slate-100"></div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Uhrazeno celkem</span>
            <span className="text-xl font-black text-emerald-600">{totalPaid.toLocaleString()} Kč</span>
          </div>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat fakturu (ID, Zákazník, Vozidlo)..." 
          className="flex-1 text-sm font-medium outline-none bg-transparent"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-0 lg:divide-x divide-slate-200 print:hidden pb-12">

        <div className="lg:pr-8 space-y-6">
          <div className="flex items-center justify-between mb-4 px-2">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <AlertOctagon className="w-4 h-4 text-blue-500" />
              K úhradě ({unpaidInvoices.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {unpaidInvoices.map(inv => (
              <InvoiceCard 
                key={inv.uid} 
                inv={inv} 
                customers={customers} 
                today={today}
                onSelect={setSelectedInvoice}
                onDelete={setDeletingInvoice}
                onUpdateStatus={onUpdateInvoiceStatus}
                onArchive={handleArchiveInvoice}
                openMenuId={openMenuId}
                onOpenMenu={setOpenMenuId}
              />
            ))}
            {unpaidInvoices.length === 0 && (
              <div className="py-12 text-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-bold italic">Žádné faktury k úhradě.</p>
              </div>
            )}
          </div>
        </div>

        <div className="lg:pl-8 space-y-6 mt-12 lg:mt-0">
          <div className="flex items-center justify-between mb-4 px-2">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2">
              <CheckCircle className="w-4 h-4 text-emerald-500" />
              Uhrazeno ({paidInvoices.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 gap-6">
            {paidInvoices.map(inv => (
              <InvoiceCard 
                key={inv.uid} 
                inv={inv} 
                customers={customers} 
                today={today}
                onSelect={setSelectedInvoice}
                onDelete={setDeletingInvoice}
                onUpdateStatus={onUpdateInvoiceStatus}
                onArchive={handleArchiveInvoice}
                openMenuId={openMenuId}
                onOpenMenu={setOpenMenuId}
              />
            ))}
            {paidInvoices.length === 0 && (
              <div className="py-12 text-center bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-200">
                <p className="text-slate-400 font-bold italic">Žádné uhrazené faktury.</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {selectedInvoice && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 print:hidden">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedInvoice(null)}></div>
          <div className="bg-white w-full max-w-6xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
            <div className="p-6 border-b flex flex-col gap-4 bg-slate-50">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-4">
                  <FileText className="w-6 h-6 text-blue-600" />
                  <h3 className="text-xl font-black uppercase">Faktura {selectedInvoice.id}</h3>
                </div>
                <div className="flex gap-4">
                  <button 
                    onClick={() => onUpdateInvoiceStatus(selectedInvoice.uid, selectedInvoice.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno')}
                    className={`px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 ${selectedInvoice.status === 'uhrazeno' ? 'bg-amber-100 text-amber-700' : 'bg-emerald-100 text-emerald-700'}`}
                  >
                    {selectedInvoice.status === 'uhrazeno' ? <XCircle className="w-4 h-4" /> : <CheckCircle className="w-4 h-4" />}
                    {selectedInvoice.status === 'uhrazeno' ? 'OZNAČIT JAKO NEUHRAZENO' : 'OZNAČIT JAKO UHRAZENO'}
                  </button>
                  <button 
                    onClick={handlePrint}
                    className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg shadow-blue-200"
                  >
                    <Printer className="w-4 h-4" /> TISK / PDF
                  </button>
                  <button onClick={() => setSelectedInvoice(null)} className="p-2 hover:bg-slate-100 rounded-xl"><X className="w-6 h-6 text-slate-400" /></button>
                </div>
              </div>

              <div className="flex flex-wrap items-center gap-6 p-4 bg-white rounded-[2rem] border border-slate-200 shadow-sm">
                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Úhrada:</span>
                  <div className="flex bg-slate-100 p-1 rounded-xl">
                    <button 
                      onClick={() => handleUpdateActiveInvoice('paymentType', 'Hotově')}
                      className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${selectedInvoice.paymentType === 'Hotově' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <Wallet className="w-3.5 h-3.5" /> Hotově
                    </button>
                    <button 
                      onClick={() => handleUpdateActiveInvoice('paymentType', 'Převodem')}
                      className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${selectedInvoice.paymentType === 'Převodem' ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'}`}
                    >
                      <CreditCard className="w-3.5 h-3.5" /> Převodem
                    </button>
                  </div>
                </div>

                <div className="flex items-center gap-3 border-l border-slate-100 pl-6">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Calendar className="w-3 h-3" /> Zdanitelné plnění:</span>
                  <input 
                    type="date"
                    className="bg-slate-100 border-none rounded-xl px-4 py-2 text-xs font-bold outline-none cursor-pointer"
                    value={selectedInvoice.issueDate}
                    onChange={(e) => handleUpdateActiveInvoice('issueDate', e.target.value)}
                  />
                </div>

                {selectedInvoice.paymentType === 'Převodem' && (
                  <div className="flex items-center gap-3">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Splatnost:</span>
                    <div className="flex bg-slate-100 p-1 rounded-xl">
                      {[7, 14, 31].map(days => (
                        <button 
                          key={days}
                          onClick={() => handleUpdateDueDays(days)}
                          className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                            Math.round((new Date(selectedInvoice.dueDate).getTime() - new Date(selectedInvoice.issueDate).getTime()) / (1000 * 3600 * 24)) === days 
                            ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500 hover:text-slate-700'
                          }`}
                        >
                          {days} d
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                <div className="flex items-center gap-3">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sleva:</span>
                  <select 
                    value={selectedInvoice.discount || 0}
                    onChange={(e) => handleUpdateActiveInvoice('discount', parseInt(e.target.value) || 0)}
                    className="bg-slate-100 border-none rounded-xl px-4 py-2 text-xs font-bold outline-none cursor-pointer hover:bg-slate-200 transition-colors"
                  >
                    {discountLevels.map(level => (
                      <option key={level} value={level}>{level}% sleva</option>
                    ))}
                  </select>
                </div>

                <div className="flex items-center gap-3 border-l border-slate-100 pl-6">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1">
                    <Calculator className="w-3 h-3" /> Pořizovací náklady:
                  </span>

                  <div className="flex items-center gap-2">
                    <div className="relative">
                      <input 
                        type="number"
                        placeholder="0"
                        className="bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-xs font-black outline-none w-28 focus:border-emerald-500 transition-all"
                        value={selectedInvoice.costs || ''}
                        onChange={(e) => handleUpdateActiveInvoice('costs', parseFloat(e.target.value) || 0)}
                      />
                      <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-300">Kč</span>
                    </div>

                    <button 
                      onClick={() => costFileInputRef.current?.click()}
                      disabled={isAiCostLoading}
                      className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                        isAiCostLoading 
                        ? 'bg-slate-100 text-slate-400' 
                        : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-lg shadow-emerald-200'
                      }`}
                    >
                      {isAiCostLoading ? <Loader2 className="w-3 h-3 animate-spin" /> : <Sparkles className="w-3 h-3" />}
                      {isAiCostLoading ? 'Analyzuji...' : 'AI SCAN NÁKLADŮ'}
                    </button>
                    <input 
                      type="file" 
                      className="hidden" 
                      ref={costFileInputRef} 
                      onChange={handleCostFileAnalyze} 
                      accept=".pdf,.xlsx,.xls"
                    />
                  </div>
                </div>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-12 bg-slate-100 flex justify-center custom-scrollbar">
               <InvoicePrintTemplate invoice={selectedInvoice} company={companyInfo} customers={customers} order={selectedOrder} />
            </div>
          </div>
        </div>
      )}

      {deletingInvoice && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingInvoice(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-10 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6"><AlertCircle className="w-10 h-10" /></div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat fakturu?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete nenávratně odstranit fakturu <span className="font-bold text-slate-900">{deletingInvoice.id}</span>?
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingInvoice(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button 
                  onClick={() => { onDeleteInvoice(deletingInvoice.uid); setDeletingInvoice(null); }}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm uppercase shadow-lg shadow-red-600/20"
                >
                  Smazat
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const InvoiceCard: React.FC<{
  inv: Invoice;
  customers: Customer[];
  today: string;
  onSelect: (inv: Invoice) => void;
  onDelete: (inv: Invoice) => void;
  onUpdateStatus: (uid: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onArchive: (inv: Invoice) => void;
  openMenuId: string | null;
  onOpenMenu: (uid: string | null) => void;
}> = ({ inv, customers, today, onSelect, onDelete, onUpdateStatus, onArchive, openMenuId, onOpenMenu }) => {
  const customer = customers.find(c => c.id === inv.customerId);
  const isOverdue = inv.status === 'neuhrazeno' && inv.dueDate < today;
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onOpenMenu(null);
      }
    };
    if (openMenuId === inv.uid) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [openMenuId, inv.uid, onOpenMenu]);

  return (
    <div className={`bg-white rounded-[2rem] border p-6 transition-all hover:shadow-xl group relative overflow-visible ${isOverdue ? 'border-red-200 bg-red-50/10' : 'border-slate-100'}`}>
      <div className="flex justify-between items-start mb-4">
        <div className="flex items-center gap-4">
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${inv.status === 'uhrazeno' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
            <Receipt className="w-6 h-6" />
          </div>
          <div>
            <h4 className="text-base font-black text-slate-900">{inv.id}</h4>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{formatDate(inv.issueDate)}</p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => onSelect(inv)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all">
            <Eye className="w-5 h-5" />
          </button>
          <div className="relative">
            <button 
              onClick={(e) => { e.stopPropagation(); onOpenMenu(openMenuId === inv.uid ? null : inv.uid); }}
              className={`p-2 rounded-xl transition-all ${openMenuId === inv.uid ? 'bg-slate-100 text-slate-900 shadow-inner' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'}`}
            >
              <MoreHorizontal className="w-5 h-5" />
            </button>
            {openMenuId === inv.uid && (
              <div 
                ref={menuRef}
                className="absolute top-10 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
              >
                <button 
                  onClick={(e) => { e.stopPropagation(); onUpdateStatus(inv.uid, inv.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno'); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                >
                  {inv.status === 'uhrazeno' ? <XCircle className="w-4 h-4 text-amber-500" /> : <CheckCircle className="w-4 h-4 text-emerald-500" />}
                  {inv.status === 'uhrazeno' ? 'Neuhrazeno' : 'Uhrazeno'}
                </button>
                <button 
                  onClick={(e) => { e.stopPropagation(); onArchive(inv); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"
                >
                  <Archive className="w-4 h-4" /> Archivovat
                </button>
                <div className="h-px bg-slate-100 my-1"></div>
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(inv); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                >
                  <Trash2 className="w-4 h-4" /> Smazat
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="space-y-2 mb-6">
        <p className="text-sm font-bold text-slate-700 truncate">
          {customer?.customerType === 'firemní' ? (customer?.companyName || `${customer?.firstName} ${customer?.lastName}`) : `${customer?.firstName} ${customer?.lastName}`}
        </p>
        <p className="text-[10px] font-bold text-blue-600 uppercase truncate">{inv.vehicleInfo}</p>
      </div>

      <div className="flex items-center justify-between pt-4 border-t border-slate-50">
        <div className="flex flex-col">
          <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Splatnost</span>
          <span className={`text-[11px] font-black ${isOverdue ? 'text-red-600' : 'text-slate-600'}`}>
            {formatDate(inv.dueDate)}
            {isOverdue && ' (PO SPLATNOSTI)'}
          </span>
        </div>
        <div className="text-right">
          <p className="text-lg font-black text-slate-900">{Math.round(inv.totalInclDph).toLocaleString()} Kč</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase">{inv.totalInclDph !== inv.totalExclDph ? 'včetně DPH' : ''}</p>
        </div>
      </div>
    </div>
  );
};

