    stkExpirationDate: '',
    nextServiceDate: '',
    serviceIntervalKm: 15000,
    serviceIntervalMonths: 12,
    customerId: customers[0]?.id || '',
    attachments: [],
    brakeFluidDate: '',
    coolantDate: '',
    gearboxOilDate: '',
    timingBeltDate: '',
    refrigerantDate: ''
  };

  const [formData, setFormData] = useState<Partial<Vehicle>>(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleAddNew();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialVehicleId) {
      const v = vehicles.find(item => item.id === initialVehicleId);
      if (v) setSelectedVehicle(v);
      if (onModalOpened) onModalOpened();
    }
  }, [initialVehicleId, vehicles, onModalOpened]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const availableMakes = useMemo(() => {
    return Object.keys(VEHICLE_DB);
  }, []);

  const availableModels = useMemo(() => {
    if (formData.make && VEHICLE_DB[formData.make]) {
      return Object.keys(VEHICLE_DB[formData.make]);
    }
    return [];
  }, [formData.make]);

  const availableEngines = useMemo(() => {
    if (formData.make && formData.model && VEHICLE_DB[formData.make] && VEHICLE_DB[formData.make][formData.model]) {
      return VEHICLE_DB[formData.make][formData.model];
    }
    return [];
  }, [formData.make, formData.model]);

  const alphabet = useMemo(() => {
    const letters = new Set<string>();
    vehicles.forEach(v => {
      if (v.make) letters.add(v.make[0].toUpperCase());
    });
    return Array.from(letters).sort((a, b) => a.localeCompare(b, 'cs'));
  }, [vehicles]);

  const filteredVehicles = useMemo(() => {
    return vehicles.filter(v => {
      const customer = customers.find(c => c.id === v.customerId);
      const customerName = customer 
        ? (customer.customerType === 'firemní' ? customer.companyName : `${customer.lastName} ${customer.firstName}`) 
        : "";

      const matchesSearch = 
        (v.licensePlate || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.make || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.model || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.vin || "").toLowerCase().includes(search.toLowerCase()) ||
        customerName?.toLowerCase().includes(search.toLowerCase());

      const matchesLetter = !selectedLetter || (v.make && v.make[0].toUpperCase() === selectedLetter);

      return matchesSearch && matchesLetter;
    }).sort((a, b) => (a.make || "").localeCompare(b.make || "", 'cs'));
  }, [vehicles, search, selectedLetter, customers]);

  const handleAddNew = () => {
    setEditingVehicle(null);
    setFormData(initialFormData);
    setActiveTab('basic');
    setIsModalOpen(true);
  };

  const handleEdit = (v: Vehicle) => {
    setEditingVehicle(v);
    setFormData(v);
    setActiveTab('basic');
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Force force uppercase on plate and VIN
    const sanitizedData = {
      ...formData,
      licensePlate: (formData.licensePlate || '').trim().toUpperCase(),
      vin: (formData.vin || '').trim().toUpperCase()
    };

    if (editingVehicle) {
      onUpdateVehicle({ ...editingVehicle, ...sanitizedData } as Vehicle);
    } else {
      onAddVehicle({ ...sanitizedData, id: `v${Date.now()}` } as Vehicle);
    }
    setIsModalOpen(false);
  };

  const handleDeleteConfirm = () => {
    if (deletingVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedVehicle) return;

    const file = files[0];
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64Data = reader.result as string;
      const newAttachment: VehicleAttachment = {
        id: `att-${Date.now()}`,
        name: file.name,
        type: file.type,
        data: base64Data,
        size: file.size
      };

      const updatedVehicle = {
        ...selectedVehicle,
        attachments: [...(selectedVehicle.attachments || []), newAttachment]
      };

      onUpdateVehicle(updatedVehicle);
      setSelectedVehicle(updatedVehicle);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const handleDeleteAttachment = (attachmentId: string) => {
    if (!selectedVehicle) return;
    const updatedVehicle = {
      ...selectedVehicle,
      attachments: (selectedVehicle.attachments || []).filter(a => a.id !== attachmentId)
    };
    onUpdateVehicle(updatedVehicle);
    setSelectedVehicle(updatedVehicle);
  };

  const openAttachment = (attachment: VehicleAttachment) => {
    try {
      const splitted = attachment.data.split(',');
      if (splitted.length < 2) throw new Error("Invalid base64");

      const base64Parts = splitted;
      const contentType = base64Parts[0].split(':')[1].split(';')[0];
      const byteCharacters = atob(base64Parts[1]);
      const byteArrays = [];

      for (let offset = 0; offset < byteCharacters.length; offset += 512) {
        const slice = byteCharacters.slice(offset, offset + 512);
        const byteNumbers = new Array(slice.length);
        for (let i = 0; i < slice.length; i++) {
          byteNumbers[i] = slice.charCodeAt(i);
        }
        const byteArray = new Uint8Array(byteNumbers);
        byteArrays.push(byteArray);
      }

      const blob = new Blob(byteArrays, { type: contentType });
      const blobUrl = URL.createObjectURL(blob);

      const newWindow = window.open(blobUrl, '_blank');
      if (!newWindow) {
        alert('Prohlížeč zablokoval vyskakovací okno. Povolte prosím vyskakovací okna pro tuto stránku.');
      }

      setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
    } catch (error) {
      console.error('Error opening attachment:', error);
      alert('Soubor se nepodařilo otevřít.');
    }
  };

  const vehicleServices = useMemo(() => {
    if (!historyVehicle) return [];
    return services
      .filter(s => s.vehicleId === historyVehicle.id)
      .sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  }, [historyVehicle, services]);

  const totalSpentOnVehicle = useMemo(() => {
    return vehicleServices.reduce((sum, s) => sum + (Number(s.cost) || 0) * 1.21, 0);
  }, [vehicleServices]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Vozidla</h2>
          <p className="text-slate-500 font-medium">Evidence vozového parku a servisních intervalů.</p>
        </div>
        <button 
          onClick={handleAddNew}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Hledat podle SPZ, značky, modelu, VIN nebo jména majitele..." 
            className="flex-1 text-sm font-medium outline-none bg-transparent"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
          {search && (
            <button 
              onClick={() => onSearchChange('')}
              className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
            >
              Zrušit filtr
            </button>
          )}
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <div className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 flex items-center gap-2 shrink-0">
            <Type className="w-4 h-4 text-slate-400" />
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">Značka:</span>
          </div>
          <button 
            onClick={() => setSelectedLetter(null)}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
          >
            VŠE
          </button>
          {alphabet.map(letter => (
            <button 
              key={letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVehicles.map(v => (
          <div key={v.id} className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-5 h-5" />
                </button>

                {openMenuId === v.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-52 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleEdit(v)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit vozidlo
                    </button>
                    <button 
                      onClick={() => { onCreateOrder(v.id); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"
                    >
                      <ClipboardPlus className="w-4 h-4 text-blue-400" />
                      Vytvořit zakázku
                    </button>
                    <div className="h-px bg-slate-100 my-1 mx-2"></div>
                    <button 
                      onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat vozidlo
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-4">
              <div className="w-16 h-16 rounded-2xl bg-slate-900 flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105">
                <Car className="w-8 h-8" />
              </div>
              <div className="min-w-0">
                <h3 className="text-lg font-black text-slate-900 leading-tight truncate">
                  {v.make} {v.model}
                </h3>
                <p className="text-sm font-black text-blue-600 font-mono tracking-widest mt-1 uppercase">{v.licensePlate?.toUpperCase()}</p>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter mt-0.5">{v.year}</p>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedVehicle(v)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-bold text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider"
              >
                Detail
              </button>
              <button 
                onClick={() => setHistoryVehicle(v)}
                className="flex-1 py-3 bg-blue-50 text-blue-600 rounded-xl font-bold text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider flex items-center justify-center gap-2"
              >
                <HistoryIcon className="w-3.5 h-3.5" />
                Historie
              </button>
            </div>
          </div>
        ))}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center shrink-0">
              <div>
                <h3 className="text-2xl font-black tracking-tight">{editingVehicle ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Registrace do evidence</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="flex border-b border-slate-100 bg-slate-50 shrink-0">
              <button 
                onClick={() => setActiveTab('basic')}
                className={`flex-1 py-4 text-xs font-black uppercase tracking-widest transition-all border-b-2 flex items-center justify-center gap-2 ${activeTab === 'basic' ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
              >
                <Info className="w-4 h-4" /> Základní údaje
              </button>
              <button 
                onClick={() => setActiveTab('intervals')}
                className={`flex-1 py-4 text-xs font-black uppercase tracking-widest transition-all border-b-2 flex items-center justify-center gap-2 ${activeTab === 'intervals' ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
              >
                <Timer className="w-4 h-4" /> Servisní intervaly
              </button>
            </div>

            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-8 space-y-6 custom-scrollbar">
              {activeTab === 'basic' ? (
                <div className="space-y-6 animate-in fade-in slide-in-from-left-4 duration-300">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Značka</label>
                      <input 
                        type="text" 
                        list="make-list"
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                        value={formData.make}
                        onChange={e => setFormData({...formData, make: e.target.value, model: ''})}
                        placeholder="Vyberte nebo napište značku..."
                      />
                      <datalist id="make-list">
                        {availableMakes.map(make => <option key={make} value={make} />)}
                      </datalist>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Model</label>
                      <input 
                        type="text" 
                        list="model-list"
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                        value={formData.model}
                        onChange={e => setFormData({...formData, model: e.target.value})}
                        placeholder="Vyberte nebo napište model..."
                      />
                      <datalist id="model-list">
                        {availableModels.map(model => <option key={model} value={model} />)}
                      </datalist>
                    </div>
                  </div>

                  <div className="grid grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Rok výroby</label>
                      <input 
                        type="number" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.year}
                        onChange={e => setFormData({...formData, year: parseInt(e.target.value) || 0})}
                      />
                    </div>
                    <div className="space-y-2 col-span-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">SPZ / RZ</label>
                      <input 
                        required
                        type="text" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold uppercase"
                        value={formData.licensePlate || ''}
                        onChange={e => setFormData({...formData, licensePlate: e.target.value.toUpperCase()})}
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">VIN kód</label>
                    <input 
                      type="text" 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold uppercase font-mono"
                      value={formData.vin || ''}
                      onChange={e => setFormData({...formData, vin: e.target.value.toUpperCase()})}
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Aktuální nájezd (km)</label>
                      <input 
                        type="number" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.mileage || 0}
                        onChange={e => setFormData({...formData, mileage: parseInt(e.target.value) || 0})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kód motoru</label>
                      <input 
                        type="text" 
                        list="engine-list"
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.engineCode || ''}
                        onChange={e => setFormData({...formData, engineCode: e.target.value})}
                        placeholder="Vyberte nebo napište kód..."
                      />
                      <datalist id="engine-list">
                        {availableEngines.map(engine => (
                          <option key={engine} value={engine} />
                        ))}
                      </datalist>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">STK do</label>
                      <input 
                        type="date" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.stkExpirationDate || ''}
                        onChange={e => setFormData({...formData, stkExpirationDate: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Příští servis</label>
                      <input 
                        type="date" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.nextServiceDate || ''}
                        onChange={e => setFormData({...formData, nextServiceDate: e.target.value})}
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vlastník / Zákazník</label>
                    <select 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none transition-all font-bold"
                      value={formData.customerId || ''}
                      onChange={e => setFormData({...formData, customerId: e.target.value})}
                    >
                      {customers.map(c => (
                        <option key={c.id} value={c.id}>{c.companyName || `${c.lastName} ${c.firstName}`}</option>
                      ))}
                    </select>
                  </div>
                </div>
              ) : (
                <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                  <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 mb-4 flex items-start gap-4">
                    <AlertCircle className="w-6 h-6 text-amber-600 shrink-0 mt-0.5" />
                    <div>
                      <p className="text-xs font-black text-amber-900 uppercase tracking-tight mb-1">Evidence údržby</p>
                      <p className="text-xs font-bold text-amber-700 leading-relaxed">Zde vyplňte data posledních provedených výměn. Systém je bude zobrazovat v detailu vozidla pro lepší přehlednost při příjmu.</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 gap-4">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                        <Droplets className="w-3 h-3 text-blue-500" /> Brzdová kapalina
                      </label>
                      <input 
                        type="date" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.brakeFluidDate || ''}
                        onChange={e => setFormData({...formData, brakeFluidDate: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                        <Droplets className="w-3 h-3 text-emerald-500" /> Chladicí kapalina
                      </label>
                      <input 
                        type="date" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.coolantDate || ''}
                        onChange={e => setFormData({...formData, coolantDate: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                        <Droplets className="w-3 h-3 text-amber-600" /> Olej převodovky
                      </label>
                      <input 
                        type="date" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.gearboxOilDate || ''}
                        onChange={e => setFormData({...formData, gearboxOilDate: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                        <Settings2 className="w-3 h-3 text-red-500" /> Rozvody motoru
                      </label>
                      <input 
                        type="date" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.timingBeltDate || ''}
                        onChange={e => setFormData({...formData, timingBeltDate: e.target.value})}
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                        <Wind className="w-3 h-3 text-cyan-500" /> Chladivo klimatizace
                      </label>
                      <input 
                        type="date" 
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                        value={formData.refrigerantDate || ''}
                        onChange={e => setFormData({...formData, refrigerantDate: e.target.value})}
                      />
                    </div>
                  </div>

                  <div className="bg-blue-50/50 p-6 rounded-[2rem] border border-blue-100 space-y-4">
                    <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest flex items-center gap-2">
                      <Clock3 className="w-3.5 h-3.5" /> Servisní intervaly
                    </h4>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kilometry</label>
                        <select 
                          className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                          value={formData.serviceIntervalKm || 15000}
                          onChange={e => setFormData({...formData, serviceIntervalKm: parseInt(e.target.value)})}
                        >
                          {[5000, 10000, 15000, 20000, 25000, 30000].map(km => (
                            <option key={km} value={km}>{km.toLocaleString()} km</option>
                          ))}
                        </select>
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Časový (roky)</label>
                        <select 
                          className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 outline-none font-bold"
                          value={formData.serviceIntervalMonths || 12}
                          onChange={e => setFormData({...formData, serviceIntervalMonths: parseInt(e.target.value)})}
                        >
                          {[12, 24, 36].map(m => (
                            <option key={m} value={m}>{m / 12} {m / 12 === 1 ? 'rok' : (m / 12 < 5 ? 'roky' : 'let')}</option>
                          ))}
                        </select>
                      </div>
                    </div>
                  </div>
                </div>
              )}

              <button 
                type="submit"
                className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-2 mt-4 shrink-0"
              >
                <Check className="w-5 h-5" />
                {editingVehicle ? 'ULOŽIT ZMĚNY' : 'ULOŽIT VOZIDLO'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* MODAL HISTORIE OPRAV */}
      {historyVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={() => setHistoryVehicle(null)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-blue-600 p-8 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-blue-500/20 flex items-center justify-center border border-white/10">
                  <HistoryIcon className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">Historie oprav</h3>
                  <p className="text-blue-100 text-[10px] font-black uppercase tracking-widest mt-1">
                    {historyVehicle.make} {historyVehicle.model} ({historyVehicle.licensePlate?.toUpperCase()})
                  </p>
                </div>
              </div>
              <button onClick={() => setHistoryVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="bg-slate-50 px-8 py-4 border-b border-slate-200 flex items-center justify-between shrink-0">
              <div className="flex items-center gap-6">
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase">Počet zakázek</p>
                  <p className="text-lg font-black text-slate-900">{vehicleServices.length}</p>
                </div>
                <div className="w-px h-8 bg-slate-200"></div>
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase">Celkem investováno</p>
                  <p className="text-lg font-black text-blue-600">{totalSpentOnVehicle.toLocaleString()} Kč <span className="text-[10px] font-bold text-slate-400">vč. DPH</span></p>
                </div>
              </div>
              <TrendingUp className="w-8 h-8 text-slate-200" />
            </div>

            <div className="flex-1 overflow-y-auto p-8 space-y-4 custom-scrollbar">
              {vehicleServices.length > 0 ? (
                vehicleServices.map((service) => (
                  <div 
                    key={service.id} 
                    className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all group flex items-start justify-between cursor-pointer"
                    onClick={() => { onNavigateToOrder(service.id); setHistoryVehicle(null); }}
                  >
                    <div className="flex gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${service.status === 'hotovo' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
                        {service.status === 'hotovo' ? <CheckCircle2 className="w-5 h-5" /> : <Wrench className="w-5 h-5" />}
                      </div>
                      <div>
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-xs font-black text-slate-900">#{service.id}</span>
                          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{formatDate(service.date)}</span>
                        </div>
                        <p className="text-sm font-bold text-slate-700 leading-snug mb-2">{service.description}</p>
                        <div className="flex items-center gap-4">
                           <div className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase">
                              <User className="w-3 h-3" /> {service.technician}
                           </div>
                           <div className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase">
                              <Gauge className="w-3 h-3" /> {service.mileageAtEntry?.toLocaleString() || '---'} km
                           </div>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-sm font-black text-slate-900">{(service.cost * 1.21).toLocaleString()} Kč</p>
                      <button className="text-[9px] font-black text-blue-600 uppercase tracking-widest mt-2 group-hover:underline flex items-center gap-1 ml-auto">
                        Detail <ChevronRight className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="py-20 text-center flex flex-col items-center">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                    <ClipboardList className="w-10 h-10 text-slate-200" />
                  </div>
                  <h4 className="text-lg font-black text-slate-900 mb-1">Žádná historie</h4>
                  <p className="text-sm font-bold text-slate-400 max-w-xs mx-auto">Pro toto vozidlo zatím nebyly v systému vytvořeny žádné servisní záznamy.</p>
                </div>
              )}
            </div>

            <div className="p-8 border-t border-slate-50 bg-white shrink-0">
              <button 
                onClick={() => setHistoryVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all hover:bg-slate-800"
              >
                ZAVŘÍT HISTORII
              </button>
            </div>
          </div>
        </div>
      )}

      {selectedVehicle && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-xl bg-slate-700 flex items-center justify-center font-black">
                  <Car className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">{selectedVehicle.make} {selectedVehicle.model}</h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">{selectedVehicle.licensePlate?.toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedVehicle(null)} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Info className="w-3 h-3" /> Základní informace
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Značka a model</span>
                    <span className="text-sm font-black text-slate-900">{selectedVehicle.make} {selectedVehicle.model}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Rok výroby</span>
                    <span className="text-sm font-black text-slate-900">{selectedVehicle.year}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Registrační značka</span>
                    <span className="text-sm font-black text-blue-600 font-mono tracking-wider">{selectedVehicle.licensePlate?.toUpperCase()}</span>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Layers className="w-3 h-3" /> Technické parametry
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  <div className="flex flex-col gap-1 p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">VIN kód</span>
                    <span className="text-sm font-mono font-bold text-slate-900 break-all uppercase">{selectedVehicle.vin?.toUpperCase() || 'Neuvedeno'}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Aktuální nájezd</span>
                    <span className="text-sm font-black text-slate-900">{(selectedVehicle.mileage || 0).toLocaleString()} km</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Kód motoru</span>
                    <span className="text-sm font-black text-slate-900 uppercase">{selectedVehicle.engineCode?.toUpperCase() || 'Neuvedeno'}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Barva</span>
                    <div className="flex items-center gap-2">
                      <Palette className="w-3 h-3 text-slate-300" />
                      <span className="text-sm font-bold text-slate-900">{selectedVehicle.color || 'Neuvedeno'}</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Calendar className="w-3 h-3" /> Termíny a intervaly
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Platnost STK</span>
                    <span className={`text-sm font-black ${
                      (selectedVehicle.stkExpirationDate && new Date(selectedVehicle.stkExpirationDate) < new Date()) ? 'text-red-600' : 'text-slate-900'
                    }`}>
                      {formatDate(selectedVehicle.stkExpirationDate)}
                    </span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Příští servis</span>
                    <span className="text-sm font-black text-slate-900">{formatDate(selectedVehicle.nextServiceDate)}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight">Servisní interval</span>
                    <span className="text-sm font-black text-slate-900">
                      {(selectedVehicle.serviceIntervalKm || 15000).toLocaleString()} km / {(selectedVehicle.serviceIntervalMonths || 12) / 12} rok(y)
                    </span>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <Timer className="w-3 h-3" /> Specifické výměny
                </h4>

                <div className="grid grid-cols-1 gap-3">
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight flex items-center gap-1.5"><Droplets className="w-3 h-3 text-blue-500" /> Brzdová kapalina</span>
                    <span className="text-xs font-black text-slate-900">{formatDate(selectedVehicle.brakeFluidDate)}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight flex items-center gap-1.5"><Droplets className="w-3 h-3 text-emerald-500" /> Chladicí kapalina</span>
                    <span className="text-xs font-black text-slate-900">{formatDate(selectedVehicle.coolantDate)}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight flex items-center gap-1.5"><Droplets className="w-3 h-3 text-amber-600" /> Olej převodovky</span>
                    <span className="text-xs font-black text-slate-900">{formatDate(selectedVehicle.gearboxOilDate)}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight flex items-center gap-1.5"><Settings2 className="w-3 h-3 text-red-500" /> Rozvody motoru</span>
                    <span className="text-xs font-black text-slate-900">{formatDate(selectedVehicle.timingBeltDate)}</span>
                  </div>
                  <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-tight flex items-center gap-1.5"><Wind className="w-3 h-3 text-cyan-500" /> Chladivo klimy</span>
                    <span className="text-xs font-black text-slate-900">{formatDate(selectedVehicle.refrigerantDate)}</span>
                  </div>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                  <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] flex items-center gap-2">
                    <Paperclip className="w-3 h-3" /> Přílohy a dokumentace
                  </h4>
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-all text-[9px] font-black uppercase tracking-widest"
                  >
                    <FilePlus className="w-3 h-3" /> Přidat soubor
                  </button>
                  <input 
                    type="file" 
                    className="hidden" 
                    ref={fileInputRef} 
                    onChange={handleFileUpload} 
                    accept="image/*,.pdf"
                  />
                </div>

                <div className="space-y-2">
                  {selectedVehicle.attachments && selectedVehicle.attachments.length > 0 ? (
                    selectedVehicle.attachments.map(att => (
                      <div key={att.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl group hover:bg-white hover:shadow-md transition-all border border-transparent hover:border-slate-100">
                        <div className="flex items-center gap-3 min-w-0">
                          <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${att.type.includes('pdf') ? 'bg-red-50 text-red-500' : 'bg-blue-50 text-blue-500'}`}>
                            {att.type.includes('pdf') ? <FileText className="w-5 h-5" /> : <ImageIcon className="w-5 h-5" />}
                          </div>
                          <div className="min-w-0">
                            <p className="text-xs font-bold text-slate-900 truncate pr-2">{att.name}</p>
                            <p className="text-[8px] font-black text-slate-400 uppercase">{(att.size / 1024).toFixed(1)} KB</p>
                          </div>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => openAttachment(att)}
                            className="p-2 text-slate-400 hover:text-blue-600 transition-colors"
                            title="Zobrazit"
                          >
                            <Eye className="w-4 h-4" />
                          </button>
                          <button 
                            onClick={() => handleDeleteAttachment(att.id)}
                            className="p-2 text-slate-400 hover:text-red-600 transition-colors"
                            title="Smazat"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="py-8 text-center bg-slate-50/50 rounded-xl border border-dashed border-slate-200">
                      <p className="text-[10px] font-bold text-slate-400 italic">Žádné nahrané dokumenty.</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] border-b border-slate-100 pb-2 flex items-center gap-2">
                  <User className="w-3 h-3" /> Vlastnictví
                </h4>

                <div className="p-3 bg-slate-50 rounded-xl">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-tight mb-1">Registrovaný vlastník</p>
                  <p 
                    className="text-sm font-black text-blue-600 cursor-pointer hover:underline flex items-center gap-2"
                    onClick={() => { onNavigateToCustomer(selectedVehicle.customerId); setSelectedVehicle(null); }}
                  >
                    {customers.find(c => c.id === selectedVehicle.customerId)?.companyName || 
                     `${customers.find(c => c.id === selectedVehicle.customerId)?.lastName || ''} ${customers.find(c => c.id === selectedVehicle.customerId)?.firstName || ''}`}
                    <ChevronRight className="w-4 h-4" />
                  </p>
                </div>
              </div>
            </div>

            <div className="p-8 border-t border-slate-50 bg-white shrink-0">
              <button 
                onClick={() => setSelectedVehicle(null)}
                className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl transition-all hover:bg-slate-800 shadow-xl shadow-slate-900/10"
              >
                ZAVŘÍT
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL PRO SMAZÁNÍ VOZIDLA */}
      {deletingVehicle && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
                <AlertCircle className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Opravdu smazat?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete smazat vozidlo <span className="font-bold text-slate-900">{deletingVehicle.make} {deletingVehicle.model} ({deletingVehicle.licensePlate?.toUpperCase()})</span>? Tato akce je nevratná a dojde k odstranění všech příloh.
              </p>
              <div className="flex gap-3">
                <button 
                  onClick={() => setDeletingVehicle(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm hover:bg-slate-200 transition-all"
                >
                  ZRUŠIT
                </button>
                <button 
                  onClick={handleDeleteConfirm}
                  className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm hover:bg-red-700 transition-all shadow-lg shadow-red-600/20"
                >
                  SMAZAT
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

export interface PartItem {
  id: string;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
  costPrice?: number; // Nákupní cena (základ daně)
}

export interface FixedService {
  id: string;
  name: string;
  price: number;
  costPrice?: number; // Nákupní cena vč. DPH (zadává se v nastavení)
  unit?: string; // Měrná jednotka
}

export interface PredefinedTask {
  id: string;
  label: string;
  description: string;
}

export interface Invoice {
  uid: string; // Vnitřní unikátní ID pro React a DB operace
  id: string; // Číslo faktury (viditelné)
  orderId: string;
  issueDate: string;
  dueDate: string;
  customerId: string;
  vehicleInfo: string;
  items: PartItem[];
  totalExclDph: number;
  totalInclDph: number;
  costs?: number; // Pořizovací náklady pro výpočet zisku
  paymentType: 'Hotově' | 'Převodem';
  status: 'uhrazeno' | 'neuhrazeno';
  discount?: number;
  archived?: boolean;
}

export interface Customer {
  id: string;
  customerType: 'soukromý' | 'firemní';
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
