                  <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 mb-4 flex items-start gap-4">
                    <AlertCircle className="w-6 h-6 text-amber-600 shrink-0 mt-0.5" />
                    <div>
                      <p className="text-xs font-black text-amber-900 uppercase tracking-tight mb-1">Evidence údržby</p>
