        </div>
      </div>

      {/* Tab Navigation */}
      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-full sm:w-fit rounded-2xl border border-slate-100">
        {tabs.map(tab => (
          <button
