              activeTab === tab.id 
                ? 'bg-white text-blue-600 shadow-md scale-[1.02]' 
                : 'text-slate-500 hover:text-slate-800'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label.toUpperCase()}
          </button>
        ))}
      </div>

      <div className="min-h-[500px]">
        {activeTab === 'finance' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-left-4 duration-500">
            <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:scale-110 transition-transform">
                <Coins className="w-32 h-32 text-blue-900" />
              </div>
              <div className="relative z-10">
                <div className="w-12 h-12 rounded-2xl bg-blue-50 flex items-center justify-center mb-6">
                  <Coins className="w-6 h-6 text-blue-600" />
                </div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Obrat v období (bez DPH)</p>
                <h3 className="text-3xl font-black text-slate-900 tracking-tighter">
                  {stats.turnover.toLocaleString()} Kč
