export default InvoiceManager;

import React, { useState, useMemo } from 'react';
import { 
  BarChart3, TrendingUp, Coins, Users, Car, CheckCircle2, 
  ArrowUpRight, ArrowDownRight, Wallet, Calculator,
  AlertCircle, PieChart, History, Gauge, Calendar
} from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';
import { ServiceRecord, Invoice, Vehicle, Customer, StatsSettings, CompanyInfo } from '../types';

interface StatsManagerProps {
  services: ServiceRecord[];
  invoices: Invoice[];
  vehicles: Vehicle[];
  customers: Customer[];
  statsSettings: StatsSettings;
  companyInfo: CompanyInfo;
}

type Period = 'week' | 'month' | 'all';
type Tab = 'finance' | 'orders' | 'database' | 'charts';

const StatsManager: React.FC<StatsManagerProps> = ({ services, invoices, vehicles, customers, statsSettings, companyInfo }) => {
  const [period, setPeriod] = useState<Period>('all');
  const [activeTab, setActiveTab] = useState<Tab>('finance');

  const stats = useMemo(() => {
    const now = new Date();
    const currentYear = now.getFullYear();

    const filterByPeriod = (dateStr: string) => {
      if (period === 'all') return true;
      const date = new Date(dateStr);
      if (period === 'month') {
        return date.getMonth() === now.getMonth() && date.getFullYear() === now.getFullYear();
      }
      if (period === 'week') {
        const startOfWeek = new Date(now);
        const day = now.getDay();
        const diff = now.getDate() - day + (day === 0 ? -6 : 1);
        startOfWeek.setDate(diff);
        startOfWeek.setHours(0, 0, 0, 0);
        return date >= startOfWeek;
      }
      return true;
    };

    const periodServices = services.filter(s => filterByPeriod(s.date));
    const periodInvoices = invoices.filter(inv => filterByPeriod(inv.issueDate));

    const completedOrders = periodServices.filter(s => s.status === 'hotovo').length;
    const cancelledOrders = periodServices.filter(s => s.status === 'zrušeno').length;

    // Základem pro statistiky je obrat bez DPH (sumujeme základ)
    // Fix: Added explicit type to turnoverExclDph and ensure sum is numeric
    const turnoverExclDph: number = periodInvoices.reduce((sum: number, inv) => sum + (Number(inv.totalExclDph) || 0), 0);

    // Náklady na materiál (z faktur)
    // Fix: Added explicit type to materialCostsExclDph and ensure sum is numeric
    const materialCostsExclDph: number = periodInvoices.reduce((sum: number, inv) => sum + (Number(inv.costs) || 0), 0);

    // Režijní náklady (z nastavení)
    // Fix: Added explicit type to overheadCostsExclDph
    let overheadCostsExclDph: number = 0;
    const costItems = statsSettings.costItems || [];
    const recurringSum = costItems.filter(item => item.isRecurring).reduce((sum: number, item) => sum + (Number(item.amount) || 0), 0);
    const oneTimeSum = costItems.filter(item => !item.isRecurring).reduce((sum: number, item) => sum + (Number(item.amount) || 0), 0);

    if (period === 'month') {
      overheadCostsExclDph = recurringSum + oneTimeSum;
    } else if (period === 'week') {
      overheadCostsExclDph = (recurringSum / 4) + oneTimeSum;
    } else {
      // Pro období "vše" odhadneme počet měsíců z faktur
      const uniqueMonths = new Set(invoices.map(inv => inv.issueDate.substring(0, 7)));
      const monthsCount = Math.max(1, uniqueMonths.size);
      overheadCostsExclDph = (monthsCount * recurringSum) + oneTimeSum;
    }

    // Fix: Added explicit type to totalCostsExclDph to ensure correct arithmetic inference
    const totalCostsExclDph: number = materialCostsExclDph + overheadCostsExclDph;

    // Konzistentní přepočet s DPH pro zobrazení z vypočteného základu
    const turnoverInclDph = companyInfo.isVatPayer ? turnoverExclDph * 1.21 : turnoverExclDph;
    const totalCostsInclDph = companyInfo.isVatPayer ? totalCostsExclDph * 1.21 : totalCostsExclDph;

    // Fix: Cast variables to number to avoid arithmetic operation errors on inferred types
    const netProfit = (turnoverExclDph as number) - (totalCostsExclDph as number);
    const avgOrderValue = completedOrders > 0 ? turnoverInclDph / completedOrders : 0;

    // --- Statistika vozidel ---
    const totalMileage = vehicles.reduce((sum: number, v) => sum + (Number(v.mileage) || 0), 0);
    const avgMileage = vehicles.length > 0 ? Math.round(totalMileage / vehicles.length) : 0;

    const totalYears = vehicles.reduce((sum: number, v) => sum + (v.year ? (currentYear - v.year) : 0), 0);
    const avgAge = vehicles.length > 0 ? (totalYears / vehicles.length).toFixed(1) : "0";

    // Palivo
    const fuelCounts = vehicles.reduce((acc: Record<string, number>, v) => {
      const fuel = v.fuelType || 'Neznámo';
      acc[fuel] = (acc[fuel] || 0) + 1;
      return acc;
    }, {});

    // Výrobci
    const makeCounts = vehicles.reduce((acc: Record<string, number>, v) => {
      const make = v.make || 'Neznámo';
      acc[make] = (acc[make] || 0) + 1;
      return acc;
    }, {});
    const topMakes = Object.entries(makeCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3);

    // Data pro grafy - trendy za posledních 6 měsíců
    const last6Months = Array.from({ length: 6 }).map((_, i) => {
      const d = new Date();
      d.setMonth(d.getMonth() - (5 - i));
      return d.toISOString().substring(0, 7);
    });

    const chartData = last6Months.map(monthStr => {
      const monthInvoices = invoices.filter(inv => inv.issueDate.startsWith(monthStr));
      const monthTurnover = monthInvoices.reduce((sum: number, inv) => sum + (Number(inv.totalExclDph) || 0), 0);
      const monthCosts = monthInvoices.reduce((sum: number, inv) => sum + (Number(inv.costs) || 0), 0) + recurringSum;
      return {
        name: new Date(monthStr).toLocaleDateString('cs-CZ', { month: 'short' }),
        obrat: Math.round(monthTurnover),
        naklady: Math.round(monthCosts),
        zisk: Math.round(monthTurnover - monthCosts)
      };
    });

    return {
      completedOrders,
      cancelledOrders,
      turnoverExclDph: Math.round(turnoverExclDph),
      turnoverInclDph: Math.round(turnoverInclDph),
      netProfit: Math.round(netProfit),
      totalCostsExclDph: Math.round(totalCostsExclDph),
      totalCostsInclDph: Math.round(totalCostsInclDph),
      overheadCosts: Math.round(overheadCostsExclDph),
      materialCosts: Math.round(materialCostsExclDph),
      invoiceCount: periodInvoices.length,
      avgOrderValue: Math.round(avgOrderValue),
      avgMileage,
      avgAge,
      fuelCounts,
