          {activeView === 'invoices' && <InvoiceManager invoices={invoices} customers={customers} services={services} companyInfo={companyInfo} discountLevels={discountLevels} onDeleteInvoice={(uid) => setInvoices(prev => prev.filter(inv => inv.uid !== uid))} onUpdateInvoiceStatus={(uid, status) => setInvoices(prev => prev.map(inv => inv.uid === uid ? {...inv, status} : inv))} onUpdateInvoice={handleUpdateInvoice} search={invoiceSearch} onSearchChange={setInvoiceSearch} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetCustomerId(null); }} search={customerSearch} onSearchChange={setCustomerSearch} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} onCreateOrder={handleCreateOrderForVehicle} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetVehicleId(null); }} search={vehicleSearch} onSearchChange={setVehicleSearch} />}
          {activeView === 'archive' && <ArchiveManager services={services} invoices={invoices} vehicles={vehicles} customers={customers} companyInfo={companyInfo} hourlyRate={hourlyRate} search={archiveSearch} onSearchChange={setArchiveSearch} onNavigateToOrder={handleNavigateToOrder} />}
          {activeView === 'stats' && <StatsManager services={services} invoices={invoices} vehicles={vehicles} customers={customers} statsSettings={statsSettings} companyInfo={companyInfo} />}
          {activeView === 'settings' && <Settings technicians={technicians} onTechniciansChange={setTechnicians} predefinedTasks={predefinedTasks} onPredefinedTasksChange={setPredefinedTasks} discountLevels={discountLevels} onDiscountLevelsChange={setDiscountLevels} hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} statsSettings={statsSettings} onStatsSettingsChange={setStatsSettings} customers={customers} vehicles={vehicles} services={services} invoices={invoices} onRestoreData={handleRestoreData} onClearAllData={handleClearAllData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={() => {}} setDirectoryHandle={() => {}} directoryHandle={null} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  BarChart3, TrendingUp, Coins, Users, Car, CheckCircle2, 
  ArrowUpRight, ArrowDownRight, Wallet, Calculator,
  AlertCircle, PieChart, History, Gauge, Calendar
} from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';
import { ServiceRecord, Invoice, Vehicle, Customer, StatsSettings, CompanyInfo } from '../types';

interface StatsManagerProps {
  services: ServiceRecord[];
  invoices: Invoice[];
  vehicles: Vehicle[];
  customers: Customer[];
  statsSettings: StatsSettings;
  companyInfo: CompanyInfo;
}

type Period = 'week' | 'month' | 'all';
type Tab = 'finance' | 'orders' | 'database' | 'charts';

const StatsManager: React.FC<StatsManagerProps> = ({ services, invoices, vehicles, customers, statsSettings, companyInfo }) => {
  const [period, setPeriod] = useState<Period>('all');
  const [activeTab, setActiveTab] = useState<Tab>('finance');

  const stats = useMemo(() => {
    const now = new Date();
    const currentYear = now.getFullYear();

    const filterByPeriod = (dateStr: string) => {
      if (period === 'all') return true;
      const date = new Date(dateStr);
      if (period === 'month') {
        return date.getMonth() === now.getMonth() && date.getFullYear() === now.getFullYear();
      }
      if (period === 'week') {
        const startOfWeek = new Date(now);
        const day = now.getDay();
        const diff = now.getDate() - day + (day === 0 ? -6 : 1);
        startOfWeek.setDate(diff);
        startOfWeek.setHours(0, 0, 0, 0);
        return date >= startOfWeek;
      }
      return true;
    };

    const periodServices = services.filter(s => filterByPeriod(s.date));
    const periodInvoices = invoices.filter(inv => filterByPeriod(inv.issueDate));

    const completedOrders = periodServices.filter(s => s.status === 'hotovo').length;
    const cancelledOrders = periodServices.filter(s => s.status === 'zrušeno').length;

    // Základem pro statistiky je obrat bez DPH (sumujeme základ)
    const turnoverExclDph: number = periodInvoices.reduce((sum: number, inv) => sum + (Number(inv.totalExclDph) || 0), 0);

    // Náklady na materiál (z faktur)
    const materialCostsExclDph: number = periodInvoices.reduce((sum: number, inv) => sum + (Number(inv.costs) || 0), 0);

    // Režijní náklady (z nastavení)
    let overheadCostsExclDph: number = 0;
    const costItems = statsSettings.costItems || [];
    const recurringSum = costItems.filter(item => item.isRecurring).reduce((sum: number, item) => sum + (Number(item.amount) || 0), 0);
    const oneTimeSum = costItems.filter(item => !item.isRecurring).reduce((sum: number, item) => sum + (Number(item.amount) || 0), 0);

    if (period === 'month') {
      overheadCostsExclDph = recurringSum + oneTimeSum;
    } else if (period === 'week') {
      overheadCostsExclDph = (recurringSum / 4) + oneTimeSum;
    } else {
      // Pro období "vše" odhadneme počet měsíců z faktur
      const uniqueMonths = new Set(invoices.map(inv => inv.issueDate.substring(0, 7)));
      const monthsCount = Math.max(1, uniqueMonths.size);
      overheadCostsExclDph = (monthsCount * recurringSum) + oneTimeSum;
    }

    const totalCostsExclDph: number = materialCostsExclDph + overheadCostsExclDph;

    // Konzistentní přepočet s DPH pro zobrazení z vypočteného základu
    const turnoverInclDph = companyInfo.isVatPayer ? turnoverExclDph * 1.21 : turnoverExclDph;
    const totalCostsInclDph = companyInfo.isVatPayer ? totalCostsExclDph * 1.21 : totalCostsExclDph;

    /* FIX: Ensured netProfit calculation uses guaranteed number types */
    const netProfit = turnoverExclDph - totalCostsExclDph;
    const avgOrderValue = completedOrders > 0 ? turnoverInclDph / completedOrders : 0;

    // --- Statistika vozidel ---
    const totalMileage = vehicles.reduce((sum: number, v) => sum + (Number(v.mileage) || 0), 0);
    const avgMileage = vehicles.length > 0 ? Math.round(totalMileage / vehicles.length) : 0;

    const totalYears = vehicles.reduce((sum: number, v) => sum + (v.year ? (currentYear - v.year) : 0), 0);
    const avgAge = vehicles.length > 0 ? (totalYears / vehicles.length).toFixed(1) : "0";

    // Palivo
    const fuelCounts = vehicles.reduce((acc: Record<string, number>, v) => {
      const fuel = v.fuelType || 'Neznámo';
      acc[fuel] = (acc[fuel] || 0) + 1;
      return acc;
    }, {});

    // Výrobci
    const makeCounts = vehicles.reduce((acc: Record<string, number>, v) => {
      const make = v.make || 'Neznámo';
      acc[make] = (acc[make] || 0) + 1;
      return acc;
    }, {});
    const topMakes = Object.entries(makeCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3);

    // Data pro grafy - trendy za posledních 6 měsíců
    const last6Months = Array.from({ length: 6 }).map((_, i) => {
      const d = new Date();
      d.setMonth(d.getMonth() - (5 - i));
      return d.toISOString().substring(0, 7);
    });

    const chartData = last6Months.map(monthStr => {
      const monthInvoices = invoices.filter(inv => inv.issueDate.startsWith(monthStr));
      const monthTurnover = monthInvoices.reduce((sum: number, inv) => sum + (Number(inv.totalExclDph) || 0), 0);
      const monthCosts = monthInvoices.reduce((sum: number, inv) => sum + (Number(inv.costs) || 0), 0) + recurringSum;
      return {
        name: new Date(monthStr).toLocaleDateString('cs-CZ', { month: 'short' }),
        obrat: Math.round(monthTurnover),
        naklady: Math.round(monthCosts),
        zisk: Math.round(monthTurnover - monthCosts)
      };
    });

    return {
      completedOrders,
      cancelledOrders,
      turnoverExclDph: Math.round(turnoverExclDph),
      turnoverInclDph: Math.round(turnoverInclDph),
      netProfit: Math.round(netProfit),
      totalCostsExclDph: Math.round(totalCostsExclDph),
      totalCostsInclDph: Math.round(totalCostsInclDph),
      overheadCosts: Math.round(overheadCostsExclDph),
      materialCosts: Math.round(materialCostsExclDph),
      invoiceCount: periodInvoices.length,
      avgOrderValue: Math.round(avgOrderValue),
      avgMileage,
      avgAge,
      fuelCounts,
      topMakes,
      chartData
    };
  }, [services, invoices, vehicles, period, statsSettings, companyInfo]);

  const tabs = [
    { id: 'finance', label: 'Finance', icon: Coins },
    { id: 'orders', label: 'Zakázky', icon: History },
    { id: 'database', label: 'Zákazníci/Vozidla', icon: Users },
    { id: 'charts', label: 'Grafy', icon: BarChart3 },
  ];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Statistiky servisu</h2>
          <p className="text-slate-500 font-medium">Analýza výkonnosti a ekonomiky vašeho podnikání.</p>
        </div>

        <div className="bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm flex gap-1">
          {[
            { id: 'week', label: 'Týden' },
            { id: 'month', label: 'Měsíc' },
            { id: 'all', label: 'Vše' }
          ].map((p) => (
            <button
              key={p.id}
              onClick={() => setPeriod(p.id as Period)}
              className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${
                period === p.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' 
                  : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              {p.label.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap gap-2 p-1.5 bg-slate-200/50 w-full sm:w-fit rounded-2xl border border-slate-100">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as Tab)}
            className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-xl text-xs font-black transition-all ${
              activeTab === tab.id 
                ? 'bg-white text-blue-600 shadow-md scale-[1.02]' 
                : 'text-slate-500 hover:text-slate-800'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label.toUpperCase()}
          </button>
        ))}
      </div>

      <div className="min-h-[500px]">
        {activeTab === 'finance' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-left-4 duration-500">
            <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:scale-110 transition-transform">
                <Coins className="w-32 h-32 text-blue-900" />
              </div>
              <div className="relative z-10">
                <div className="w-12 h-12 rounded-2xl bg-blue-50 flex items-center justify-center mb-6">
                  <Coins className="w-6 h-6 text-blue-600" />
                </div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Obrat v období</p>
                <div className="flex items-baseline gap-3 flex-wrap">
                  <h3 className="text-3xl font-black text-slate-900 tracking-tighter">
                    {stats.turnoverInclDph.toLocaleString()} Kč
                  </h3>
                  <span className="text-sm font-bold text-slate-400">
                    ({stats.turnoverExclDph.toLocaleString()} Kč <span className="text-[10px] uppercase font-black">bez DPH</span>)
                  </span>
                </div>
                <div className="mt-4 flex items-center gap-2 text-blue-600">
                  <ArrowUpRight className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase">z {stats.invoiceCount} dokladů</span>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm relative overflow-hidden group">
              <div className="relative z-10">
                <div className="w-12 h-12 rounded-2xl bg-red-50 flex items-center justify-center mb-6 text-red-600">
                  <Calculator className="w-6 h-6" />
                </div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Celkové výdaje</p>
                <div className="flex items-baseline gap-3 flex-wrap">
                  <h3 className="text-3xl font-black text-slate-900 tracking-tighter">
                    {stats.totalCostsInclDph.toLocaleString()} Kč
                  </h3>
                  <span className="text-sm font-bold text-slate-400">
                    ({stats.totalCostsExclDph.toLocaleString()} Kč <span className="text-[10px] uppercase font-black">bez DPH</span>)
                  </span>
                </div>
                <div className="mt-4 flex flex-col gap-1">
                   <div className="flex items-center gap-2 text-red-500">
                      <ArrowDownRight className="w-3 h-3" />
                      <span className="text-[9px] font-bold uppercase">Materiál: {stats.materialCosts.toLocaleString()} Kč</span>
                   </div>
                   <div className="flex items-center gap-2 text-slate-400">
                      <ArrowDownRight className="w-3 h-3" />
                      <span className="text-[9px] font-bold uppercase">Provoz: {stats.overheadCosts.toLocaleString()} Kč</span>
                   </div>
                </div>
              </div>
            </div>

            <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group lg:col-span-1">
              <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform">
                <TrendingUp className="w-32 h-32 text-emerald-400" />
              </div>
              <div className="relative z-10">
                <div className="w-12 h-12 rounded-2xl bg-emerald-500/20 flex items-center justify-center mb-6 border border-emerald-500/30">
                  <TrendingUp className="w-6 h-6 text-emerald-400" />
                </div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Čistý zisk (bez DPH)</p>
                <h3 className="text-3xl font-black text-white tracking-tighter">
                  {stats.netProfit.toLocaleString()} Kč
                </h3>
                <div className="mt-4 flex items-center gap-2 text-emerald-400">
                  <CheckCircle2 className="w-4 h-4" />
                  <span className="text-xs font-bold uppercase">Odhadovaný profit</span>
                </div>
              </div>
            </div>

            <div className="md:col-span-2 lg:col-span-3 bg-slate-50 rounded-[2.5rem] p-10 border border-slate-100 mt-4">
              <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6">Rozdělení financí v období (v základu daně)</h4>
              <div className="space-y-6">
