  { id: 'v4', customerId: 'c2', make: 'BMW', model: 'M3 Competition', year: 2023, vin: 'WBS31AR020LM45678', licensePlate: '1AA 0001', mileage: 8500, engineCode: 'S58 (3.0 Bi-Turbo)', color: 'Isle of Man Green', lastServiceDate: '2024-03-01', stkExpirationDate: new Date(Date.now() + 45 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], nextServiceDate: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0], brakeFluidInterval: 24, coolantInterval: 60, gearboxOilInterval: 60, timingBeltInterval: 120, refrigerantInterval: 24 },
];

