const INITIAL_FIXED_SERVICES: FixedService[] = [
  { id: 'fs1', name: 'Prezutí', price: 800, costPrice: 0 },
  { id: 'fs2', name: 'Vyvážení', price: 400, costPrice: 50 },
  { id: 'fs3', name: 'Prezutí + vyvážení', price: 1200, costPrice: 50 },
