                         type="number" 
                         step="0.5"
                         className="bg-transparent outline-none font-black text-[11px] w-10 py-0.5 text-center" 
                         value={order.laborHours || 0} 
                         onChange={(e) => onUpdateOrder?.('laborHours', parseFloat(e.target.value) || 0)} 
                       />
                       <span className="text-[9px] font-black">h</span>
