                   <span className="text-[8px] text-slate-400 font-normal ml-1">({displayPrice(hourlyRate)}/h)</span>
                </div>
                <span className="font-black text-[10px]">{Math.round((order.laborHours || 0) * displayPrice(hourlyRate)).toLocaleString()} Kč</span>
             </div>

             {company?.isVatPayer ? (
               <>
