                 <div className="flex justify-between p-1.5 border-b border-black font-black text-[10px]"><span>DPH 21%</span><span>{Math.round((order.cost || 0) * 0.21).toLocaleString()} Kč</span></div>
                 <div className="flex flex-col p-3 bg-white min-h-[70px] justify-center border-b-2 border-black"><span className="text-[9px] font-bold uppercase text-slate-400 text-center">Cena opravy celkem (zaokrouhleno)</span><span className="text-[24px] font-black text-center mt-0.5">{Math.round((order.cost || 0) * 1.21).toLocaleString()} Kč</span></div>
               </>
             ) : (
               <div className="flex flex-col p-4 bg-white min-h-[90px] justify-center border-b-2 border-black">
                 <span className="text-[11px] font-black uppercase text-slate-400 text-center mb-0.5">CELKOVÁ CENA K ÚHRADĚ</span>
