      <div className="mt-4 flex justify-between text-[8px] font-bold uppercase opacity-60"><span>71 00 033</span><span>{new Date().toLocaleDateString('cs-CZ')} {new Date().toLocaleTimeString('cs-CZ', { hour: '2-digit', minute: '2-digit' })}</span><span>AUTOSERVICE PRO SYSTEM</span></div>
