              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const InvoiceCard: React.FC<{
  inv: Invoice;
  customers: Customer[];
  today: string;
  onSelect: (inv: Invoice) => void;
  onDelete: (inv: Invoice) => void;
  onUpdateStatus: (uid: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onArchive: (inv: Invoice) => void;
  openMenuId: string | null;
  onOpenMenu: (uid: string | null) => void;
}> = ({ inv, customers, today, onSelect, onDelete, onUpdateStatus, onArchive, openMenuId, onOpenMenu }) => {
  const customer = customers.find(c => c.id === inv.customerId);
  const isOverdue = inv.status === 'neuhrazeno' && inv.dueDate < today;
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onOpenMenu(null);
      }
    };
    if (openMenuId === inv.uid) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [openMenuId, inv.uid, onOpenMenu]);

  return (
    <div className={`bg-white rounded-[2rem] border p-6 transition-all hover:shadow-xl group relative overflow-visible ${isOverdue ? 'border-red-200 bg-red-50/10' : 'border-slate-100'}`}>
      <div className="flex justify-between items-start mb-4">
        <div className="flex items-center gap-4">
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${inv.status === 'uhrazeno' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
            <Receipt className="w-6 h-6" />
          </div>
          <div>
            <h4 className="text-base font-black text-slate-900">{inv.id}</h4>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{formatDate(inv.issueDate)}</p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          <button onClick={() => onSelect(inv)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all">
            <Eye className="w-5 h-5" />
          </button>
          <div className="relative">
            <button 
              onClick={(e) => { e.stopPropagation(); onOpenMenu(openMenuId === inv.uid ? null : inv.uid); }}
              className={`p-2 rounded-xl transition-all ${openMenuId === inv.uid ? 'bg-slate-100 text-slate-900 shadow-inner' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'}`}
            >
              <MoreHorizontal className="w-5 h-5" />
            </button>
            {openMenuId === inv.uid && (
              <div 
                ref={menuRef}
                className="absolute top-10 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
              >
                <button 
                  onClick={(e) => { e.stopPropagation(); onUpdateStatus(inv.uid, inv.status === 'uhrazeno' ? 'neuhrazeno' : 'uhrazeno'); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                >
                  {inv.status === 'uhrazeno' ? <XCircle className="w-4 h-4 text-amber-500" /> : <CheckCircle className="w-4 h-4 text-emerald-500" />}
                  {inv.status === 'uhrazeno' ? 'Neuhrazeno' : 'Uhrazeno'}
                </button>
                {inv.status === 'uhrazeno' && (
                  <button 
                    onClick={(e) => { e.stopPropagation(); onArchive(inv); onOpenMenu(null); }}
                    className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"
                  >
                    <Archive className="w-4 h-4" /> Archivovat
                  </button>
                )}
                <div className="h-px bg-slate-100 my-1"></div>
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(inv); onOpenMenu(null); }}
                  className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                >
                  <Trash2 className="w-4 h-4" /> Smazat
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="space-y-2 mb-6">
        <p className="text-sm font-bold text-slate-700 truncate">
          {customer?.customerType === 'firemní' ? (customer?.companyName || `${customer?.firstName} ${customer?.lastName}`) : `${customer?.firstName} ${customer?.lastName}`}
        </p>
        <p className="text-[10px] font-bold text-blue-600 uppercase truncate">{inv.vehicleInfo}</p>
      </div>

      <div className="flex items-center justify-between pt-4 border-t border-slate-50">
        <div className="flex flex-col">
          <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Splatnost</span>
          <span className={`text-[11px] font-black ${isOverdue ? 'text-red-600' : 'text-slate-600'}`}>
            {formatDate(inv.dueDate)}
            {isOverdue && ' (PO SPLATNOSTI)'}
          </span>
        </div>
        <div className="text-right">
          <p className="text-lg font-black text-slate-900">{Math.round(inv.totalInclDph).toLocaleString()} Kč</p>
          <p className="text-[10px] font-bold text-slate-400 uppercase">{inv.totalInclDph !== inv.totalExclDph ? 'včetně DPH' : ''}</p>
        </div>
      </div>
    </div>
  );
};

export const InvoicePrintTemplate: React.FC<{
  invoice: Invoice;
  company: CompanyInfo;
  customers: Customer[];
  order?: ServiceRecord | null;
}> = ({ invoice, company, customers, order }) => {
  const customer = customers.find(c => c.id === invoice.customerId);
  const totalExclDph = (invoice.items || []).reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
  const discountPercent = Number(invoice.discount) || 0;
  const discountAmount = totalExclDph * (discountPercent / 100);
  const finalExclDph = totalExclDph - discountAmount;

  const isPayer = company.isVatPayer;
  const vatAmount = isPayer ? Math.round(finalExclDph * 0.21) : 0;
  const finalInclDph = isPayer ? Math.round(finalExclDph + vatAmount) : Math.round(finalExclDph);

  const items = invoice.items || [];
  const emptyRowsCount = Math.max(0, 12 - items.length);

  return (
    <div className="bg-white p-4 text-black font-sans print-block" style={{ width: '200mm', minHeight: '275mm', margin: '0 auto', border: '2px solid #000' }}>

      <div className="grid grid-cols-2 border-b-2 border-black">
        <div className="p-3 border-r-2 border-black">
          <p className="text-[10px] font-bold uppercase mb-1">DODAVATEL:</p>
          <div className="text-[12px] leading-tight">
            <p className="font-black text-[14px]">{company.name}</p>
            <p>{company.address}</p>
            <p className="mt-1 font-bold">IČ: {company.ico} {isPayer && `DIČ: ${company.dic}`}</p>
            <p className="font-bold italic">Banka: {company.bankAccount || '---'}</p>
          </div>
        </div>
        <div className="p-3 flex flex-col justify-start">
          <h1 className="text-[16px] font-black uppercase mb-2 tracking-tighter">FAKTURA - DAŇOVÝ DOKLAD č.</h1>
          <p className="text-[22px] font-black text-right pr-4">{invoice.id}</p>
        </div>
      </div>

      <div className="grid grid-cols-2 border-b-2 border-black">
        <div className="p-3 border-r-2 border-black bg-gray-50/20">
          <p className="text-[10px] font-bold uppercase mb-1">ODBĚRATEL:</p>
          <div className="text-[12px] leading-tight ml-4">
            {customer?.customerType === 'firemní' ? (
              <>
                <p className="font-black text-[14px] uppercase">{customer?.companyName}</p>
                <p>{customer?.companyAddress || customer?.address}</p>
                <p className="mt-1 font-bold">IČ: {customer?.ico || '---'} {customer?.dic && `DIČ: ${customer?.dic}`}</p>
              </>
            ) : (
              <>
                <p className="font-black text-[14px] uppercase">{customer?.firstName} {customer?.lastName}</p>
                <p>{customer?.address}</p>
                <p className="mt-1 font-bold">Tel: {customer?.phone}</p>
              </>
            )}
          </div>
        </div>
        <div className="p-3 bg-white">
          <p className="text-[10px] font-bold uppercase mb-1">VOZIDLO:</p>
          <div className="text-[12px] leading-tight ml-4">
            <p className="font-black text-[14px] uppercase text-blue-600">{invoice.vehicleInfo}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-5 text-[9px] border-b-2 border-black font-bold uppercase bg-gray-100">
        <div className="p-1.5 border-r-2 border-black text-center">Převzetí do opravy<br /><span className="text-[10px] mt-1 block">{formatDate(order?.date || invoice.issueDate)}</span></div>
        <div className="p-1.5 border-r-2 border-black text-center">Ukončení opravy<br /><span className="text-[10px] mt-1 block">{formatDate(order?.deliveryDate || invoice.issueDate)}</span></div>
        <div className="p-1.5 border-r-2 border-black text-center">Zdanitel. plnění<br /><span className="text-[10px] mt-1 block">{formatDate(invoice.issueDate)}</span></div>
        <div className="p-1.5 border-r-2 border-black text-center">Způsob platby<br /><span className="text-[10px] mt-1 block">{invoice.paymentType}</span></div>
        <div className="p-1.5 text-center bg-yellow-50/50">Splatnost<br /><span className="text-[10px] mt-1 block font-black">{formatDate(invoice.dueDate)}</span></div>
      </div>

      <div className="relative border-b-2 border-black" style={{ minHeight: '450px' }}>
        <div className="absolute top-0 bottom-0 left-[60px] w-[1.5px] bg-black"></div>
        <div className="absolute top-0 bottom-0 left-[calc(100%-200px)] w-[1.5px] bg-black"></div>
        <div className="absolute top-0 bottom-0 left-[calc(100%-100px)] w-[1.5px] bg-black"></div>

        <table className="w-full border-collapse relative z-10">
          <thead>
            <tr className="border-b-2 border-black text-[9px] font-black uppercase bg-gray-50 h-8">
              <th className="px-2 w-[60px] text-center">Množství</th>
              <th className="px-3 text-left">Popis položky</th>
              <th className="px-2 text-right w-[100px]">Cena/J</th>
              <th className="px-2 text-right w-[100px]">CELKEM</th>
            </tr>
          </thead>
          <tbody className="text-[11px]">
            {items.map((item, idx) => (
              <tr key={idx} className="border-b border-gray-300 h-7 font-bold">
                <td className="px-2 text-center whitespace-nowrap">{item.quantity} {item.unit || 'ks'}</td>
                <td className="px-3">{item.description}</td>
                <td className="px-2 text-right">{Math.round(item.unitPrice).toLocaleString()} Kč</td>
