                  <button 
                    onClick={handlePohodaExport}
                    disabled={selectedExportUids.size === 0}
                    className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase shadow-xl shadow-blue-200 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center gap-2"
