  const [userSettings, setUserSettings] = useState<UserSettings>(() => {
    const saved = localStorage.getItem('userSettings');
    return saved ? JSON.parse(saved) : { enabled: false, username: 'admin', password: '' };
  });
  const [isAuthenticated, setIsAuthenticated] = useState(!userSettings.enabled);

  const [autoBackupSettings, setAutoBackupSettings] = useState<AutoBackupSettings>(() => {
    const saved = localStorage.getItem('autoBackupSettings');
    return saved ? JSON.parse(saved) : { enabled: false, hour: 20, lastBackupDate: null, folderName: null };
  });

  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);
  useEffect(() => { localStorage.setItem('vehicles', JSON.stringify(vehicles)); }, [vehicles]);
  useEffect(() => { localStorage.setItem('services', JSON.stringify(services)); }, [services]);
  useEffect(() => { localStorage.setItem('invoices', JSON.stringify(invoices)); }, [invoices]);
  useEffect(() => { localStorage.setItem('hourlyRate', JSON.stringify(hourlyRate)); }, [hourlyRate]);
  useEffect(() => { localStorage.setItem('fixedServices', JSON.stringify(fixedServices)); }, [fixedServices]);
  useEffect(() => { localStorage.setItem('predefinedTasks', JSON.stringify(predefinedTasks)); }, [predefinedTasks]);
  useEffect(() => { localStorage.setItem('discountLevels', JSON.stringify(discountLevels)); }, [discountLevels]);
  useEffect(() => { localStorage.setItem('technicians', JSON.stringify(technicians)); }, [technicians]);
  useEffect(() => { localStorage.setItem('companyInfo', JSON.stringify(companyInfo)); }, [companyInfo]);
  useEffect(() => { localStorage.setItem('notifSettings', JSON.stringify(notifSettings)); }, [notifSettings]);
  useEffect(() => { localStorage.setItem('statsSettings', JSON.stringify(statsSettings)); }, [statsSettings]);
  useEffect(() => { localStorage.setItem('selectedPrinter', JSON.stringify(selectedPrinter)); }, [selectedPrinter]);
  useEffect(() => { 
    localStorage.setItem('userSettings', JSON.stringify(userSettings));
    if (!userSettings.enabled) {
      setIsAuthenticated(true);
    }
  }, [userSettings]);

  const syncVehicleMileage = useCallback((vehicleId: string, mileageAtEntry?: number) => {
    if (mileageAtEntry === undefined || mileageAtEntry === null || mileageAtEntry === 0) return;
    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === vehicleId && mileageAtEntry > v.mileage) {
        return { ...v, mileage: mileageAtEntry };
      }
      return v;
    }));
  }, []);

  const syncVehicleDates = useCallback((service: ServiceRecord) => {
    if (service.status !== 'hotovo') return;

    const parts = service.parts || [];
    const mainDesc = (service.description || "").toLowerCase();
    const partsText = parts.map(p => (p.description || "").toLowerCase()).join(" ");
    const fullText = `${mainDesc} ${partsText}`;

    const hasSTK = fullText.includes('ek+tk') || fullText.includes('technicka kontrola') || fullText.includes('technická kontrola');
    const hasOil = fullText.includes('motorovy olej') || fullText.includes('motorový olej') || fullText.includes('vymena oleje');

    // Nově sledované výrazy
    const hasBrakeFluid = fullText.includes('brzdova kapalina') || fullText.includes('brzdová kapalina');
    const hasCoolant = fullText.includes('chladici kapalina') || fullText.includes('chladící kapalina') || fullText.includes('chlad. kapalina');
    const hasGearboxOil = fullText.includes('prevodovy olej') || fullText.includes('převodový olej') || fullText.includes('olej prevodovky') || fullText.includes('olej převodovky') || fullText.includes('olej prevovy') || fullText.includes('olej převodový');
    const hasTimingBelt = fullText.includes('rozvodova sada') || fullText.includes('rozvodová sada') || fullText.includes('sada rozvodu') || fullText.includes('sada rozvodů');
    const hasRefrigerant = fullText.includes('chladivo r134') || fullText.includes('chladivo klimatizace') || fullText.includes('plneni klimatizace') || fullText.includes('plnění klimatizace');

    const baseDateStr = service.deliveryDate || service.date;
    const baseDate = new Date(baseDateStr);
    if (isNaN(baseDate.getTime())) return;

    setVehicles(prevVehicles => prevVehicles.map(v => {
      if (v.id === service.vehicleId) {
        let updates: Partial<Vehicle> = {};

        if (hasSTK) {
          const nextSTK = new Date(baseDate);
          nextSTK.setFullYear(nextSTK.getFullYear() + 2);
          updates.stkExpirationDate = nextSTK.toISOString().split('T')[0];
        }

        if (hasOil) {
          const nextService = new Date(baseDate);
          const intervalMonths = v.serviceIntervalMonths || 12;
          nextService.setMonth(nextService.getMonth() + intervalMonths);
          updates.nextServiceDate = nextService.toISOString().split('T')[0];
          updates.lastServiceDate = baseDateStr;
        }

        // Aktualizace specifických dat výměn
        if (hasBrakeFluid) updates.brakeFluidDate = baseDateStr;
        if (hasCoolant) updates.coolantDate = baseDateStr;
        if (hasGearboxOil) updates.gearboxOilDate = baseDateStr;
        if (hasTimingBelt) updates.timingBeltDate = baseDateStr;
        if (hasRefrigerant) updates.refrigerantDate = baseDateStr;

        return { ...v, ...updates };
      }
      return v;
    }));
  }, []);

  const handleAddService = (service: ServiceRecord) => {
    setServices(prev => [service, ...prev]);
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
    syncVehicleDates(service);
  };

  const handleUpdateService = (service: ServiceRecord) => {
    setServices(prev => prev.map(item => item.id === service.id ? service : item));
    syncVehicleMileage(service.vehicleId, service.mileageAtEntry);
    syncVehicleDates(service);
  };

  const handleUpdateInvoice = (updatedInvoice: Invoice) => {
    setInvoices(prev => prev.map(inv => inv.uid === updatedInvoice.uid ? updatedInvoice : inv));
  };

  const handleCreateInvoiceFromOrder = (orderId: string) => {
    const order = services.find(s => s.id === orderId);
    if (!order) return;

    const vehicle = vehicles.find(v => v.id === order.vehicleId);
    if (!vehicle) return;

    const existingInvoice = invoices.find(inv => inv.orderId === orderId);
    if (existingInvoice) {
      setActiveView('invoices');
      return;
    }

    const invoiceItems: PartItem[] = [];
    if (order.parts && order.parts.length > 0) {
      order.parts.forEach(p => invoiceItems.push({ ...p }));
    }

    if (order.laborHours && order.laborHours > 0) {
      invoiceItems.push({ 
        id: `labor-${Date.now()}`, 
        description: `Servisní práce (${order.laborHours} h)`, 
        quantity: order.laborHours, 
        unit: 'h', 
        unitPrice: hourlyRate,
        costPrice: 0 
      });
    }

    if (invoiceItems.length === 0 && order.cost > 0) {
      invoiceItems.push({
        id: `fallback-${Date.now()}`,
        description: 'Servisní práce a materiál (dle zakázky)',
        quantity: 1,
        unit: 'ks',
        unitPrice: order.cost,
        costPrice: 0
      });
    }

    const taxDateStr = order.deliveryDate || order.date;
    const issueDate = new Date(taxDateStr);
    const dueDate = new Date(issueDate);
    dueDate.setDate(dueDate.getDate() + 14);

    const yearPrefix = new Date().getFullYear().toString().slice(-2);
    const monthPrefix = (new Date().getMonth() + 1).toString().padStart(2, '0');
    const prefix = `${yearPrefix}/${monthPrefix}/`;

    // FIX: Inteligentní vyhledání první volné mezery v číselné řadě namísto prostého maxSeq+1
    const monthlyInvoices = invoices.filter(inv => inv.id.startsWith(prefix));
    const usedSequences = new Set(monthlyInvoices.map(inv => {
      const parts = inv.id.split('/');
      return parseInt(parts[parts.length - 1]);
    }));

    let seq = 1;
    while (usedSequences.has(seq)) {
      seq++;
    }

    const nextSequence = seq.toString().padStart(3, '0');
    const invoiceId = `${prefix}${nextSequence}`;

    const calculatedTotalExclDph = invoiceItems.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);

    const newInvoice: Invoice = {
      uid: `inv-uid-${Math.random().toString(36).substr(2, 9)}`,
      id: invoiceId,
      orderId: order.id,
      issueDate: taxDateStr,
      dueDate: dueDate.toISOString().split('T')[0],
      customerId: vehicle.customerId,
      vehicleInfo: `${vehicle.make} ${vehicle.model} (${vehicle.licensePlate})`,
      items: invoiceItems,
      totalExclDph: calculatedTotalExclDph,
      totalInclDph: companyInfo.isVatPayer ? Math.round(calculatedTotalExclDph * 1.21) : Math.round(calculatedTotalExclDph),
      paymentType: 'Převodem',
      status: 'neuhrazeno',
      discount: 0,
      costs: Math.round(order.parts?.reduce((sum, p) => sum + ((p.costPrice || 0) * p.quantity), 0) || 0)
    };

    setInvoices([newInvoice, ...invoices]);
    resetAllSearches();
    setActiveView('invoices');
  };

  const resetAllSearches = () => {
    setCustomerSearch('');
    setVehicleSearch('');
    setOrderSearch('');
    setInvoiceSearch('');
    setArchiveSearch('');
  };

  const handleNavigate = (view: AppView, autoOpen: boolean = false) => {
    resetAllSearches();
    setTargetVehicleId(null);
    setTargetOrderId(null);
    setTargetCustomerId(null);
    setActiveView(view);
    setShouldOpenModal(autoOpen);
  };

  const handleRestoreData = (fullState: any) => {
    if (fullState.customers) setCustomers([...fullState.customers]);
    if (fullState.vehicles) setVehicles([...fullState.vehicles]);
    if (fullState.services) setServices([...fullState.services]);

    if (fullState.invoices) {
      // Při importu generujeme nová unikátní UID aby bylo smazání faktur bezpečné i u duplicitních ID
      const sanitizedInvoices = fullState.invoices.map((inv: any) => ({
        ...inv,
        uid: inv.uid || `inv-uid-restored-${Math.random().toString(36).substr(2, 9)}`
      }));
      setInvoices(sanitizedInvoices);
    }

    if (fullState.settings) {
      if (fullState.settings.hourlyRate !== undefined) setHourlyRate(fullState.settings.hourlyRate);
      if (fullState.settings.fixedServices) setFixedServices([...fullState.settings.fixedServices]);
      if (fullState.settings.predefinedTasks) setPredefinedTasks([...fullState.settings.predefinedTasks]);
      if (fullState.settings.technicians) setTechnicians([...fullState.settings.technicians]);
      if (fullState.settings.discountLevels) setDiscountLevels([...fullState.settings.discountLevels]);
    }

    if (fullState.companyInfo) setCompanyInfo({...fullState.companyInfo});
    if (fullState.statsSettings) setStatsSettings({...fullState.statsSettings});
  };

  const handleClearAllData = () => {
    setCustomers([]);
    setVehicles([]);
    setServices([]);
    setInvoices([]);
    resetAllSearches();
    setActiveView('dashboard');
  };

  const handleNavigateToVehicle = (vId: string) => { 
    resetAllSearches();
    const v = vehicles.find(item => item.id === vId);
    if (v) setVehicleSearch(v.licensePlate);
    setTargetVehicleId(vId); 
    setActiveView('vehicles'); 
  };

  const handleNavigateToOrder = (oId: string) => { 
    resetAllSearches();
    const order = services.find(item => item.id === oId);
    if (!order) return;

    const relatedInvoice = invoices.find(inv => inv.orderId === order.id);
    const isArchived = relatedInvoice?.status === 'uhrazeno' && (order.status === 'hotovo' || order.status === 'zrušeno');

    if (isArchived) {
      setArchiveSearch(order.id);
      setActiveView('archive');
    } else {
      setOrderSearch(order.id);
      setActiveView('orders');
    }
  };

  const handleCreateOrderForVehicle = (vId: string) => {
    resetAllSearches();
    setTargetVehicleId(vId);
    setTargetOrderId(null);
    setActiveView('orders');
    setShouldOpenModal(true);
  };

  const handleNavigateToCustomer = (cId: string) => { 
    resetAllSearches();
    const c = customers.find(item => item.id === cId);
    if (c) setCustomerSearch(c.lastName || c.companyName || '');
    setTargetCustomerId(cId); 
    setActiveView('customers'); 
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
  };

  if (userSettings.enabled && !isAuthenticated) {
    return <Login settings={userSettings} onLogin={() => setIsAuthenticated(true)} />;
  }

  const companyNameParts = (companyInfo?.name || '').split(' ');

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden text-slate-900">
      <header className="bg-white border-b border-slate-200 shrink-0 sticky top-0 z-40 shadow-md print:hidden">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 group cursor-pointer" onClick={() => handleNavigate('dashboard')}>
              <div className="bg-blue-600 p-2 rounded-xl shadow-lg shadow-blue-900/20 group-hover:scale-110 transition-transform">
                <Wrench className="w-5 h-5 text-white" />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">
                {companyNameParts[0]} <span className="text-blue-600 font-black">{companyNameParts.slice(1).join(' ')}</span>
              </h1>
            </div>
            <nav className="hidden lg:flex items-center gap-1">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleNavigate(item.id as AppView)}
                  className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-200 text-sm font-bold ${
                    activeView === item.id 
                      ? 'bg-blue-50 text-blue-700' 
                      : 'text-slate-600 hover:text-slate-950 hover:bg-slate-50'
                  }`}
                >
                  <item.icon className="w-4 h-4" />
                  {item.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-4">
            {userSettings.enabled && (
              <button 
                onClick={handleLogout}
                className="hidden lg:flex items-center gap-2 px-4 py-2.5 text-slate-500 hover:text-red-600 font-bold text-sm transition-colors"
              >
                <LogOut className="w-4 h-4" />
                Odhlásit
              </button>
            )}
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-6 md:p-10 print:p-0">
        <div className="max-w-7xl mx-auto pb-10 print:max-w-none">
          {activeView === 'dashboard' && <Dashboard customers={customers} vehicles={vehicles} services={services} onNavigate={handleNavigate} onViewVehicle={handleNavigateToVehicle} onViewOrder={handleNavigateToOrder} notifSettings={notifSettings} />}
          {activeView === 'orders' && <OrderManager services={services} vehicles={vehicles} customers={customers} invoices={invoices} technicians={technicians} predefinedTasks={predefinedTasks} hourlyRate={hourlyRate} fixedServices={fixedServices} companyInfo={companyInfo} onAddService={handleAddService} onUpdateService={handleUpdateService} onDeleteService={(id) => setServices(prev => prev.filter(item => item.id !== id))} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetOrderId(null); setTargetVehicleId(null); }} initialOrderId={targetOrderId} preselectedVehicleId={targetVehicleId} selectedPrinter={selectedPrinter} onCreateInvoice={handleCreateInvoiceFromOrder} search={orderSearch} onSearchChange={setOrderSearch} />}
          {activeView === 'invoices' && <InvoiceManager invoices={invoices} customers={customers} services={services} companyInfo={companyInfo} discountLevels={discountLevels} onDeleteInvoice={(uid) => setInvoices(prev => prev.filter(inv => inv.uid !== uid))} onUpdateInvoiceStatus={(uid, status) => setInvoices(prev => prev.map(inv => inv.uid === uid ? {...inv, status} : inv))} onUpdateInvoice={handleUpdateInvoice} search={invoiceSearch} onSearchChange={setInvoiceSearch} />}
          {activeView === 'customers' && <CustomerManager customers={customers} vehicles={vehicles} setCustomers={setCustomers} onAddCustomer={(c) => setCustomers([c, ...customers])} onUpdateCustomer={(c) => setCustomers(prev => prev.map(item => item.id === c.id ? c : item))} onDeleteCustomer={(id) => setCustomers(prev => prev.filter(item => item.id !== id))} onNavigateToVehicle={handleNavigateToVehicle} initialCustomerId={targetCustomerId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetCustomerId(null); }} search={customerSearch} onSearchChange={setCustomerSearch} />}
          {activeView === 'vehicles' && <VehicleManager vehicles={vehicles} customers={customers} services={services} onAddVehicle={(v) => setVehicles([v, ...vehicles])} onUpdateVehicle={(v) => setVehicles(prev => prev.map(item => item.id === v.id ? v : item))} onDeleteVehicle={(id) => setVehicles(prev => prev.filter(item => item.id !== id))} onNavigateToCustomer={handleNavigateToCustomer} onNavigateToOrder={handleNavigateToOrder} onCreateOrder={handleCreateOrderForVehicle} initialVehicleId={targetVehicleId} autoOpen={shouldOpenModal} onModalOpened={() => { setShouldOpenModal(false); setTargetVehicleId(null); }} search={vehicleSearch} onSearchChange={setVehicleSearch} />}
          {activeView === 'archive' && <ArchiveManager services={services} invoices={invoices} vehicles={vehicles} customers={customers} companyInfo={companyInfo} hourlyRate={hourlyRate} search={archiveSearch} onSearchChange={setArchiveSearch} onNavigateToOrder={handleNavigateToOrder} />}
          {activeView === 'stats' && <StatsManager services={services} invoices={invoices} vehicles={vehicles} customers={customers} statsSettings={statsSettings} companyInfo={companyInfo} />}
          {activeView === 'settings' && <Settings technicians={technicians} onTechniciansChange={setTechnicians} predefinedTasks={predefinedTasks} onPredefinedTasksChange={setPredefinedTasks} discountLevels={discountLevels} onDiscountLevelsChange={setDiscountLevels} hourlyRate={hourlyRate} onRateChange={setHourlyRate} fixedServices={fixedServices} onFixedServicesChange={setFixedServices} selectedPrinter={selectedPrinter} onPrinterChange={setSelectedPrinter} companyInfo={companyInfo} onCompanyChange={setCompanyInfo} notifSettings={notifSettings} onNotifSettingsChange={setNotifSettings} statsSettings={statsSettings} onStatsSettingsChange={setStatsSettings} customers={customers} vehicles={vehicles} services={services} invoices={invoices} onRestoreData={handleRestoreData} onClearAllData={handleClearAllData} autoBackupSettings={autoBackupSettings} onAutoBackupSettingsChange={() => {}} setDirectoryHandle={() => {}} directoryHandle={null} userSettings={userSettings} onUserSettingsChange={setUserSettings} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Mail, 
  Phone, 
  MapPin, 
  MoreHorizontal, 
  UserPlus, 
  X, 
  Check, 
  Car, 
  Calendar,
  ChevronRight,
  User as UserIcon,
  Edit3,
  Trash2,
  AlertCircle,
  Building2,
  Briefcase,
  Type,
  User
} from 'lucide-react';
import { Customer, Vehicle } from '../types';

interface CustomerProps {
  customers: Customer[];
  vehicles: Vehicle[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer?: (customer: Customer) => void;
  onDeleteCustomer?: (id: string) => void;
  onNavigateToVehicle?: (vehicleId: string) => void;
  initialCustomerId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const CustomerManager: React.FC<CustomerProps> = ({ 
  customers, 
  vehicles, 
  onAddCustomer, 
  onUpdateCustomer, 
  onDeleteCustomer,
  onNavigateToVehicle,
  initialCustomerId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState<Customer | null>(null);
  const [selectedDetailCustomer, setSelectedDetailCustomer] = useState<Customer | null>(null);
  const [selectedVehiclesCustomer, setSelectedVehiclesCustomer] = useState<Customer | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [selectedLetter, setSelectedLetter] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData = {
    customerType: 'soukromý' as 'soukromý' | 'firemní',
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    companyName: '',
    companyAddress: '',
    ico: '',
    dic: '',
    contactPerson: ''
  };

  const [formData, setFormData] = useState(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleOpenAdd();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const alphabet = useMemo(() => {
    const letters = new Set<string>();
    customers.forEach(c => {
      const char = c.customerType === 'firemní' && c.companyName ? c.companyName[0] : (c.lastName ? c.lastName[0] : '');
      if (char) letters.add(char.toUpperCase());
    });
    return Array.from(letters).sort((a, b) => a.localeCompare(b, 'cs'));
  }, [customers]);

  const filtered = useMemo(() => {
    return customers
      .filter(c => {
        const customerVehicles = vehicles.filter(v => v.customerId === c.id);
        const hasMatchingVehicle = customerVehicles.some(v => 
          (v.licensePlate || "").toLowerCase().includes(search.toLowerCase())
        );

        const matchesSearch = 
          `${c.lastName} ${c.firstName}`.toLowerCase().includes(search.toLowerCase()) ||
          c.email.toLowerCase().includes(search.toLowerCase()) ||
          (c.companyName && c.companyName.toLowerCase().includes(search.toLowerCase())) ||
          c.phone.includes(search) ||
          hasMatchingVehicle;

        const char = c.customerType === 'firemní' && c.companyName ? c.companyName[0] : (c.lastName ? c.lastName[0] : '');
        const matchesLetter = !selectedLetter || (char.toUpperCase() === selectedLetter);

        return matchesSearch && matchesLetter;
      })
      .sort((a, b) => {
        const nameA = a.customerType === 'firemní' ? (a.companyName || '') : (a.lastName || '');
        const nameB = b.customerType === 'firemní' ? (b.companyName || '') : (b.lastName || '');
        return nameA.localeCompare(nameB, 'cs');
      });
  }, [customers, search, selectedLetter, vehicles]);

  const handleOpenAdd = () => {
    setEditingCustomer(null);
    setFormData(initialFormData);
    setIsAddModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      customerType: customer.customerType || 'soukromý',
      firstName: customer.firstName || '',
      lastName: customer.lastName || '',
      email: customer.email || '',
      phone: customer.phone || '',
      address: customer.address || '',
      companyName: customer.companyName || '',
      companyAddress: customer.companyAddress || '',
      ico: customer.ico || '',
      dic: customer.dic || '',
      contactPerson: customer.contactPerson || ''
    });
    setIsAddModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const submissionData = {
      ...formData,
      firstName: formData.customerType === 'soukromý' ? formData.firstName.trim() : '',
      lastName: formData.customerType === 'soukromý' ? formData.lastName.trim() : '',
      companyName: formData.customerType === 'firemní' ? formData.companyName.trim() : undefined,
      companyAddress: formData.companyAddress.trim() || undefined,
      ico: formData.ico.trim() || undefined,
      dic: formData.dic.trim() || undefined,
      contactPerson: formData.customerType === 'firemní' ? formData.contactPerson.trim() : undefined
    };

    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...submissionData
        } as Customer);
      }
    } else {
      const newCustomer: Customer = {
        ...submissionData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      } as Customer;
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData(initialFormData);
  };

  const confirmDelete = () => {
    if (deletingCustomer && onDeleteCustomer) {
      onDeleteCustomer(deletingCustomer.id);
      setDeletingCustomer(null);
    }
  };

  const handleViewVehicle = (vehicleId: string) => {
    if (onNavigateToVehicle) {
      onNavigateToVehicle(vehicleId);
      setSelectedVehiclesCustomer(null);
    }
  };

  const customerVehicles = selectedVehiclesCustomer 
    ? vehicles.filter(v => v.customerId === selectedVehiclesCustomer.id)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zákazníci</h2>
          <p className="text-slate-500 font-medium">Správa kontaktů a klientských karet.</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg shadow-slate-300"
        >
          <UserPlus className="w-5 h-5" />
          Nový zákazník
        </button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-300 shadow-md flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-500" />
          <input 
            type="text" 
            placeholder="Hledat podle jména, emailu, firmy, telefonu nebo SPZ..." 
            className="flex-1 text-sm font-semibold outline-none bg-transparent placeholder:text-slate-400"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
          {search && (
            <button 
              onClick={() => onSearchChange('')}
              className="text-blue-600 font-black text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
            >
              Zrušit filtr
            </button>
          )}
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <div className="p-2 bg-white rounded-xl shadow-sm border border-slate-200 flex items-center gap-2 shrink-0">
            <Type className="w-4 h-4 text-slate-500" />
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest mr-2">Abecedně:</span>
          </div>
          <button 
            onClick={() => setSelectedLetter(null)}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
          >
            VŠE
          </button>
          {alphabet.map(letter => (
            <button 
              key={letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.map(c => (
          <div key={c.id} className="bg-white rounded-3xl border border-slate-200 p-6 shadow hover:shadow-xl transition-all group relative overflow-visible">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === c.id ? null : c.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === c.id ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-6 h-6" />
                </button>

                {openMenuId === c.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-200 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleOpenEdit(c)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit kartu
                    </button>
                    <button 
                      onClick={() => { setDeletingCustomer(c); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat kartu
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-6">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105 ${c.customerType === 'firemní' ? 'bg-slate-900 shadow-slate-900/20' : 'bg-blue-600 shadow-blue-600/20'}`}>
                {c.customerType === 'firemní' ? <Building2 className="w-8 h-8" /> : <UserIcon className="w-8 h-8" />}
              </div>
              <div>
                <h3 className="text-lg font-black text-slate-900 leading-tight">
                  {c.customerType === 'firemní' ? (c.companyName || `${c.lastName} ${c.firstName}`) : `${c.lastName} ${c.firstName}`}
                </h3>
                <div className="flex items-center gap-2 mt-1">
                  <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md ${c.customerType === 'firemní' ? 'bg-slate-100 text-slate-700' : 'bg-blue-50 text-blue-700'}`}>
                    {c.customerType === 'firemní' ? 'FIRMA' : 'SOUKROMÝ'}
                  </span>
