interface VehicleManagerProps {
  vehicles: Vehicle[];
  customers: Customer[];
  services: ServiceRecord[];
  onAddVehicle: (v: Vehicle) => void;
  onUpdateVehicle: (v: Vehicle) => void;
  onDeleteVehicle: (id: string) => void;
  onNavigateToCustomer: (id: string) => void;
  onNavigateToOrder: (id: string) => void;
  onCreateOrder: (id: string) => void;
  initialVehicleId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const VehicleManager: React.FC<VehicleManagerProps> = ({ 
  vehicles, 
  customers, 
  services,
  onAddVehicle, 
  onUpdateVehicle, 
  onDeleteVehicle,
  onNavigateToCustomer,
  onNavigateToOrder,
  onCreateOrder,
  initialVehicleId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [selectedVehicleId, setSelectedVehicleId] = useState<string | null>(null);
  const [historyVehicleId, setHistoryVehicleId] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [selectedLetter, setSelectedLetter] = useState<string | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData: Partial<Vehicle> = {
    customerId: '', make: '', model: '', year: new Date().getFullYear(),
    vin: '', licensePlate: '', mileage: 0, engineCode: '', color: '',
    lastServiceDate: '', stkExpirationDate: '', nextServiceDate: '',
    serviceIntervalKm: 15000, serviceIntervalMonths: 12, notes: '',
    brakeFluidInterval: 24, coolantInterval: 60, gearboxOilInterval: 60,
    timingBeltInterval: 120, refrigerantInterval: 24
  };

  const [formData, setFormData] = useState<Partial<Vehicle>>(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      setEditingVehicle(null);
      setFormData(initialFormData);
      setIsModalOpen(true);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const alphabet = useMemo(() => {
    const letters = new Set<string>();
    vehicles.forEach(v => {
      if (v.make) letters.add(v.make[0].toUpperCase());
    });
    return Array.from(letters).sort((a, b) => a.localeCompare(b, 'cs'));
  }, [vehicles]);

  const filteredVehicles = useMemo(() => {
    return vehicles.filter(v => {
      const customer = customers.find(c => c.id === v.customerId);
      const customerName = customer 
        ? (customer.customerType === 'firemní' ? customer.companyName : `${customer.lastName} ${customer.firstName}`) 
        : "";

      const matchesSearch = 
        (v.licensePlate || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.make || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.model || "").toLowerCase().includes(search.toLowerCase()) ||
        (v.vin || "").toLowerCase().includes(search.toLowerCase()) ||
        customerName?.toLowerCase().includes(search.toLowerCase());

      const matchesLetter = !selectedLetter || (v.make && v.make[0].toUpperCase() === selectedLetter);

      return matchesSearch && matchesLetter;
    }).sort((a, b) => (a.make || "").localeCompare(b.make || "", 'cs'));
  }, [vehicles, search, selectedLetter, customers]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingVehicle) {
      onUpdateVehicle({ ...editingVehicle, ...formData } as Vehicle);
    } else {
      onAddVehicle({ ...formData, id: `v${Date.now()}` } as Vehicle);
    }
    setIsModalOpen(false);
  };

  const handleOpenEdit = (v: Vehicle) => {
    setEditingVehicle(v);
    setFormData(v);
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const confirmDelete = () => {
    if (deletingVehicle) {
      onDeleteVehicle(deletingVehicle.id);
      setDeletingVehicle(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Vozidla</h2>
          <p className="text-slate-500 font-medium">Evidence vozového parku a servisních intervalů.</p>
        </div>
        <button 
          onClick={() => { setEditingVehicle(null); setFormData(initialFormData); setIsModalOpen(true); }}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-black hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg shadow-slate-300"
        >
          <Plus className="w-5 h-5" />
          Nové vozidlo
        </button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-300 shadow-md flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-500" />
          <input 
            type="text" 
            placeholder="Hledat podle SPZ, značky, modelu, VIN nebo jména majitele..." 
            className="flex-1 text-sm font-semibold outline-none bg-transparent placeholder:text-slate-400"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <div className="p-2 bg-white rounded-xl shadow-sm border border-slate-200 flex items-center gap-2 shrink-0">
            <Type className="w-4 h-4 text-slate-500" />
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest mr-2">Značka:</span>
          </div>
          <button 
            onClick={() => setSelectedLetter(null)}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
          >
            VŠE
          </button>
          {alphabet.map(letter => (
            <button 
              key={letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVehicles.map(v => (
          <div key={v.id} className="bg-white rounded-3xl border border-slate-200 p-6 shadow-md hover:shadow-xl transition-all group relative">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-5 h-5" />
                </button>
                {openMenuId === v.id && (
                  <div ref={menuRef} className="absolute top-12 right-0 w-52 bg-white rounded-2xl shadow-2xl border border-slate-200 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                    <button onClick={() => handleOpenEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold">
                      <Edit3 className="w-4 h-4 text-slate-400" /> Upravit kartu
                    </button>
                    <button onClick={() => onCreateOrder(v.id)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold">
                      <ClipboardPlus className="w-4 h-4" /> Nová zakázka
                    </button>
                    <div className="h-px bg-slate-100 my-1"></div>
                    <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold">
                      <Trash2 className="w-4 h-4" /> Smazat kartu
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-4">
              <div className="w-16 h-16 rounded-2xl bg-slate-900 flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105">
                <Car className="w-8 h-8" />
              </div>
              <div className="min-w-0 pr-8">
                <h3 className="text-lg font-black text-slate-900 leading-tight truncate">
                  {v.make} {v.model}
                </h3>
                <p className="text-sm font-black text-blue-600 font-mono tracking-widest mt-1 uppercase">{v.licensePlate?.toUpperCase()}</p>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter mt-0.5">{v.year}</p>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedVehicleId(v.id)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-black text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider border border-slate-200"
              >
                Detail
              </button>
              <button 
                onClick={() => setHistoryVehicleId(v.id)}
                className="flex-1 py-3 bg-blue-50 text-blue-700 rounded-xl font-black text-xs hover:bg-blue-100 transition-all uppercase tracking-wider flex items-center justify-center gap-2 border border-blue-200"
              >
                <HistoryIcon className="w-3.5 h-3.5" /> Historie
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Další modály (Add/Edit, Detail, History, Delete) jsou součástí plného kódu... */}
    </div>
  );
};

