  const [editingOrder, setEditingOrder] = useState<ServiceRecord | null>(null);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);

  const handleEdit = (order: ServiceRecord) => {
    setEditingOrder(order);
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const columns = useMemo(() => {
    const filtered = services.filter(s => {
      const v = vehicles.find(veh => veh.id === s.vehicleId);
      const c = v ? customers.find(cust => cust.id === v.customerId) : null;
      const sLower = search.toLowerCase();
      return (
        s.id.toLowerCase().includes(sLower) ||
        (v?.licensePlate || "").toLowerCase().includes(sLower) ||
        (c?.lastName || "").toLowerCase().includes(sLower) ||
        (c?.companyName || "").toLowerCase().includes(sLower)
      );
    });

    return {
      waiting: filtered.filter(s => s.status === 'naplánováno'),
      active: filtered.filter(s => s.status === 'probíhá'),
      done: filtered.filter(s => s.status === 'hotovo')
    };
  }, [services, vehicles, customers, search]);

  useEffect(() => {
    if (autoOpen) {
      setEditingOrder(null);
      setIsModalOpen(true);
      if (onModalOpened) onModalOpened();
    }
