      <div className="space-y-3 mb-6">
        <div className="flex items-center gap-2 text-slate-800">
          <User className="w-4 h-4 text-slate-400" />
          <span className="text-sm font-black truncate">
            {customer?.customerType === 'firemní' ? (customer?.companyName || `${customer?.firstName} ${customer?.lastName}`) : `${customer?.firstName} ${customer?.lastName}`}
          </span>
        </div>
        <div className="flex items-center gap-2 text-slate-800">
          <Car className="w-4 h-4 text-slate-400" />
          <span className="text-[10px] font-black text-blue-700 font-mono tracking-wider uppercase">{vehicle?.licensePlate?.toUpperCase() || '---'}</span>
          <span className="text-xs font-bold text-slate-500">• {vehicle?.make} {vehicle?.model}</span>
        </div>
      </div>

      <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
        <div className="flex flex-col">
          <span className="text-[9px] font-black text-slate-500 uppercase">Odhad ceny</span>
          <span className="text-sm font-black text-slate-900">{Math.round(order.estimatedPrice || 0).toLocaleString()} Kč</span>
        </div>
        <button onClick={() => onEdit(order)} className="flex items-center gap-1 text-[10px] font-black text-blue-700 uppercase tracking-widest hover:underline px-3 py-1.5 bg-blue-50 rounded-lg border border-blue-200">
          Otevřít <ChevronRight className="w-3 h-3" />
        </button>
      </div>
    </div>
  );
};

