                    <button onClick={() => onCreateOrder(v.id)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold">
                      <ClipboardPlus className="w-4 h-4" /> Nová zakázka
