                   <button type="button" onClick={() => setActiveTab('basic')} className={`px-8 py-3 rounded-xl font-black text-[10px] uppercase transition-all ${activeTab === 'basic' ? 'bg-white text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>ZÁKLADNÍ ÚDAJE</button>
                   <button type="button" onClick={() => setActiveTab('intervals')} className={`px-8 py-3 rounded-xl font-black text-[10px] uppercase transition-all ${activeTab === 'intervals' ? 'bg-white text-slate-900 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>SERVISNÍ INTERVALY</button>
                </div>

                {activeTab === 'basic' ? (
