                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Majitel vozu</label>
                      <select required className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl outline-none font-bold" value={formData.customerId} onChange={e => setFormData({...formData, customerId: e.target.value})}>
                        <option value="">Vyberte zákazníka...</option>
                        {customers.map(c => <option key={c.id} value={c.id}>{c.customerType === 'firemní' ? c.companyName : `${c.lastName} ${c.firstName}`}</option>)}
                      </select>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Výrobce</label>
