        <div className="text-right border-l border-black pl-4">
           <p className="text-[9px] font-black uppercase mb-2">Zpracoval / Mechanik</p>
           <p className="text-sm font-black underline">{order.technician}</p>
           <p className="text-[10px] font-bold mt-4 uppercase">Stav tachometru</p>
           <p className="text-base font-black italic">{order.mileageAtEntry?.toLocaleString() || '---'} KM</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-0 border-b border-black">
        <div className="p-3 border-r border-black">
           <p className="text-[9px] font-black uppercase mb-2 text-slate-500 tracking-widest">ODBĚRATEL / MAJITEL</p>
           <div className="text-[12px] leading-tight font-bold">
              {customer?.customerType === 'firemní' ? (
                <>
                  <p className="font-black text-[14px]">{customer.companyName}</p>
                  <p>{customer.companyAddress}</p>
                  <p className="mt-1">IČ: {customer.ico} {customer.dic && `DIČ: ${customer.dic}`}</p>
                </>
              ) : (
                <>
                  <p className="font-black text-[14px] uppercase">{customer?.lastName} {customer?.firstName}</p>
                  <p>{customer?.address}</p>
                  <p className="mt-1">Tel: {customer?.phone}</p>
                </>
              )}
           </div>
        </div>
        <div className="p-3">
           <p className="text-[9px] font-black uppercase mb-2 text-slate-500 tracking-widest">VOZIDLO</p>
           <div className="text-[12px] leading-tight font-bold">
              <p className="font-black text-[16px] text-blue-800 uppercase">{vehicle?.make} {vehicle?.model}</p>
              <p className="text-[14px] font-black mt-1">SPZ: {vehicle?.licensePlate}</p>
              <p className="mt-1 opacity-70">VIN: {vehicle?.vin}</p>
              <div className="flex gap-4 mt-2">
                 <p className="text-[10px]"><span className="opacity-50">Rok:</span> {vehicle?.year}</p>
                 <p className="text-[10px]"><span className="opacity-50">Motor:</span> {vehicle?.engineCode}</p>
              </div>
           </div>
        </div>
      </div>

      <div className="p-3 border-b border-black">
         <p className="text-[9px] font-black uppercase mb-2 text-slate-500 tracking-widest">POŽADOVANÉ ÚKONY / POPIS ZÁVADY</p>
         <p className="text-[12px] font-bold leading-relaxed whitespace-pre-wrap min-h-[60px] italic">{order.description}</p>
      </div>

      <div className="grid grid-cols-4 text-[9px] border-b border-black font-black uppercase bg-gray-50 h-8 items-center text-center">
         <div className="border-r border-black px-1">Palivo: {order.fuelLevel || '---'}</div>
         <div className="border-r border-black px-1">Vracet díly: {order.returnParts === 'vrátit' ? 'ANO' : 'NE'}</div>
         <div className="border-r border-black px-1">Termín: {formatDate(order.deliveryDate || order.date)}</div>
         <div className="px-1">Platba: {order.paymentType || 'Hotově'}</div>
      </div>

      <div className="mt-4 border border-black min-h-[350px]">
        <table className="w-full text-[11px] border-collapse">
           <thead>
              <tr className="border-b border-black text-[9px] font-black uppercase bg-gray-100 h-8">
                 <th className="px-2 w-[40px] border-r border-black">Množ</th>
                 <th className="px-2 text-left border-r border-black">Náhradní díl / Práce</th>
                 <th className="px-2 w-[70px] text-right border-r border-black">Cena/J</th>
                 <th className="px-2 w-[80px] text-right">Celkem</th>
              </tr>
           </thead>
           <tbody>
              {items.map((it, idx) => (
                <tr key={idx} className="border-b border-gray-300 h-7 font-bold">
                   <td className="px-2 text-center border-r border-black">{it.quantity} {it.unit}</td>
                   <td className="px-2 border-r border-black">{it.description}</td>
                   <td className="px-2 text-right border-r border-black">{Math.round(it.unitPrice).toLocaleString()} Kč</td>
                   <td className="px-2 text-right">{Math.round(it.quantity * it.unitPrice).toLocaleString()} Kč</td>
                </tr>
              ))}
              {order.laborHours && order.laborHours > 0 && (
                <tr className="border-b border-gray-300 h-7 font-black italic bg-blue-50/20">
                   <td className="px-2 text-center border-r border-black">{order.laborHours} h</td>
                   <td className="px-2 border-r border-black">Servisní práce</td>
                   <td className="px-2 text-right border-r border-black">{Math.round(hourlyRate).toLocaleString()} Kč</td>
                   <td className="px-2 text-right">{Math.round(order.laborHours * hourlyRate).toLocaleString()} Kč</td>
                </tr>
              )}
              {Array.from({ length: emptyRowsCount }).map((_, i) => (
                <tr key={i} className="border-b border-gray-100 h-7">
                   <td className="border-r border-black"></td><td className="border-r border-black"></td><td className="border-r border-black"></td><td></td>
                </tr>
              ))}
           </tbody>
        </table>
      </div>

      <div className="flex justify-between items-start mt-4 gap-8">
         <div className="flex-1 space-y-4">
            <div className="bg-slate-50 p-3 border border-black/10 rounded-lg">
               <p className="text-[9px] font-black uppercase mb-1 opacity-50">Výbava vozidla při převzetí</p>
               <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-[10px] font-bold">
                  <div>[ {order.checklist?.rezerva ? 'X' : '  '} ] Rezerva / Sada</div>
                  <div>[ {order.checklist?.lekarna ? 'X' : '  '} ] Lékárnička</div>
                  <div>[ {order.checklist?.zvedak ? 'X' : '  '} ] Zvedák</div>
                  <div>[ {order.checklist?.trojuhelnik ? 'X' : '  '} ] Trojúhelník</div>
                  <div>[ {order.checklist?.klic ? 'X' : '  '} ] Klíč na kola</div>
                  <div>[ {order.checklist?.bezp_klic ? 'X' : '  '} ] Bezp. ořech</div>
               </div>
            </div>
            <div className="text-[8px] italic leading-tight text-slate-400">
               <p>Zákazník souhlasí s cenou opravy a termínem dokončení. Servis neručí za věci ponechané ve vozidle. Zákazník byl seznámen s obchodními podmínkami.</p>
            </div>
         </div>
         <div className="w-[200px] bg-gray-50 border-2 border-black p-4 text-center">
            <p className="text-[9px] font-black uppercase opacity-50 mb-1">CELKOVÁ CENA (Základ)</p>
            <p className="text-3xl font-black tracking-tighter leading-none">{Math.round(order.cost).toLocaleString()} Kč</p>
            <p className="text-[10px] font-bold mt-2 opacity-70">Sazba DPH: {company.isVatPayer ? '21%' : '0%'}</p>
         </div>
      </div>

      <div className="flex justify-between mt-12 px-6">
         <div className="text-center w-[40%] border-t border-black pt-1">
            <p className="text-[9px] font-black uppercase">Podpis zákazníka</p>
         </div>
         <div className="text-center w-[40%] border-t border-black pt-1">
            <p className="text-[9px] font-black uppercase">Za servis převzal</p>
         </div>
      </div>
