                               <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={formData.mileageAtEntry || ''} onChange={e => setFormData({...formData, mileageAtEntry: parseInt(e.target.value) || 0})} />
                            </div>
                         </div>
                      </div>

                      <div className="space-y-6">
                         <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Požadavek a stav</h4>
                         <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center justify-between">
                               Popis opravy / závady
                               <div className="flex gap-1">
                                  {predefinedTasks.slice(0, 3).map(pt => (
                                    <button key={pt.id} type="button" onClick={() => handleApplyTemplate(pt)} className="px-2 py-0.5 bg-blue-50 text-blue-600 rounded-md text-[8px] font-black uppercase hover:bg-blue-100 transition-colors">+{pt.label}</button>
                                  ))}
                               </div>
                            </label>
                            <textarea rows={5} className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold resize-none" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} placeholder="Popište závadu..." />
                         </div>
                         <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Kontrolní seznam & Palivo</p>
                            <div className="grid grid-cols-2 gap-4">
                               <div className="space-y-2">
                                  <label className="text-[8px] font-black text-slate-400 uppercase ml-1">Stav paliva</label>
                                  <select className="w-full px-4 py-2 bg-white rounded-xl text-xs font-bold shadow-sm" value={formData.fuelLevel} onChange={e => setFormData({...formData, fuelLevel: e.target.value})}>
