                               </div>
                               <div className="space-y-2">
                                  <label className="text-[8px] font-black text-slate-400 uppercase ml-1">Vracet díly?</label>
                                  <div className="flex bg-white rounded-xl p-1 shadow-sm border border-slate-100">
                                     <button type="button" onClick={() => setFormData({...formData, returnParts: 'vrátit'})} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${formData.returnParts === 'vrátit' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400'}`}>ANO</button>
                                     <button type="button" onClick={() => setFormData({...formData, returnParts: 'nevracet'})} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${formData.returnParts === 'nevracet' ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400'}`}>NE</button>
                                  </div>
                               </div>
                            </div>
