                      <div className="flex gap-2">
                         <button type="button" onClick={() => pdfInputRef.current?.click()} disabled={isAiAnalyzing} className={`flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase shadow-lg shadow-indigo-200 transition-all ${isAiAnalyzing ? 'opacity-50' : 'hover:scale-105 hover:bg-indigo-700'}`}>
