                         </button>
                         <input type="file" ref={pdfInputRef} className="hidden" accept=".pdf" onChange={handlePdfAnalyze} />
                         <button type="button" onClick={handleAddPart} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase shadow-lg hover:scale-105 transition-all"><Plus className="w-4 h-4" /> Přidat položku</button>
                      </div>
                   </div>

                   <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      <div className="lg:col-span-3 space-y-4">
                         <div className="overflow-hidden border border-slate-100 rounded-[2rem] shadow-sm">
                            <table className="w-full text-sm">
                               <thead className="bg-slate-50 border-b border-slate-100">
                                  <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                     <th className="px-6 py-4 text-left">Popis položky</th>
                                     <th className="px-4 py-4 w-24 text-center">Množ</th>
                                     <th className="px-4 py-4 w-32 text-right">Cena/J</th>
                                     <th className="px-4 py-4 w-32 text-right">Celkem</th>
                                     <th className="px-4 py-4 w-16"></th>
                                  </tr>
                               </thead>
                               <tbody className="divide-y divide-slate-50">
                                  {(formData.parts || []).map((it, idx) => (
                                    <tr key={it.id} className="group hover:bg-slate-50/50 transition-colors">
                                       <td className="px-6 py-3">
                                          <input type="text" className="w-full bg-transparent border-none font-bold text-slate-900 outline-none placeholder:text-slate-300" placeholder="Název dílu nebo úkonu..." value={it.description} onChange={e => {
                                            const next = [...(formData.parts || [])];
                                            next[idx].description = e.target.value;
                                            updateParts(next);
                                          }} />
                                       </td>
                                       <td className="px-4 py-3">
                                          <input type="number" className="w-full bg-transparent border-none font-black text-slate-900 text-center outline-none" value={it.quantity} onChange={e => {
                                            const next = [...(formData.parts || [])];
                                            next[idx].quantity = parseFloat(e.target.value) || 0;
                                            updateParts(next);
                                          }} />
                                       </td>
                                       <td className="px-4 py-3">
                                          <input type="number" className="w-full bg-transparent border-none font-black text-blue-600 text-right outline-none" value={it.unitPrice} onChange={e => {
                                            const next = [...(formData.parts || [])];
                                            next[idx].unitPrice = parseInt(e.target.value) || 0;
                                            updateParts(next);
                                          }} />
                                       </td>
                                       <td className="px-4 py-3 text-right font-black text-slate-900">{(it.quantity * it.unitPrice).toLocaleString()} Kč</td>
                                       <td className="px-4 py-3 text-center">
                                          <button type="button" onClick={() => updateParts((formData.parts || []).filter((_, i) => i !== idx))} className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4" /></button>
                                       </td>
                                    </tr>
                                  ))}
                                  <tr className="bg-blue-50/20 border-t-2 border-slate-100">
