import { Customer, Vehicle } from '../types';

interface CustomerProps {
  customers: Customer[];
  vehicles: Vehicle[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer?: (customer: Customer) => void;
  onDeleteCustomer?: (id: string) => void;
  onNavigateToVehicle?: (vehicleId: string) => void;
  initialCustomerId?: string | null;
  autoOpen?: boolean;
  onModalOpened?: () => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const CustomerManager: React.FC<CustomerProps> = ({ 
  customers, 
  vehicles, 
  onAddCustomer, 
  onUpdateCustomer, 
  onDeleteCustomer,
  onNavigateToVehicle,
  initialCustomerId,
  autoOpen,
  onModalOpened,
  search,
  onSearchChange
}) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | null>(null);
  const [deletingCustomer, setDeletingCustomer] = useState<Customer | null>(null);
  const [selectedDetailCustomer, setSelectedDetailCustomer] = useState<Customer | null>(null);
  const [selectedVehiclesCustomer, setSelectedVehiclesCustomer] = useState<Customer | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [selectedLetter, setSelectedLetter] = useState<string | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);

  const initialFormData = {
    customerType: 'soukromý' as 'soukromý' | 'firemní',
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    companyName: '',
    companyAddress: '',
    ico: '',
    dic: '',
    contactPerson: ''
  };

  const [formData, setFormData] = useState(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      handleOpenAdd();
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const alphabet = useMemo(() => {
    const letters = new Set<string>();
    customers.forEach(c => {
      const char = c.customerType === 'firemní' && c.companyName ? c.companyName[0] : (c.lastName ? c.lastName[0] : '');
      if (char) letters.add(char.toUpperCase());
    });
    return Array.from(letters).sort((a, b) => a.localeCompare(b, 'cs'));
  }, [customers]);

  const filtered = useMemo(() => {
    return customers
      .filter(c => {
        const customerVehicles = vehicles.filter(v => v.customerId === c.id);
        const hasMatchingVehicle = customerVehicles.some(v => 
          (v.licensePlate || "").toLowerCase().includes(search.toLowerCase())
        );

        const matchesSearch = 
          `${c.lastName} ${c.firstName}`.toLowerCase().includes(search.toLowerCase()) ||
          c.email.toLowerCase().includes(search.toLowerCase()) ||
          (c.companyName && c.companyName.toLowerCase().includes(search.toLowerCase())) ||
          c.phone.includes(search) ||
          hasMatchingVehicle;

        const char = c.customerType === 'firemní' && c.companyName ? c.companyName[0] : (c.lastName ? c.lastName[0] : '');
        const matchesLetter = !selectedLetter || (char.toUpperCase() === selectedLetter);

        return matchesSearch && matchesLetter;
      })
      .sort((a, b) => {
        const nameA = a.customerType === 'firemní' ? (a.companyName || '') : (a.lastName || '');
        const nameB = b.customerType === 'firemní' ? (b.companyName || '') : (b.lastName || '');
        return nameA.localeCompare(nameB, 'cs');
      });
  }, [customers, search, selectedLetter, vehicles]);

  const handleOpenAdd = () => {
    setEditingCustomer(null);
    setFormData(initialFormData);
    setIsAddModalOpen(true);
  };

  const handleOpenEdit = (customer: Customer) => {
    setEditingCustomer(customer);
    setFormData({
      customerType: customer.customerType || 'soukromý',
      firstName: customer.firstName || '',
      lastName: customer.lastName || '',
      email: customer.email || '',
      phone: customer.phone || '',
      address: customer.address || '',
      companyName: customer.companyName || '',
      companyAddress: customer.companyAddress || '',
      ico: customer.ico || '',
      dic: customer.dic || '',
      contactPerson: customer.contactPerson || ''
    });
    setIsAddModalOpen(true);
    setOpenMenuId(null);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const submissionData = {
      ...formData,
      firstName: formData.customerType === 'soukromý' ? formData.firstName.trim() : '',
      lastName: formData.customerType === 'soukromý' ? formData.lastName.trim() : '',
      companyName: formData.customerType === 'firemní' ? formData.companyName.trim() : undefined,
      companyAddress: formData.companyAddress.trim() || undefined,
      ico: formData.ico.trim() || undefined,
      dic: formData.dic.trim() || undefined,
      contactPerson: formData.customerType === 'firemní' ? formData.contactPerson.trim() : undefined
    };

    if (editingCustomer) {
      if (onUpdateCustomer) {
        onUpdateCustomer({
          ...editingCustomer,
          ...submissionData
        } as Customer);
      }
    } else {
      const newCustomer: Customer = {
        ...submissionData,
        id: `c${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0]
      } as Customer;
      onAddCustomer(newCustomer);
    }
    setIsAddModalOpen(false);
    setFormData(initialFormData);
  };

  const confirmDelete = () => {
    if (deletingCustomer && onDeleteCustomer) {
      onDeleteCustomer(deletingCustomer.id);
      setDeletingCustomer(null);
    }
  };

  const handleViewVehicle = (vehicleId: string) => {
    if (onNavigateToVehicle) {
      onNavigateToVehicle(vehicleId);
      setSelectedVehiclesCustomer(null);
    }
  };

  const customerVehicles = selectedVehiclesCustomer 
    ? vehicles.filter(v => v.customerId === selectedVehiclesCustomer.id)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Zákazníci</h2>
          <p className="text-slate-500 font-medium">Správa kontaktů a klientských karet.</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg shadow-slate-300"
        >
          <UserPlus className="w-5 h-5" />
          Nový zákazník
        </button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-300 shadow-md flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-500" />
          <input 
            type="text" 
            placeholder="Hledat podle jména, emailu, firmy, telefonu nebo SPZ..." 
            className="flex-1 text-sm font-semibold outline-none bg-transparent placeholder:text-slate-400"
            value={search}
            onChange={(e) => onSearchChange(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <div className="p-2 bg-white rounded-xl shadow-sm border border-slate-200 flex items-center gap-2 shrink-0">
            <Type className="w-4 h-4 text-slate-500" />
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest mr-2">Abecedně:</span>
          </div>
          <button 
            onClick={() => setSelectedLetter(null)}
            className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
          >
            VŠE
          </button>
          {alphabet.map(letter => (
            <button 
              key={letter}
              onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)}
              className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-600 hover:bg-slate-50 border border-slate-200'}`}
            >
              {letter}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filtered.map(c => (
          <div key={c.id} className="bg-white rounded-3xl border border-slate-200 p-6 shadow-md hover:shadow-xl transition-all group relative overflow-visible">
            <div className="absolute top-0 right-0 p-4">
              <div className="relative">
                <button 
                  onClick={() => setOpenMenuId(openMenuId === c.id ? null : c.id)}
                  className={`p-2 rounded-xl transition-all ${openMenuId === c.id ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-900'}`}
                >
                  <MoreHorizontal className="w-6 h-6" />
                </button>

                {openMenuId === c.id && (
                  <div 
                    ref={menuRef}
                    className="absolute top-12 right-0 w-48 bg-white rounded-2xl shadow-2xl border border-slate-200 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200"
                  >
                    <button 
                      onClick={() => handleOpenEdit(c)}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"
                    >
                      <Edit3 className="w-4 h-4 text-slate-400" />
                      Upravit kartu
                    </button>
                    <button 
                      onClick={() => { setDeletingCustomer(c); setOpenMenuId(null); }}
                      className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"
                    >
                      <Trash2 className="w-4 h-4" />
                      Smazat kartu
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center gap-5 mb-6">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg transition-transform group-hover:scale-105 ${c.customerType === 'firemní' ? 'bg-slate-900 shadow-slate-900/20' : 'bg-blue-600 shadow-blue-600/20'}`}>
                {c.customerType === 'firemní' ? <Building2 className="w-8 h-8" /> : <UserIcon className="w-8 h-8" />}
              </div>
              <div className="min-w-0 pr-8">
                <h3 className="text-lg font-black text-slate-900 leading-tight truncate">
                  {c.customerType === 'firemní' ? (c.companyName || `${c.lastName} ${c.firstName}`) : `${c.lastName} ${c.firstName}`}
                </h3>
                <div className="flex items-center gap-2 mt-1">
                  <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md ${c.customerType === 'firemní' ? 'bg-slate-100 text-slate-700' : 'bg-blue-50 text-blue-700'}`}>
                    {c.customerType === 'firemní' ? 'FIRMA' : 'SOUKROMÝ'}
                  </span>
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">Od {formatDate(c.createdAt)}</p>
                </div>
              </div>
            </div>

            <div className="space-y-3 pt-4 border-t border-slate-100">
              <div className="flex items-center gap-3 text-slate-700">
                <div className="p-2 bg-slate-50 rounded-lg border border-slate-200"><Mail className="w-4 h-4 text-slate-500" /></div>
                <span className="text-sm font-bold truncate">{c.email || 'Bez e-mailu'}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-700">
                <div className="p-2 bg-slate-50 rounded-lg border border-slate-200"><Phone className="w-4 h-4 text-slate-500" /></div>
                <span className="text-sm font-bold">{c.phone}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-700">
                <div className="p-2 bg-slate-50 rounded-lg border border-slate-200"><MapPin className="w-4 h-4 text-slate-500" /></div>
                <span className="text-sm font-bold truncate">
                  {c.customerType === 'firemní' ? (c.companyAddress || c.address) : c.address || 'Bez adresy'}
                </span>
              </div>
            </div>

            <div className="mt-6 flex gap-2">
              <button 
                onClick={() => setSelectedDetailCustomer(c)}
                className="flex-1 py-3 bg-slate-100 text-slate-900 rounded-xl font-black text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider border border-slate-200"
              >
                Detail
              </button>
              <button 
                onClick={() => setSelectedVehiclesCustomer(c)}
                className="flex-1 py-3 bg-blue-50 text-blue-700 rounded-xl font-black text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider border border-blue-200"
              >
                Vozidla
              </button>
            </div>
          </div>
        ))}
      </div>

      {isAddModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsAddModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <form onSubmit={handleSubmit} className="flex flex-col h-full max-h-[90vh]">
              <div className="p-8 border-b flex justify-between items-center bg-slate-50">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
                    <UserPlus className="w-6 h-6" />
                  </div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight">{editingCustomer ? 'Upravit zákazníka' : 'Nový zákazník'}</h3>
                </div>
                <button type="button" onClick={() => setIsAddModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-xl transition-colors"><X className="w-6 h-6 text-slate-400" /></button>
              </div>

              <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
                <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
                  <button type="button" onClick={() => setFormData({...formData, customerType: 'soukromý'})} className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-xs font-black transition-all ${formData.customerType === 'soukromý' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-400'}`}>
                    <UserIcon className="w-4 h-4" /> SOUKROMÝ
                  </button>
                  <button type="button" onClick={() => setFormData({...formData, customerType: 'firemní'})} className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl text-xs font-black transition-all ${formData.customerType === 'firemní' ? 'bg-white text-slate-900 shadow-md' : 'text-slate-400'}`}>
                    <Building2 className="w-4 h-4" /> FIREMNÍ
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {formData.customerType === 'soukromý' ? (
                    <>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Jméno</label>
                        <input type="text" required className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={formData.firstName} onChange={e => setFormData({...formData, firstName: e.target.value})} />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Příjmení</label>
                        <input type="text" required className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={formData.lastName} onChange={e => setFormData({...formData, lastName: e.target.value})} />
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="col-span-1 md:col-span-2 space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Název firmy</label>
                        <input type="text" required className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl outline-none font-bold" value={formData.companyName} onChange={e => setFormData({...formData, companyName: e.target.value})} />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">IČO</label>
                        <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl outline-none font-bold" value={formData.ico} onChange={e => setFormData({...formData, ico: e.target.value})} />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">DIČ</label>
                        <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl outline-none font-bold" value={formData.dic} onChange={e => setFormData({...formData, dic: e.target.value})} />
                      </div>
                      <div className="col-span-1 md:col-span-2 space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kontaktní osoba</label>
                        <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl outline-none font-bold" value={formData.contactPerson} onChange={e => setFormData({...formData, contactPerson: e.target.value})} />
                      </div>
                    </>
                  )}
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail</label>
                    <input type="email" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Telefon</label>
                    <input type="tel" required className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} />
                  </div>
                  <div className="col-span-1 md:col-span-2 space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Adresa</label>
                    <input type="text" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl outline-none font-bold" value={formData.customerType === 'firemní' ? formData.companyAddress : formData.address} onChange={e => setFormData({...formData, [formData.customerType === 'firemní' ? 'companyAddress' : 'address']: e.target.value})} />
                  </div>
                </div>
              </div>

              <div className="p-8 border-t bg-slate-50 flex gap-4">
                <button type="button" onClick={() => setIsAddModalOpen(false)} className="flex-1 py-4 bg-white border-2 border-slate-200 rounded-2xl font-black text-xs uppercase hover:bg-slate-100 transition-all">Zrušit</button>
                <button type="submit" className="flex-[2] py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase hover:bg-slate-800 transition-all shadow-xl shadow-slate-200">
                  {editingCustomer ? 'Uložit změny' : 'Vytvořit zákazníka'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {selectedDetailCustomer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setSelectedDetailCustomer(null)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg ${selectedDetailCustomer.customerType === 'firemní' ? 'bg-slate-900' : 'bg-blue-600'}`}>
                   {selectedDetailCustomer.customerType === 'firemní' ? <Building2 /> : <UserIcon />}
                </div>
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">Detail zákazníka</h3>
              </div>
              <button onClick={() => setSelectedDetailCustomer(null)} className="p-2 hover:bg-slate-200 rounded-xl transition-colors"><X className="w-6 h-6 text-slate-400" /></button>
            </div>
            <div className="p-10 space-y-8">
              <div className="grid grid-cols-2 gap-8">
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Příjmení a jméno / Firma</p>
                  <p className="text-xl font-black text-slate-900">{selectedDetailCustomer.customerType === 'firemní' ? selectedDetailCustomer.companyName : `${selectedDetailCustomer.lastName} ${selectedDetailCustomer.firstName}`}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Typ klienta</p>
                  <p className="text-xl font-black text-blue-600 uppercase tracking-tight">{selectedDetailCustomer.customerType}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">E-mail</p>
                  <p className="text-lg font-bold text-slate-700">{selectedDetailCustomer.email || 'Nenastaven'}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Telefon</p>
                  <p className="text-lg font-bold text-slate-700">{selectedDetailCustomer.phone}</p>
                </div>
                <div className="col-span-2 space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Adresa</p>
                  <p className="text-lg font-bold text-slate-700">{selectedDetailCustomer.customerType === 'firemní' ? selectedDetailCustomer.companyAddress : selectedDetailCustomer.address}</p>
                </div>
                {selectedDetailCustomer.customerType === 'firemní' && (
                  <>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">IČO</p>
                      <p className="text-lg font-bold text-slate-700">{selectedDetailCustomer.ico || '---'}</p>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">DIČ</p>
                      <p className="text-lg font-bold text-slate-700">{selectedDetailCustomer.dic || '---'}</p>
                    </div>
                    <div className="col-span-2 space-y-1">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kontaktní osoba</p>
                      <p className="text-lg font-bold text-slate-700">{selectedDetailCustomer.contactPerson || '---'}</p>
                    </div>
                  </>
                )}
              </div>
            </div>
            <div className="p-8 border-t bg-slate-50 flex justify-end">
