const OrderManager: React.FC<OrderManagerProps> = ({ 
  services, 
  vehicles, 
  customers,
  invoices,
  technicians,
  predefinedTasks,
  hourlyRate,
  fixedServices,
  companyInfo,
  onAddService,
  onUpdateService,
  onDeleteService,
  onCreateInvoice,
  autoOpen, 
  onModalOpened, 
  initialOrderId,
  preselectedVehicleId,
  search,
  onSearchChange
}) => {
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingOrder, setEditingOrder] = useState<ServiceRecord | null>(null);
  const [deletingOrder, setDeletingOrder] = useState<ServiceRecord | null>(null);

  const columns = useMemo(() => {
    const filtered = services.filter(s => {
      const v = vehicles.find(veh => veh.id === s.vehicleId);
      const c = v ? customers.find(cust => cust.id === v.customerId) : null;
      const sLower = search.toLowerCase();
      return (
        s.id.toLowerCase().includes(sLower) ||
        (v?.licensePlate || "").toLowerCase().includes(sLower) ||
        (c?.lastName || "").toLowerCase().includes(sLower) ||
        (c?.companyName || "").toLowerCase().includes(sLower)
      );
    });

    return {
      waiting: filtered.filter(s => s.status === 'naplánováno'),
      active: filtered.filter(s => s.status === 'probíhá'),
      done: filtered.filter(s => s.status === 'hotovo')
    };
  }, [services, vehicles, customers, search]);

  useEffect(() => {
    if (autoOpen) {
      setEditingOrder(null);
      setIsModalOpen(true);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen, onModalOpened]);

  useEffect(() => {
    if (initialOrderId) {
      const o = services.find(s => s.id === initialOrderId);
      if (o) {
        setEditingOrder(o);
        setIsModalOpen(true);
      }
    }
  }, [initialOrderId, services]);

  const handleEdit = (order: ServiceRecord) => {
    setEditingOrder(order);
    setIsModalOpen(true);
    setOpenMenuId(null);
  };

  const confirmDelete = () => {
    if (deletingOrder) {
      onDeleteService(deletingOrder.id);
      setDeletingOrder(null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Servisní zakázky</h2>
          <p className="text-slate-500 font-medium">Správa průběhu oprav a plánování servisu.</p>
        </div>
        <button 
          onClick={() => { setEditingOrder(null); setIsModalOpen(true); }}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg shadow-blue-200"
        >
          <Plus className="w-5 h-5" />
          Nová zakázka
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3 print:hidden">
        <Search className="w-5 h-5 text-slate-400" />
        <input 
          type="text" 
          placeholder="Hledat zakázku (ID, SPZ, Zákazník)..." 
          className="flex-1 text-sm font-semibold outline-none bg-transparent placeholder:text-slate-400"
          value={search}
          onChange={(e) => onSearchChange(e.target.value)}
        />
        {search && (
          <button 
            onClick={() => onSearchChange('')}
            className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all"
          >
            Zrušit filtr
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 pb-12 print:hidden">
        <div className="space-y-6">
          <h3 className="text-sm font-black text-slate-700 uppercase tracking-widest px-2 border-l-4 border-blue-500 ml-1">K VYŘÍZENÍ ({columns.waiting.length})</h3>
          <div className="space-y-4">
            {columns.waiting.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
            {columns.waiting.length === 0 && (
              <div className="py-12 border-2 border-dashed border-slate-200 rounded-[2rem] text-center"><p className="text-slate-400 text-sm font-bold italic">Žádné naplánované zakázky.</p></div>
            )}
          </div>
        </div>

        <div className="space-y-6">
          <h3 className="text-sm font-black text-amber-800 uppercase tracking-widest px-2 border-l-4 border-amber-500 ml-1">PROBÍHÁ ({columns.active.length})</h3>
          <div className="space-y-4">
            {columns.active.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
            {columns.active.length === 0 && (
              <div className="py-12 border-2 border-dashed border-slate-200 rounded-[2rem] text-center"><p className="text-slate-400 text-sm font-bold italic">Momentálně se nepracuje na žádném voze.</p></div>
            )}
          </div>
        </div>

        <div className="space-y-6">
          <h3 className="text-sm font-black text-emerald-800 uppercase tracking-widest px-2 border-l-4 border-emerald-500 ml-1">HOTOVO ({columns.done.length})</h3>
          <div className="space-y-4">
            {columns.done.map(order => (
              <OrderCard key={order.id} order={order} vehicles={vehicles} customers={customers} onEdit={handleEdit} onUpdateStatus={(s) => onUpdateService({...order, status: s})} onOpenMenu={setOpenMenuId} openMenuId={openMenuId} onCreateInvoice={onCreateInvoice} onDelete={() => setDeletingOrder(order)} />
            ))}
            {columns.done.length === 0 && (
              <div className="py-12 border-2 border-dashed border-slate-200 rounded-[2rem] text-center"><p className="text-slate-400 text-sm font-bold italic">Žádné dokončené zakázky k vyúčtování.</p></div>
            )}
          </div>
        </div>
      </div>

      {isModalOpen && (
        <ServiceOrderModal 
          order={editingOrder} 
          vehicles={vehicles} 
          customers={customers} 
          technicians={technicians}
          predefinedTasks={predefinedTasks}
          fixedServices={fixedServices}
          hourlyRate={hourlyRate}
          companyInfo={companyInfo}
          onClose={() => setIsModalOpen(false)} 
          onSave={(newOrder) => {
            if (editingOrder) onUpdateService(newOrder);
            else onAddService(newOrder);
            setIsModalOpen(false);
          }}
          preselectedVehicleId={preselectedVehicleId}
        />
      )}

      {deletingOrder && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setDeletingOrder(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="p-10 text-center">
              <div className="w-20 h-20 bg-red-50 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6"><AlertCircle className="w-10 h-10" /></div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">Smazat zakázku?</h3>
              <p className="text-slate-500 font-medium mb-8 leading-relaxed">
                Opravdu chcete nenávratně odstranit zakázku <span className="font-bold text-slate-900">#{deletingOrder.id}</span>? Tuto akci nelze vzít zpět.
              </p>
              <div className="flex gap-3">
                <button onClick={() => setDeletingOrder(null)} className="flex-1 py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button onClick={confirmDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm uppercase shadow-lg shadow-red-600/20">Smazat</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const OrderCard: React.FC<{
  order: ServiceRecord;
  vehicles: Vehicle[];
  customers: Customer[];
  onEdit: (order: ServiceRecord) => void;
  onUpdateStatus: (status: 'naplánováno' | 'probíhá' | 'hotovo' | 'zrušeno') => void;
  onOpenMenu: (id: string | null) => void;
  openMenuId: string | null;
  onCreateInvoice: (id: string) => void;
  onDelete: () => void;
}> = ({ order, vehicles, customers, onEdit, onUpdateStatus, onOpenMenu, openMenuId, onCreateInvoice, onDelete }) => {
  const vehicle = vehicles.find(v => v.id === order.vehicleId);
  const customer = vehicle ? customers.find(c => c.id === vehicle.customerId) : null;
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        onOpenMenu(null);
      }
    };
    if (openMenuId === order.id) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [openMenuId, order.id, onOpenMenu]);

  return (
    <div className="bg-white rounded-3xl border border-slate-100 p-6 shadow-sm hover:shadow-xl transition-all group relative overflow-visible">
      <div className="absolute top-0 right-0 p-4">
        <div className="relative">
          <button 
            onClick={(e) => { e.stopPropagation(); onOpenMenu(openMenuId === order.id ? null : order.id); }}
            className={`p-2 rounded-xl transition-all ${openMenuId === order.id ? 'bg-slate-100 text-slate-900 shadow-inner' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-50'}`}
          >
            <MoreHorizontal className="w-5 h-5" />
          </button>
          {openMenuId === order.id && (
            <div ref={menuRef} className="absolute top-12 right-0 w-52 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
               <button onClick={(e) => { e.stopPropagation(); onEdit(order); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold">
                 <Edit3 className="w-4 h-4 text-slate-400" /> Upravit zakázku
               </button>
               <div className="h-px bg-slate-100 my-1"></div>
               {order.status !== 'naplánováno' && <button onClick={(e) => { e.stopPropagation(); onUpdateStatus('naplánováno'); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-xs font-black uppercase">Do čekárny</button>}
               {order.status !== 'probíhá' && <button onClick={(e) => { e.stopPropagation(); onUpdateStatus('probíhá'); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-amber-600 transition-colors text-xs font-black uppercase">Pracovat na tom</button>}
               {order.status !== 'hotovo' && <button onClick={(e) => { e.stopPropagation(); onUpdateStatus('hotovo'); onOpenMenu(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-emerald-600 transition-colors text-xs font-black uppercase">Hotovo</button>}
               <div className="h-px bg-slate-100 my-1"></div>
               {order.status === 'hotovo' && (
                 <button onClick={(e) => { e.stopPropagation(); onCreateInvoice(order.id); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-emerald-50 text-emerald-600 transition-colors text-sm font-bold">
                   <Receipt className="w-4 h-4" /> Vystavit fakturu
                 </button>
               )}
               <button onClick={(e) => { e.stopPropagation(); onDelete(); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold">
                 <Trash2 className="w-4 h-4" /> Smazat
               </button>
            </div>
          )}
        </div>
      </div>

      <div className="flex items-center gap-4 mb-4">
        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-inner ${
          order.status === 'hotovo' ? 'bg-emerald-50 text-emerald-700' : 
          order.status === 'probíhá' ? 'bg-amber-50 text-amber-700' : 'bg-blue-50 text-blue-700'
        }`}>
          {order.status === 'hotovo' ? <CheckCircle2 className="w-6 h-6" /> : <Clock className="w-6 h-6" />}
        </div>
        <div>
          <h4 className="text-base font-black text-slate-900">#{order.id}</h4>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{formatDate(order.date)}</p>
        </div>
      </div>

      <div className="space-y-3 mb-6">
        <div className="flex items-center gap-2 text-slate-800">
          <User className="w-4 h-4 text-slate-400" />
          <span className="text-sm font-black truncate">
            {customer?.customerType === 'firemní' ? (customer?.companyName || `${customer?.firstName} ${customer?.lastName}`) : `${customer?.firstName} ${customer?.lastName}`}
          </span>
        </div>
        <div className="flex items-center gap-2 text-slate-800">
          <Car className="w-4 h-4 text-slate-400" />
          <span className="text-[10px] font-black text-blue-700 font-mono tracking-wider uppercase">{vehicle?.licensePlate?.toUpperCase() || '---'}</span>
          <span className="text-xs font-bold text-slate-500">• {vehicle?.make} {vehicle?.model}</span>
        </div>
      </div>

      <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
        <div className="flex flex-col">
          <span className="text-[9px] font-black text-slate-500 uppercase">Odhad ceny</span>
          <span className="text-sm font-black text-slate-900">{Math.round(order.estimatedPrice || 0).toLocaleString()} Kč</span>
        </div>
        <button onClick={() => onEdit(order)} className="flex items-center gap-1 text-[10px] font-black text-blue-700 uppercase tracking-widest hover:underline px-3 py-1.5 bg-blue-50 rounded-lg border border-blue-200">
          Otevřít <ChevronRight className="w-3 h-3" />
        </button>
      </div>
    </div>
  );
};

const ServiceOrderModal: React.FC<{
  order: ServiceRecord | null;
  vehicles: Vehicle[];
  customers: Customer[];
  technicians: string[];
  predefinedTasks: PredefinedTask[];
  fixedServices: FixedService[];
  hourlyRate: number;
  companyInfo: CompanyInfo;
  onClose: () => void;
  onSave: (order: ServiceRecord) => void;
  preselectedVehicleId?: string | null;
}> = ({ order, vehicles, customers, technicians, predefinedTasks, fixedServices, hourlyRate, companyInfo, onClose, onSave, preselectedVehicleId }) => {
  const [activeTab, setActiveTab] = useState<'basic' | 'parts' | 'attachments' | 'print'>('basic');
  const [formData, setFormData] = useState<Partial<ServiceRecord>>(() => {
    if (order) return { ...order };
    const date = new Date().toISOString().split('T')[0];
    const yearPrefix = date.slice(2, 4);
    const monthPrefix = date.slice(5, 7);
    return {
      id: `${yearPrefix}/${monthPrefix}/XXX`, 
      date, 
      vehicleId: preselectedVehicleId || '', 
      status: 'naplánováno', 
      technician: technicians[0],
      laborHours: 0,
      cost: 0,
      parts: [],
      fuelLevel: '50%',
      returnParts: 'nevracet',
      checklist: { rezerva: false, zvedak: false, klic: false, bezp_klic: false, trojuhelnik: false, lekarna: false, lepeni: false },
      estimatedPrice: 0
    };
  });

  const [isAiAnalyzing, setIsAiAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const pdfInputRef = useRef<HTMLInputElement>(null);

  const calculateTotal = (parts: PartItem[], labor: number) => {
    const partsSum = parts.reduce((sum, it) => sum + (it.quantity * it.unitPrice), 0);
    const laborSum = labor * hourlyRate;
    return partsSum + laborSum;
  };

  const updateParts = (newParts: PartItem[]) => {
    const total = calculateTotal(newParts, formData.laborHours || 0);
    setFormData({ ...formData, parts: newParts, cost: total, estimatedPrice: total });
  };

  const handleAddPart = () => {
    const newPart: PartItem = { id: `p${Date.now()}`, description: '', quantity: 1, unit: 'ks', unitPrice: 0 };
    updateParts([...(formData.parts || []), newPart]);
  };

  const handleAddFixedService = (fs: FixedService) => {
    const newPart: PartItem = { 
      id: `p-fs-${Date.now()}`, 
      description: fs.name, 
      quantity: 1, 
      unit: fs.unit || 'ks', 
      unitPrice: fs.price, 
      costPrice: fs.costPrice 
    };
    updateParts([...(formData.parts || []), newPart]);
  };

  const handleApplyTemplate = (tpl: PredefinedTask) => {
    setFormData({ ...formData, description: (formData.description ? formData.description + '\n' : '') + tpl.description });
  };

  const handlePdfAnalyze = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsAiAnalyzing(true);
    try {
      const reader = new FileReader();
      const base64Promise = new Promise<string>((resolve) => {
        reader.onload = () => resolve(reader.result as string);
        reader.readAsDataURL(file);
      });
      const base64Data = await base64Promise;
      const splitted = base64Data.split(',');
      const parts = await analyzePdfParts(splitted.length > 1 ? splitted[1] : splitted[0], companyInfo.isVatPayer);
      const mapped: PartItem[] = parts.map((p, i) => ({
        id: `ai-${Date.now()}-${i}`,
        description: p.description || '',
        quantity: p.quantity || 1,
        unit: 'ks',
        unitPrice: p.unitPrice || 0,
        costPrice: p.costPrice || 0
      }));
      updateParts([...(formData.parts || []), ...mapped]);
    } catch (err) { alert("Chyba při analýze PDF."); }
    finally { setIsAiAnalyzing(false); if (pdfInputRef.current) pdfInputRef.current.value = ''; }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const newAtt: VehicleAttachment = { id: `att-${Date.now()}`, name: file.name, type: file.type, data: reader.result as string, size: file.size };
      setFormData({ ...formData, attachments: [...(formData.attachments || []), newAtt] });
    };
    reader.readAsDataURL(file);
    if (e.target) e.target.value = '';
  };

  const handlePrint = () => window.print();

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md" onClick={onClose}></div>
      <div className="bg-white w-full max-w-6xl h-[95vh] rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
        <div className="p-6 border-b flex justify-between items-center bg-slate-50 shrink-0">
