           </div>
           <div className="flex gap-2">
              <button onClick={handlePrint} className="px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-xs flex items-center gap-2 hover:bg-slate-800 transition-all"><Printer className="w-4 h-4" /> TISK ZL</button>
