           </div>
        </div>

        <div className="flex-1 overflow-hidden flex flex-col lg:flex-row">
           <aside className="w-full lg:w-64 bg-slate-50 border-r border-slate-100 flex lg:flex-col p-4 gap-2 shrink-0">
              <button onClick={() => setActiveTab('basic')} className={`flex-1 lg:flex-none flex items-center gap-3 px-6 py-4 rounded-2xl font-black text-xs uppercase transition-all ${activeTab === 'basic' ? 'bg-white text-blue-600 shadow-md border border-blue-50' : 'text-slate-400 hover:bg-slate-100'}`}><Layout className="w-4 h-4" /> Základní</button>
              <button onClick={() => setActiveTab('parts')} className={`flex-1 lg:flex-none flex items-center gap-3 px-6 py-4 rounded-2xl font-black text-xs uppercase transition-all ${activeTab === 'parts' ? 'bg-white text-blue-600 shadow-md border border-blue-50' : 'text-slate-400 hover:bg-slate-100'}`}><Package className="w-4 h-4" /> Položky</button>
              <button onClick={() => setActiveTab('attachments')} className={`flex-1 lg:flex-none flex items-center gap-3 px-6 py-4 rounded-2xl font-black text-xs uppercase transition-all ${activeTab === 'attachments' ? 'bg-white text-blue-600 shadow-md border border-blue-50' : 'text-slate-400 hover:bg-slate-100'}`}><Paperclip className="w-4 h-4" /> Přílohy</button>
              <button onClick={() => setActiveTab('print')} className={`flex-1 lg:flex-none flex items-center gap-3 px-6 py-4 rounded-2xl font-black text-xs uppercase transition-all ${activeTab === 'print' ? 'bg-white text-blue-600 shadow-md border border-blue-50' : 'text-slate-400 hover:bg-slate-100'}`}><Eye className="w-4 h-4" /> Náhled</button>
           </aside>

           <div className="flex-1 overflow-y-auto p-8 custom-scrollbar bg-white">
              {activeTab === 'basic' && (
                <div className="space-y-8 animate-in fade-in slide-in-from-left-4 duration-300">
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-6">
                         <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Detaily zakázky</h4>
                         <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vozidlo a zákazník</label>
                            <select required className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-blue-600 rounded-2xl outline-none font-bold" value={formData.vehicleId} onChange={e => setFormData({...formData, vehicleId: e.target.value})}>
                               <option value="">Vyberte vozidlo...</option>
                               {vehicles.map(v => {
                                 const c = customers.find(cust => cust.id === v.customerId);
                                 return <option key={v.id} value={v.id}>{v.licensePlate} • {v.make} {v.model} ({c?.lastName || c?.companyName})</option>
                               })}
                            </select>
                         </div>
                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Datum přijetí</label>
                               <input type="date" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                            </div>
                            <div className="space-y-2">
                               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Předpokládané dokončení</label>
                               <input type="date" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={formData.deliveryDate || ''} onChange={e => setFormData({...formData, deliveryDate: e.target.value})} />
                            </div>
                         </div>
                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-2">
                               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mechanik</label>
                               <select className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={formData.technician} onChange={e => setFormData({...formData, technician: e.target.value})}>
                                  {technicians.map(t => <option key={t} value={t}>{t}</option>)}
                               </select>
                            </div>
                            <div className="space-y-2">
                               <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Stav tachometru</label>
                               <input type="number" className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold" value={formData.mileageAtEntry || ''} onChange={e => setFormData({...formData, mileageAtEntry: parseInt(e.target.value) || 0})} />
                            </div>
                         </div>
                      </div>

                      <div className="space-y-6">
                         <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Požadavek a stav</h4>
                         <div className="space-y-2">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center justify-between">
                               Popis opravy / závady
                               <div className="flex gap-1">
                                  {predefinedTasks.slice(0, 3).map(pt => (
                                    <button key={pt.id} type="button" onClick={() => handleApplyTemplate(pt)} className="px-2 py-0.5 bg-blue-50 text-blue-600 rounded-md text-[8px] font-black uppercase hover:bg-blue-100 transition-colors">+{pt.label}</button>
                                  ))}
                               </div>
                            </label>
                            <textarea rows={5} className="w-full px-5 py-4 bg-slate-50 rounded-2xl font-bold resize-none" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} placeholder="Popište závadu..." />
                         </div>
                         <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4">
                            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Kontrolní seznam & Palivo</p>
                            <div className="grid grid-cols-2 gap-4">
                               <div className="space-y-2">
                                  <label className="text-[8px] font-black text-slate-400 uppercase ml-1">Stav paliva</label>
                                  <select className="w-full px-4 py-2 bg-white rounded-xl text-xs font-bold shadow-sm" value={formData.fuelLevel} onChange={e => setFormData({...formData, fuelLevel: e.target.value})}>
                                     {['Rezerva', '25%', '50%', '75%', 'Plná'].map(v => <option key={v} value={v}>{v}</option>)}
                                  </select>
                               </div>
                               <div className="space-y-2">
                                  <label className="text-[8px] font-black text-slate-400 uppercase ml-1">Vracet díly?</label>
                                  <div className="flex bg-white rounded-xl p-1 shadow-sm border border-slate-100">
                                     <button type="button" onClick={() => setFormData({...formData, returnParts: 'vrátit'})} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${formData.returnParts === 'vrátit' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400'}`}>ANO</button>
                                     <button type="button" onClick={() => setFormData({...formData, returnParts: 'nevracet'})} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${formData.returnParts === 'nevracet' ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400'}`}>NE</button>
                                  </div>
                               </div>
                            </div>
                         </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'parts' && (
                <div className="space-y-8 animate-in fade-in slide-in-from-left-4 duration-300">
                   <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-6 border-b border-slate-50">
                      <div className="flex items-center gap-4">
                         <div className="w-12 h-12 bg-emerald-50 rounded-2xl flex items-center justify-center text-emerald-600 shadow-sm"><Package className="w-6 h-6" /></div>
