                            <h4 className="text-xl font-black text-slate-900 tracking-tight">Kalkulace materiálu a práce</h4>
                            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">Hodinová sazba: <span className="text-slate-900">{Math.round(hourlyRate).toLocaleString()} Kč</span></p>
