                         <input type="file" ref={pdfInputRef} className="hidden" accept=".pdf" onChange={handlePdfAnalyze} />
                         <button type="button" onClick={handleAddPart} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase shadow-lg hover:scale-105 transition-all"><Plus className="w-4 h-4" /> Přidat položku</button>
                      </div>
