                   <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                      <div className="lg:col-span-3 space-y-4">
                         <div className="overflow-hidden border border-slate-100 rounded-[2rem] shadow-sm">
                            <table className="w-full text-sm">
                               <thead className="bg-slate-50 border-b border-slate-100">
                                  <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                                     <th className="px-6 py-4 text-left">Popis položky</th>
                                     <th className="px-4 py-4 w-24 text-center">Množ</th>
                                     <th className="px-4 py-4 w-32 text-right">Cena/J</th>
                                     <th className="px-4 py-4 w-32 text-right">Celkem</th>
                                     <th className="px-4 py-4 w-16"></th>
                                  </tr>
                               </thead>
                               <tbody className="divide-y divide-slate-50">
                                  {(formData.parts || []).map((it, idx) => (
                                    <tr key={it.id} className="group hover:bg-slate-50/50 transition-colors">
                                       <td className="px-6 py-3">
                                          <input type="text" className="w-full bg-transparent border-none font-bold text-slate-900 outline-none placeholder:text-slate-300" placeholder="Název dílu nebo úkonu..." value={it.description} onChange={e => {
                                            const next = [...(formData.parts || [])];
                                            next[idx].description = e.target.value;
