                                            updateParts(next);
                                          }} />
                                       </td>
                                       <td className="px-4 py-3 text-right font-black text-slate-900">{(it.quantity * it.unitPrice).toLocaleString()} Kč</td>
                                       <td className="px-4 py-3 text-center">
