                                     <td className="px-4 py-4 text-center">
                                        <input type="number" step="0.5" className="w-full bg-transparent border-none font-black text-blue-800 text-center outline-none" value={formData.laborHours || 0} onChange={e => {
                                          const val = parseFloat(e.target.value) || 0;
                                          const total = calculateTotal(formData.parts || [], val);
                                          setFormData({...formData, laborHours: val, cost: total, estimatedPrice: total});
                                        }} />
                                     </td>
                                     <td className="px-4 py-4 text-right font-bold text-slate-400">{Math.round(hourlyRate).toLocaleString()} Kč</td>
                                     <td className="px-4 py-4 text-right font-black text-blue-800">{Math.round((formData.laborHours || 0) * hourlyRate).toLocaleString()} Kč</td>
                                     <td></td>
                                  </tr>
                               </tbody>
                            </table>
                            {(formData.parts || []).length === 0 && !formData.laborHours && (
                              <div className="py-20 text-center flex flex-col items-center bg-white"><Calculator className="w-12 h-12 text-slate-100 mb-4" /><p className="text-slate-300 font-bold italic">Seznam je prázdný. Přidejte položky ručně nebo pomocí AI.</p></div>
                            )}
                         </div>
                      </div>

                      <div className="space-y-6">
                         <div className="bg-slate-900 rounded-[2rem] p-8 text-white shadow-xl relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-6 opacity-10 rotate-12"><Calculator className="w-24 h-24" /></div>
                            <div className="relative z-10">
                               <p className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400 mb-2">CELKOVÁ CENA</p>
                               <h3 className="text-4xl font-black tracking-tighter leading-none mb-4">{Math.round(formData.cost || 0).toLocaleString()} Kč</h3>
                               <div className="pt-4 border-t border-white/10 flex justify-between items-center">
                                  <span className="text-[9px] font-black uppercase text-slate-400">Včetně DPH:</span>
                                  <span className="text-xl font-black text-emerald-400">{Math.round((formData.cost || 0) * (companyInfo.isVatPayer ? 1.21 : 1)).toLocaleString()} Kč</span>
                               </div>
                            </div>
                         </div>
                         <div className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2"><Tag className="w-3.5 h-3.5" /> Rychlé služby</h4>
                            <div className="grid grid-cols-1 gap-2">
                               {fixedServices.map(fs => (
                                 <button key={fs.id} type="button" onClick={() => handleAddFixedService(fs)} className="w-full px-4 py-3 bg-slate-50 hover:bg-blue-50 border border-transparent hover:border-blue-200 rounded-xl flex items-center justify-between text-left transition-all group">
                                    <span className="text-xs font-bold text-slate-700 group-hover:text-blue-700 truncate mr-2">{fs.name}</span>
                                    <span className="text-[10px] font-black text-slate-900 shrink-0">{fs.price.toLocaleString()} Kč</span>
                                 </button>
                               ))}
                            </div>
                         </div>
                      </div>
                   </div>
                </div>
              )}

              {activeTab === 'attachments' && (
                <div className="space-y-8 animate-in fade-in slide-in-from-left-4 duration-300">
                   <div className="flex items-center justify-between pb-6 border-b border-slate-50">
                      <div>
                        <h4 className="text-xl font-black text-slate-900">Dokumentace zakázky</h4>
                        <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Fotografie, dokumenty a protokoly</p>
                      </div>
                      <button type="button" onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-slate-800 transition-all"><FilePlus className="w-5 h-5" /> NAHRÁT SOUBORY</button>
                      <input type="file" ref={fileInputRef} className="hidden" multiple onChange={handleFileUpload} />
                   </div>
                   <div className="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-5 gap-6">
                      {(formData.attachments || []).map(att => (
                        <div key={att.id} className="bg-slate-50 border border-slate-100 rounded-3xl p-6 group relative overflow-hidden flex flex-col items-center text-center">
                           <div className="w-16 h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center text-blue-500 mb-4 group-hover:scale-110 transition-transform">
                              {att.type.startsWith('image/') ? <ImageIcon className="w-8 h-8" /> : <FileText className="w-8 h-8" />}
                           </div>
                           <p className="text-xs font-bold text-slate-700 truncate w-full px-2">{att.name}</p>
                           <p className="text-[10px] font-black text-slate-400 uppercase mt-1">{(att.size / 1024).toFixed(0)} KB</p>
                           <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center gap-3">
                              <a href={att.data} download={att.name} className="p-3 bg-white/10 hover:bg-blue-600 rounded-xl text-white transition-colors"><Download className="w-5 h-5" /></a>
                              <button type="button" onClick={() => setFormData({...formData, attachments: (formData.attachments || []).filter(a => a.id !== att.id)})} className="p-3 bg-white/10 hover:bg-red-600 rounded-xl text-white transition-colors"><Trash2 className="w-5 h-5" /></button>
                           </div>
                        </div>
                      ))}
                      {(formData.attachments || []).length === 0 && (
                        <div className="col-span-full py-24 border-2 border-dashed border-slate-100 rounded-[3rem] flex flex-col items-center justify-center text-slate-300">
                           <Paperclip className="w-16 h-16 mb-4 opacity-20" />
                           <p className="text-sm font-black uppercase tracking-widest italic">Nahrajte fotografie nebo protokoly</p>
                        </div>
                      )}
                   </div>
                </div>
              )}

              {activeTab === 'print' && (
                <div className="animate-in fade-in zoom-in-95 duration-500 flex justify-center bg-slate-100/50 p-12 rounded-[3rem] min-h-full">
                   <PrintTemplate 
                    order={formData as ServiceRecord} 
                    company={companyInfo} 
                    vehicles={vehicles} 
                    customers={customers} 
                    hourlyRate={hourlyRate}
                    technicians={technicians}
                   />
                </div>
              )}
           </div>
        </div>

        <div className="p-8 border-t bg-slate-50 flex gap-4 shrink-0">
           <button onClick={onClose} className="flex-1 py-4 bg-white border-2 border-slate-200 rounded-2xl font-black text-xs uppercase hover:bg-slate-100 transition-all">Storno</button>
           <button onClick={() => onSave(formData as ServiceRecord)} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase hover:bg-blue-700 transition-all shadow-xl shadow-blue-200">Uložit zakázku</button>
        </div>
      </div>
    </div>
  );
};

