import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock, ShieldCheck, ShieldAlert, CreditCard,
  AlertOctagon, BarChart3, Coins, Wallet, Briefcase, Calendar
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice, VehicleAttachment, VehicleChecklist, StatsSettings, CostItem, CostCategory } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  statsSettings: StatsSettings;
  onStatsSettingsChange: (settings: StatsSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  onClearAllData: () => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const UNITS = ['ks', 'litr', 'gram', 'kg', 'm', 'sada', 'úkon'];
const COST_CATEGORIES: CostCategory[] = ['energie', 'nájemné', 'spotřební zboží', 'mzdy', 'pojištění', 'marketing', 'ostatní'];

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  statsSettings, onStatsSettingsChange,
  customers, vehicles, services, invoices, onRestoreData, onClearAllData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
  userSettings, onUserSettingsChange
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates' | 'stats_config'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);
  const [isClearDataConfirmOpen, setIsClearDataConfirmOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const addCostItem = () => {
    const newItem: CostItem = {
      id: `cost-${Date.now()}`,
      name: '',
      amount: 0,
      category: 'ostatní',
      isRecurring: true
    };
    onStatsSettingsChange({
      ...statsSettings,
      costItems: [...(statsSettings.costItems || []), newItem]
    });
  };

  const updateCostItem = (id: string, field: keyof CostItem, value: any) => {
    onStatsSettingsChange({
      ...statsSettings,
      costItems: statsSettings.costItems.map(item => item.id === id ? { ...item, [field]: value } : item)
    });
  };

  const removeCostItem = (id: string) => {
    onStatsSettingsChange({
      ...statsSettings,
      costItems: statsSettings.costItems.filter(item => item.id !== id)
    });
  };

  const handleHourlyRateChange = (value: string) => {
    const rawValue = parseFloat(value) || 0;
    const finalValue = companyInfo.isVatPayer ? (rawValue / 1.21) : rawValue;
    onRateChange(finalValue);
  };

  const displayHourlyRate = () => companyInfo.isVatPayer ? Math.round(hourlyRate * 1.21) : Math.round(hourlyRate);

  const addDiscountLevel = () => {
    const val = parseInt(newDiscount);
    if (!isNaN(val) && !discountLevels.includes(val)) {
      onDiscountLevelsChange([...discountLevels, val].sort((a, b) => a - b));
      setNewDiscount('');
    }
  };

  const removeDiscountLevel = (val: number) => onDiscountLevelsChange(discountLevels.filter(d => d !== val));

  const addFixedService = () => onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0, costPrice: 0, unit: 'ks' }]);
  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));

  const addTemplate = () => onPredefinedTasksChange([...predefinedTasks, { id: `pt${Date.now()}`, label: '', description: '' }]);
  const updateTemplate = (id: string, field: keyof PredefinedTask, value: string) => onPredefinedTasksChange(predefinedTasks.map(pt => pt.id === id ? { ...pt, [field]: value } : pt));

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };
  const removeTechnician = (name: string) => onTechniciansChange(technicians.filter(t => t !== name));

  const esc = (str: any) => String(str || '').replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c] || c));
  const xmlTag = (name: string, value: any, indent: string = '    ') => `${indent}<${name}>${esc(value)}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="3.5">\n`;

    // 1. FIREMNÍ ÚDAJE
    xml += `  <CompanyInfo>\n`;
    xml += xmlTag('Name', companyInfo?.name);
    xml += xmlTag('Address', companyInfo?.address);
    xml += xmlTag('ICO', companyInfo?.ico);
    xml += xmlTag('DIC', companyInfo?.dic);
    xml += xmlTag('Phone', companyInfo?.phone);
    xml += xmlTag('Email', companyInfo?.email);
    xml += xmlTag('BankAccount', companyInfo?.bankAccount);
    xml += xmlTag('FoundationDate', companyInfo?.foundationDate);
    xml += xmlTag('IsVatPayer', !!companyInfo?.isVatPayer);
    xml += `  </CompanyInfo>\n`;

    // 2. ZÁKAZNÍCI
    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${esc(c.id)}">\n`;
      xml += xmlTag('CustomerType', c.customerType);
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      if (c.companyAddress) xml += xmlTag('CompanyAddress', c.companyAddress);
      if (c.contactPerson) xml += xmlTag('ContactPerson', c.contactPerson);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    // 3. VOZIDLA (ROZŠÍŘENO O VŠECHNA DATA KARTY)
    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${esc(v.id)}" customerId="${esc(v.customerId)}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += xmlTag('ServiceIntervalKm', v.serviceIntervalKm);
      xml += xmlTag('ServiceIntervalMonths', v.serviceIntervalMonths);
      xml += xmlTag('Notes', v.notes);

      // Specifické intervaly
      xml += xmlTag('BrakeFluidDate', v.brakeFluidDate);
      xml += xmlTag('CoolantDate', v.coolantDate);
      xml += xmlTag('GearboxOilDate', v.gearboxOilDate);
      xml += xmlTag('TimingBeltDate', v.timingBeltDate);
      xml += xmlTag('RefrigerantDate', v.refrigerantDate);
      xml += xmlTag('BrakeFluidInterval', v.brakeFluidInterval);
      xml += xmlTag('CoolantInterval', v.coolantInterval);
      xml += xmlTag('GearboxOilInterval', v.gearboxOilInterval);
      xml += xmlTag('TimingBeltInterval', v.timingBeltInterval);
      xml += xmlTag('RefrigerantInterval', v.refrigerantInterval);

      if (v.attachments && v.attachments.length > 0) {
        xml += `      <Attachments>\n`;
        v.attachments.forEach(att => {
          xml += `        <Attachment id="${esc(att.id)}">\n`;
          xml += xmlTag('Name', att.name, '          ');
          xml += xmlTag('Type', att.type, '          ');
          xml += xmlTag('Data', att.data, '          ');
          xml += xmlTag('Size', att.size, '          ');
          xml += `        </Attachment>\n`;
        });
        xml += `      </Attachments>\n`;
      }
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    // 4. ZAKÁZKY
    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${esc(s.id)}" vehicleId="${esc(s.vehicleId)}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      xml += xmlTag('MileageAtEntry', s.mileageAtEntry);
      xml += xmlTag('DeliveryDate', s.deliveryDate);
      xml += xmlTag('FuelLevel', s.fuelLevel);
      xml += xmlTag('ReturnParts', s.returnParts);

      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${esc(p.id)}">\n`;
          xml += xmlTag('Description', p.description, '          ');
          xml += xmlTag('Quantity', p.quantity, '          ');
          xml += xmlTag('UnitPrice', p.unitPrice, '          ');
          xml += xmlTag('CostPrice', p.costPrice, '          ');
          xml += xmlTag('Unit', p.unit, '          ');
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }

      if (s.checklist) {
        xml += `      <Checklist>\n`;
        Object.entries(s.checklist).forEach(([key, val]) => {
          xml += `        <${key}>${val}</${key}>\n`;
        });
        xml += `      </Checklist>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    // 5. FAKTURY
    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${esc(inv.id)}" orderId="${esc(inv.orderId)}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalExclDph', inv.totalExclDph);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Costs', inv.costs || 0);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += xmlTag('Discount', inv.discount || 0);
      xml += xmlTag('Archived', !!inv.archived);

      if (inv.items && inv.items.length > 0) {
        xml += `      <InvoiceItems>\n`;
        inv.items.forEach(item => {
          xml += `        <Item id="${esc(item.id)}">\n`;
          xml += xmlTag('Description', item.description, '          ');
          xml += xmlTag('Quantity', item.quantity, '          ');
          xml += xmlTag('UnitPrice', item.unitPrice, '          ');
          xml += xmlTag('Unit', item.unit || 'ks', '          ');
          xml += `        </Item>\n`;
        });
        xml += `      </InvoiceItems>\n`;
      }
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    // 6. SYSTÉMOVÉ NASTAVENÍ
    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);

    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${esc(t)}</Technician>\n`);
    xml += `    </Technicians>\n`;

    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;

    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${esc(fs.id)}">\n`;
      xml += xmlTag('Name', fs.name, '        ');
      xml += xmlTag('Price', fs.price, '        ');
      xml += xmlTag('CostPrice', fs.costPrice, '        ');
      xml += xmlTag('Unit', fs.unit, '        ');
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;

    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${esc(pt.id)}">\n`;
      xml += xmlTag('Label', pt.label, '        ');
      xml += xmlTag('Description', pt.description, '        ');
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;

    xml += `    <StatsSettings>\n`;
    (statsSettings.costItems || []).forEach(item => {
        xml += `      <CostItem id="${item.id}">\n`;
        xml += xmlTag('Name', item.name, '        ');
        xml += xmlTag('Amount', item.amount, '        ');
        xml += xmlTag('Category', item.category, '        ');
        xml += xmlTag('IsRecurring', item.isRecurring, '        ');
        xml += `      </CostItem>\n`;
    });
    xml += `    </StatsSettings>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xml = generateBackupXml();
      const blob = new Blob([xml], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 2000);
    } catch (err) {
      console.error(err);
      setBackupStatus('error');
    }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setBackupStatus('processing');
    const reader = new FileReader();

    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");

        const txt = (parent: Element | Document, selector: string) => parent.querySelector(selector)?.textContent || '';
        const num = (parent: Element | Document, selector: string) => {
          const val = txt(parent, selector);
          return val ? parseFloat(val) : 0;
        };
        const bool = (parent: Element | Document, selector: string) => txt(parent, selector) === 'true';

        const restoredData = {
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id") || `cust-${Math.random().toString(36).substr(2, 9)}`,
            customerType: txt(node, "CustomerType") as any,
            firstName: txt(node, "FirstName"),
            lastName: txt(node, "LastName"),
            email: txt(node, "Email"),
            phone: txt(node, "Phone"),
            address: txt(node, "Address"),
            createdAt: txt(node, "CreatedAt") || new Date().toISOString(),
            companyName: txt(node, "CompanyName"),
            ico: txt(node, "ICO"),
            dic: txt(node, "DIC"),
            companyAddress: txt(node, "CompanyAddress"),
            contactPerson: txt(node, "ContactPerson")
          })),
          vehicles: Array.from(xmlDoc.querySelectorAll("Vehicle")).map(node => ({
            id: node.getAttribute("id") || `veh-${Math.random().toString(36).substr(2, 9)}`,
            customerId: node.getAttribute("customerId") || '',
            make: txt(node, "Make"),
            model: txt(node, "Model"),
            year: num(node, "Year"),
            vin: txt(node, "VIN"),
            licensePlate: txt(node, "LicensePlate"),
            mileage: num(node, "Mileage"),
            engineCode: txt(node, "EngineCode"),
            color: txt(node, "Color"),
            stkExpirationDate: txt(node, "STKExpirationDate"),
            nextServiceDate: txt(node, "NextServiceDate"),
            // Nově přidaná pole s výchozími hodnotami pro kompatibilitu
            serviceIntervalKm: num(node, "ServiceIntervalKm") || 15000,
            serviceIntervalMonths: num(node, "ServiceIntervalMonths") || 12,
            notes: txt(node, "Notes"),
            brakeFluidDate: txt(node, "BrakeFluidDate"),
            coolantDate: txt(node, "CoolantDate"),
            gearboxOilDate: txt(node, "GearboxOilDate"),
            timingBeltDate: txt(node, "TimingBeltDate"),
            refrigerantDate: txt(node, "RefrigerantDate"),
            brakeFluidInterval: num(node, "BrakeFluidInterval") || 24,
            coolantInterval: num(node, "CoolantInterval") || 60,
            gearboxOilInterval: num(node, "GearboxOilInterval") || 60,
            timingBeltInterval: num(node, "TimingBeltInterval") || 120,
            refrigerantInterval: num(node, "RefrigerantInterval") || 24,
            attachments: Array.from(node.querySelectorAll("Attachment")).map(att => ({
              id: att.getAttribute("id") || `att-${Math.random().toString(36).substr(2, 9)}`,
              name: txt(att, "Name"),
              type: txt(att, "Type"),
              data: txt(att, "Data"),
              size: num(att, "Size")
            }))
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => {
            const checklist: any = {};
            const checklistNode = node.querySelector("Checklist");
            if (checklistNode) {
              Array.from(checklistNode.children).forEach(child => {
                checklist[child.tagName] = child.textContent === 'true';
              });
            }
            return {
              id: node.getAttribute("id") || `srv-${Math.random().toString(36).substr(2, 9)}`,
              vehicleId: node.getAttribute("vehicleId") || '',
              date: txt(node, "Date"),
              description: txt(node, "Description"),
              cost: num(node, "Cost"),
              status: txt(node, "Status") as any,
              technician: txt(node, "Technician"),
              laborHours: num(node, "LaborHours"),
              mileageAtEntry: num(node, "MileageAtEntry"),
              deliveryDate: txt(node, "DeliveryDate"),
              fuelLevel: txt(node, "FuelLevel"),
              returnParts: txt(node, "ReturnParts") as any,
              parts: Array.from(node.querySelectorAll("Part")).map(p => ({
                id: p.getAttribute("id") || `part-${Math.random().toString(36).substr(2, 9)}`,
                description: txt(p, "Description"),
                quantity: num(p, "Quantity"),
                unitPrice: num(p, "UnitPrice"),
                costPrice: num(p, "CostPrice"),
                unit: txt(p, "Unit") || 'ks'
              })),
              checklist: checklist
            };
          }),
          invoices: Array.from(xmlDoc.querySelectorAll("Invoice")).map(node => {
            return {
              uid: `inv-uid-imp-${Math.random().toString(36).substr(2, 9)}`,
              id: node.getAttribute("id") || `inv-${Math.random().toString(36).substr(2, 9)}`,
              orderId: node.getAttribute("orderId") || '',
              issueDate: txt(node, "IssueDate") || new Date().toISOString(),
              dueDate: txt(node, "DueDate") || new Date().toISOString(),
              customerId: txt(node, "CustomerId"),
              vehicleInfo: txt(node, "VehicleInfo"),
              totalExclDph: num(node, "TotalExclDph"),
              totalInclDph: num(node, "TotalInclDph"),
              costs: num(node, "Costs"),
              status: txt(node, "Status") as any,
              paymentType: txt(node, "PaymentType") as any,
              discount: num(node, "Discount"),
              archived: bool(node, "Archived"),
              items: Array.from(node.querySelectorAll("Item")).map(itemNode => ({
                id: itemNode.getAttribute("id") || `item-${Math.random().toString(36).substr(2, 9)}`,
                description: txt(itemNode, "Description"),
                quantity: num(itemNode, "Quantity"),
                unitPrice: num(itemNode, "UnitPrice"),
                unit: txt(itemNode, "Unit") || 'ks'
              }))
            };
          }),
          companyInfo: {
            name: txt(xmlDoc, "CompanyInfo Name"),
            address: txt(xmlDoc, "CompanyInfo Address"),
            ico: txt(xmlDoc, "CompanyInfo ICO"),
            dic: txt(xmlDoc, "CompanyInfo DIC"),
            phone: txt(xmlDoc, "CompanyInfo Phone"),
            email: txt(xmlDoc, "CompanyInfo Email"),
            bankAccount: txt(xmlDoc, "CompanyInfo BankAccount"),
            foundationDate: txt(xmlDoc, "CompanyInfo FoundationDate"),
            isVatPayer: bool(xmlDoc, "CompanyInfo IsVatPayer")
          },
          settings: {
            hourlyRate: num(xmlDoc, "HourlyRate"),
            technicians: Array.from(xmlDoc.querySelectorAll("Technician")).map(t => t.textContent || ''),
            discountLevels: Array.from(xmlDoc.querySelectorAll("Level")).map(l => parseInt(l.textContent || '0')),
            fixedServices: Array.from(xmlDoc.querySelectorAll("FixedService")).map(node => ({
              id: node.getAttribute("id") || `fs-${Math.random()}`,
              name: txt(node, "Name"),
              price: num(node, "Price"),
              costPrice: num(node, "CostPrice"),
              unit: txt(node, "Unit") || 'ks'
            })),
            predefinedTasks: Array.from(xmlDoc.querySelectorAll("PredefinedTask")).map(node => ({
              id: node.getAttribute("id") || `pt-${Math.random()}`,
              label: txt(node, "Label"),
              description: txt(node, "Description")
            }))
          },
          statsSettings: {
            costItems: Array.from(xmlDoc.querySelectorAll("CostItem")).map(node => ({
              id: node.getAttribute("id") || `cost-${Math.random()}`,
              name: txt(node, "Name"),
              amount: num(node, "Amount"),
              category: txt(node, "Category") as any,
              isRecurring: bool(node, "IsRecurring")
            }))
          }
        };

        onRestoreData(restoredData);
        setBackupStatus('success');
        setTimeout(() => setBackupStatus('idle'), 3000);
      } catch (err) {
        console.error("Restore failed:", err);
        setBackupStatus('error');
      }
    };
    reader.readAsText(file);
    if (event.target) event.target.value = '';
  };

