            <Dashboard 
              customers={customers} 
              vehicles={vehicles} 
              services={services} 
              tasks={tasks}
              onAddTask={handleAddTask}
              onUpdateTask={handleUpdateTask}
              onDeleteTask={handleDeleteTask}
              onNavigate={handleNavigate} 
