export const getMaintenanceAdvice = async (vehicle: Vehicle, history: ServiceRecord[]) => {
  const prompt = `Jsi expertní automechanik. Navrhni plán údržby pro vozidlo:
  Model: ${vehicle.make} ${vehicle.model}
