/**
 * BOT pro ověřování STK z veřejných registrů (dataovozidlech.cz)
 */
export const checkVehicleStkOnline = async (vin: string): Promise<{ 
  stkDate: string | null; 
  found: boolean; 
  sources: {uri: string, title: string}[];
  rawText: string;
}> => {
  const prompt = `Vyhledej technické informace o vozidle s VIN: ${vin}. 
  Zaměř se na datum příští pravidelné technické prohlídky (STK). 
  Zkus najít konkrétní informaci z webu dataovozidlech.cz nebo jiných registrů.
  Pokud datum najdeš, uveď ho ve formátu RRRR-MM-DD.
  Odpověz česky a stručně shrň, co jsi zjistil.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => ({
        uri: chunk.web?.uri || "",
        title: chunk.web?.title || "Zdroj informací"
      })).filter((s: any) => s.uri) || [];

    const text = response.text || "";
    // Pokusíme se z textu vytáhnout datum ve formátu RRRR-MM-DD nebo DD.MM.RRRR
    const dateMatch = text.match(/(\d{4}-\d{2}-\d{2})|(\d{2}\.\d{2}\.\d{4})/);
    let extractedDate = null;

    if (dateMatch) {
      if (dateMatch[1]) {
        extractedDate = dateMatch[1];
      } else if (dateMatch[2]) {
        const parts = dateMatch[2].split('.');
        extractedDate = `${parts[2]}-${parts[1]}-${parts[2]}`;
      }
    }

    return {
      stkDate: extractedDate,
      found: !!extractedDate,
      sources,
      rawText: text
    };
  } catch (error) {
    console.error("STK Bot Error:", error);
    return { stkDate: null, found: false, sources: [], rawText: "Chyba při komunikaci s botem." };
  }
};

