/**
 * Specializovaný BOT pro ověřování STK výhradně z webu dataovozidlech.cz
 */
export const checkVehicleStkOnline = async (vin: string): Promise<{ 
  stkDate: string | null; 
  found: boolean; 
  sources: {uri: string, title: string}[];
  rawText: string;
}> => {
  const prompt = `Jsi specializovaný bot pro kontrolu STK. Tvým úkolem je vyhledat vozidlo s VIN: ${vin} výhradně na webu "https://dataovozidlech.cz/".
  Najdi sekci s technickými údaji a v ní kolonku s názvem "Pravidelná technická prohlídka do".
  Z této kolonky extrahuj datum.

  DŮLEŽITÉ:
  1. Pokud datum najdeš, vrať ho ve formátu RRRR-MM-DD.
  2. Pokud se ti nepodaří najít data přímo na dataovozidlech.cz, uveď to.
  3. Odpověz česky a buď velmi stručný.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => ({
        uri: chunk.web?.uri || "",
        title: chunk.web?.title || "Data o vozidlech"
      })).filter((s: any) => s.uri && s.uri.includes('dataovozidlech.cz')) || [];

    const text = response.text || "";

    // Regex pro zachycení různých formátů data (český DD.MM.RRRR nebo ISO RRRR-MM-DD)
    const dateMatch = text.match(/(\d{4}-\d{2}-\d{2})|(\d{1,2}\.\s?\d{1,2}\.\s?\d{4})/);
    let extractedDate = null;

    if (dateMatch) {
      if (dateMatch[1]) {
        extractedDate = dateMatch[1];
      } else if (dateMatch[2]) {
        // Převod českého formátu DD.MM.RRRR na YYYY-MM-DD
        const parts = dateMatch[2].replace(/\s/g, '').split('.');
        if (parts.length === 3) {
          const day = parts[0].padStart(2, '0');
          const month = parts[1].padStart(2, '0');
          const year = parts[2];
          extractedDate = `${year}-${month}-${day}`;
        }
      }
    }

    return {
      stkDate: extractedDate,
      found: !!extractedDate,
      sources: sources.length > 0 ? sources : (response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
        uri: chunk.web?.uri || "",
        title: chunk.web?.title || "Zdroj"
      })).filter((s: any) => s.uri) || []),
      rawText: text
    };
  } catch (error) {
    console.error("STK Bot Error:", error);
    return { stkDate: null, found: false, sources: [], rawText: "Chyba při komunikaci s botem." };
  }
};

