  const [editingVehicle, setEditingVehicle] = useState<Vehicle | null>(null);
  const [deletingVehicle, setDeletingVehicle] = useState<Vehicle | null>(null);
  const [selectedVehicleId, setSelectedVehicleId] = useState<string | null>(null);
  const [historyVehicleId, setHistoryVehicleId] = useState<string | null>(null);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [selectedLetter, setSelectedLetter] = useState<string | null>(null);

  // Bot States
  const [isBotLoading, setIsBotLoading] = useState(false);
  const [botResult, setBotResult] = useState<{stkDate: string | null, rawText: string, sources: {uri: string, title: string}[]} | null>(null);

  const menuRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const selectedVehicle = useMemo(() => vehicles.find(v => v.id === selectedVehicleId) || null, [vehicles, selectedVehicleId]);
  const historyVehicle = useMemo(() => vehicles.find(v => v.id === historyVehicleId) || null, [vehicles, historyVehicleId]);

  const initialFormData: Partial<Vehicle> = {
    make: 'Škoda', model: '', year: new Date().getFullYear(), vin: '', licensePlate: '', mileage: 0, engineCode: '', color: '', stkExpirationDate: '', nextServiceDate: '', serviceIntervalKm: 15000, serviceIntervalMonths: 12, customerId: customers[0]?.id || '', attachments: [], brakeFluidDate: '', coolantDate: '', gearboxOilDate: '', timingBeltDate: '', refrigerantDate: '', brakeFluidInterval: 24, coolantInterval: 60, gearboxOilInterval: 60, timingBeltInterval: 120, refrigerantInterval: 24
  };

  const [formData, setFormData] = useState<Partial<Vehicle>>(initialFormData);

  useEffect(() => {
    if (autoOpen) {
      setEditingVehicle(null);
      setFormData(initialFormData);
      setActiveTab('basic');
      setIsModalOpen(true);
      if (onModalOpened) onModalOpened();
    }
  }, [autoOpen]);

  useEffect(() => {
    if (initialVehicleId) {
      setSelectedVehicleId(initialVehicleId);
      if (onModalOpened) onModalOpened();
    }
  }, [initialVehicleId]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setOpenMenuId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const availableMakes = useMemo(() => Object.keys(VEHICLE_DB), []);
  const availableModels = useMemo(() => (formData.make && VEHICLE_DB[formData.make]) ? Object.keys(VEHICLE_DB[formData.make]) : [], [formData.make]);
  const availableEngines = useMemo(() => (formData.make && formData.model && VEHICLE_DB[formData.make] && VEHICLE_DB[formData.make][formData.model]) ? VEHICLE_DB[formData.make][formData.model] : [], [formData.make, formData.model]);

  const alphabet = useMemo(() => {
    const letters = new Set<string>();
    vehicles.forEach(v => { if (v.make) letters.add(v.make[0].toUpperCase()); });
    return Array.from(letters).sort((a, b) => a.localeCompare(b, 'cs'));
  }, [vehicles]);

  const filteredVehicles = useMemo(() => {
    return vehicles.filter(v => {
      const customer = customers.find(c => c.id === v.customerId);
      const customerName = customer ? (customer.customerType === 'firemní' ? customer.companyName : `${customer.lastName} ${customer.firstName}`) : "";
      const matchesSearch = (v.licensePlate || "").toLowerCase().includes(search.toLowerCase()) || (v.make || "").toLowerCase().includes(search.toLowerCase()) || (v.model || "").toLowerCase().includes(search.toLowerCase()) || (v.vin || "").toLowerCase().includes(search.toLowerCase()) || customerName?.toLowerCase().includes(search.toLowerCase());
      const matchesLetter = !selectedLetter || (v.make && v.make[0].toUpperCase() === selectedLetter);
      return matchesSearch && matchesLetter;
    }).sort((a, b) => (a.make || "").localeCompare(b.make || "", 'cs'));
  }, [vehicles, search, selectedLetter, customers]);

  const handleAddNew = () => { setEditingVehicle(null); setFormData(initialFormData); setActiveTab('basic'); setIsModalOpen(true); };
  const handleEdit = (v: Vehicle) => { setEditingVehicle(v); setFormData({ ...initialFormData, ...v }); setActiveTab('basic'); setIsModalOpen(true); setOpenMenuId(null); };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const sanitizedData = { ...formData, licensePlate: (formData.licensePlate || '').trim().toUpperCase(), vin: (formData.vin || '').trim().toUpperCase() };
    if (editingVehicle) onUpdateVehicle({ ...editingVehicle, ...sanitizedData } as Vehicle);
    else onAddVehicle({ ...sanitizedData, id: `v${Date.now()}` } as Vehicle);
    setIsModalOpen(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files; if (!files || !selectedVehicle) return;
    const file = files[0]; const reader = new FileReader();
    reader.onloadend = () => {
      const newAttachment: VehicleAttachment = { id: `att-${Date.now()}`, name: file.name, type: file.type, data: reader.result as string, size: file.size };
      onUpdateVehicle({ ...selectedVehicle, attachments: [...(selectedVehicle.attachments || []), newAttachment] });
    };
    reader.readAsDataURL(file); e.target.value = '';
  };

  const handleStkBotCheck = async () => {
    if (!selectedVehicle || !selectedVehicle.vin) return;
    setIsBotLoading(true); setBotResult(null);
    try {
      const result = await checkVehicleStkOnline(selectedVehicle.vin);
      setBotResult(result);
    } catch (err) { console.error(err); } finally { setIsBotLoading(false); }
  };

  const handleSyncStk = () => {
    if (!selectedVehicle || !botResult?.stkDate) return;
    onUpdateVehicle({ ...selectedVehicle, stkExpirationDate: botResult.stkDate });
    setBotResult(null);
  };

  const vehicleServices = useMemo(() => historyVehicleId ? services.filter(s => s.vehicleId === historyVehicleId).sort((a, b) => (b.date || "").localeCompare(a.date || "")) : [], [historyVehicleId, services]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Vozidla</h2>
          <p className="text-slate-500 font-medium">Evidence vozového parku a servisních intervalů.</p>
        </div>
        <button onClick={handleAddNew} className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg"><Plus className="w-5 h-5" />Nové vozidlo</button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input type="text" placeholder="Hledat podle SPZ, značky, modelu, VIN nebo jména majitele..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
          {search && <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>}
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <div className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 flex items-center gap-2 shrink-0"><Type className="w-4 h-4 text-slate-400" /><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">Značka:</span></div>
          <button onClick={() => setSelectedLetter(null)} className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>VŠE</button>
          {alphabet.map(letter => <button key={letter} onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)} className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>{letter}</button>)}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVehicles.map(v => {
          const isOverdue = checkVehicleOverdueStatus(v);
          return (
            <div key={v.id} className={`bg-white rounded-[2.5rem] border ${isOverdue ? 'border-red-200 bg-red-50/5' : 'border-slate-100'} p-8 shadow-sm hover:shadow-xl transition-all group relative overflow-visible`}>
              {isOverdue && <div className="absolute -top-2 -left-2 z-10 animate-bounce"><div className="bg-red-600 text-white p-2 rounded-full shadow-lg border-2 border-white"><AlertTriangle className="w-5 h-5 stroke-[3]" /></div></div>}
              <div className="absolute top-0 right-0 p-6">
                <div className="relative">
                  <button onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)} className={`p-2 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}><MoreHorizontal className="w-5 h-5" /></button>
                  {openMenuId === v.id && (
                    <div ref={menuRef} className="absolute top-12 right-0 w-52 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                      <button onClick={() => handleEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"><Edit3 className="w-4 h-4 text-slate-400" />Upravit vozidlo</button>
                      <button onClick={() => { onCreateOrder(v.id); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"><ClipboardPlus className="w-4 h-4 text-blue-400" />Vytvořit zakázku</button>
                      <div className="h-px bg-slate-100 my-1 mx-2"></div>
                      <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"><Trash2 className="w-4 h-4" />Smazat vozidlo</button>
                    </div>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-6 mb-6">
                <div className={`w-20 h-20 rounded-3xl ${isOverdue ? 'bg-red-500 shadow-red-200' : 'bg-slate-900 shadow-slate-200'} flex items-center justify-center text-white font-black text-xl shadow-xl transition-transform group-hover:scale-105`}><Car className="w-10 h-10" /></div>
                <div className="min-w-0 pr-8">
                  <h3 className="text-xl font-black text-slate-900 leading-tight truncate">{v.make} {v.model}</h3>
                  <div className="flex items-center gap-2 mt-1.5">
                    <p className="text-sm font-black text-blue-600 font-mono tracking-widest uppercase">{v.licensePlate?.toUpperCase()}</p>
                    {isOverdue && <span className="text-[10px] font-black text-red-600 px-2 py-0.5 bg-red-50 rounded-lg uppercase tracking-tighter">Prošlý servis</span>}
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3 mt-8">
                <button onClick={() => setSelectedVehicleId(v.id)} className="py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider">Detail karty</button>
                <button onClick={() => setHistoryVehicleId(v.id)} className="py-4 bg-blue-50 text-blue-600 rounded-2xl font-black text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider flex items-center justify-center gap-2"><HistoryIcon className="w-4 h-4" />Historie</button>
              </div>
            </div>
          );
        })}
      </div>

      {/* DETAIL MODAL - THE CORE UI REQUESTED BY USER */}
      {selectedVehicle && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedVehicleId(null)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 p-10 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 rounded-2xl bg-slate-800 flex items-center justify-center font-black shadow-inner"><Car className="w-8 h-8" /></div>
                <div>
                  <h3 className="text-3xl font-black tracking-tighter">{selectedVehicle.make} {selectedVehicle.model}</h3>
                  <p className="text-slate-400 text-sm font-black uppercase tracking-[0.2em] mt-1">{selectedVehicle.licensePlate?.toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedVehicleId(null)} className="p-3 hover:bg-white/10 rounded-2xl transition-colors"><X className="w-8 h-8" /></button>
            </div>

            <div className="p-10 space-y-10 overflow-y-auto custom-scrollbar bg-white">
              {/* STK BOT SECTION - INTEGRATED INTO THE TOP */}
              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden border border-white/5">
                <div className="absolute top-0 right-0 p-6 opacity-10"><Bot className="w-24 h-24" /></div>
                <div className="relative z-10">
                  <div className="flex items-center gap-3 mb-6">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center shadow-lg shadow-blue-900/40"><Bot className="w-6 h-6" /></div>
                    <h4 className="text-base font-black uppercase tracking-widest">STK BOT (dataovozidlech.cz)</h4>
                  </div>
                  {botResult ? (
                    <div className="space-y-6 animate-in fade-in zoom-in-95 duration-300">
                      <div className="p-6 bg-white/5 rounded-3xl border border-white/10 flex justify-between items-center">
                        <div className="space-y-1"><p className="text-[10px] font-black text-slate-500 uppercase">Databáze</p><p className="text-lg font-black">{formatDate(selectedVehicle.stkExpirationDate)}</p></div>
                        <RefreshCcw className="w-6 h-6 text-slate-600" />
                        <div className="text-right space-y-1"><p className="text-[10px] font-black text-blue-400 uppercase">Zjištěno online</p><p className="text-lg font-black text-blue-400">{botResult.stkDate ? formatDate(botResult.stkDate) : 'Nenalezeno'}</p></div>
                      </div>
                      {botResult.stkDate && botResult.stkDate !== selectedVehicle.stkExpirationDate && <button onClick={handleSyncStk} className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black uppercase shadow-xl transition-all flex items-center justify-center gap-3"><RefreshCcw className="w-5 h-5" /> AKTUALIZOVAT DATUM STK</button>}
                      <div className="flex flex-wrap gap-2">{botResult.sources.map((src, i) => <a key={i} href={src.uri} target="_blank" rel="noopener noreferrer" className="px-4 py-2 bg-white/5 hover:bg-white/10 rounded-xl text-[10px] font-bold flex items-center gap-2 transition-all"><ExternalLink className="w-4 h-4" /> {src.title.substring(0, 30)}...</a>)}</div>
                      <button onClick={() => setBotResult(null)} className="text-[10px] font-black text-slate-500 uppercase hover:text-white transition-colors border-t border-white/5 pt-4 w-full text-center">Zavřít výsledky kontroly</button>
                    </div>
                  ) : (
                    <div className="flex flex-col gap-6">
                      <p className="text-sm font-medium text-slate-400">Automaticky ověří termín „Pravidelná technická prohlídka do“ přímo z registru vozidel dle VIN kódu.</p>
                      <button onClick={handleStkBotCheck} disabled={isBotLoading || !selectedVehicle.vin} className="flex items-center justify-center gap-4 w-full py-5 bg-white/10 hover:bg-white/20 disabled:opacity-50 disabled:cursor-not-allowed rounded-2xl transition-all border border-white/5 font-black text-sm uppercase">{isBotLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Bot className="w-6 h-6" />}{isBotLoading ? 'Hledám v registru...' : 'OVĚŘIT STK ONLINE DLE VIN'}</button>
                    </div>
                  )}
                </div>
              </div>

              {/* TECHNICAL DATA */}
              <div className="space-y-6">
                <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.3em] border-b border-slate-100 pb-3 flex items-center gap-3"><Layers className="w-4 h-4" /> Technické údaje</h4>
                <div className="grid grid-cols-1 gap-4">
                   <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">VIN kód</span><span className="text-base font-mono font-black text-slate-900 break-all uppercase tracking-wider">{selectedVehicle.vin?.toUpperCase() || 'Neuvedeno'}</span></div>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">Nájezd</span><span className="text-xl font-black text-slate-900">{(selectedVehicle.mileage || 0).toLocaleString()} km</span></div>
                      <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">Kód motoru</span><span className="text-xl font-black text-slate-900 uppercase">{selectedVehicle.engineCode?.toUpperCase() || 'Neuvedeno'}</span></div>
                   </div>
                </div>
              </div>

              {/* SERVICE INTERVALS - RESTORED CARDS */}
              <div className="space-y-6">
                <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.3em] border-b border-slate-100 pb-3 flex items-center gap-3"><Timer className="w-4 h-4" /> Servisní intervaly</h4>
                <div className="grid grid-cols-1 gap-4">
                  {[
                    { label: 'Brzdová kapalina', date: selectedVehicle.brakeFluidDate, interval: selectedVehicle.brakeFluidInterval, icon: Droplets, color: 'text-blue-500', bg: 'bg-blue-50/30' },
                    { label: 'Chladicí kapalina', date: selectedVehicle.coolantDate, interval: selectedVehicle.coolantInterval, icon: Droplets, color: 'text-emerald-500', bg: 'bg-emerald-50/30' },
                    { label: 'Olej převodovky', date: selectedVehicle.gearboxOilDate, interval: selectedVehicle.gearboxOilInterval, icon: Droplets, color: 'text-amber-600', bg: 'bg-amber-50/30' },
                    { label: 'Rozvody motoru', date: selectedVehicle.timingBeltDate, interval: selectedVehicle.timingBeltInterval, icon: Settings2, color: 'text-red-500', bg: 'bg-red-50/30' },
                    { label: 'Klimatizace', date: selectedVehicle.refrigerantDate, interval: selectedVehicle.refrigerantInterval, icon: Wind, color: 'text-cyan-500', bg: 'bg-cyan-50/30' },
                  ].map((item, idx) => {
                    const nextDate = calculateNextDate(item.date, item.interval);
                    const isOverdue = nextDate && nextDate < new Date();
                    return (
                      <div key={idx} className={`rounded-[2rem] p-6 border transition-all ${isOverdue ? 'bg-red-50 border-red-200 animate-pulse' : 'bg-slate-50 border-slate-100'}`}>
                        <div className="flex justify-between items-center mb-4">
                          <span className={`text-[11px] font-black uppercase flex items-center gap-2 ${isOverdue ? 'text-red-600' : item.color}`}><item.icon className="w-4 h-4" /> {item.label}</span>
                          <span className="text-[10px] font-bold text-slate-400">Int: {item.interval} m.</span>
                        </div>
                        <div className="flex justify-between items-end">
                           <div><p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Naposledy</p><p className="text-sm font-black">{formatDate(item.date)}</p></div>
                           <div className="text-right"><p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Doporučená výměna</p><p className={`text-lg font-black ${isOverdue ? 'text-red-600' : (nextDate ? 'text-emerald-600' : 'text-slate-300')}`}>{nextDate ? nextDate.toLocaleDateString('cs-CZ') : '---'}</p></div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* ATTACHMENTS - RESTORED LIST */}
              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                  <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.3em] flex items-center gap-3"><Paperclip className="w-4 h-4" /> Přílohy</h4>
                  <button onClick={() => fileInputRef.current?.click()} className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 transition-all text-[10px] font-black uppercase tracking-widest flex items-center gap-2"><FilePlus className="w-4 h-4" /> Přidat</button>
                  <input type="file" className="hidden" ref={fileInputRef} onChange={handleFileUpload} accept="image/*,.pdf" />
                </div>
                <div className="space-y-3">
                  {selectedVehicle.attachments?.length ? selectedVehicle.attachments.map(att => (
                    <div key={att.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl group border border-transparent hover:border-slate-200 transition-all">
                      <div className="flex items-center gap-4 min-w-0">
                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${att.type.includes('pdf') ? 'bg-red-50 text-red-500' : 'bg-blue-50 text-blue-500'}`}>{att.type.includes('pdf') ? <FileText className="w-6 h-6" /> : <ImageIcon className="w-6 h-6" />}</div>
                        <div className="min-w-0"><p className="text-sm font-black text-slate-900 truncate pr-4">{att.name}</p><p className="text-[10px] font-bold text-slate-400 uppercase">{(att.size / 1024).toFixed(1)} KB</p></div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button className="p-3 text-slate-400 hover:text-blue-600 transition-colors"><Eye className="w-5 h-5" /></button>
                        <button onClick={() => {}} className="p-3 text-slate-400 hover:text-red-600 transition-colors"><Trash2 className="w-5 h-5" /></button>
                      </div>
                    </div>
                  )) : <div className="py-12 text-center bg-slate-50/50 rounded-3xl border-2 border-dashed border-slate-200"><p className="text-xs font-bold text-slate-400 italic">Žádné nahrané dokumenty.</p></div>}
                </div>
              </div>
            </div>

            <div className="p-10 border-t border-slate-50 bg-white shrink-0"><button onClick={() => setSelectedVehicleId(null)} className="w-full bg-slate-900 text-white font-black py-5 rounded-[2rem] transition-all hover:bg-slate-800 shadow-2xl">ZAVŘÍT KARTU</button></div>
          </div>
        </div>
      )}

      {/* RE-ADDING MISSING MODALS LIKE ADD/EDIT, DELETE CONFIRMATION ETC... */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
