/**
 * RSV Service - Propojení s Registrem silničních vozidel (api.dataovozidlech.cz)
 */

export interface RsvVehicleData {
  TovarniZnacka: string;
  ObchodniOznaceni: string;
  MotorTyp: string;
  VozidloKaroserieBarva: string;
  PravidelnaTechnickaProhlidkaDo: string; // ISO date string
  RokVyroby?: number;
}

export const fetchVehicleFromRsv = async (vin: string, apiKey: string): Promise<RsvVehicleData | null> => {
  if (!apiKey) throw new Error("Chybí RSV API klíč v nastavení systému.");

  const url = `https://api.dataovozidlech.cz/api/vehicletechnicaldata/v2?vin=${vin.trim().toUpperCase()}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'API_KEY': apiKey,
        'Accept': 'application/json'
      }
    });

    if (!response.ok) {
      if (response.status === 401) throw new Error("Neplatný RSV API klíč.");
      if (response.status === 429) throw new Error("Překročen limit dotazů na API RSV.");
      throw new Error(`Chyba API RSV: ${response.statusText}`);
    }

    const json = await response.json();

    if (json.Status === 1 && json.Data) {
      return json.Data as RsvVehicleData;
    }

    return null;
  } catch (error) {
    console.error("RSV Fetch Error:", error);
    throw error;
  }
};

