    xml += xmlTag('Address', companyInfo?.address);
    xml += xmlTag('ICO', companyInfo?.ico);
    xml += xmlTag('DIC', companyInfo?.dic);
    xml += xmlTag('Phone', companyInfo?.phone);
    xml += xmlTag('Email', companyInfo?.email);
    xml += xmlTag('BankAccount', companyInfo?.bankAccount);
    xml += xmlTag('FoundationDate', companyInfo?.foundationDate);
    xml += xmlTag('IsVatPayer', !!companyInfo?.isVatPayer);
    xml += xmlTag('RsvApiKey', companyInfo?.rsvApiKey);
    xml += `  </CompanyInfo>\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${esc(c.id)}">\n`;
      xml += xmlTag('CustomerType', c.customerType);
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      if (c.companyAddress) xml += xmlTag('CompanyAddress', c.companyAddress);
      if (c.contactPerson) xml += xmlTag('ContactPerson', c.contactPerson);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${esc(v.id)}" customerId="${esc(v.customerId)}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += xmlTag('ServiceIntervalKm', v.serviceIntervalKm);
      xml += xmlTag('ServiceIntervalMonths', v.serviceIntervalMonths);
      xml += xmlTag('Notes', v.notes);

      xml += xmlTag('BrakeFluidDate', v.brakeFluidDate);
      xml += xmlTag('CoolantDate', v.coolantDate);
      xml += xmlTag('GearboxOilDate', v.gearboxOilDate);
      xml += xmlTag('TimingBeltDate', v.timingBeltDate);
      xml += xmlTag('RefrigerantDate', v.refrigerantDate);
      xml += xmlTag('BrakeFluidInterval', v.brakeFluidInterval);
      xml += xmlTag('CoolantInterval', v.coolantInterval);
      xml += xmlTag('GearboxOilInterval', v.gearboxOilInterval);
      xml += xmlTag('TimingBeltInterval', v.timingBeltInterval);
      xml += xmlTag('RefrigerantInterval', v.refrigerantInterval);

      if (v.attachments && v.attachments.length > 0) {
        xml += `      <Attachments>\n`;
        v.attachments.forEach(att => {
          xml += `        <Attachment id="${esc(att.id)}">\n`;
          xml += xmlTag('Name', att.name, '          ');
          xml += xmlTag('Type', att.type, '          ');
          xml += xmlTag('Data', att.data, '          ');
          xml += xmlTag('Size', att.size, '          ');
          xml += `        </Attachment>\n`;
        });
        xml += `      </Attachments>\n`;
      }
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${esc(s.id)}" vehicleId="${esc(s.vehicleId)}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      xml += xmlTag('MileageAtEntry', s.mileageAtEntry);
      xml += xmlTag('DeliveryDate', s.deliveryDate);
      xml += xmlTag('FuelLevel', s.fuelLevel);
      xml += xmlTag('ReturnParts', s.returnParts);

      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${esc(p.id)}">\n`;
          xml += xmlTag('Description', p.description, '          ');
          xml += xmlTag('Quantity', p.quantity, '          ');
          xml += xmlTag('UnitPrice', p.unitPrice, '          ');
          xml += xmlTag('CostPrice', p.costPrice, '          ');
          xml += xmlTag('Unit', p.unit, '          ');
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }

      if (s.checklist) {
        xml += `      <Checklist>\n`;
        Object.entries(s.checklist).forEach(([key, val]) => {
          xml += `        <${key}>${val}</${key}>\n`;
        });
        xml += `      </Checklist>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${esc(inv.id)}" orderId="${esc(inv.orderId)}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalExclDph', inv.totalExclDph);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Costs', inv.costs || 0);
      xml += xmlTag('Status', inv.status);
