        });
        xml += `      </InvoiceItems>\n`;
      }
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);

    xml += `    <Technicians>\n`;
