            gearboxOilInterval: num(node, "GearboxOilInterval") || 60,
            timingBeltInterval: num(node, "TimingBeltInterval") || 120,
            refrigerantInterval: num(node, "RefrigerantInterval") || 24,
            attachments: Array.from(node.querySelectorAll("Attachment")).map(att => ({
              id: att.getAttribute("id") || `att-${Math.random().toString(36).substr(2, 9)}`,
              name: txt(att, "Name"),
              type: txt(att, "Type"),
              data: txt(att, "Data"),
              size: num(att, "Size")
            }))
          })),
          services: Array.from(xmlDoc.querySelectorAll("ServiceRecord")).map(node => {
            const checklist: any = {};
            const checklistNode = node.querySelector("Checklist");
            if (checklistNode) {
              Array.from(checklistNode.children).forEach(child => {
                checklist[child.tagName] = child.textContent === 'true';
