  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const sanitizedData = { ...formData, licensePlate: (formData.licensePlate || '').trim().toUpperCase(), vin: (formData.vin || '').trim().toUpperCase() };
    if (editingVehicle) onUpdateVehicle({ ...editingVehicle, ...sanitizedData } as Vehicle);
    else onAddVehicle({ ...sanitizedData, id: `v${Date.now()}` } as Vehicle);
    setIsModalOpen(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files; if (!files || !selectedVehicle) return;
    const file = files[0]; const reader = new FileReader();
    reader.onloadend = () => {
      const newAttachment: VehicleAttachment = { id: `att-${Date.now()}`, name: file.name, type: file.type, data: reader.result as string, size: file.size };
      onUpdateVehicle({ ...selectedVehicle, attachments: [...(selectedVehicle.attachments || []), newAttachment] });
    };
    reader.readAsDataURL(file); e.target.value = '';
  };

  // RSV SYNC LOGIC
  const handleRsvSync = async () => {
    if (!selectedVehicle || !selectedVehicle.vin) return;
    if (!companyInfo.rsvApiKey) {
      alert("Pro tuto funkci musíte v Nastavení -> Moje Firma vyplnit RSV API Klíč.");
      return;
    }

    setIsRsvLoading(true);
    setRsvDiffs([]);

    try {
      const data = await fetchVehicleFromRsv(selectedVehicle.vin, companyInfo.rsvApiKey, companyInfo.rsvProxyUrl);
      if (!data) {
        alert("Vozidlo s tímto VIN nebylo v registru nalezeno.");
        setIsRsvLoading(false);
        return;
      }

      setRsvSourceData(data);

      const diffs: any[] = [];
      const newStk = data.PravidelnaTechnickaProhlidkaDo?.split('T')[0] || '';

      // Porovnání polí
      if (data.TovarniZnacka && data.TovarniZnacka !== selectedVehicle.make.toUpperCase()) {
        diffs.push({ field: 'make', label: 'Značka', oldVal: selectedVehicle.make, newVal: data.TovarniZnacka });
      }
      if (data.ObchodniOznaceni && data.ObchodniOznaceni !== selectedVehicle.model.toUpperCase()) {
        diffs.push({ field: 'model', label: 'Model', oldVal: selectedVehicle.model, newVal: data.ObchodniOznaceni });
      }
      if (data.MotorTyp && data.MotorTyp !== selectedVehicle.engineCode.toUpperCase()) {
        diffs.push({ field: 'engineCode', label: 'Kód motoru', oldVal: selectedVehicle.engineCode, newVal: data.MotorTyp });
      }
      if (data.VozidloKaroserieBarva && data.VozidloKaroserieBarva !== selectedVehicle.color.toUpperCase()) {
        diffs.push({ field: 'color', label: 'Barva', oldVal: selectedVehicle.color, newVal: data.VozidloKaroserieBarva });
      }
      if (newStk && newStk !== selectedVehicle.stkExpirationDate) {
        diffs.push({ field: 'stkExpirationDate', label: 'STK Platnost', oldVal: selectedVehicle.stkExpirationDate, newVal: newStk });
      }

      if (diffs.length === 0) {
        alert("Data v kartě vozidla jsou aktuální a shodují se s registrem RSV.");
      } else {
        setRsvDiffs(diffs);
      }
    } catch (err: any) {
      alert(err.message || "Při komunikaci s registrem RSV došlo k neočekávané chybě.");
    } finally {
      setIsRsvLoading(false);
    }
  };

  const applyRsvChanges = () => {
    if (!selectedVehicle || !rsvSourceData) return;

    const updatedVehicle = { ...selectedVehicle };
    rsvDiffs.forEach(diff => {
      (updatedVehicle as any)[diff.field] = diff.newVal;
    });

    onUpdateVehicle(updatedVehicle);
    setRsvDiffs([]);
    setRsvSourceData(null);
  };

  const vehicleServices = useMemo(() => historyVehicleId ? services.filter(s => s.vehicleId === historyVehicleId).sort((a, b) => (b.date || "").localeCompare(a.date || "")) : [], [historyVehicleId, services]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tight">Vozidla</h2>
          <p className="text-slate-500 font-medium">Evidence vozového parku a servisních intervalů.</p>
        </div>
        <button onClick={handleAddNew} className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg"><Plus className="w-5 h-5" />Nové vozidlo</button>
      </div>

      <div className="space-y-4">
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <Search className="w-5 h-5 text-slate-400" />
          <input type="text" placeholder="Hledat podle SPZ, značky, modelu, VIN nebo jména majitele..." className="flex-1 text-sm font-medium outline-none bg-transparent" value={search} onChange={(e) => onSearchChange(e.target.value)} />
          {search && <button onClick={() => onSearchChange('')} className="text-blue-600 font-bold text-xs px-3 py-1 hover:bg-blue-50 rounded-lg transition-all">Zrušit filtr</button>}
        </div>

        <div className="flex items-center gap-2 overflow-x-auto pb-2 px-1 custom-scrollbar-h">
          <div className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 flex items-center gap-2 shrink-0"><Type className="w-4 h-4 text-slate-400" /><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mr-2">Značka:</span></div>
          <button onClick={() => setSelectedLetter(null)} className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${!selectedLetter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>VŠE</button>
          {alphabet.map(letter => <button key={letter} onClick={() => setSelectedLetter(selectedLetter === letter ? null : letter)} className={`px-4 py-2 rounded-xl text-xs font-black transition-all shrink-0 ${selectedLetter === letter ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>{letter}</button>)}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredVehicles.map(v => {
          const isOverdue = checkVehicleOverdueStatus(v);
          return (
            <div key={v.id} className={`bg-white rounded-[2.5rem] border ${isOverdue ? 'border-red-200 bg-red-50/5' : 'border-slate-100'} p-8 shadow-sm hover:shadow-xl transition-all group relative overflow-visible`}>
              {isOverdue && <div className="absolute -top-2 -left-2 z-10 animate-bounce"><div className="bg-red-600 text-white p-2 rounded-full shadow-lg border-2 border-white"><AlertTriangle className="w-5 h-5 stroke-[3]" /></div></div>}
              <div className="absolute top-0 right-0 p-6">
                <div className="relative">
                  <button onClick={() => setOpenMenuId(openMenuId === v.id ? null : v.id)} className={`p-2 rounded-xl transition-all ${openMenuId === v.id ? 'bg-slate-100 text-slate-900' : 'text-slate-300 hover:text-slate-900'}`}><MoreHorizontal className="w-5 h-5" /></button>
                  {openMenuId === v.id && (
                    <div ref={menuRef} className="absolute top-12 right-0 w-52 bg-white rounded-2xl shadow-2xl border border-slate-100 p-2 z-[60] animate-in fade-in zoom-in-95 duration-200">
                      <button onClick={() => handleEdit(v)} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-50 text-slate-700 transition-colors text-sm font-bold"><Edit3 className="w-4 h-4 text-slate-400" />Upravit vozidlo</button>
                      <button onClick={() => { onCreateOrder(v.id); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-blue-50 text-blue-600 transition-colors text-sm font-bold"><ClipboardPlus className="w-4 h-4 text-blue-400" />Vytvořit zakázku</button>
                      <div className="h-px bg-slate-100 my-1 mx-2"></div>
                      <button onClick={() => { setDeletingVehicle(v); setOpenMenuId(null); }} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 transition-colors text-sm font-bold"><Trash2 className="w-4 h-4" />Smazat vozidlo</button>
                    </div>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-6 mb-6">
                <div className={`w-20 h-20 rounded-3xl ${isOverdue ? 'bg-red-500 shadow-red-200' : 'bg-slate-900 shadow-slate-200'} flex items-center justify-center text-white font-black text-xl shadow-xl transition-transform group-hover:scale-105`}><Car className="w-10 h-10" /></div>
                <div className="min-w-0 pr-8">
                  <h3 className="text-xl font-black text-slate-900 leading-tight truncate">{v.make} {v.model}</h3>
                  <div className="flex items-center gap-2 mt-1.5">
                    <p className="text-sm font-black text-blue-600 font-mono tracking-widest uppercase">{v.licensePlate?.toUpperCase()}</p>
                    {isOverdue && <span className="text-[10px] font-black text-red-600 px-2 py-0.5 bg-red-50 rounded-lg uppercase tracking-tighter">Prošlý servis</span>}
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3 mt-8">
                <button onClick={() => setSelectedVehicleId(v.id)} className="py-4 bg-slate-100 text-slate-900 rounded-2xl font-black text-xs hover:bg-slate-200 transition-colors uppercase tracking-wider">Detail karty</button>
                <button onClick={() => setHistoryVehicleId(v.id)} className="py-4 bg-blue-50 text-blue-600 rounded-2xl font-black text-xs hover:bg-blue-100 transition-colors uppercase tracking-wider flex items-center justify-center gap-2"><HistoryIcon className="w-4 h-4" />Historie</button>
              </div>
            </div>
          );
        })}
      </div>

      {selectedVehicle && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setSelectedVehicleId(null)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 p-10 text-white flex justify-between items-center shrink-0">
              <div className="flex items-center gap-6">
                <div className="w-16 h-16 rounded-2xl bg-slate-800 flex items-center justify-center font-black shadow-inner"><Car className="w-8 h-8" /></div>
                <div>
                  <h3 className="text-3xl font-black tracking-tighter">{selectedVehicle.make} {selectedVehicle.model}</h3>
                  <p className="text-slate-400 text-sm font-black uppercase tracking-[0.2em] mt-1">{selectedVehicle.licensePlate?.toUpperCase()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedVehicleId(null)} className="p-3 hover:bg-white/10 rounded-2xl transition-colors"><X className="w-8 h-8" /></button>
            </div>

            <div className="p-10 space-y-10 overflow-y-auto custom-scrollbar bg-white">
              {/* RSV BOT SECTION - REAL API INTEGRATION */}
              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden border border-white/5">
                <div className="absolute top-0 right-0 p-6 opacity-10"><SearchCode className="w-24 h-24" /></div>
                <div className="relative z-10">
                  <div className="flex items-center gap-3 mb-6">
                    <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center shadow-lg shadow-blue-900/40"><RefreshCcw className="w-6 h-6" /></div>
                    <h4 className="text-base font-black uppercase tracking-widest">AKTUALIZACE Z REGISTRU (RSV)</h4>
                  </div>

                  {rsvDiffs.length > 0 ? (
                    <div className="space-y-6 animate-in fade-in zoom-in-95 duration-300">
                      <div className="bg-white/5 rounded-3xl border border-white/10 overflow-hidden">
                        <table className="w-full text-left">
                          <thead>
                            <tr className="bg-white/5 text-[9px] font-black uppercase text-slate-400 tracking-widest">
                              <th className="px-5 py-3">Údaj</th>
                              <th className="px-5 py-3">Původní</th>
                              <th className="px-5 py-3">Registr (Nové)</th>
                            </tr>
                          </thead>
                          <tbody className="text-xs font-bold divide-y divide-white/5">
                            {rsvDiffs.map((diff, i) => (
                              <tr key={i}>
                                <td className="px-5 py-4 text-slate-400 uppercase text-[10px]">{diff.label}</td>
                                <td className="px-5 py-4 line-through opacity-40">{diff.field === 'stkExpirationDate' ? formatDate(diff.oldVal) : diff.oldVal || '---'}</td>
                                <td className="px-5 py-4 text-blue-400">{diff.field === 'stkExpirationDate' ? formatDate(diff.newVal) : diff.newVal}</td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>

                      <div className="flex gap-4">
                        <button 
                          onClick={() => setRsvDiffs([])}
                          className="flex-1 py-4 bg-white/5 hover:bg-white/10 rounded-2xl font-black text-xs uppercase transition-all"
                        >
                          Zrušit
                        </button>
                        <button 
                          onClick={applyRsvChanges}
                          className="flex-[2] py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-xs uppercase shadow-xl transition-all flex items-center justify-center gap-2"
                        >
                          <Check className="w-5 h-5" /> AKTUALIZOVAT KARTU
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div className="flex flex-col gap-6">
                      <p className="text-sm font-medium text-slate-400 leading-relaxed">
                        Bot se připojí k databázi <b>dataovozidlech.cz</b> přes API a porovná technická data vašeho vozidla s úředním registrem.
                      </p>
                      <button 
                        onClick={handleRsvSync} 
                        disabled={isRsvLoading || !selectedVehicle.vin} 
                        className="flex items-center justify-center gap-4 w-full py-5 bg-white/10 hover:bg-white/20 disabled:opacity-50 disabled:cursor-not-allowed rounded-2xl transition-all border border-white/5 font-black text-sm uppercase"
                      >
                        {isRsvLoading ? <Loader2 className="w-6 h-6 animate-spin text-blue-400" /> : <SearchCode className="w-6 h-6" />}
                        {isRsvLoading ? 'PŘIPOJOVÁNÍ K REGISTRU...' : 'AKTUALIZOVAT DATA DLE VIN'}
                      </button>
                      {!companyInfo.rsvApiKey && (
                        <div className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-xl flex items-center gap-3">
                           <AlertCircle className="w-5 h-5 text-amber-500 shrink-0" />
                           <p className="text-[10px] font-bold text-amber-400 uppercase tracking-tight">V nastavení chybí RSV API Klíč!</p>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>

              {/* TECHNICAL DATA */}
              <div className="space-y-6">
                <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.3em] border-b border-slate-100 pb-3 flex items-center gap-3"><Layers className="w-4 h-4" /> Technické údaje</h4>
                <div className="grid grid-cols-1 gap-4">
                   <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">VIN kód</span><span className="text-base font-mono font-black text-slate-900 break-all uppercase tracking-wider">{selectedVehicle.vin?.toUpperCase() || 'Neuvedeno'}</span></div>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">Značka</span><span className="text-xl font-black text-slate-900 uppercase">{selectedVehicle.make}</span></div>
                      <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">Model</span><span className="text-xl font-black text-slate-900 uppercase">{selectedVehicle.model}</span></div>
                   </div>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">Nájezd</span><span className="text-xl font-black text-slate-900">{(selectedVehicle.mileage || 0).toLocaleString()} km</span></div>
                      <div className="flex flex-col p-5 bg-slate-50 rounded-3xl border border-slate-100"><span className="text-[10px] font-black text-slate-400 uppercase mb-1">Kód motoru</span><span className="text-xl font-black text-slate-900 uppercase">{selectedVehicle.engineCode?.toUpperCase() || 'Neuvedeno'}</span></div>
                   </div>
                </div>
              </div>

              {/* SERVICE INTERVALS */}
              <div className="space-y-6">
                <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.3em] border-b border-slate-100 pb-3 flex items-center gap-3"><Timer className="w-4 h-4" /> Servisní intervaly</h4>
                <div className="grid grid-cols-1 gap-4">
                  <div className={`rounded-[2rem] p-6 border transition-all ${
                    (selectedVehicle.stkExpirationDate && new Date(selectedVehicle.stkExpirationDate) < new Date()) ? 'bg-red-50 border-red-200 animate-pulse' : 'bg-slate-50 border-slate-100'
                  }`}>
                    <div className="flex justify-between items-center mb-4">
                      <span className={`text-[11px] font-black uppercase flex items-center gap-2 ${(selectedVehicle.stkExpirationDate && new Date(selectedVehicle.stkExpirationDate) < new Date()) ? 'text-red-600' : 'text-blue-600'}`}>
                        <ShieldCheck className="w-4 h-4" /> Technická kontrola (STK)
                      </span>
                    </div>
                    <div className="flex justify-between items-end">
                       <div><p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Stav v databázi</p><p className="text-sm font-black">{formatDate(selectedVehicle.stkExpirationDate)}</p></div>
                       <div className="text-right">
                          <p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Platnost do</p>
                          <p className={`text-lg font-black ${(selectedVehicle.stkExpirationDate && new Date(selectedVehicle.stkExpirationDate) < new Date()) ? 'text-red-600' : 'text-emerald-600'}`}>
                            {selectedVehicle.stkExpirationDate ? new Date(selectedVehicle.stkExpirationDate).toLocaleDateString('cs-CZ') : '---'}
                          </p>
                       </div>
                    </div>
                  </div>

                  {[
                    { label: 'Brzdová kapalina', date: selectedVehicle.brakeFluidDate, interval: selectedVehicle.brakeFluidInterval, icon: Droplets, color: 'text-blue-500' },
                    { label: 'Chladicí kapalina', date: selectedVehicle.coolantDate, interval: selectedVehicle.coolantInterval, icon: Droplets, color: 'text-emerald-500' },
                    { label: 'Olej převodovky', date: selectedVehicle.gearboxOilDate, interval: selectedVehicle.gearboxOilInterval, icon: Droplets, color: 'text-amber-600' },
                    { label: 'Rozvody motoru', date: selectedVehicle.timingBeltDate, interval: selectedVehicle.timingBeltInterval, icon: Settings2, color: 'text-red-500' },
                    { label: 'Klimatizace', date: selectedVehicle.refrigerantDate, interval: selectedVehicle.refrigerantInterval, icon: Wind, color: 'text-cyan-500' },
                  ].map((item, idx) => {
                    const nextDate = calculateNextDate(item.date, item.interval);
                    const isOverdue = nextDate && nextDate < new Date();
                    return (
                      <div key={idx} className={`rounded-[2rem] p-6 border transition-all ${isOverdue ? 'bg-red-50 border-red-200 animate-pulse' : 'bg-slate-50 border-slate-100'}`}>
                        <div className="flex justify-between items-center mb-4">
                          <span className={`text-[11px] font-black uppercase flex items-center gap-2 ${isOverdue ? 'text-red-600' : item.color}`}><item.icon className="w-4 h-4" /> {item.label}</span>
                          <span className="text-[10px] font-bold text-slate-400">Int: {item.interval} m.</span>
                        </div>
                        <div className="flex justify-between items-end">
                           <div><p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Naposledy</p><p className="text-sm font-black">{formatDate(item.date)}</p></div>
                           <div className="text-right"><p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Doporučená výměna</p><p className={`text-lg font-black ${isOverdue ? 'text-red-600' : (nextDate ? 'text-emerald-600' : 'text-slate-300')}`}>{nextDate ? nextDate.toLocaleDateString('cs-CZ') : '---'}</p></div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* ATTACHMENTS */}
              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                  <h4 className="text-xs font-black text-blue-600 uppercase tracking-[0.3em] flex items-center gap-3"><Paperclip className="w-4 h-4" /> Přílohy</h4>
                  <button onClick={() => fileInputRef.current?.click()} className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 transition-all text-[10px] font-black uppercase tracking-widest flex items-center gap-2"><FilePlus className="w-4 h-4" /> Přidat</button>
                  <input type="file" className="hidden" ref={fileInputRef} onChange={handleFileUpload} accept="image/*,.pdf" />
                </div>
                <div className="space-y-3">
                  {selectedVehicle.attachments?.length ? selectedVehicle.attachments.map(att => (
                    <div key={att.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl group border border-transparent hover:border-slate-200 transition-all">
                      <div className="flex items-center gap-4 min-w-0">
                        <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${att.type.includes('pdf') ? 'bg-red-50 text-red-500' : 'bg-blue-50 text-blue-500'}`}>{att.type.includes('pdf') ? <FileText className="w-6 h-6" /> : <ImageIcon className="w-6 h-6" />}</div>
                        <div className="min-w-0"><p className="text-sm font-black text-slate-900 truncate pr-4">{att.name}</p><p className="text-[10px] font-bold text-slate-400 uppercase">{(att.size / 1024).toFixed(1)} KB</p></div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button className="p-3 text-slate-400 hover:text-blue-600 transition-colors"><Eye className="w-5 h-5" /></button>
                        <button onClick={() => {}} className="p-3 text-slate-400 hover:text-red-600 transition-colors"><Trash2 className="w-5 h-5" /></button>
                      </div>
                    </div>
                  )) : <div className="py-12 text-center bg-slate-50/50 rounded-3xl border-2 border-dashed border-slate-200"><p className="text-xs font-bold text-slate-400 italic">Žádné nahrané dokumenty.</p></div>}
                </div>
              </div>
            </div>

            <div className="p-10 border-t border-slate-50 bg-white shrink-0"><button onClick={() => setSelectedVehicleId(null)} className="w-full bg-slate-900 text-white font-black py-5 rounded-[2rem] transition-all hover:bg-slate-800 shadow-2xl">ZAVŘÍT KARTU</button></div>
          </div>
        </div>
      )}

      {/* MODALS (ADD/EDIT, DELETE) */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300 flex flex-col max-h-[90vh]">
            <div className="bg-slate-900 p-8 text-white flex justify-between items-center shrink-0">
              <h3 className="text-2xl font-black tracking-tight">{editingVehicle ? 'Upravit vozidlo' : 'Nové vozidlo'}</h3>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/10 rounded-xl transition-colors"><X className="w-6 h-6" /></button>
            </div>
            <div className="flex border-b border-slate-100 bg-slate-50">
               <button onClick={() => setActiveTab('basic')} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'basic' ? 'border-b-4 border-blue-600 text-blue-600 bg-white' : 'text-slate-400 hover:text-slate-600'}`}>Základní údaje</button>
               <button onClick={() => setActiveTab('intervals')} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'intervals' ? 'border-b-4 border-blue-600 text-blue-600 bg-white' : 'text-slate-400 hover:text-slate-600'}`}>Intervaly</button>
            </div>
            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-10 space-y-8 custom-scrollbar">
              {activeTab === 'basic' ? (
                <div className="space-y-6">
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Značka</label><input type="text" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-bold" value={formData.make} onChange={e => setFormData({...formData, make: e.target.value})} /></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Model</label><input type="text" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-bold" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} /></div>
                  </div>
                  <div className="grid grid-cols-3 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Rok výroby</label><input type="number" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-bold" value={formData.year} onChange={e => setFormData({...formData, year: parseInt(e.target.value) || 0})} /></div>
                    <div className="space-y-2 col-span-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">SPZ / RZ</label><input required type="text" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-bold uppercase tracking-widest" value={formData.licensePlate || ''} onChange={e => setFormData({...formData, licensePlate: e.target.value.toUpperCase()})} /></div>
                  </div>
                  <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">VIN kód</label><input type="text" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-black uppercase font-mono tracking-widest" value={formData.vin || ''} onChange={e => setFormData({...formData, vin: e.target.value.toUpperCase()})} /></div>
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">STK do</label><input type="date" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-bold" value={formData.stkExpirationDate || ''} onChange={e => setFormData({...formData, stkExpirationDate: e.target.value})} /></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Najeto (km)</label><input type="number" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-bold" value={formData.mileage || 0} onChange={e => setFormData({...formData, mileage: parseInt(e.target.value) || 0})} /></div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Kód motoru</label>
                    <input type="text" className="w-full bg-slate-50 border-none rounded-2xl px-6 py-4 outline-none font-bold uppercase" value={formData.engineCode || ''} onChange={e => setFormData({...formData, engineCode: e.target.value})} />
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                   {[
                    { label: 'Brzdová kapalina', date: 'brakeFluidDate', interval: 'brakeFluidInterval' },
                    { label: 'Chladicí kapalina', date: 'coolantDate', interval: 'coolantInterval' },
                    { label: 'Olej převodovky', date: 'gearboxOilDate', interval: 'gearboxOilInterval' },
                    { label: 'Rozvody motoru', date: 'timingBeltDate', interval: 'timingBeltInterval' },
                    { label: 'Klimatizace', date: 'refrigerantDate', interval: 'refrigerantInterval' },
                  ].map(item => (
                    <div key={item.date} className="grid grid-cols-2 gap-6 p-6 bg-slate-50 rounded-3xl">
                       <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{item.label}</label><input type="date" className="w-full bg-white border-none rounded-xl px-4 py-2 font-bold text-xs" value={(formData as any)[item.date] || ''} onChange={e => setFormData({...formData, [item.date]: e.target.value})} /></div>
                       <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Interval (měsíce)</label><input type="number" className="w-full bg-white border-none rounded-xl px-4 py-2 font-bold text-xs" value={(formData as any)[item.interval] || 0} onChange={e => setFormData({...formData, [item.interval]: parseInt(e.target.value)})} /></div>
                    </div>
                  ))}
                </div>
              )}
              <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-2xl shadow-xl transition-all flex items-center justify-center gap-3"><Check className="w-6 h-6" /> {editingVehicle ? 'ULOŽIT ZMĚNY' : 'REGISTROVAT VOZIDLO'}</button>
            </form>
          </div>
        </div>
      )}

      {deletingVehicle && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDeletingVehicle(null)}></div>
          <div className="bg-white w-full max-w-md rounded-[3rem] p-10 text-center relative z-10 shadow-2xl">
             <AlertCircle className="w-16 h-16 text-red-500 mx-auto mb-6" />
             <h3 className="text-2xl font-black mb-2 tracking-tighter">Opravdu smazat?</h3>
             <p className="text-slate-500 mb-8 font-medium leading-relaxed">Vozidlo {deletingVehicle.make} {deletingVehicle.model} bude trvale odstraněno z databáze.</p>
             <div className="flex gap-4">
                <button onClick={() => setDeletingVehicle(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-black text-sm uppercase">Zrušit</button>
                <button onClick={() => { onDeleteVehicle(deletingVehicle.id); setDeletingVehicle(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-sm uppercase shadow-lg shadow-red-600/20">Smazat</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VehicleManager;

import React, { useState, useRef } from 'react';
import { 
  Building, Bell, Save, 
  DollarSign, Loader2,
  Plus, Trash2, Database, DownloadCloud, UploadCloud, CheckCircle2, AlertCircle, Check,
  Tag, User, Layout, Percent, X, FolderOpen, Clock, ShieldCheck, ShieldAlert, CreditCard,
  AlertOctagon, BarChart3, Coins, Wallet, Briefcase, Calendar, Key, UserPlus, Settings2,
  Wrench, AlertTriangle, Link as LinkIcon
} from 'lucide-react';
import { CompanyInfo, NotificationSettings, Customer, Vehicle, ServiceRecord, AutoBackupSettings, UserSettings, FixedService, PredefinedTask, PartItem, Invoice, VehicleAttachment, VehicleChecklist, StatsSettings, CostItem, CostCategory } from '../types';

interface SettingsProps {
  hourlyRate: number;
  onRateChange: (rate: number) => void;
  fixedServices: FixedService[];
  onFixedServicesChange: (services: FixedService[]) => void;
  predefinedTasks: PredefinedTask[];
  onPredefinedTasksChange: (tasks: PredefinedTask[]) => void;
  discountLevels: number[];
  onDiscountLevelsChange: (levels: number[]) => void;
  technicians: string[];
  onTechniciansChange: (techs: string[]) => void;
  companyInfo: CompanyInfo;
  onCompanyChange: (info: CompanyInfo) => void;
  notifSettings: NotificationSettings;
  onNotifSettingsChange: (settings: NotificationSettings) => void;
  statsSettings: StatsSettings;
  onStatsSettingsChange: (settings: StatsSettings) => void;
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  invoices: Invoice[];
  onRestoreData: (fullState: any) => void;
  onClearAllData: () => void;
  autoBackupSettings: AutoBackupSettings;
  onAutoBackupSettingsChange: (settings: AutoBackupSettings) => void;
  setDirectoryHandle: (handle: FileSystemDirectoryHandle | null) => void;
  directoryHandle: FileSystemDirectoryHandle | null;
  userSettings: UserSettings;
  onUserSettingsChange: (settings: UserSettings) => void;
  selectedPrinter: string;
  onPrinterChange: (printer: string) => void;
}

const UNITS = ['ks', 'litr', 'gram', 'kg', 'm', 'sada', 'úkon'];
const COST_CATEGORIES: CostCategory[] = ['energie', 'nájemné', 'spotřební zboží', 'mzdy', 'pojištění', 'marketing', 'ostatní'];

const Settings: React.FC<SettingsProps> = ({ 
  hourlyRate, onRateChange, fixedServices, onFixedServicesChange,
  predefinedTasks, onPredefinedTasksChange,
  discountLevels, onDiscountLevelsChange,
  technicians, onTechniciansChange,
  companyInfo, onCompanyChange, notifSettings, onNotifSettingsChange,
  statsSettings, onStatsSettingsChange,
  customers, vehicles, services, invoices, onRestoreData, onClearAllData,
  autoBackupSettings, onAutoBackupSettingsChange, setDirectoryHandle, directoryHandle,
  userSettings, onUserSettingsChange
}) => {
  const [activeTab, setActiveTab] = useState<'company' | 'invoicing' | 'notifications' | 'services' | 'backups' | 'team' | 'templates' | 'stats_config'>('company');
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [backupStatus, setBackupStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');

  const [newTechName, setNewTechName] = useState('');
  const [newDiscount, setNewDiscount] = useState<string>('');
  const [deletingFixedService, setDeletingFixedService] = useState<FixedService | null>(null);
  const [deletingTemplate, setDeletingTemplate] = useState<PredefinedTask | null>(null);
  const [isClearDataConfirmOpen, setIsClearDataConfirmOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSave = () => {
    setSaveStatus('saving');
    setTimeout(() => {
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 800);
  };

  const addCostItem = () => {
    const newItem: CostItem = {
      id: `cost-${Date.now()}`,
      name: '',
      amount: 0,
      category: 'ostatní',
      isRecurring: true
    };
    onStatsSettingsChange({
      ...statsSettings,
      costItems: [...(statsSettings.costItems || []), newItem]
    });
  };

  const updateCostItem = (id: string, field: keyof CostItem, value: any) => {
    onStatsSettingsChange({
      ...statsSettings,
      costItems: statsSettings.costItems.map(item => item.id === id ? { ...item, [field]: value } : item)
    });
  };

  const removeCostItem = (id: string) => {
    onStatsSettingsChange({
      ...statsSettings,
      costItems: statsSettings.costItems.filter(item => item.id !== id)
    });
  };

  const addDiscountLevel = () => {
    const val = parseInt(newDiscount);
    if (!isNaN(val) && !discountLevels.includes(val)) {
      onDiscountLevelsChange([...discountLevels, val].sort((a, b) => a - b));
      setNewDiscount('');
    }
  };

  const removeDiscountLevel = (val: number) => onDiscountLevelsChange(discountLevels.filter(d => d !== val));

  const addFixedService = () => onFixedServicesChange([...fixedServices, { id: `fs${Date.now()}`, name: '', price: 0, costPrice: 0, unit: 'ks' }]);
  const updateFixedService = (id: string, field: keyof FixedService, value: string | number) => onFixedServicesChange(fixedServices.map(fs => fs.id === id ? { ...fs, [field]: value } : fs));

  const addTemplate = () => onPredefinedTasksChange([...predefinedTasks, { id: `pt${Date.now()}`, label: '', description: '' }]);
  const updateTemplate = (id: string, field: keyof PredefinedTask, value: string) => onPredefinedTasksChange(predefinedTasks.map(pt => pt.id === id ? { ...pt, [field]: value } : pt));

  const addTechnician = () => {
    if (newTechName.trim()) {
      onTechniciansChange([...technicians, newTechName.trim()]);
      setNewTechName('');
    }
  };
  const removeTechnician = (name: string) => onTechniciansChange(technicians.filter(t => t !== name));

  // XML Helpers
  const esc = (str: any) => String(str || '').replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c] || c));
  const xmlTag = (name: string, value: any, indent: string = '    ') => `${indent}<${name}>${esc(value)}</${name}>\n`;

  const generateBackupXml = () => {
    const timestamp = new Date().toISOString();
    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n<AutoServiceBackup timestamp="${timestamp}" version="3.6">\n`;

    xml += `  <CompanyInfo>\n`;
    xml += xmlTag('Name', companyInfo?.name);
    xml += xmlTag('Address', companyInfo?.address);
    xml += xmlTag('ICO', companyInfo?.ico);
    xml += xmlTag('DIC', companyInfo?.dic);
    xml += xmlTag('Phone', companyInfo?.phone);
    xml += xmlTag('Email', companyInfo?.email);
    xml += xmlTag('BankAccount', companyInfo?.bankAccount);
    xml += xmlTag('FoundationDate', companyInfo?.foundationDate);
    xml += xmlTag('IsVatPayer', !!companyInfo?.isVatPayer);
    xml += xmlTag('RsvApiKey', companyInfo?.rsvApiKey);
    xml += xmlTag('RsvProxyUrl', companyInfo?.rsvProxyUrl);
    xml += `  </CompanyInfo>\n`;

    xml += `  <Customers>\n`;
    customers.forEach(c => {
      xml += `    <Customer id="${esc(c.id)}">\n`;
      xml += xmlTag('CustomerType', c.customerType);
      xml += xmlTag('FirstName', c.firstName);
      xml += xmlTag('LastName', c.lastName);
      xml += xmlTag('Email', c.email);
      xml += xmlTag('Phone', c.phone);
      xml += xmlTag('Address', c.address);
      xml += xmlTag('CreatedAt', c.createdAt);
      if (c.companyName) xml += xmlTag('CompanyName', c.companyName);
      if (c.ico) xml += xmlTag('ICO', c.ico);
      if (c.dic) xml += xmlTag('DIC', c.dic);
      if (c.companyAddress) xml += xmlTag('CompanyAddress', c.companyAddress);
      if (c.contactPerson) xml += xmlTag('ContactPerson', c.contactPerson);
      xml += `    </Customer>\n`;
    });
    xml += `  </Customers>\n`;

    xml += `  <Vehicles>\n`;
    vehicles.forEach(v => {
      xml += `    <Vehicle id="${esc(v.id)}" customerId="${esc(v.customerId)}">\n`;
      xml += xmlTag('Make', v.make);
      xml += xmlTag('Model', v.model);
      xml += xmlTag('Year', v.year);
      xml += xmlTag('VIN', v.vin);
      xml += xmlTag('LicensePlate', v.licensePlate);
      xml += xmlTag('Mileage', v.mileage);
      xml += xmlTag('EngineCode', v.engineCode);
      xml += xmlTag('Color', v.color);
      xml += xmlTag('STKExpirationDate', v.stkExpirationDate);
      xml += xmlTag('NextServiceDate', v.nextServiceDate);
      xml += xmlTag('Notes', v.notes);

      xml += xmlTag('BrakeFluidDate', v.brakeFluidDate);
      xml += xmlTag('CoolantDate', v.coolantDate);
      xml += xmlTag('GearboxOilDate', v.gearboxOilDate);
      xml += xmlTag('TimingBeltDate', v.timingBeltDate);
      xml += xmlTag('RefrigerantDate', v.refrigerantDate);
      xml += xmlTag('BrakeFluidInterval', v.brakeFluidInterval);
      xml += xmlTag('CoolantInterval', v.coolantInterval);
      xml += xmlTag('GearboxOilInterval', v.gearboxOilInterval);
      xml += xmlTag('TimingBeltInterval', v.timingBeltInterval);
      xml += xmlTag('RefrigerantInterval', v.refrigerantInterval);

      if (v.attachments && v.attachments.length > 0) {
        xml += `      <Attachments>\n`;
        v.attachments.forEach(att => {
          xml += `        <Attachment id="${esc(att.id)}">\n`;
          xml += xmlTag('Name', att.name, '          ');
          xml += xmlTag('Type', att.type, '          ');
          xml += xmlTag('Data', att.data, '          ');
          xml += xmlTag('Size', att.size, '          ');
          xml += `        </Attachment>\n`;
        });
        xml += `      </Attachments>\n`;
      }
      xml += `    </Vehicle>\n`;
    });
    xml += `  </Vehicles>\n`;

    xml += `  <Services>\n`;
    services.forEach(s => {
      xml += `    <ServiceRecord id="${esc(s.id)}" vehicleId="${esc(s.vehicleId)}">\n`;
      xml += xmlTag('Date', s.date);
      xml += xmlTag('Description', s.description);
      xml += xmlTag('Cost', s.cost);
      xml += xmlTag('Status', s.status);
      xml += xmlTag('Technician', s.technician);
      xml += xmlTag('LaborHours', s.laborHours);
      xml += xmlTag('MileageAtEntry', s.mileageAtEntry);
      xml += xmlTag('DeliveryDate', s.deliveryDate);
      xml += xmlTag('FuelLevel', s.fuelLevel);
      xml += xmlTag('ReturnParts', s.returnParts);

      if (s.parts && s.parts.length > 0) {
        xml += `      <Parts>\n`;
        s.parts.forEach(p => {
          xml += `        <Part id="${esc(p.id)}">\n`;
          xml += xmlTag('Description', p.description, '          ');
          xml += xmlTag('Quantity', p.quantity, '          ');
          xml += xmlTag('UnitPrice', p.unitPrice, '          ');
          xml += xmlTag('CostPrice', p.costPrice, '          ');
          xml += xmlTag('Unit', p.unit, '          ');
          xml += `        </Part>\n`;
        });
        xml += `      </Parts>\n`;
      }

      if (s.checklist) {
        xml += `      <Checklist>\n`;
        Object.entries(s.checklist).forEach(([key, val]) => {
          xml += `        <${key}>${val}</${key}>\n`;
        });
        xml += `      </Checklist>\n`;
      }
      xml += `    </ServiceRecord>\n`;
    });
    xml += `  </Services>\n`;

    xml += `  <Invoices>\n`;
    invoices.forEach(inv => {
      xml += `    <Invoice id="${esc(inv.id)}" orderId="${esc(inv.orderId)}">\n`;
      xml += xmlTag('IssueDate', inv.issueDate);
      xml += xmlTag('DueDate', inv.dueDate);
      xml += xmlTag('CustomerId', inv.customerId);
      xml += xmlTag('VehicleInfo', inv.vehicleInfo);
      xml += xmlTag('TotalExclDph', inv.totalExclDph);
      xml += xmlTag('TotalInclDph', inv.totalInclDph);
      xml += xmlTag('Costs', inv.costs || 0);
      xml += xmlTag('Status', inv.status);
      xml += xmlTag('PaymentType', inv.paymentType);
      xml += xmlTag('Discount', inv.discount || 0);
      xml += xmlTag('Archived', !!inv.archived);

      if (inv.items && inv.items.length > 0) {
        xml += `      <InvoiceItems>\n`;
        inv.items.forEach(item => {
          xml += `        <Item id="${esc(item.id)}">\n`;
          xml += xmlTag('Description', item.description, '          ');
          xml += xmlTag('Quantity', item.quantity, '          ');
          xml += xmlTag('UnitPrice', item.unitPrice, '          ');
          xml += xmlTag('Unit', item.unit || 'ks', '          ');
          xml += `        </Item>\n`;
        });
        xml += `      </InvoiceItems>\n`;
      }
      xml += `    </Invoice>\n`;
    });
    xml += `  </Invoices>\n`;

    xml += `  <Settings>\n`;
    xml += xmlTag('HourlyRate', hourlyRate);

    xml += `    <Technicians>\n`;
    technicians.forEach(t => xml += `      <Technician>${esc(t)}</Technician>\n`);
    xml += `    </Technicians>\n`;

    xml += `    <DiscountLevels>\n`;
    discountLevels.forEach(d => xml += `      <Level>${d}</Level>\n`);
    xml += `    </DiscountLevels>\n`;

    xml += `    <FixedServices>\n`;
    fixedServices.forEach(fs => {
      xml += `      <FixedService id="${esc(fs.id)}">\n`;
      xml += xmlTag('Name', fs.name, '        ');
      xml += xmlTag('Price', fs.price, '        ');
      xml += xmlTag('CostPrice', fs.costPrice, '        ');
      xml += xmlTag('Unit', fs.unit, '        ');
      xml += `      </FixedService>\n`;
    });
    xml += `    </FixedServices>\n`;

    xml += `    <PredefinedTasks>\n`;
    predefinedTasks.forEach(pt => {
      xml += `      <PredefinedTask id="${esc(pt.id)}">\n`;
      xml += xmlTag('Label', pt.label, '        ');
      xml += xmlTag('Description', pt.description, '        ');
      xml += `      </PredefinedTask>\n`;
    });
    xml += `    </PredefinedTasks>\n`;

    xml += `    <StatsSettings>\n`;
    (statsSettings.costItems || []).forEach(item => {
        xml += `      <CostItem id="${item.id}">\n`;
        xml += xmlTag('Name', item.name, '        ');
        xml += xmlTag('Amount', item.amount, '        ');
        xml += xmlTag('Category', item.category, '        ');
        xml += xmlTag('IsRecurring', item.isRecurring, '        ');
        xml += `      </CostItem>\n`;
    });
    xml += `    </StatsSettings>\n`;
    xml += `  </Settings>\n`;

    xml += `</AutoServiceBackup>`;
    return xml;
  };

  const handleDownloadBackup = () => {
    setBackupStatus('processing');
    try {
      const xml = generateBackupXml();
      const blob = new Blob([xml], { type: 'text/xml' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `autoservice_backup_${new Date().toISOString().split('T')[0]}.xml`;
      link.click();
      setBackupStatus('success');
      setTimeout(() => setBackupStatus('idle'), 2000);
    } catch (err) {
      console.error(err);
      setBackupStatus('error');
    }
  };

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setBackupStatus('processing');
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const parser = new DOMParser();
        const xmlDoc = parser.parseFromString(content, "text/xml");
        const txt = (parent: Element | Document, selector: string) => parent.querySelector(selector)?.textContent || '';
        const num = (parent: Element | Document, selector: string) => {
          const val = txt(parent, selector);
          return val ? parseFloat(val) : 0;
        };
        const bool = (parent: Element | Document, selector: string) => txt(parent, selector) === 'true';

        const restoredData = {
          customers: Array.from(xmlDoc.querySelectorAll("Customer")).map(node => ({
            id: node.getAttribute("id") || `cust-${Math.random().toString(36).substr(2, 9)}`,
            customerType: txt(node, "CustomerType") as any,
            firstName: txt(node, "FirstName"),
            lastName: txt(node, "LastName"),
            email: txt(node, "Email"),
            phone: txt(node, "Phone"),
            address: txt(node, "Address"),
            createdAt: txt(node, "CreatedAt") || new Date().toISOString(),
            companyName: txt(node, "CompanyName"),
            ico: txt(node, "ICO"),
            dic: txt(node, "DIC"),
            companyAddress: txt(node, "CompanyAddress"),
            contactPerson: txt(node, "ContactPerson")
          })),
