             <div className="flex gap-3"><button onClick={() => setIsClearDataConfirmOpen(false)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-black text-xs uppercase">ZRUŠIT</button><button onClick={() => { onClearAllData(); setIsClearDataConfirmOpen(false); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-xs uppercase">ANO, VYMAZAT</button></div>
