                   <button onClick={handleDownloadBackup} disabled={backupStatus === 'processing'} className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase hover:bg-slate-800 transition-all flex items-center justify-center gap-3 shadow-xl">
