                    </div>
                    <button onClick={() => setIsClearDataConfirmOpen(true)} className="px-8 py-4 bg-red-600 text-white rounded-2xl font-black text-xs uppercase hover:bg-red-700 transition-all shadow-xl shadow-red-200">
                       VYMAZAT SYSTÉM
                    </button>
                 </div>
              </div>
            </div>
          </div>
        )}
