import React, { useMemo, useState, useEffect, useRef } from 'react';
import { 
  AlertCircle, 
  Plus, 
  Car, 
  Wrench, 
  ShieldAlert, 
  UserPlus,
  ClipboardPlus,
  Clock,
  ChevronRight,
  ClipboardList,
  CheckCircle2,
  Trash2,
  Edit2,
  X,
  Check,
  ListTodo,
  Droplets,
  Settings2,
  AlertTriangle
} from 'lucide-react';
import { Customer, Vehicle, ServiceRecord, AppView, NotificationSettings, Task } from '../types';

interface DashboardProps {
  customers: Customer[];
  vehicles: Vehicle[];
  services: ServiceRecord[];
  tasks: Task[];
  onAddTask: (text: string) => void;
  onUpdateTask: (task: Task) => void;
  onDeleteTask: (id: string) => void;
  onNavigate: (view: AppView, autoOpen?: boolean) => void;
  onViewVehicle: (vehicleId: string) => void;
  onViewOrder: (orderId: string) => void;
  notifSettings: NotificationSettings;
}

const formatDate = (dateStr: string) => {
  if (!dateStr) return '---';
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

const calculateNextDate = (lastDate: string | undefined, intervalMonths: number | undefined) => {
  if (!lastDate || !intervalMonths || intervalMonths === 0) return null;
  const date = new Date(lastDate);
  if (isNaN(date.getTime())) return null;
  date.setMonth(date.getMonth() + intervalMonths);
  return date;
};

const Dashboard: React.FC<DashboardProps> = ({ 
  vehicles, 
  customers, 
  services, 
  tasks,
  onAddTask,
  onUpdateTask,
  onDeleteTask,
  onNavigate, 
  onViewVehicle, 
  onViewOrder,
  notifSettings 
}) => {
  const [isQuickActionOpen, setIsQuickActionOpen] = useState(false);
  const [newTaskText, setNewTaskText] = useState('');
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editTaskText, setEditTaskText] = useState('');
  const [taskToDelete, setTaskToDelete] = useState<string | null>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsQuickActionOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const vehicleAlerts = useMemo(() => {
    const alerts: { type: string; label: string; vehicle: Vehicle; daysLeft: number; priority: 'high' | 'medium' }[] = [];
    const now = new Date();
    now.setHours(0, 0, 0, 0);

    vehicles.forEach(v => {
      const checkDate = (dateStr: string | undefined, label: string, type: string, threshold: number, intervalMonths?: number) => {
        if (!dateStr) return;

        let targetDate: Date;
        if (intervalMonths) {
          const calculated = calculateNextDate(dateStr, intervalMonths);
          if (!calculated) return;
          targetDate = calculated;
        } else {
          targetDate = new Date(dateStr);
        }

        if (isNaN(targetDate.getTime())) return;

        const diffTime = targetDate.getTime() - now.getTime();
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        // Zobrazit pokud je po termínu (diffDays < 0) nebo v limitu (diffDays <= threshold)
        if (diffDays <= threshold) {
          alerts.push({ 
            type, 
            label, 
            vehicle: v, 
            daysLeft: diffDays,
            priority: diffDays < 0 ? 'high' : 'medium'
          });
        }
      };

      // 1. STK
      checkDate(v.stkExpirationDate, 'STK Expirace', 'stk', notifSettings.stkThresholdDays);

      // 2. Obecný servis / Olej
      checkDate(v.nextServiceDate, 'Plánovaný servis', 'service', notifSettings.serviceThresholdDays);
