const formatDate = (dateStr: any) => {
  if (typeof dateStr !== 'string' || !dateStr) return '---';
  const datePart = dateStr.split('T')[0];
  if (!datePart) return '---';
  const parts = datePart.split('-');
  if (parts.length !== 3) return dateStr;
  return `${parts[2]}.${parts[1]}.${parts[0]}`;
};

interface InvoiceManagerProps {
  invoices: Invoice[];
  customers: Customer[];
  services?: ServiceRecord[]; 
  companyInfo: CompanyInfo;
  discountLevels: number[];
  onDeleteInvoice: (uid: string) => void;
  onUpdateInvoiceStatus: (uid: string, status: 'uhrazeno' | 'neuhrazeno') => void;
  onUpdateInvoice: (invoice: Invoice) => void;
  search: string;
  onSearchChange: (value: string) => void;
}

const InvoiceManager: React.FC<InvoiceManagerProps> = ({ invoices, customers, services = [], companyInfo, discountLevels, onDeleteInvoice, onUpdateInvoiceStatus, onUpdateInvoice, search, onSearchChange }) => {
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [deletingInvoice, setDeletingInvoice] = useState<Invoice | null>(null);
  const [isAiCostLoading, setIsAiCostLoading] = useState(false);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);

  const [isExportModalOpen, setIsExportModalOpen] = useState(false);
  const [exportDateFrom, setExportDateFrom] = useState('');
  const [exportDateTo, setExportDateTo] = useState('');
  const [selectedExportUids, setSelectedExportUids] = useState<Set<string>>(new Set());

  const today = new Date().toISOString().split('T')[0];
  const costFileInputRef = useRef<HTMLInputElement>(null);

  const handlePrint = () => window.print();

  const filteredInvoices = useMemo(() => {
    return invoices.filter(inv => {
      if (inv.archived) return false;
      const customer = customers.find(c => c.id === inv.customerId);
      const searchLower = search.toLowerCase();
      return (
        (inv.id || "").toLowerCase().includes(searchLower) ||
        (customer?.lastName || '').toLowerCase().includes(searchLower) ||
        (customer?.companyName || '').toLowerCase().includes(searchLower) ||
        (inv.vehicleInfo || "").toLowerCase().includes(searchLower)
      );
    });
  }, [invoices, customers, search]);

  const invoicesForExport = useMemo(() => {
    return invoices.filter(inv => {
      const matchesDateFrom = !exportDateFrom || inv.issueDate >= exportDateFrom;
      const matchesDateTo = !exportDateTo || inv.issueDate <= exportDateTo;
      return matchesDateFrom && matchesDateTo;
    }).sort((a, b) => b.issueDate.localeCompare(a.issueDate));
  }, [invoices, exportDateFrom, exportDateTo]);

  const { unpaidInvoices, paidInvoices, totalUnpaid, totalPaid } = useMemo(() => {
    const unpaid = filteredInvoices.filter(inv => inv.status === 'neuhrazeno');
    const paid = filteredInvoices.filter(inv => inv.status === 'uhrazeno');

    return {
      unpaidInvoices: unpaid,
      paidInvoices: paid,
      totalUnpaid: Math.round(unpaid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0)),
      totalPaid: Math.round(paid.reduce((sum, inv) => sum + (Number(inv.totalInclDph) || 0), 0))
    };
  }, [filteredInvoices]);

  const toggleExportSelection = (uid: string) => {
    const next = new Set(selectedExportUids);
    if (next.has(uid)) next.delete(uid);
    else next.add(uid);
    setSelectedExportUids(next);
  };

  const selectAllForExport = () => {
    if (selectedExportUids.size === invoicesForExport.length) {
      setSelectedExportUids(new Set());
    } else {
      setSelectedExportUids(new Set(invoicesForExport.map(i => i.uid)));
    }
  };

  const handlePohodaExport = () => {
    const selectedInvoices = invoices.filter(inv => selectedExportUids.has(inv.uid));
    if (selectedInvoices.length === 0) return;

    let filename = 'Rohacek_export';
    const monthsInSelection = Array.from(new Set(selectedInvoices.map(inv => inv.issueDate.substring(0, 7))));
    if (monthsInSelection.length === 1) {
      filename = `Rohacek_${monthsInSelection[0]}`;
    }

    const esc = (str: any) => String(str || '').trim().replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c] || c));

    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
    xml += `<dat:dataPack id="export001" ico="${esc(companyInfo.ico?.trim())}" application="AutoService Pro" version="2.0" note="Export faktur" xmlns:dat="http://www.stormware.cz/schema/version_2/data.xsd" xmlns:inv="http://www.stormware.cz/schema/version_2/invoice.xsd" xmlns:typ="http://www.stormware.cz/schema/version_2/type.xsd">\n`;

    selectedInvoices.forEach((inv, index) => {
      const customer = customers.find(c => c.id === inv.customerId);
      const isVat = companyInfo.isVatPayer;

      const addrParts = (customer?.address || '').split(',').map(p => p.trim());
      const street = addrParts[0] || '';
      const cityAndZip = addrParts.slice(1).join(', ') || '';
      const zipMatch = cityAndZip.match(/\d{3}\s?\d{2}/);
      const zip = zipMatch ? zipMatch[0].replace(/\s/g, '') : '';
      const city = cityAndZip.replace(/\d{3}\s?\d{2}/, '').replace(/^[,\s]+|[,\s]+$/g, '').trim();

      xml += `  <dat:dataPackItem id="inv${index}" version="2.0">\n`;
      xml += `    <inv:invoice version="2.0">\n`;
      xml += `      <inv:invoiceHeader>\n`;
      xml += `        <inv:invoiceType>issuedInvoice</inv:invoiceType>\n`;
      xml += `        <inv:number>\n`;
      xml += `          <typ:numberRequested>${esc(inv.id)}</typ:numberRequested>\n`;
      xml += `        </inv:number>\n`;
      xml += `        <inv:date>${inv.issueDate}</inv:date>\n`;
      xml += `        <inv:dateTax>${inv.issueDate}</inv:dateTax>\n`;
      xml += `        <inv:dateDue>${inv.dueDate}</inv:dateDue>\n`;
      xml += `        <inv:text>Oprava vozidla: ${esc(inv.vehicleInfo)}</inv:text>\n`;
      xml += `        <inv:paymentType>\n`;
      xml += `          <typ:ids>${inv.paymentType === 'Hotově' ? 'cash' : 'account'}</typ:ids>\n`;
      xml += `        </inv:paymentType>\n`;
      xml += `        <inv:partnerIdentity>\n`;
      xml += `          <typ:address>\n`;
      xml += `            <typ:company>${esc(customer?.companyName || (customer?.lastName + ' ' + customer?.firstName))}</typ:company>\n`;
      xml += `            <typ:city>${esc(city)}</typ:city>\n`;
      xml += `            <typ:street>${esc(street)}</typ:street>\n`;
      xml += `            <typ:zip>${esc(zip)}</typ:zip>\n`;
      xml += `            <typ:ico>${esc(customer?.ico?.trim())}</typ:ico>\n`;
      xml += `            <typ:dic>${esc(customer?.dic?.trim())}</typ:dic>\n`;
      xml += `          </typ:address>\n`;
      xml += `        </inv:partnerIdentity>\n`;
      xml += `      </inv:invoiceHeader>\n`;
      xml += `      <inv:invoiceDetail>\n`;

      inv.items.forEach(item => {
        xml += `        <inv:invoiceItem>\n`;
        xml += `          <inv:text>${esc(item.description)}</inv:text>\n`;
        xml += `          <inv:quantity>${item.quantity}</inv:          <inv:unit>${esc(item.unit)}</inv:unit>\n`;
        xml += `          <inv:payVAT>${isVat}</inv:payVAT>\n`;
        xml += `          <inv:rateVAT>${isVat ? 'high' : 'none'}</inv:rateVAT>\n`;
        xml += `          <inv:homeCurrency>\n`;
        xml += `            <typ:unitPrice>${Math.round(item.unitPrice)}</typ:unitPrice>\n`;
        xml += `          </inv:homeCurrency>\n`;
        xml += `        </inv:invoiceItem>\n`;
      });

      xml += `      </inv:invoiceDetail>\n`;
      xml += `    </inv:invoice>\n`;
      xml += `  </dat:dataPackItem>\n`;
    });

    xml += `</dat:dataPack>`;

    const blob = new Blob([xml], { type: 'application/xml' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${filename}.xml`;
    link.click();
    URL.revokeObjectURL(url);
    setIsExportModalOpen(false);
  };

  const handleUpdateActiveInvoice = (field: keyof Invoice, value: any) => {
    if (!selectedInvoice) return;

    let updated = { ...selectedInvoice, [field]: value };

    if (field === 'paymentType' || field === 'issueDate') {
      if (updated.paymentType === 'Hotově') {
        updated.dueDate = updated.issueDate;
      } else {
        const currentDiff = Math.round((new Date(selectedInvoice.dueDate).getTime() - new Date(selectedInvoice.issueDate).getTime()) / (1000 * 3600 * 24));
        const diff = isNaN(currentDiff) || currentDiff < 0 ? 14 : currentDiff;
        const date = new Date(updated.issueDate);
        date.setDate(date.getDate() + diff);
        updated.dueDate = date.toISOString().split('T')[0];
      }
    }

    if (field === 'discount' || field === 'items') {
      const currentItems = updated.items || [];
      const baseTotal = currentItems.reduce((sum, item) => sum + (Number(item.quantity) * Number(item.unitPrice)), 0);
      const discountedBase = baseTotal * (1 - ((Number(updated.discount) || 0) / 100));
      updated.totalExclDph = discountedBase;
      updated.totalInclDph = companyInfo.isVatPayer ? Math.round(discountedBase * 1.21) : Math.round(discountedBase);
    }

    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleUpdateDueDays = (days: number) => {
    if (!selectedInvoice) return;
    const date = new Date(selectedInvoice.issueDate);
    date.setDate(date.getDate() + days);
    const updated = { ...selectedInvoice, dueDate: date.toISOString().split('T')[0] };
    setSelectedInvoice(updated);
    onUpdateInvoice(updated);
  };

  const handleArchiveInvoice = (inv: Invoice) => {
